/// One mutable row selected by a DML statement. A local heap identity and a
/// remote PostgreSQL tuple identity are distinct closed states: callers cannot
/// accidentally turn a foreign row into a local shadow row.
#[derive(Clone, Copy)]
pub(crate) enum PhysicalRow {
    Local {
        table_index: usize,
        rowid: u64,
        home: crate::storage::RowSnapshot,
    },
    Foreign {
        table_index: usize,
        tuple_id: crate::sql::foreign::RemoteTupleId,
    },
}

impl PhysicalRow {
    fn local(table_index: usize, rowid: u64, snapshot: crate::storage::RowSnapshot) -> Self {
        Self::Local {
            table_index,
            rowid,
            home: snapshot,
        }
    }

    fn local_parts(self) -> (usize, u64, crate::storage::RowSnapshot) {
        match self {
            Self::Local {
                table_index,
                rowid,
                home,
            } => (table_index, rowid, home),
            Self::Foreign { .. } => unreachable!("local DML path received a foreign row"),
        }
    }

    fn sort_key(self) -> (usize, u64) {
        match self {
            Self::Local {
                table_index, rowid, ..
            } => (table_index, rowid),
            Self::Foreign {
                table_index,
                tuple_id,
            } => (table_index, tuple_id.sort_key()),
        }
    }
}

pub(crate) type DmlScratch = MutableSlice<PhysicalRow>;

#[derive(Clone, Copy)]
struct DmlRowImage<'arena> {
    table: usize,
    rowid: u64,
    bytes: &'arena [u8],
}

#[derive(Clone, Copy)]
struct DmlTableLayout<'arena> {
    table: usize,
    columns: crate::storage::RelationColumnMap<'arena>,
    schema: &'arena [ColType],
    checks: constraints::ParsedChecks<'arena>,
    generated: &'arena [Option<&'arena Expr<'arena>>],
}

impl DmlTableLayout<'_> {
    fn project<'values>(self, physical: &[Datum<'values>], logical: &mut [Datum<'values>]) {
        self.columns.project(physical, logical);
    }

    fn overlay<'values>(self, logical: &[Datum<'values>], physical: &mut [Datum<'values>]) {
        self.columns.overlay(logical, physical);
    }

    fn column_set(self, logical: ColumnSet) -> ColumnSet {
        self.columns.column_set(logical)
    }
}

/// Selected bytes outlive target ordering and nested trigger scratch changes.
/// The staging records remain independent of this statement's arena lifetime.
pub(super) struct DmlRowImages<'arena> {
    rows: ArenaList<'arena, DmlRowImage<'arena>>,
    tables: ArenaList<'arena, DmlTableLayout<'arena>>,
    /// The FROM row each selected target row of `UPDATE ... FROM` joined,
    /// keyed by the target row's `PhysicalRow::sort_key`.
    joined: ArenaList<'arena, ((usize, u64), super::query::JoinedFromRow<'arena>)>,
}

impl<'arena> DmlRowImages<'arena> {
    fn new(arena: &'arena Arena) -> Self {
        Self {
            rows: ArenaList::new(arena),
            tables: ArenaList::new(arena),
            joined: ArenaList::new(arena),
        }
    }

    fn push_joined(
        &mut self,
        row: PhysicalRow,
        joined: super::query::JoinedFromRow<'arena>,
    ) -> Result<(), SqlError> {
        self.joined.push((row.sort_key(), joined)).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "joined FROM rows exceed the statement arena"
            )
        })
    }

    /// A read committed recheck continues with the FROM row that still meets
    /// the statement's conditions for the target row's latest version.
    fn replace_joined(
        &mut self,
        row: PhysicalRow,
        joined: super::query::JoinedFromRow<'arena>,
    ) -> Result<(), SqlError> {
        let rows = self.joined.as_mut_slice().map_err(|_| arena_full())?;
        if let Ok(index) = rows.binary_search_by_key(&row.sort_key(), |(key, _)| *key) {
            rows[index].1 = joined;
        }
        Ok(())
    }

    /// The joined row kept for `row`, when the selection joined one.
    fn joined_bytes(&self, row: PhysicalRow) -> Option<&'arena [u8]> {
        let rows = self.joined.as_slice();
        rows.binary_search_by_key(&row.sort_key(), |(key, _)| *key)
            .ok()
            .map(|index| rows[index].1.bytes())
    }

    fn joined(&self, row: PhysicalRow) -> Result<super::query::JoinedFromRow<'arena>, SqlError> {
        let rows = self.joined.as_slice();
        rows.binary_search_by_key(&row.sort_key(), |(key, _)| *key)
            .map(|index| rows[index].1)
            .map_err(|_| {
                sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "selected DML row has no retained FROM row"
                )
            })
    }

    #[expect(
        clippy::too_many_arguments,
        reason = "retained DML layouts bind stored expressions with their catalog and transaction authority"
    )]
    fn capture_layout<
        Definition0: crate::storage::DefinitionBacking,
        Definition1: crate::storage::DefinitionBacking,
    >(
        &mut self,
        table: usize,
        logical: &crate::storage::TableDefinition<Definition0>,
        physical: &crate::storage::TableDefinition<Definition1>,
        capture: DmlCapture,
        arena: &'arena Arena,
        storage: &Storage,
        txid: u32,
    ) -> Result<DmlTableLayout<'arena>, SqlError> {
        if let Some(layout) = self
            .tables
            .as_slice()
            .iter()
            .find(|layout| layout.table == table)
        {
            return Ok(*layout);
        }
        let columns = crate::storage::RelationColumnMap::new(logical, physical, arena)?;
        let schema = arena
            .alloc_slice_with(physical.n_columns, |column| {
                physical.columns()[column].ctype
            })
            .map_err(|_| arena_full())?;
        let (checks, generated) = if matches!(capture, DmlCapture::Update { .. }) {
            let checks = parse_checks(physical, arena)?;
            let generated = if physical
                .columns()
                .iter()
                .any(|column| column.default.is_generated())
            {
                let generated = parse_generated(physical, arena, storage, txid)?;
                &*arena
                    .alloc_slice_copy(&generated[..physical.n_columns])
                    .map_err(|_| arena_full())?
            } else {
                &[][..]
            };
            (checks, generated)
        } else {
            (
                [None; crate::storage::MAX_CHECKS + crate::storage::MAX_EXCLUSIONS],
                &[][..],
            )
        };
        let layout = DmlTableLayout {
            table,
            columns,
            schema,
            checks,
            generated,
        };
        self.tables.push(layout).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "DML table layouts exceed the statement arena"
            )
        })?;
        Ok(layout)
    }

    fn layout(&self, table: usize) -> Result<DmlTableLayout<'arena>, SqlError> {
        self.tables
            .as_slice()
            .iter()
            .find(|layout| layout.table == table)
            .copied()
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "selected DML table has no retained layout"
                )
            })
    }

    fn push(&mut self, table: usize, rowid: u64, bytes: &'arena [u8]) -> Result<(), SqlError> {
        self.rows
            .push(DmlRowImage {
                table,
                rowid,
                bytes,
            })
            .map_err(|_| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "selected DML row records exceed the statement arena"
                )
            })
    }

    fn finish(mut self) -> Result<Self, SqlError> {
        self.rows
            .as_mut_slice()
            .map_err(|_| arena_full())?
            .sort_unstable_by_key(|row| (row.table, row.rowid));
        self.joined
            .as_mut_slice()
            .map_err(|_| arena_full())?
            .sort_unstable_by_key(|(key, _)| *key);
        Ok(self)
    }

    /// A read committed recheck continues with the row's latest version.
    /// Rows selected without bytes keep none.
    fn replace(&mut self, table: usize, rowid: u64, bytes: &'arena [u8]) -> Result<(), SqlError> {
        let rows = self.rows.as_mut_slice().map_err(|_| arena_full())?;
        if let Ok(index) = rows.binary_search_by_key(&(table, rowid), |row| (row.table, row.rowid))
        {
            rows[index].bytes = bytes;
        }
        Ok(())
    }

    pub(super) fn bytes(&self, table: usize, rowid: u64) -> Result<&'arena [u8], SqlError> {
        let rows = self.rows.as_slice();
        let index = rows
            .binary_search_by_key(&(table, rowid), |row| (row.table, row.rowid))
            .map_err(|_| {
                sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "selected DML row has no retained bytes"
                )
            })?;
        Ok(rows[index].bytes)
    }
}

#[derive(Clone, Copy)]
pub(super) enum DmlCapture {
    Update { command: u32 },
    Delete { command: u32, returning: bool },
}

impl DmlCapture {
    /// `UPDATE ... FROM` assignments read the FROM row each target row joined.
    fn retains_joined(self) -> bool {
        matches!(self, Self::Update { .. })
    }

    fn command(self) -> u32 {
        match self {
            Self::Update { command } | Self::Delete { command, .. } => command,
        }
    }

    fn needs_bytes(self, storage: &Storage, logical_table: usize, table: usize, txid: u32) -> bool {
        match self {
            Self::Update { .. } => true,
            Self::Delete { returning, .. } => {
                let physical = (*storage.table_def(table, txid)).clone();
                returning
                    || table_is_referenced(
                        storage,
                        physical.schema.as_str(),
                        physical.name.as_str(),
                        txid,
                    )
                    || storage.triggers_for_table(table, txid).next().is_some()
                    || storage
                        .triggers_for_table(logical_table, txid)
                        .next()
                        .is_some()
            }
        }
    }
}

enum MatchedDmlRow<'arena> {
    Identity,
    Bytes(&'arena [u8]),
}

fn retain_dml_bytes<'arena>(arena: &'arena Arena, bytes: &[u8]) -> Result<&'arena [u8], SqlError> {
    arena
        .alloc_slice_copy(bytes)
        .map(|bytes| &*bytes)
        .map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "selected DML row exceeds the statement arena"
            )
        })
}

fn dml_row_available(
    storage: &Storage,
    txn: &TxnState,
    row: PhysicalRow,
    action: &str,
) -> Result<bool, SqlError> {
    let PhysicalRow::Local {
        table_index,
        rowid,
        home,
    } = row
    else {
        return Ok(true);
    };
    let original = home;
    Ok(
        match storage.row_self_change(table_index, rowid, original, txn.txid, txn.command_id())? {
            crate::storage::RowSelfChange::Original => true,
            crate::storage::RowSelfChange::SameCommand => false,
            crate::storage::RowSelfChange::TriggeredCommand => {
                return Err(sql_err!(
                    sqlstate::TRIGGERED_DATA_CHANGE_VIOLATION,
                    "tuple to be {} was already modified by an operation triggered by the current command",
                    action
                ));
            }
        },
    )
}

/// The statement conditions a row selected by `UPDATE` or `DELETE` must still
/// meet in its latest version (PostgreSQL's EvalPlanQual recheck).
struct DmlRequalify<'q, 'a, Definition: crate::storage::DefinitionBacking> {
    def: &'q crate::storage::TableDefinition<Definition>,
    alias: Option<&'q str>,
    from: Option<&'a crate::sql::ast::FromClause<'a>>,
    where_clause: Option<&'a Expr<'a>>,
    params: &'q [Datum<'a>],
    hooks: &'q super::eval::EvalHooks<'q, 'a>,
    row_security: Option<super::query::RowSecurityPlan<'a>>,
    outer: Option<&'q dyn ColumnLookup<'a>>,
    sequences: Option<&'q dyn crate::sql::eval::SequenceAccess>,
}

impl<'a, Definition: crate::storage::DefinitionBacking> DmlRequalify<'_, 'a, Definition> {
    /// The latest version's bytes when it still qualifies.
    #[allow(clippy::too_many_arguments)]
    fn latest(
        &self,
        storage: &Storage,
        txid: u32,
        layout: DmlTableLayout<'a>,
        table: usize,
        rowid: u64,
        seen: crate::storage::RowSnapshot,
        latest: crate::storage::VisibleRowHome,
        arena: &'a Arena,
    ) -> Result<Option<RequalifiedRow<'a>>, SqlError> {
        let bytes = storage.row_bytes(table, rowid, latest, arena)?;
        let mut physical = [Datum::Null; MAX_COLUMNS];
        rowenc::decode(bytes, layout.schema, &mut physical)?;
        let mut values = [Datum::Null; MAX_COLUMNS];
        layout.project(&physical, &mut values);
        let Some(from) = self.from else {
            if !row_matches_values(
                storage,
                txid,
                self.def,
                self.alias,
                &values,
                None,
                arena,
                self.params,
                self.hooks,
                self.row_security,
                self.outer,
            )? {
                return Ok(None);
            }
            let unjoined = RequalifiedRow {
                bytes,
                joined: None,
            };
            let Some(predicate) = self.where_clause else {
                return Ok(Some(unjoined));
            };
            // The version the statement selected, for the semi-joins whose
            // recheck keeps the subquery row it first matched.
            let first_bytes = storage.row_bytes(table, rowid, seen, arena)?;
            let mut first_physical = [Datum::Null; MAX_COLUMNS];
            rowenc::decode(first_bytes, layout.schema, &mut first_physical)?;
            let mut first_values = [Datum::Null; MAX_COLUMNS];
            layout.project(&first_physical, &mut first_values);
            let relation = crate::storage::RelationDefinition::from_definition(self.def);
            let first_row = RowCtx {
                def: relation,
                values: &first_values[..self.def.n_columns],
                alias: self.alias,
            };
            let latest_row = RowCtx {
                def: relation,
                values: &values[..self.def.n_columns],
                alias: self.alias,
            };
            let first_scope = self.outer.map(|outer| TriggerDmlScope {
                row: &first_row,
                outer,
            });
            let latest_scope = self.outer.map(|outer| TriggerDmlScope {
                row: &latest_row,
                outer,
            });
            let matched = super::query::locked_row_where_passes(
                storage,
                txid,
                predicate,
                match first_scope.as_ref() {
                    Some(scope) => scope,
                    None => &first_row,
                },
                match latest_scope.as_ref() {
                    Some(scope) => scope,
                    None => &latest_row,
                },
                arena,
                self.params,
                self.hooks,
            )?;
            return Ok(matched.then_some(unjoined));
        };
        let context = RowCtx {
            def: crate::storage::RelationDefinition::from_definition(self.def),
            values: &values[..self.def.n_columns],
            alias: self.alias,
        };
        if let Some(plan) = self.row_security
            && !super::query::row_security_passes(
                plan,
                &context,
                storage,
                txid,
                arena,
                self.params,
                self.hooks,
            )?
        {
            return Ok(None);
        }
        let first_bytes = storage.row_bytes(table, rowid, seen, arena)?;
        let mut first_physical = [Datum::Null; MAX_COLUMNS];
        rowenc::decode(first_bytes, layout.schema, &mut first_physical)?;
        let mut first_values = [Datum::Null; MAX_COLUMNS];
        layout.project(&first_physical, &mut first_values);
        let first_row = RowCtx {
            values: &first_values[..self.def.n_columns],
            ..context
        };
        let first_joined = self.outer.map(|outer| JoinedTriggerDmlScope {
            row: &first_row,
            outer,
        });
        let latest_joined = self.outer.map(|outer| JoinedTriggerDmlScope {
            row: &context,
            outer,
        });
        let joined = super::query::recheck_joined_from_match(
            storage,
            from,
            txid,
            self.where_clause,
            arena,
            self.params,
            match first_joined.as_ref() {
                Some(joined) => joined,
                None => &first_row,
            },
            match latest_joined.as_ref() {
                Some(joined) => joined,
                None => &context,
            },
            self.sequences,
            arena,
        )?;
        Ok(joined.map(|joined| RequalifiedRow {
            bytes,
            joined: Some(joined),
        }))
    }
}

/// A selected row's latest version that still meets the statement's
/// conditions, with the FROM row an `UPDATE ... FROM` or `DELETE ... USING`
/// recheck joined it to.
struct RequalifiedRow<'a> {
    bytes: &'a [u8],
    joined: Option<super::query::JoinedFromRow<'a>>,
}

/// Locks every selected row before any row changes, as PostgreSQL does. A
/// row another transaction changed after the statement's snapshot fails the
/// statement with `40001` under repeatable read and serializable; under read
/// committed the statement continues with the row's latest version when it
/// still meets the statement's conditions, and skips the row otherwise.
#[allow(clippy::too_many_arguments)]
fn lock_selected_dml_rows<'a, Definition: crate::storage::DefinitionBacking>(
    storage: &Storage,
    txn: &TxnState,
    scratch: &mut DmlScratch,
    retained_rows: &mut DmlRowImages<'a>,
    strength: crate::sql::ast::LockStrength,
    requalify: &DmlRequalify<'_, 'a, Definition>,
    arena: &'a Arena,
) -> Result<(), SqlError> {
    let repeatable = row_conflicts::uses_transaction_snapshot(txn.isolation);
    let mut kept = 0usize;
    for index in 0..scratch.len() {
        let row = scratch[index];
        let PhysicalRow::Local {
            table_index: table,
            rowid,
            home,
        } = row
        else {
            scratch.as_mut_slice()[kept] = row;
            kept += 1;
            continue;
        };
        let locked = row_conflicts::lock_selected_row(
            storage,
            txn.txid,
            table,
            rowid,
            home,
            strength,
            crate::sql::ast::LockWait::Wait,
        )?
        .ok_or_else(|| {
            sql_err!(
                sqlstate::INTERNAL_ERROR,
                "data modification skipped a locked row"
            )
        })?;
        let row = match locked {
            row_conflicts::LockedVersion::Selected => Some(row),
            row_conflicts::LockedVersion::Deleted if repeatable => {
                return Err(row_conflicts::concurrent_change(true));
            }
            row_conflicts::LockedVersion::Updated(_) if repeatable => {
                return Err(row_conflicts::concurrent_change(false));
            }
            row_conflicts::LockedVersion::Deleted => None,
            row_conflicts::LockedVersion::Updated(latest) => {
                let snapshot = latest.snapshot();
                let layout = retained_rows.layout(table)?;
                match requalify
                    .latest(storage, txn.txid, layout, table, rowid, home, latest, arena)?
                {
                    Some(requalified) => {
                        retained_rows.replace(table, rowid, requalified.bytes)?;
                        let row = PhysicalRow::local(table, rowid, snapshot);
                        if let Some(joined) = requalified.joined {
                            retained_rows.replace_joined(row, joined)?;
                        }
                        Some(row)
                    }
                    None => None,
                }
            }
        };
        if let Some(row) = row {
            scratch.as_mut_slice()[kept] = row;
            kept += 1;
        }
    }
    scratch.truncate(kept);
    Ok(())
}

/// The role whose privileges and row-security policies authorize a DML
/// target. Rewrite actions use their owning relation's role without changing
/// SQL-visible session identity.
#[derive(Clone, Copy)]
pub(crate) enum DmlAuthorization {
    Invoker,
    RuleOwner(u16),
}

impl DmlAuthorization {
    fn role(self, storage: &Storage, txid: u32) -> Result<usize, SqlError> {
        match self {
            Self::Invoker => storage.current_role_slot(txid).ok_or_else(|| {
                sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "current role is not present in the role catalog"
                )
            }),
            Self::RuleOwner(role) => Ok(usize::from(role)),
        }
    }
}

/// PostgreSQL's maximum target-list and query-result width.
pub const MAX_PROJ: usize = 1_664;

/// Fixed stack reserved by every thread that may execute a query. Query
/// scratch is statically bounded, including PostgreSQL's complete result width.
pub const QUERY_STACK_BYTES: usize = 128 << 20;

/// The session services a statement lends to the triggers it fires while it
/// holds the engine's storage: sequence state, the session's SQL cursors, and
/// the query workspace's scan buffers a cursor reads its next rows with.
pub(crate) struct TriggerServices<'s> {
    pub(crate) seq_session: &'s crate::sql::guc::SeqSession,
    pub(crate) cursors: &'s mut crate::sql::cursor::CursorPool,
    pub(crate) row_buffers: &'s mut crate::storage::RowCursorBuffers,
}

impl<'s> TriggerServices<'s> {
    pub(crate) fn new(
        seq_session: &'s crate::sql::guc::SeqSession,
        cursors: &'s mut crate::sql::cursor::CursorPool,
        row_buffers: &'s mut crate::storage::RowCursorBuffers,
    ) -> Self {
        Self {
            seq_session,
            cursors,
            row_buffers,
        }
    }

    pub(crate) fn reborrow(&mut self) -> TriggerServices<'_> {
        TriggerServices {
            seq_session: self.seq_session,
            cursors: self.cursors,
            row_buffers: self.row_buffers,
        }
    }
}

/// Apply uses its worker's session and bounded response buffer. Nested writes
/// own their selection ranges in the shared startup row-work pool.
pub(crate) struct ReplicationTriggerContext<'a, 'response> {
    services: TriggerServices<'a>,
    responder: &'a mut Responder<'response>,
}

impl<'a, 'response> ReplicationTriggerContext<'a, 'response> {
    /// The apply worker's session with the engine workspace's scan buffers.
    pub(crate) fn new(
        session: ReplicationSession<'a, 'response>,
        row_buffers: &'a mut crate::storage::RowCursorBuffers,
    ) -> Self {
        Self {
            services: TriggerServices::new(session.seq_session, session.cursors, row_buffers),
            responder: session.responder,
        }
    }
}

/// The apply worker's sequence state, cursors and response buffer, which the
/// engine joins with its workspace to fire replicated rows' triggers.
pub(crate) struct ReplicationSession<'a, 'response> {
    seq_session: &'a crate::sql::guc::SeqSession,
    cursors: &'a mut crate::sql::cursor::CursorPool,
    responder: &'a mut Responder<'response>,
}

impl<'a, 'response> ReplicationSession<'a, 'response> {
    pub(crate) fn new(
        seq_session: &'a crate::sql::guc::SeqSession,
        cursors: &'a mut crate::sql::cursor::CursorPool,
        responder: &'a mut Responder<'response>,
    ) -> Self {
        Self {
            seq_session,
            cursors,
            responder,
        }
    }
}

/// Each replicated action ends its row-trigger query before the next action
/// can reset scratch. Subscription apply never fires statement triggers here.
pub(crate) fn finish_replication_row(
    storage: &mut Storage,
    txn: &mut TxnState,
    arena: &Arena,
    context: &mut ReplicationTriggerContext<'_, '_>,
) -> Result<(), SqlError> {
    let depth = txn.trigger_depth();
    fire_statement_row_trigger_events(
        &mut TriggerExecContext {
            host: PlpgsqlExecHost::Atomic {
                storage,
                services: context.services.reborrow(),
            },
            txn,
            arena,
            params: crate::sql::eval::NO_PARAMS,
            responder: context.responder,
        },
        depth,
        TransitionRowSets::EMPTY,
    )
}

/// Column resolution over one decoded row. The datum lifetime `'v` (heap /
/// arena bytes) is independent of the borrow of the value slice itself, so
/// looked-up datums may outlive the decode buffer.
pub struct RowCtx<'s, 'v, 'd> {
    pub def: crate::storage::RelationDefinition<'d>,
    pub values: &'s [Datum<'v>],
    pub alias: Option<&'d str>,
}

/// The view rules a write through an auto-updatable view keeps: the
/// `WITH CHECK OPTION` filters its rows must pass and the view defaults an
/// INSERT applies. Predicates are retained as parsed expressions over the
/// base table, so the write boundary never reparses catalog text while rows
/// are being changed.
#[derive(Clone, Copy)]
pub(crate) struct ViewCheck<'a> {
    /// `(view name, filter)` pairs, innermost view first, as PostgreSQL's
    /// `ExecWithCheckOptions` evaluates them.
    pub checks: &'a [(&'a str, &'a Expr<'a>)],
    /// Each view level's defaults, outermost first; the first level with a
    /// default for a base column supplies it.
    pub defaults: &'a [ViewInsertDefaults<'a>],
}

/// View-column defaults paired with the base columns reached by an
/// auto-updatable view.  Keeping this mapping with the view rewrite avoids
/// treating catalog aliases as table-column names at the INSERT boundary.
#[derive(Clone, Copy)]
pub(crate) struct ViewInsertDefaults<'a> {
    pub base_columns: &'a [&'a str],
    pub columns: crate::storage::ViewColumns,
    pub inputs: &'a [(
        crate::storage::StoredInputSection,
        &'a [super::type_inputs::Binding<'a>],
    )],
}

struct ViewCheckContext<'storage, 'arena, 'params, 'sequence> {
    storage: &'storage Storage,
    txid: u32,
    arena: &'arena Arena,
    params: &'params [Datum<'arena>],
    seq_session: &'sequence crate::sql::guc::SeqSession,
}

impl<'v> ColumnLookup<'v> for RowCtx<'_, 'v, '_> {
    fn column_type_mod(&self, qualifier: Option<&str>, name: &str) -> i32 {
        describe::AliasedDefCols {
            definition: self.def,
            alias: self.alias,
            output_aliases: &[],
        }
        .column_type_mod(qualifier, name)
    }

    fn whole_row_field_metadata(
        &self,
        table: &str,
        index: usize,
        catalog: Option<&dyn super::eval::CatalogAccess>,
    ) -> Option<(StackStr<64>, StaticTypeMeta)> {
        if crate::sql::eval::qualifier_answers_target(self.def, self.alias, table) {
            super::eval::stored_row_field_metadata(self.def.columns().get(index)?, catalog)
        } else {
            None
        }
    }

    fn resolve_column_type(
        &self,
        qualifier: Option<&str>,
        name: &str,
    ) -> Result<ColType, SqlError> {
        describe::AliasedDefCols {
            definition: self.def,
            alias: self.alias,
            output_aliases: &[],
        }
        .resolve_column_type(qualifier, name)
    }

    fn whole_row_type(&self, table: &str) -> Option<ColType> {
        crate::sql::eval::qualifier_answers_target(self.def, self.alias, table)
            .then_some(ColType::Record)
    }
    fn whole_row_relation(&self, table: &str) -> Option<(&str, &str)> {
        crate::sql::eval::qualifier_answers_target(self.def, self.alias, table)
            .then(|| (self.def.schema.as_str(), self.def.name.as_str()))
    }

    fn lookup(&self, qualifier: Option<&str>, name: &str) -> Result<Datum<'v>, SqlError> {
        if let Some(q) = qualifier
            && !crate::sql::eval::qualifier_answers_target(self.def, self.alias, q)
        {
            return Err(sql_err!(
                sqlstate::UNDEFINED_TABLE,
                "missing FROM-clause entry for table \"{}\"",
                q
            ));
        }
        match self.def.column_index(name) {
            Some(i) => Ok(self.values[i]),
            None => Err(sql_err!(
                sqlstate::UNDEFINED_COLUMN,
                "column \"{}\" does not exist",
                name
            )),
        }
    }

    fn whole_row_fields(
        &self,
        table: &str,
        arena: &'v Arena,
    ) -> Result<Option<&'v [super::types::RecordField<'v>]>, SqlError> {
        if !crate::sql::eval::qualifier_answers_target(self.def, self.alias, table) {
            return Err(sql_err!(
                sqlstate::UNDEFINED_TABLE,
                "missing FROM-clause entry for table \"{}\"",
                table
            ));
        }
        let cols = self.def.columns();
        let mut fields = [super::types::RecordField {
            name: "",
            type_oid: 0,
            type_mod: -1,
            value: Datum::Null,
        }; MAX_COLUMNS];
        let too_large = || sql_err!(sqlstate::PROGRAM_LIMIT_EXCEEDED, "record exceeds the arena");
        for (i, field) in fields.iter_mut().enumerate().take(self.def.n_columns) {
            field.name = arena
                .alloc_str(cols[i].name.as_str())
                .map_err(|_| too_large())?;
            field.type_oid = cols[i].ctype.oid();
            field.value = self.values.get(i).copied().unwrap_or(Datum::Null);
        }
        let out = arena
            .alloc_slice_copy(&fields[..self.def.n_columns])
            .map_err(|_| too_large())?;
        Ok(Some(&*out))
    }

    fn col_type(&self, qualifier: Option<&str>, name: &str) -> Option<ColType> {
        if let Some(q) = qualifier
            && !crate::sql::eval::qualifier_answers_target(self.def, self.alias, q)
        {
            return None;
        }
        self.def
            .column_index(name)
            .map(|i| self.def.columns()[i].ctype)
    }

    fn collation(&self, qualifier: Option<&str>, name: &str) -> crate::sql::ast::Collation {
        if let Some(q) = qualifier
            && !crate::sql::eval::qualifier_answers_target(self.def, self.alias, q)
        {
            return crate::sql::ast::Collation::None;
        }
        self.def
            .column_index(name)
            .map(|index| self.def.columns()[index].collation)
            .unwrap_or(crate::sql::ast::Collation::None)
    }

    fn column_user_type(
        &self,
        qualifier: Option<&str>,
        name: &str,
    ) -> Option<crate::storage::UserTypeName> {
        if let Some(q) = qualifier
            && !crate::sql::eval::qualifier_answers_target(self.def, self.alias, q)
        {
            return None;
        }
        self.def
            .column_index(name)
            .and_then(|i| self.def.columns()[i].user_type)
    }
}

/// The output-only `OLD`/`NEW` namespace.  A missing image is still a typed
/// target row: PostgreSQL exposes each of its fields as NULL rather than
/// removing the namespace for an INSERT or DELETE result.
struct ReturningLookup<'d, 'v> {
    definition: crate::storage::RelationDefinition<'d>,
    target_alias: Option<&'d str>,
    current: &'v [Datum<'v>],
    old_name: &'d str,
    old: Option<&'v [Datum<'v>]>,
    new_name: &'d str,
    new: Option<&'v [Datum<'v>]>,
}

impl<'v> ReturningLookup<'_, 'v> {
    fn image(&self, qualifier: &str) -> Option<Option<&[Datum<'v>]>> {
        if qualifier == self.old_name {
            Some(self.old)
        } else if qualifier == self.new_name {
            Some(self.new)
        } else {
            None
        }
    }

    fn image_column(&self, image: Option<&[Datum<'v>]>, name: &str) -> Result<Datum<'v>, SqlError> {
        let index = self
            .definition
            .column_index(name)
            .ok_or_else(|| undefined_column(name))?;
        Ok(image.map_or(Datum::Null, |values| values[index]))
    }

    fn image_fields(
        &self,
        image: Option<&[Datum<'v>]>,
        arena: &'v Arena,
    ) -> Result<&'v [super::types::RecordField<'v>], SqlError> {
        let mut fields = [super::types::RecordField {
            name: "",
            type_oid: 0,
            type_mod: -1,
            value: Datum::Null,
        }; MAX_COLUMNS];
        for (index, field) in fields
            .iter_mut()
            .enumerate()
            .take(self.definition.n_columns)
        {
            let column = &self.definition.columns()[index];
            field.name = arena.alloc_str(column.name.as_str()).map_err(|_| {
                sql_err!(sqlstate::PROGRAM_LIMIT_EXCEEDED, "record exceeds the arena")
            })?;
            field.type_oid = column.ctype.oid();
            field.value = image.map_or(Datum::Null, |values| values[index]);
        }
        let fields = arena
            .alloc_slice_copy(&fields[..self.definition.n_columns])
            .map_err(|_| sql_err!(sqlstate::PROGRAM_LIMIT_EXCEEDED, "record exceeds the arena"))?;
        Ok(&*fields)
    }
}

impl<'v> ColumnLookup<'v> for ReturningLookup<'_, 'v> {
    fn whole_row_field_metadata(
        &self,
        table: &str,
        index: usize,
        catalog: Option<&dyn super::eval::CatalogAccess>,
    ) -> Option<(StackStr<64>, StaticTypeMeta)> {
        self.whole_row_type(table)?;
        super::eval::stored_row_field_metadata(self.definition.columns().get(index)?, catalog)
    }

    fn column_type_mod(&self, qualifier: Option<&str>, name: &str) -> i32 {
        let aliases = [self.old_name, self.new_name];
        describe::AliasedDefCols {
            definition: self.definition,
            alias: self.target_alias,
            output_aliases: &aliases,
        }
        .column_type_mod(qualifier, name)
    }

    fn whole_row_relation(&self, table: &str) -> Option<(&str, &str)> {
        self.whole_row_type(table)?;
        Some((
            self.definition.schema.as_str(),
            self.definition.name.as_str(),
        ))
    }
    fn whole_row_type(&self, table: &str) -> Option<ColType> {
        (self.image(table).is_some()
            || crate::sql::eval::qualifier_answers_target(
                self.definition,
                self.target_alias,
                table,
            ))
        .then_some(ColType::Record)
    }

    fn lookup(&self, qualifier: Option<&str>, name: &str) -> Result<Datum<'v>, SqlError> {
        if let Some(qualifier) = qualifier
            && let Some(image) = self.image(qualifier)
        {
            return self.image_column(image, name);
        }
        let context = RowCtx {
            def: self.definition,
            values: self.current,
            alias: self.target_alias,
        };
        context.lookup(qualifier, name)
    }

    fn whole_row_fields(
        &self,
        table: &str,
        arena: &'v Arena,
    ) -> Result<Option<&'v [super::types::RecordField<'v>]>, SqlError> {
        if let Some(image) = self.image(table) {
            return self.image_fields(image, arena).map(Some);
        }
        let context = RowCtx {
            def: self.definition,
            values: self.current,
            alias: self.target_alias,
        };
        context.whole_row_fields(table, arena)
    }

    fn col_type(&self, qualifier: Option<&str>, name: &str) -> Option<ColType> {
        if qualifier.is_some_and(|qualifier| self.image(qualifier).is_some()) {
            return self
                .definition
                .column_index(name)
                .map(|i| self.definition.columns()[i].ctype);
        }
        RowCtx {
            def: self.definition,
            values: self.current,
            alias: self.target_alias,
        }
        .col_type(qualifier, name)
    }

    fn collation(&self, qualifier: Option<&str>, name: &str) -> crate::sql::ast::Collation {
        if qualifier.is_some_and(|qualifier| self.image(qualifier).is_some()) {
            return self
                .definition
                .column_index(name)
                .map(|i| self.definition.columns()[i].collation)
                .unwrap_or(crate::sql::ast::Collation::None);
        }
        RowCtx {
            def: self.definition,
            values: self.current,
            alias: self.target_alias,
        }
        .collation(qualifier, name)
    }

    fn column_user_type(
        &self,
        qualifier: Option<&str>,
        name: &str,
    ) -> Option<crate::storage::UserTypeName> {
        if qualifier.is_some_and(|qualifier| self.image(qualifier).is_some()) {
            return self
                .definition
                .column_index(name)
                .and_then(|i| self.definition.columns()[i].user_type);
        }
        RowCtx {
            def: self.definition,
            values: self.current,
            alias: self.target_alias,
        }
        .column_user_type(qualifier, name)
    }
}

/// The FROM items' matched values for one `UPDATE ... FROM` or
/// `DELETE ... USING` row, in the order of `join`'s FROM items.
#[derive(Clone, Copy)]
struct JoinedReturningValues<'r, 'a> {
    table: crate::sql::ast::QualName<'a>,
    alias: Option<&'a str>,
    from: &'a crate::sql::ast::FromClause<'a>,
    values: &'r [Datum<'r>],
}

/// `RETURNING` of `UPDATE ... FROM` or `DELETE ... USING`: `old` and `new`
/// name the target's images; every other name resolves in the joined row of
/// the target and the FROM items, where an unqualified name present in two
/// of them is ambiguous.
struct JoinedReturningLookup<'r, 'd, 'v> {
    returning: &'r ReturningLookup<'d, 'v>,
    joined: &'r dyn ColumnLookup<'v>,
}

impl<'v> JoinedReturningLookup<'_, '_, 'v> {
    fn image(&self, qualifier: Option<&str>) -> bool {
        qualifier.is_some_and(|qualifier| self.returning.image(qualifier).is_some())
    }

    fn row(&self, qualifier: Option<&str>) -> &dyn ColumnLookup<'v> {
        if self.image(qualifier) {
            self.returning
        } else {
            self.joined
        }
    }
}

impl<'v> ColumnLookup<'v> for JoinedReturningLookup<'_, '_, 'v> {
    fn lookup(&self, qualifier: Option<&str>, name: &str) -> Result<Datum<'v>, SqlError> {
        self.row(qualifier).lookup(qualifier, name)
    }

    fn column_type_mod(&self, qualifier: Option<&str>, name: &str) -> i32 {
        self.row(qualifier).column_type_mod(qualifier, name)
    }

    fn resolve_column_type(
        &self,
        qualifier: Option<&str>,
        name: &str,
    ) -> Result<ColType, SqlError> {
        self.row(qualifier).resolve_column_type(qualifier, name)
    }

    fn is_empty_scope(&self) -> bool {
        false
    }

    fn whole_row_fields(
        &self,
        table: &str,
        arena: &'v Arena,
    ) -> Result<Option<&'v [super::types::RecordField<'v>]>, SqlError> {
        self.row(Some(table)).whole_row_fields(table, arena)
    }

    fn whole_row_field_metadata(
        &self,
        table: &str,
        index: usize,
        catalog: Option<&dyn super::eval::CatalogAccess>,
    ) -> Option<(StackStr<64>, StaticTypeMeta)> {
        self.row(Some(table))
            .whole_row_field_metadata(table, index, catalog)
    }

    fn whole_row_present(&self, table: &str) -> Result<bool, SqlError> {
        if self.image(Some(table)) {
            return Ok(true);
        }
        self.joined.whole_row_present(table)
    }

    fn col_type(&self, qualifier: Option<&str>, name: &str) -> Option<ColType> {
        self.row(qualifier).col_type(qualifier, name)
    }

    fn collation(&self, qualifier: Option<&str>, name: &str) -> crate::sql::ast::Collation {
        self.row(qualifier).collation(qualifier, name)
    }

    fn record_field_collation(&self, base: &Expr<'v>, field: &str) -> crate::sql::ast::Collation {
        self.joined.record_field_collation(base, field)
    }

    fn column_user_type(
        &self,
        qualifier: Option<&str>,
        name: &str,
    ) -> Option<crate::storage::UserTypeName> {
        self.row(qualifier).column_user_type(qualifier, name)
    }

    fn whole_row_is_scalar(&self, table: &str) -> bool {
        self.row(Some(table)).whole_row_is_scalar(table)
    }

    fn whole_row_type(&self, table: &str) -> Option<ColType> {
        self.row(Some(table)).whole_row_type(table)
    }
}

type Outcome = Result<Result<(), SqlError>, WireFull>;

fn sql_ok() -> Outcome {
    Ok(Ok(()))
}

fn sql_fail(e: SqlError) -> Outcome {
    Ok(Err(e))
}

use crate::sql::catalog::dependencies::ObjectAddress;

const DROPPED_NOTHING: ObjectAddress = ObjectAddress::new(0, 0, 0);

/// Whether a `DROP` may proceed to its dependency report: the object is no
/// extension member and the current role owns it. Otherwise the executor
/// reports PostgreSQL's error first.
fn may_drop(
    storage: &Storage,
    class: crate::storage::AccessClass,
    slot: usize,
    txid: u32,
    kind: &str,
) -> bool {
    let object = crate::storage::AccessObject {
        class,
        slot: slot as u16,
    };
    storage
        .require_not_extension_member(object, txid, kind)
        .is_ok()
        && storage.require_owner(object, txid, kind).is_ok()
}

/// What a relation name denotes, for PostgreSQL's wrong-kind `DROP` error.
#[derive(Clone, Copy, PartialEq, Eq)]
enum RelationKindName {
    Table,
    Sequence,
    View,
    MaterializedView,
    Index,
    Type,
    ForeignTable,
}

impl RelationKindName {
    fn noun(self) -> &'static str {
        match self {
            Self::Table => "table",
            Self::Sequence => "sequence",
            Self::View => "view",
            Self::MaterializedView => "materialized view",
            Self::Index => "index",
            Self::Type => "type",
            Self::ForeignTable => "foreign table",
        }
    }

    fn drop_hint(self) -> &'static str {
        match self {
            Self::Table => "Use DROP TABLE to remove a table.",
            Self::Sequence => "Use DROP SEQUENCE to remove a sequence.",
            Self::View => "Use DROP VIEW to remove a view.",
            Self::MaterializedView => "Use DROP MATERIALIZED VIEW to remove a materialized view.",
            Self::Index => "Use DROP INDEX to remove an index.",
            Self::Type => "Use DROP TYPE to remove a type.",
            Self::ForeignTable => "Use DROP FOREIGN TABLE to remove a foreign table.",
        }
    }

    /// The kind of relation `name` denotes, if any.
    fn of(storage: &Storage, name: &QualName, txid: u32) -> Option<Self> {
        match storage.resolve_relation(name.schema, name.name, txid) {
            Some(crate::storage::ResolvedRelation::Table(slot)) => {
                let definition = storage.table_def(slot, txid);
                return Some(
                    if storage
                        .matview_slot(definition.schema.as_str(), definition.name.as_str(), txid)
                        .is_some()
                    {
                        Self::MaterializedView
                    } else if definition.kind == crate::storage::TableKind::Foreign {
                        Self::ForeignTable
                    } else {
                        Self::Table
                    },
                );
            }
            Some(crate::storage::ResolvedRelation::View(_)) => return Some(Self::View),
            Some(crate::storage::ResolvedRelation::Catalog) | None => {}
        }
        if storage
            .sequence_on_path(name.schema, name.name, txid)
            .is_some()
        {
            Some(Self::Sequence)
        } else if storage
            .resolve_index_slot(name.schema, name.name, txid)
            .is_some()
        {
            Some(Self::Index)
        } else if match name.schema {
            Some(schema) => storage.composite_slot(schema, name.name, txid),
            None => storage.resolve_composite_slot(name.name, txid),
        }
        .is_some()
        {
            Some(Self::Type)
        } else {
            None
        }
    }

    /// PostgreSQL's `DropErrorMsgWrongType` when `name` is a relation of
    /// another kind than the `DROP` names; `IF EXISTS` does not suppress it.
    fn wrong_kind(
        storage: &Storage,
        name: &QualName,
        txid: u32,
        expected: Self,
    ) -> Option<SqlError> {
        let actual = Self::of(storage, name, txid).filter(|actual| *actual != expected)?;
        crate::sql::eval::stash_diagnostic(
            None,
            Some(crate::util::StackStr::from_str(actual.drop_hint())),
        );
        Some(sql_err!(
            sqlstate::WRONG_OBJECT_TYPE,
            "\"{}\" is not a {}",
            name.name,
            expected.noun()
        ))
    }
}

/// Runs a `DROP`'s executors after its dependency report: a failed report
/// fails the statement, and a sent one covers the executors' own notices.
fn run_reported_drop<'b>(
    report: Result<Option<crate::pg::respond::DependencyReport>, SqlError>,
    responder: &mut Responder<'b>,
    drop: impl FnOnce(&mut Responder<'b>) -> Outcome,
) -> Outcome {
    match report {
        Err(error) => sql_fail(error),
        Ok(Some(filter)) => responder.with_dependency_report(filter, drop),
        Ok(None) => drop(responder),
    }
}

