#[derive(Clone, Copy)]
struct OwnedSequencePlan {
    schema: SqlName,
    name: SqlName,
    spec: SeqSpec,
    identity: bool,
    explicit_name: bool,
    owner: crate::storage::SequenceOwner,
}

#[derive(Clone, Copy)]
struct IdentitySequenceAlteration {
    slot: usize,
    spec: SeqSpec,
    restart: Option<i64>,
}

fn plan_identity_sequence_alteration(
    alterations: &mut [Option<IdentitySequenceAlteration>; MAX_COLUMNS],
    n_alterations: &mut usize,
    slot: usize,
    options: &crate::sql::ast::SeqOptions,
    base: SeqSpec,
) -> Result<(), SqlError> {
    let existing = alterations[..*n_alterations]
        .iter()
        .position(|alteration| alteration.is_some_and(|alteration| alteration.slot == slot));
    let prior = existing.map_or(base, |index| {
        alterations[index]
            .expect("identity sequence alteration is present")
            .spec
    });
    let (spec, restart) = resolve_seq_spec(options, Some(prior))?;
    if let Some(index) = existing {
        let alteration = alterations[index]
            .as_mut()
            .expect("identity sequence alteration");
        alteration.spec = spec;
        if options.restart.is_some() {
            alteration.restart = restart;
        }
    } else {
        alterations[*n_alterations] = Some(IdentitySequenceAlteration {
            slot,
            spec,
            restart,
        });
        *n_alterations += 1;
    }
    Ok(())
}

fn default_owned_sequence_name(table: &str, column: &str) -> Result<SqlName, SqlError> {
    crate::storage::constraint_names::generated(table, Some(column), "seq")
}

fn available_owned_sequence_name(
    storage: &Storage,
    owner: crate::storage::SequenceOwner,
    transaction: u32,
) -> Result<SqlName, SqlError> {
    use core::fmt::Write;
    let bound = storage
        .table_count()
        .saturating_add(storage.view_count())
        .saturating_add(storage.sequence_count())
        .saturating_add(storage.index_count())
        .saturating_add(storage.composite_count());
    for suffix in 0..=bound {
        let mut label = StackStr::<32>::from_str("seq");
        if suffix != 0 {
            write!(label, "{suffix}").expect("catalog-count suffix fits");
        }
        let name = crate::storage::constraint_names::generated(
            owner.table.as_str(),
            Some(owner.column.as_str()),
            label.as_str(),
        )?;
        if !storage.relation_name_taken(owner.table_schema.as_str(), name.as_str(), transaction) {
            return Ok(name);
        }
    }
    Err(sql_err!(
        sqlstate::PROGRAM_LIMIT_EXCEEDED,
        "generated sequence names exhausted"
    ))
}

fn owned_sequence_plan<Definition0: crate::storage::DefinitionBacking>(
    def: &crate::storage::TableDefinition<Definition0>,
    column_index: usize,
    identity: Option<crate::sql::ast::IdentitySpec<'_>>,
) -> Result<OwnedSequencePlan, SqlError> {
    let column = def.columns()[column_index];
    let mut options = identity.map_or(crate::sql::ast::SeqOptions::EMPTY, |i| i.options);
    options.data_type = Some(match column.ctype {
        ColType::Int2 => "smallint",
        ColType::Int8 => "bigint",
        _ => "integer",
    });
    options.owned_by = None;
    let (spec, _) = resolve_seq_spec(&options, None)?;
    let (schema, name) = match identity.and_then(|i| i.sequence_name) {
        Some(name) => {
            if let Some(schema) = name.schema
                && schema != def.schema.as_str()
            {
                return Err(sql_err!(
                    sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                    "sequence must be in same schema as table it is linked to"
                ));
            }
            (def.schema, SqlName::parse(name.name)?)
        }
        None => (
            def.schema,
            default_owned_sequence_name(def.name.as_str(), column.name.as_str())?,
        ),
    };
    Ok(OwnedSequencePlan {
        schema,
        name,
        spec,
        identity: column.is_identity,
        explicit_name: identity
            .and_then(|identity| identity.sequence_name)
            .is_some(),
        owner: crate::storage::SequenceOwner {
            table_schema: def.schema,
            table: def.name,
            column: column.name,
        },
    })
}

fn like_identity_sequence_plan(
    storage: &Storage,
    definition: &TableDefBuilder,
    column: usize,
    statement: &CreateTable,
    txid: u32,
) -> Result<OwnedSequencePlan, SqlError> {
    for like in statement.likes.iter().filter(|like| like.identity) {
        let source = like_source(storage, like, txid)?;
        let Some(source_column) = source.column_index(definition.columns()[column].name.as_str())
        else {
            continue;
        };
        if !source.columns()[source_column].is_identity {
            continue;
        }
        let sequence = storage
            .generated_sequence_slot(
                source.schema.as_str(),
                source.name.as_str(),
                source.columns()[source_column].name.as_str(),
                crate::storage::GeneratedSequenceScope::PartitionRoot,
                txid,
            )
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                    "identity column \"{}\" has no generator sequence",
                    source.columns()[source_column].name.as_str()
                )
            })?;
        let sequence = storage.sequence_for(sequence, txid);
        let mut plan = owned_sequence_plan(definition, column, None)?;
        plan.spec = SeqSpec {
            data_type: sequence.data_type,
            increment: sequence.increment,
            min_value: sequence.min_value,
            max_value: sequence.max_value,
            start_value: sequence.start_value,
            cache: sequence.cache,
            cycle: sequence.cycle,
        };
        return Ok(plan);
    }
    Err(sql_err!(
        sqlstate::INTERNAL_ERROR,
        "copied identity column has no LIKE source"
    ))
}

fn sequence_column_default(
    storage: &Storage,
    sequence: usize,
) -> Result<crate::storage::ColumnDefault, SqlError> {
    use core::fmt::Write;
    let mut expression = StackStr::new();
    let _ = write!(
        expression,
        "\"pg_catalog\".nextval('{}'::pg_catalog.regclass)",
        crate::sql::catalog::sequence_oid(storage, sequence)
    );
    if expression.is_truncated() {
        return Err(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "sequence default is too long"
        ));
    }
    Ok(crate::storage::ColumnDefault::Expression(expression))
}

fn create_owned_sequence(
    storage: &mut Storage,
    wal: &mut Wal,
    mut plan: OwnedSequencePlan,
    persistence: crate::storage::RelationPersistence,
    txid: u32,
) -> Result<crate::storage::SequenceChange, SqlError> {
    if !plan.explicit_name {
        plan.name = available_owned_sequence_name(storage, plan.owner, txid)?;
    }
    if storage.relation_name_taken(plan.schema.as_str(), plan.name.as_str(), txid) {
        return Err(sql_err!(
            sqlstate::DUPLICATE_TABLE,
            "relation \"{}\" already exists",
            plan.name.as_str()
        ));
    }
    let slot = storage.create_sequence(
        crate::storage::SequenceCreateSpec {
            allocation: crate::storage::CatalogAllocation::New,
            schema: plan.schema,
            name: plan.name,
            spec: plan.spec,
            owner: Some(plan.owner),
            generator_for: plan.identity.then_some(plan.owner),
            persistence,
        },
        txid,
    )?;
    let wal_result = if persistence == crate::storage::RelationPersistence::Temporary {
        Ok(())
    } else {
        let lsn = storage.bump_lsn();
        wal.stage_reserved(
            txid,
            lsn,
            &WalOp::CreateSequence {
                restart: None,
                identity: storage.sequence_position(slot.slot()),
                schema: plan.schema.as_str(),
                name: plan.name.as_str(),
                data_type: plan.spec.data_type,
                increment: plan.spec.increment,
                min_value: plan.spec.min_value,
                max_value: plan.spec.max_value,
                start_value: plan.spec.start_value,
                cache: plan.spec.cache,
                cycle: plan.spec.cycle,
                owner: Some(plan.owner),
                generator_for: plan.identity.then_some(plan.owner),
                persistence,
            },
        )
    };
    if let Err(error) = wal_result {
        storage.finish_sequence_change(slot, crate::storage::CatalogDdlDecision::Rollback);
        return Err(error);
    }
    Ok(slot)
}

fn ensure_temporary_namespace(
    storage: &Storage,
    txn: &mut TxnState,
    persistence: crate::storage::RelationPersistence,
) -> Result<(), SqlError> {
    if persistence == crate::storage::RelationPersistence::Temporary
        && let Some(identity) = storage.create_temporary_namespace(txn.txid)?
        && let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::TemporaryNamespaceCreated(identity),
        )
    {
        storage.finish_temporary_namespace(
            identity,
            txn.txid,
            crate::storage::CatalogDdlDecision::Rollback,
        );
        return Err(error);
    }
    Ok(())
}

pub fn create_table(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    statement: &CreateTable,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    create_table_kind(storage, wal, txn, statement, None, arena, responder)
}

#[derive(Clone, Copy)]
struct ForeignTableCreation {
    server: u16,
    options: crate::storage::foreign::ForeignOptions,
    column_options: crate::storage::foreign::ForeignColumnOptions,
}

fn create_table_kind(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    statement: &CreateTable,
    foreign: Option<ForeignTableCreation>,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    let tag = if foreign.is_some() {
        "CREATE FOREIGN TABLE"
    } else {
        "CREATE TABLE"
    };
    if foreign.is_some() && statement.persistence != crate::sql::ast::RelationPersistence::Permanent
    {
        return sql_fail(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "foreign tables cannot be temporary or unlogged"
        ));
    }
    if statement.persistence == crate::sql::ast::RelationPersistence::Unlogged
        && matches!(
            statement.partition,
            crate::sql::ast::PartitionClause::By { .. }
        )
    {
        return sql_fail(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "partitioned tables cannot be unlogged"
        ));
    }
    if statement.persistence != crate::sql::ast::RelationPersistence::Temporary
        && statement.on_commit != crate::sql::ast::OnCommitAction::PreserveRows
    {
        return sql_fail(sql_err!(
            sqlstate::INVALID_TABLE_DEFINITION,
            "ON COMMIT can only be used on temporary tables"
        ));
    }
    let mut def = match build_partitioned_table_def(storage, statement, txn.txid, arena) {
        Ok(d) => d,
        Err(e) => return sql_fail(e),
    };
    if let Err(error) = notify_inherited_column_merges(storage, statement, txn.txid, responder)? {
        return sql_fail(error);
    }
    if let Err(error) = capture_created_table_inputs(storage, &mut def, statement, txn.txid, arena)
    {
        return sql_fail(error);
    }
    def.persistence = statement.persistence.into();
    def.on_commit = statement.on_commit.into();
    def.schema = match if statement.persistence == crate::sql::ast::RelationPersistence::Temporary {
        if statement
            .name
            .schema
            .is_some_and(|schema| schema != "pg_temp")
        {
            Err(sql_err!(
                sqlstate::INVALID_TABLE_DEFINITION,
                "temporary tables cannot specify a schema name"
            ))
        } else {
            storage
                .require_temporary_privilege(txn.txid)
                .and_then(|()| storage.temporary_schema())
        }
    } else {
        storage.creation_schema(
            statement.name.schema,
            statement.name.name,
            txn.txid,
            crate::storage::SchemaObjectKind::Relation,
        )
    } {
        Ok(n) => n,
        Err(e) => return sql_fail(e),
    };
    if let Err(error) = ensure_temporary_namespace(storage, txn, def.persistence) {
        return sql_fail(error);
    }
    def.kind = if foreign.is_some() {
        crate::storage::TableKind::Foreign
    } else {
        crate::storage::TableKind::Local
    };
    def.access_method = match statement.access_method {
        crate::sql::ast::TableAccessMethod::Heap => crate::storage::TableAccessMethod::Heap,
        crate::sql::ast::TableAccessMethod::Named(name) => {
            match storage.table_access_method(name, txn.txid) {
                Some(method) => method,
                None => {
                    return sql_fail(sql_err!(
                        sqlstate::UNDEFINED_OBJECT,
                        "access method \"{}\" does not exist",
                        name
                    ));
                }
            }
        }
    };
    def.storage_options = crate::storage::TableStorageOptions {
        fillfactor: statement.storage_options.fillfactor,
    };
    def.tablespace = match resolve_relation_tablespace(storage, statement.tablespace, txn.txid) {
        Ok(tablespace) => tablespace,
        Err(error) => return sql_fail(error),
    };
    // A copied constraint lands before the explicitly written ones, so a
    // duplicate primary key is caught with PostgreSQL's own message.
    if let Err(e) = copy_like_constraints(storage, &mut def, statement, txn.txid, arena) {
        return sql_fail(e);
    }
    if let Err(e) = reject_multiple_primary(&def) {
        return sql_fail(e);
    }
    if let Err(e) = attach_constraints(
        storage,
        &mut def,
        statement.constraints,
        true,
        txn.txid,
        None,
        arena,
    ) {
        return sql_fail(e);
    }
    if let Err(e) = validate_partitioned_unique_keys(&def) {
        return sql_fail(e);
    }
    let creates_owned_sequences = !matches!(statement.partition, PartitionClause::Of { .. });
    let sequence_count = if creates_owned_sequences {
        def.columns()
            .iter()
            .filter(|column| column.auto_increment)
            .count()
    } else {
        0
    };
    let sequence_plans = match arena.alloc_slice_with(sequence_count, |_| None) {
        Ok(plans) => plans,
        Err(_) => return sql_fail(arena_full()),
    };
    if creates_owned_sequences {
        for (destination, (column, metadata)) in sequence_plans.iter_mut().zip(
            def.columns()
                .iter()
                .enumerate()
                .filter(|(_, metadata)| metadata.auto_increment),
        ) {
            let plan = match statement
                .columns
                .iter()
                .find(|parsed| parsed.name == metadata.name.as_str())
            {
                Some(parsed) => owned_sequence_plan(&def, column, parsed.identity),
                None => like_identity_sequence_plan(storage, &def, column, statement, txn.txid),
            };
            *destination = Some(match plan {
                Ok(plan) => plan,
                Err(error) => return sql_fail(error),
            });
        }
    }
    if statement.if_not_exists
        && storage.relation_name_taken(def.schema.as_str(), def.name.as_str(), txn.txid)
    {
        responder.notice(
            sqlstate::DUPLICATE_TABLE,
            stack_format!(
                128,
                "relation \"{}\" already exists, skipping",
                statement.name.name
            )
            .as_str(),
        )?;
        responder.command_complete(tag)?;
        return sql_ok();
    }
    for plan in sequence_plans.iter().flatten() {
        let sequence_slot =
            match create_owned_sequence(storage, wal, *plan, def.persistence, txn.txid) {
                Ok(sequence_slot) => sequence_slot,
                Err(error) => return sql_fail(error),
            };
        if let Err(error) = txn.record_sequence_change(storage, sequence_slot) {
            return sql_fail(error);
        }
        if let Err(error) = apply_default_privileges_to_new_object(
            storage,
            txn,
            crate::storage::AccessObject {
                class: crate::storage::AccessClass::Sequence,
                slot: sequence_slot.slot() as u16,
            },
        ) {
            return sql_fail(error);
        }
        let column = def
            .column_index(plan.owner.column.as_str())
            .expect("sequence plan names its column");
        if !def.columns[column].is_identity {
            def.columns[column].default =
                match sequence_column_default(storage, sequence_slot.slot()) {
                    Ok(default) => default,
                    Err(error) => return sql_fail(error),
                };
            def.columns[column].auto_increment = false;
        }
    }
    let created_slot = match storage.create_table_in(def.clone(), txn.txid) {
        Ok(slot) => {
            let foreign_slot = if let Some(foreign) = foreign {
                match storage.create_foreign_table_binding(
                    crate::storage::foreign::ForeignTableDefinition {
                        table: slot as u16,
                        server: foreign.server,
                        options: foreign.options,
                        column_options: foreign.column_options,
                    },
                    txn.txid,
                ) {
                    Ok(binding) => Some(binding),
                    Err(error) => {
                        storage.rollback_create(slot);
                        return sql_fail(error);
                    }
                }
            } else {
                None
            };
            let wal_result = if def.persistence == crate::storage::RelationPersistence::Temporary {
                Ok(())
            } else {
                let lsn = storage.bump_lsn();
                wal.stage_reserved(
                    txn.txid,
                    lsn,
                    &WalOp::CreateTable {
                        identity: storage.table_position(slot),
                        definition: (&(*storage.table_def(slot, txn.txid)).clone()).into(),
                    },
                )
            };
            if let Err(e) = wal_result {
                // Nothing reached the journal; undo the in-memory apply.
                if let Some(binding) = foreign_slot {
                    storage.foreign_catalog_rollback_create(
                        crate::storage::foreign::ForeignObjectClass::Table,
                        binding,
                    );
                }
                storage.rollback_create(slot);
                return sql_fail(e);
            }
            if let Err(e) = txn.record_ddl(storage, super::txn::DdlUndo::Created(slot as u32)) {
                if let Some(binding) = foreign_slot {
                    storage.foreign_catalog_rollback_create(
                        crate::storage::foreign::ForeignObjectClass::Table,
                        binding,
                    );
                }
                storage.rollback_create(slot);
                return sql_fail(e);
            }
            if let Some(binding) = foreign_slot
                && let Err(error) = txn.record_ddl(
                    storage,
                    super::txn::DdlUndo::ForeignTableCreated(binding as u32),
                )
            {
                storage.foreign_catalog_rollback_create(
                    crate::storage::foreign::ForeignObjectClass::Table,
                    binding,
                );
                return sql_fail(error);
            }
            if let Err(error) = apply_default_privileges_to_new_object(
                storage,
                txn,
                crate::storage::AccessObject {
                    class: crate::storage::AccessClass::Table,
                    slot: slot as u16,
                },
            ) {
                return sql_fail(error);
            }
            slot
        }
        Err(e) if e.sqlstate == sqlstate::DUPLICATE_TABLE && statement.if_not_exists => {
            responder.notice(
                crate::sql::eval::sqlstate::DUPLICATE_TABLE,
                stack_format!(
                    128,
                    "relation \"{}\" already exists, skipping",
                    statement.name.name
                )
                .as_str(),
            )?;
            responder.command_complete(tag)?;
            return sql_ok();
        }
        Err(e) => return sql_fail(e),
    };
    def = TableDefBuilder::from_definition(&storage.table_def(created_slot, txn.txid));
    if let Some(attachment) = def.partition.attachment
        && let Err(error) = ensure_partition_indexes(
            storage,
            wal,
            txn,
            usize::from(attachment.parent),
            created_slot,
            PartitionJoin::Create,
            arena,
        )
    {
        return sql_fail(error);
    }
    if foreign.is_none()
        && let Err(e) =
            copy_like_statistics(storage, wal, txn, statement, &def, created_slot, arena)
    {
        return sql_fail(e);
    }
    if foreign.is_none()
        && let Err(e) = copy_like_indexes(storage, wal, txn, statement, &def, arena)
    {
        return sql_fail(e);
    }
    if foreign.is_none()
        && let Err(e) = copy_like_comments(storage, wal, txn, statement, &def, created_slot)
    {
        return sql_fail(e);
    }
    responder.command_complete(tag)?;
    sql_ok()
}

pub fn create_foreign_table(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    statement: &super::ast::CreateForeignTable<'_>,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    if !statement.relation.likes.is_empty() {
        return sql_fail(sql_err!(
            sqlstate::SYNTAX_ERROR,
            "LIKE is not allowed in CREATE FOREIGN TABLE"
        ));
    }
    // PostgreSQL rejects these while transforming the statement, before it
    // resolves the server or any column type. The parser keeps every key
    // written on a foreign table's column in `constraints`.
    for constraint in statement.relation.constraints {
        if let Err(error) = ddl::reject_foreign_table_constraint(constraint) {
            return sql_fail(error);
        }
    }
    let Some((server, server_definition)) = storage.foreign_server(statement.server, txn.txid)
    else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "server \"{}\" does not exist",
            statement.server
        ));
    };
    let Some(current) = storage.current_role_slot(txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "current role does not exist"
        ));
    };
    if !storage.has_object_privilege(
        crate::storage::AccessObject {
            class: crate::storage::AccessClass::ForeignServer,
            slot: server as u16,
        },
        current,
        crate::storage::PrivilegeSet::USAGE,
        txn.txid,
    ) {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied for server {}",
            statement.server
        ));
    }
    let options = match crate::storage::foreign::ForeignOptions::parse(statement.options) {
        Ok(options) => options,
        Err(error) => return sql_fail(error),
    };
    let wrapper = storage.foreign_wrapper_by_slot(server_definition.wrapper as usize, txn.txid);
    if wrapper.is_some_and(|wrapper| {
        wrapper.validator == crate::storage::foreign::ForeignDataValidator::Postgres
    }) && let Err(error) =
        validate_postgres_foreign_options(&options, PostgresForeignOptionContext::Table)
    {
        return sql_fail(error);
    }
    let mut column_options = crate::storage::foreign::ForeignColumnOptions::EMPTY;
    for (column, definition) in statement.relation.columns.iter().enumerate() {
        let options =
            match crate::storage::foreign::ForeignOptions::parse(definition.foreign_options) {
                Ok(options) => options,
                Err(error) => return sql_fail(error),
            };
        if let Err(error) = column_options.append(column as u16, options) {
            return sql_fail(error);
        }
        if wrapper.is_some_and(|wrapper| {
            wrapper.validator == crate::storage::foreign::ForeignDataValidator::Postgres
        }) && let Err(error) =
            validate_postgres_foreign_options(&options, PostgresForeignOptionContext::Column)
        {
            return sql_fail(error);
        }
    }
    create_table_kind(
        storage,
        wal,
        txn,
        &statement.relation,
        Some(ForeignTableCreation {
            server: server as u16,
            options,
            column_options,
        }),
        arena,
        responder,
    )
}

#[derive(Clone, Copy)]
enum PostgresForeignOptionContext {
    Wrapper,
    Server,
    Mapping,
    Table,
    Column,
    Import,
}

fn validate_positive_foreign_integer(value: &str, name: &str) -> Result<(), SqlError> {
    if value.parse::<u32>().is_ok_and(|value| value != 0) {
        Ok(())
    } else {
        Err(sql_err!(
            sqlstate::FDW_INVALID_ATTRIBUTE_VALUE,
            "invalid value for integer option \"{}\": \"{}\"",
            name,
            value
        ))
    }
}

fn validate_postgres_foreign_option_value(name: &str, value: &str) -> Result<(), SqlError> {
    match name {
        "port" => {
            if value.parse::<u16>().is_ok_and(|value| value != 0) {
                Ok(())
            } else {
                Err(sql_err!(
                    sqlstate::FDW_INVALID_ATTRIBUTE_VALUE,
                    "invalid value for integer option \"port\": \"{}\"",
                    value
                ))
            }
        }
        "connect_timeout" | "fetch_size" | "batch_size" => {
            validate_positive_foreign_integer(value, name)
        }
        "sslmode" if matches!(value, "disable" | "prefer" | "require") => Ok(()),
        "sslmode" => Err(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "foreign sslmode \"{}\" is not supported",
            value
        )),
        "updatable" | "truncatable" | "import_collate" | "import_default" | "import_generated"
        | "import_not_null" => super::eval::parse_bool(value).map(|_| ()),
        "host" | "hostaddr" => value.parse::<std::net::IpAddr>().map(|_| ()).map_err(|_| {
            sql_err!(
                sqlstate::FEATURE_NOT_SUPPORTED,
                "foreign PostgreSQL hosts must be numeric IP addresses"
            )
        }),
        _ => Ok(()),
    }
}

fn validate_postgres_foreign_options(
    options: &crate::storage::foreign::ForeignOptions,
    context: PostgresForeignOptionContext,
) -> Result<(), SqlError> {
    for option in options.entries() {
        let name = option.name.as_str();
        let accepted = match context {
            PostgresForeignOptionContext::Wrapper => false,
            PostgresForeignOptionContext::Server => matches!(
                name,
                "host"
                    | "hostaddr"
                    | "port"
                    | "dbname"
                    | "connect_timeout"
                    | "application_name"
                    | "sslmode"
                    | "updatable"
                    | "truncatable"
            ),
            PostgresForeignOptionContext::Mapping => matches!(name, "user" | "password"),
            PostgresForeignOptionContext::Table => matches!(
                name,
                "schema_name" | "table_name" | "updatable" | "truncatable"
            ),
            PostgresForeignOptionContext::Column => name == "column_name",
            PostgresForeignOptionContext::Import => matches!(
                name,
                "import_collate" | "import_default" | "import_generated" | "import_not_null"
            ),
        };
        if !accepted {
            return Err(sql_err!(
                sqlstate::FDW_INVALID_OPTION_NAME,
                "invalid option \"{}\"",
                name
            ));
        }
        validate_postgres_foreign_option_value(name, option.value.as_str())?;
    }
    Ok(())
}

pub fn import_foreign_schema(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    command: &super::ast::ImportForeignSchema<'_>,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    let Some((server_slot, server)) = storage.foreign_server(command.server, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "server \"{}\" does not exist",
            command.server
        ));
    };
    let Some(current) = storage.current_role_slot(txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "current role does not exist"
        ));
    };
    if !storage.has_object_privilege(
        crate::storage::AccessObject {
            class: crate::storage::AccessClass::ForeignServer,
            slot: server_slot as u16,
        },
        current,
        crate::storage::PrivilegeSet::USAGE,
        txn.txid,
    ) {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied for server {}",
            command.server
        ));
    }
    let Some(wrapper) = storage.foreign_wrapper_by_slot(server.wrapper as usize, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "foreign-data wrapper for server does not exist"
        ));
    };
    if let Err(error) = wrapper.require_handler() {
        return sql_fail(error);
    }
    let options = match crate::storage::foreign::ForeignOptions::parse(command.options) {
        Ok(options) => options,
        Err(error) => return sql_fail(error),
    };
    if let Err(error) =
        validate_postgres_foreign_options(&options, PostgresForeignOptionContext::Import)
    {
        return sql_fail(error);
    }
    let commands = match super::foreign::import_commands(storage, command, txn.txid, arena) {
        Ok(commands) => commands,
        Err(error) => return sql_fail(error),
    };
    for imported in commands {
        let mut parser = match super::parser::Parser::new(imported.sql, arena) {
            Ok(parser) => parser,
            Err(error) => return sql_fail(super::parse_error_to_sql(&error)),
        };
        let statement = match parser.next_stmt() {
            Ok(Some(Stmt::CreateForeignTable(statement))) => statement,
            Ok(_) => {
                return sql_fail(sql_err!(
                    sqlstate::PROTOCOL_VIOLATION,
                    "foreign import did not produce one foreign-table definition"
                ));
            }
            Err(error) => return sql_fail(super::parse_error_to_sql(&error)),
        };
        let outcome = responder.without_command_complete(|responder| {
            create_foreign_table(storage, wal, txn, &statement, arena, responder)
        })?;
        if let Err(error) = outcome {
            return Ok(Err(error));
        }
    }
    responder.command_complete("IMPORT FOREIGN SCHEMA")?;
    sql_ok()
}

fn resolve_foreign_handler(
    handler: super::ast::ForeignDataHandler<'_>,
) -> Result<crate::storage::foreign::ForeignDataHandler, SqlError> {
    match handler {
        super::ast::ForeignDataHandler::None => {
            Ok(crate::storage::foreign::ForeignDataHandler::None)
        }
        super::ast::ForeignDataHandler::Function(name)
            if name.name.eq_ignore_ascii_case("postgres_fdw_handler") =>
        {
            Ok(crate::storage::foreign::ForeignDataHandler::Postgres)
        }
        super::ast::ForeignDataHandler::Function(name) => Err(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "native foreign-data handler {} is not supported",
            name.name
        )),
    }
}

fn resolve_foreign_validator(
    validator: super::ast::ForeignDataValidator<'_>,
) -> Result<crate::storage::foreign::ForeignDataValidator, SqlError> {
    match validator {
        super::ast::ForeignDataValidator::None => {
            Ok(crate::storage::foreign::ForeignDataValidator::None)
        }
        super::ast::ForeignDataValidator::Function(name)
            if name.name.eq_ignore_ascii_case("postgres_fdw_validator") =>
        {
            Ok(crate::storage::foreign::ForeignDataValidator::Postgres)
        }
        super::ast::ForeignDataValidator::Function(name) => Err(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "native foreign-data validator {} is not supported",
            name.name
        )),
    }
}

fn bounded_foreign_value(
    value: Option<&str>,
    what: &'static str,
) -> Result<Option<StackStr<{ crate::storage::foreign::FOREIGN_OPTION_VALUE_MAX }>>, SqlError> {
    let Some(value) = value else {
        return Ok(None);
    };
    let parsed = StackStr::from_str(value);
    if parsed.is_truncated() {
        return Err(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "{} exceeds {} bytes",
            what,
            crate::storage::foreign::FOREIGN_OPTION_VALUE_MAX
        ));
    }
    Ok(Some(parsed))
}

pub fn create_foreign_data_wrapper(
    storage: &mut Storage,
    _wal: &mut Wal,
    txn: &mut TxnState,
    command: &super::ast::CreateForeignDataWrapper<'_>,
    responder: &mut Responder,
) -> Outcome {
    let Some(current) = storage.current_role_slot(txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "current role does not exist"
        ));
    };
    if !storage.role(current).attributes_to(txn.txid).superuser {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied to create foreign-data wrapper"
        ));
    }
    let handler = match resolve_foreign_handler(command.handler) {
        Ok(handler) => handler,
        Err(error) => return sql_fail(error),
    };
    let validator = match resolve_foreign_validator(command.validator) {
        Ok(validator) => validator,
        Err(error) => return sql_fail(error),
    };
    let options = match crate::storage::foreign::ForeignOptions::parse(command.options) {
        Ok(options) => options,
        Err(error) => return sql_fail(error),
    };
    if validator == crate::storage::foreign::ForeignDataValidator::Postgres
        && let Err(error) =
            validate_postgres_foreign_options(&options, PostgresForeignOptionContext::Wrapper)
    {
        return sql_fail(error);
    }
    let definition = crate::storage::foreign::ForeignDataWrapperDefinition {
        name: match SqlName::parse(command.name) {
            Ok(name) => name,
            Err(error) => return sql_fail(error),
        },
        handler,
        validator,
        options,
    };
    let slot = match storage.create_foreign_wrapper(definition, txn.txid) {
        Ok(slot) => slot,
        Err(error) => return sql_fail(error),
    };
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::ForeignDataWrapperCreated(slot as u32),
    ) {
        storage.foreign_catalog_rollback_create(
            crate::storage::foreign::ForeignObjectClass::Wrapper,
            slot,
        );
        return sql_fail(error);
    }
    responder.command_complete("CREATE FOREIGN DATA WRAPPER")?;
    sql_ok()
}

pub fn create_foreign_server(
    storage: &mut Storage,
    _wal: &mut Wal,
    txn: &mut TxnState,
    command: &super::ast::CreateForeignServer<'_>,
    responder: &mut Responder,
) -> Outcome {
    let Some((wrapper_slot, wrapper)) = storage.foreign_wrapper(command.wrapper, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "foreign-data wrapper \"{}\" does not exist",
            command.wrapper
        ));
    };
    let Some(current) = storage.current_role_slot(txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "current role does not exist"
        ));
    };
    if !storage.has_object_privilege(
        crate::storage::AccessObject {
            class: crate::storage::AccessClass::ForeignDataWrapper,
            slot: wrapper_slot as u16,
        },
        current,
        crate::storage::PrivilegeSet::USAGE,
        txn.txid,
    ) {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied for foreign-data wrapper {}",
            command.wrapper
        ));
    }
    let options = match crate::storage::foreign::ForeignOptions::parse(command.options) {
        Ok(options) => options,
        Err(error) => return sql_fail(error),
    };
    if wrapper.validator == crate::storage::foreign::ForeignDataValidator::Postgres
        && let Err(error) =
            validate_postgres_foreign_options(&options, PostgresForeignOptionContext::Server)
    {
        return sql_fail(error);
    }
    let definition = crate::storage::foreign::ForeignServerDefinition {
        name: match SqlName::parse(command.name) {
            Ok(name) => name,
            Err(error) => return sql_fail(error),
        },
        wrapper: wrapper_slot as u16,
        server_type: match bounded_foreign_value(command.server_type, "foreign server type") {
            Ok(value) => value,
            Err(error) => return sql_fail(error),
        },
        version: match bounded_foreign_value(command.version, "foreign server version") {
            Ok(value) => value,
            Err(error) => return sql_fail(error),
        },
        options,
    };
    let slot = match storage.create_foreign_server(definition, txn.txid) {
        Ok(slot) => slot,
        Err(error) if command.if_not_exists && error.sqlstate == sqlstate::DUPLICATE_OBJECT => {
            responder.notice(
                sqlstate::DUPLICATE_OBJECT,
                stack_format!(128, "server \"{}\" already exists, skipping", command.name).as_str(),
            )?;
            responder.command_complete("CREATE SERVER")?;
            return sql_ok();
        }
        Err(error) => return sql_fail(error),
    };
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::ForeignServerCreated(slot as u32),
    ) {
        storage.foreign_catalog_rollback_create(
            crate::storage::foreign::ForeignObjectClass::Server,
            slot,
        );
        return sql_fail(error);
    }
    responder.command_complete("CREATE SERVER")?;
    sql_ok()
}

/// `format_type_be` of a type OID, without the statement arena.
fn type_display_fixed(
    storage: &Storage,
    txid: u32,
    type_oid: i32,
) -> Result<StackStr<260>, SqlError> {
    super::catalog::user_type_name_fixed(storage, txid, type_oid)?
        .or_else(|| describe::builtin_type_name_fixed(type_oid))
        .ok_or_else(|| sql_err!(sqlstate::INTERNAL_ERROR, "type {} has no name", type_oid))
}

/// PostgreSQL's `cast from type X to type Y does not exist`.
fn missing_cast_message(
    storage: &Storage,
    txid: u32,
    source: crate::storage::RoutineResult,
    target: crate::storage::RoutineResult,
) -> Result<StackStr<600>, SqlError> {
    let name = |result: crate::storage::RoutineResult| {
        let oid = storage
            .routine_type_oid(result.ctype, result.user_type, txid)
            .ok_or_else(|| sql_err!(sqlstate::INTERNAL_ERROR, "cast type has no identity"))?;
        type_display_fixed(storage, txid, oid)
    };
    Ok(stack_format!(
        600,
        "cast from type {} to type {} does not exist",
        name(source)?.as_str(),
        name(target)?.as_str()
    ))
}

/// PostgreSQL's `MappingUserName`: `public` or the role's name.
fn mapping_user_name(
    storage: &Storage,
    user: crate::storage::foreign::ForeignMappingUser,
    txid: u32,
) -> SqlName {
    match user {
        crate::storage::foreign::ForeignMappingUser::Public => {
            SqlName::parse("public").expect("public fits an identifier")
        }
        crate::storage::foreign::ForeignMappingUser::Role(role) => {
            storage.role_name(usize::from(role), txid)
        }
    }
}

fn resolve_foreign_mapping_user(
    storage: &Storage,
    user: super::ast::ForeignUser<'_>,
    txid: u32,
) -> Result<crate::storage::foreign::ForeignMappingUser, SqlError> {
    if matches!(user, super::ast::ForeignUser::Public) {
        return Ok(crate::storage::foreign::ForeignMappingUser::Public);
    }
    let name = match user {
        super::ast::ForeignUser::Named(name) => StackStr::from_str(name),
        super::ast::ForeignUser::CurrentRole
        | super::ast::ForeignUser::CurrentUser
        | super::ast::ForeignUser::User => super::eval::funcs::system::current_user_owned(),
        super::ast::ForeignUser::Public => unreachable!(),
    };
    storage
        .find_role_visible(name.as_str(), txid)
        .and_then(|slot| u16::try_from(slot).ok())
        .map(crate::storage::foreign::ForeignMappingUser::Role)
        .ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                name.as_str()
            )
        })
}

fn require_user_mapping_authority(
    storage: &Storage,
    server: usize,
    user: crate::storage::foreign::ForeignMappingUser,
    txid: u32,
) -> Result<(), SqlError> {
    let current = storage.current_role_slot(txid).ok_or_else(|| {
        sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "current role does not exist"
        )
    })?;
    let owns_server = storage.foreign_catalog_owner_to(
        crate::storage::foreign::ForeignObjectClass::Server,
        server,
        txid,
    ) as usize
        == current;
    let own_mapping = matches!(user, crate::storage::foreign::ForeignMappingUser::Role(role) if role as usize == current);
    if storage.role(current).attributes_to(txid).superuser
        || owns_server
        || (own_mapping
            && storage.has_object_privilege(
                crate::storage::AccessObject {
                    class: crate::storage::AccessClass::ForeignServer,
                    slot: server as u16,
                },
                current,
                crate::storage::PrivilegeSet::USAGE,
                txid,
            ))
    {
        Ok(())
    } else {
        Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied for server"
        ))
    }
}

pub fn create_user_mapping(
    storage: &mut Storage,
    _wal: &mut Wal,
    txn: &mut TxnState,
    command: &super::ast::CreateUserMapping<'_>,
    responder: &mut Responder,
) -> Outcome {
    let Some((server_slot, server)) = storage.foreign_server(command.server, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "server \"{}\" does not exist",
            command.server
        ));
    };
    let user = match resolve_foreign_mapping_user(storage, command.user, txn.txid) {
        Ok(user) => user,
        Err(error) => return sql_fail(error),
    };
    let Some(current) = storage.current_role_slot(txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "current role does not exist"
        ));
    };
    let owns_server = storage.foreign_catalog_owner_to(
        crate::storage::foreign::ForeignObjectClass::Server,
        server_slot,
        txn.txid,
    ) as usize
        == current;
    let own_mapping = matches!(user, crate::storage::foreign::ForeignMappingUser::Role(role) if role as usize == current);
    if !storage.role(current).attributes_to(txn.txid).superuser
        && !owns_server
        && !(own_mapping
            && storage.has_object_privilege(
                crate::storage::AccessObject {
                    class: crate::storage::AccessClass::ForeignServer,
                    slot: server_slot as u16,
                },
                current,
                crate::storage::PrivilegeSet::USAGE,
                txn.txid,
            ))
    {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied for server {}",
            command.server
        ));
    }
    let options = match crate::storage::foreign::ForeignOptions::parse(command.options) {
        Ok(options) => options,
        Err(error) => return sql_fail(error),
    };
    let wrapper = storage.foreign_wrapper_by_slot(server.wrapper as usize, txn.txid);
    if wrapper.is_some_and(|wrapper| {
        wrapper.validator == crate::storage::foreign::ForeignDataValidator::Postgres
    }) && let Err(error) =
        validate_postgres_foreign_options(&options, PostgresForeignOptionContext::Mapping)
    {
        return sql_fail(error);
    }
    let slot = match storage.create_foreign_user_mapping(
        crate::storage::foreign::UserMappingDefinition {
            server: server_slot as u16,
            user,
            options,
        },
        txn.txid,
    ) {
        Ok(slot) => slot,
        Err(error) if command.if_not_exists && error.sqlstate == sqlstate::DUPLICATE_OBJECT => {
            responder.notice(
                sqlstate::DUPLICATE_OBJECT,
                "user mapping already exists for server, skipping",
            )?;
            responder.command_complete("CREATE USER MAPPING")?;
            return sql_ok();
        }
        Err(error) => return sql_fail(error),
    };
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::UserMappingCreated(slot as u32),
    ) {
        storage.foreign_catalog_rollback_create(
            crate::storage::foreign::ForeignObjectClass::Mapping,
            slot,
        );
        return sql_fail(error);
    }
    responder.command_complete("CREATE USER MAPPING")?;
    sql_ok()
}

fn require_foreign_owner(
    storage: &Storage,
    class: crate::storage::foreign::ForeignObjectClass,
    slot: usize,
    txid: u32,
) -> Result<(), SqlError> {
    let current = storage.current_role_slot(txid).ok_or_else(|| {
        sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "current role is not present in the role catalog"
        )
    })?;
    let owner = storage.foreign_catalog_owner_to(class, slot, txid) as usize;
    if storage.role(current).attributes_to(txid).superuser
        || current == owner
        || storage.role_has_privileges_of(current, owner, txid)
    {
        return Ok(());
    }
    let (noun, name) = match class {
        crate::storage::foreign::ForeignObjectClass::Wrapper => (
            "foreign-data wrapper",
            storage
                .foreign_wrapper_by_slot(slot, txid)
                .map(|definition| definition.name),
        ),
        crate::storage::foreign::ForeignObjectClass::Server => (
            "foreign server",
            storage
                .foreign_server_by_slot(slot, txid)
                .map(|definition| definition.name),
        ),
        crate::storage::foreign::ForeignObjectClass::Mapping => {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "user mappings have no independent owner"
            ));
        }
        crate::storage::foreign::ForeignObjectClass::Table => {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "foreign tables use relation ownership"
            ));
        }
    };
    let name = name.ok_or_else(|| {
        sql_err!(
            sqlstate::INTERNAL_ERROR,
            "selected foreign object is unavailable"
        )
    })?;
    Err(sql_err!(
        sqlstate::INSUFFICIENT_PRIVILEGE,
        "must be owner of {} {}",
        noun,
        name.as_str()
    ))
}

fn alter_foreign_owner(
    storage: &mut Storage,
    txn: &mut TxnState,
    class: crate::storage::foreign::ForeignObjectClass,
    slot: usize,
    role: &str,
) -> Result<(), SqlError> {
    let role = resolve_role_name(role);
    let owner = storage
        .find_role_visible(role.as_str(), txn.txid)
        .ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                role.as_str()
            )
        })?;
    let current = storage.current_role_slot(txn.txid).ok_or_else(|| {
        sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "current role is not present in the role catalog"
        )
    })?;
    let superuser = storage.role(current).attributes_to(txn.txid).superuser;
    if class == crate::storage::foreign::ForeignObjectClass::Wrapper {
        let hint = if !superuser {
            Some("Must be superuser to change owner of a foreign-data wrapper.")
        } else if !storage.role(owner).attributes_to(txn.txid).superuser {
            Some("The owner of a foreign-data wrapper must be a superuser.")
        } else {
            None
        };
        if let Some(hint) = hint {
            let definition = storage
                .foreign_wrapper_by_slot(slot, txn.txid)
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "selected foreign-data wrapper is unavailable"
                    )
                })?;
            super::eval::stash_diagnostic(None, Some(crate::util::StackStr::from_str(hint)));
            return Err(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to change owner of foreign-data wrapper \"{}\"",
                definition.name.as_str()
            ));
        }
    }
    if storage.foreign_catalog_owner_to(class, slot, txn.txid) as usize == owner {
        return Ok(());
    }
    require_foreign_owner(storage, class, slot, txn.txid)?;
    if !superuser && !storage.role_can_set(current, owner, txn.txid) {
        return Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be able to SET ROLE \"{}\"",
            role.as_str()
        ));
    }
    if !superuser && class == crate::storage::foreign::ForeignObjectClass::Server {
        let definition = storage
            .foreign_server_by_slot(slot, txn.txid)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "selected foreign server is unavailable"
                )
            })?;
        if !storage.has_object_privilege(
            crate::storage::AccessObject {
                class: crate::storage::AccessClass::ForeignDataWrapper,
                slot: definition.wrapper,
            },
            owner,
            crate::storage::PrivilegeSet::USAGE,
            txn.txid,
        ) {
            let wrapper = storage
                .foreign_wrapper_by_slot(usize::from(definition.wrapper), txn.txid)
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "foreign server wrapper is unavailable"
                    )
                })?;
            return Err(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied for foreign-data wrapper {}",
                wrapper.name.as_str()
            ));
        }
    }
    let prior = storage.stage_foreign_catalog_owner(class, slot, owner as u16, txn.txid)?;
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::ForeignOwnerChanged {
            class,
            slot: slot as u32,
            prior,
        },
    ) {
        storage.rollback_foreign_catalog_owner(class, slot, prior);
        return Err(error);
    }
    Ok(())
}

pub fn alter_foreign_data_wrapper(
    storage: &mut Storage,
    _wal: &mut Wal,
    txn: &mut TxnState,
    name: &str,
    action: super::ast::AlterForeignDataWrapperAction<'_>,
    responder: &mut Responder,
) -> Outcome {
    let Some((slot, mut definition)) = storage.foreign_wrapper(name, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "foreign-data wrapper \"{}\" does not exist",
            name
        ));
    };
    if !matches!(action, super::ast::AlterForeignDataWrapperAction::Owner(_))
        && let Err(error) = require_foreign_owner(
            storage,
            crate::storage::foreign::ForeignObjectClass::Wrapper,
            slot,
            txn.txid,
        )
    {
        return sql_fail(error);
    }
    match action {
        super::ast::AlterForeignDataWrapperAction::Owner(role) => {
            if let Err(error) = alter_foreign_owner(
                storage,
                txn,
                crate::storage::foreign::ForeignObjectClass::Wrapper,
                slot,
                role,
            ) {
                return sql_fail(error);
            }
        }
        super::ast::AlterForeignDataWrapperAction::Rename(new_name) => {
            if storage.foreign_wrapper(new_name, txn.txid).is_some() {
                return sql_fail(sql_err!(
                    sqlstate::DUPLICATE_OBJECT,
                    "foreign-data wrapper \"{}\" already exists",
                    new_name
                ));
            }
            definition.name = match SqlName::parse(new_name) {
                Ok(name) => name,
                Err(error) => return sql_fail(error),
            };
            let prior = match storage.alter_foreign_wrapper(slot, definition, txn.txid) {
                Ok(prior) => prior,
                Err(error) => return sql_fail(error),
            };
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::ForeignDataWrapperAltered {
                    slot: slot as u32,
                    prior,
                },
            ) {
                storage.rollback_foreign_wrapper_alter(slot, prior);
                return sql_fail(error);
            }
        }
        super::ast::AlterForeignDataWrapperAction::Definition {
            handler,
            validator,
            options,
        } => {
            let prior_handler = definition.handler;
            if let Some(handler) = handler {
                definition.handler = match resolve_foreign_handler(handler) {
                    Ok(handler) => handler,
                    Err(error) => return sql_fail(error),
                };
            }
            if let Some(validator) = validator {
                definition.validator = match resolve_foreign_validator(validator) {
                    Ok(validator) => validator,
                    Err(error) => return sql_fail(error),
                };
            }
            definition.options = match definition.options.alter(options) {
                Ok(options) => options,
                Err(error) => return sql_fail(error),
            };
            if definition.validator == crate::storage::foreign::ForeignDataValidator::Postgres
                && let Err(error) = validate_postgres_foreign_options(
                    &definition.options,
                    PostgresForeignOptionContext::Wrapper,
                )
            {
                return sql_fail(error);
            }
            if definition.handler != prior_handler
                && storage.has_foreign_table_for_wrapper(slot as u16, txn.txid)
            {
                responder.warning(
                    sqlstate::WARNING,
                    "changing the foreign-data wrapper handler can change behavior of existing foreign tables",
                )?;
            }
            let prior = match storage.alter_foreign_wrapper(slot, definition, txn.txid) {
                Ok(prior) => prior,
                Err(error) => return sql_fail(error),
            };
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::ForeignDataWrapperAltered {
                    slot: slot as u32,
                    prior,
                },
            ) {
                storage.rollback_foreign_wrapper_alter(slot, prior);
                return sql_fail(error);
            }
        }
    }
    responder.command_complete("ALTER FOREIGN DATA WRAPPER")?;
    sql_ok()
}

pub fn alter_foreign_server(
    storage: &mut Storage,
    _wal: &mut Wal,
    txn: &mut TxnState,
    name: &str,
    action: super::ast::AlterForeignServerAction<'_>,
    responder: &mut Responder,
) -> Outcome {
    let Some((slot, mut definition)) = storage.foreign_server(name, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "server \"{}\" does not exist",
            name
        ));
    };
    if !matches!(action, super::ast::AlterForeignServerAction::Owner(_))
        && let Err(error) = require_foreign_owner(
            storage,
            crate::storage::foreign::ForeignObjectClass::Server,
            slot,
            txn.txid,
        )
    {
        return sql_fail(error);
    }
    match action {
        super::ast::AlterForeignServerAction::Owner(role) => {
            if let Err(error) = alter_foreign_owner(
                storage,
                txn,
                crate::storage::foreign::ForeignObjectClass::Server,
                slot,
                role,
            ) {
                return sql_fail(error);
            }
        }
        super::ast::AlterForeignServerAction::Rename(new_name) => {
            if storage.foreign_server(new_name, txn.txid).is_some() {
                return sql_fail(sql_err!(
                    sqlstate::DUPLICATE_OBJECT,
                    "server \"{}\" already exists",
                    new_name
                ));
            }
            definition.name = match SqlName::parse(new_name) {
                Ok(name) => name,
                Err(error) => return sql_fail(error),
            };
        }
        super::ast::AlterForeignServerAction::Definition { version, options } => {
            if let Some(version) = version {
                definition.version = match bounded_foreign_value(version, "foreign server version")
                {
                    Ok(version) => version,
                    Err(error) => return sql_fail(error),
                };
            }
            definition.options = match definition.options.alter(options) {
                Ok(options) => options,
                Err(error) => return sql_fail(error),
            };
            let Some(wrapper) =
                storage.foreign_wrapper_by_slot(definition.wrapper as usize, txn.txid)
            else {
                return sql_fail(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "foreign-data wrapper for server does not exist"
                ));
            };
            if wrapper.validator == crate::storage::foreign::ForeignDataValidator::Postgres
                && let Err(error) = validate_postgres_foreign_options(
                    &definition.options,
                    PostgresForeignOptionContext::Server,
                )
            {
                return sql_fail(error);
            }
        }
    }
    if !matches!(action, super::ast::AlterForeignServerAction::Owner(_)) {
        let prior = match storage.alter_foreign_server(slot, definition, txn.txid) {
            Ok(prior) => prior,
            Err(error) => return sql_fail(error),
        };
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ForeignServerAltered {
                slot: slot as u32,
                prior,
            },
        ) {
            storage.rollback_foreign_server_alter(slot, prior);
            return sql_fail(error);
        }
    }
    responder.command_complete("ALTER SERVER")?;
    sql_ok()
}

pub fn alter_user_mapping(
    storage: &mut Storage,
    _wal: &mut Wal,
    txn: &mut TxnState,
    command: &super::ast::AlterUserMapping<'_>,
    responder: &mut Responder,
) -> Outcome {
    let Some((server_slot, server)) = storage.foreign_server(command.server, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "server \"{}\" does not exist",
            command.server
        ));
    };
    let user = match resolve_foreign_mapping_user(storage, command.user, txn.txid) {
        Ok(user) => user,
        Err(error) => return sql_fail(error),
    };
    if let Err(error) = require_user_mapping_authority(storage, server_slot, user, txn.txid) {
        return sql_fail(error);
    }
    let Some((slot, mut definition)) =
        storage.foreign_user_mapping(server_slot as u16, user, txn.txid)
    else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "user mapping for \"{}\" does not exist for server \"{}\"",
            mapping_user_name(storage, user, txn.txid).as_str(),
            command.server
        ));
    };
    definition.options = match definition.options.alter(command.options) {
        Ok(options) => options,
        Err(error) => return sql_fail(error),
    };
    if storage
        .foreign_wrapper_by_slot(server.wrapper as usize, txn.txid)
        .is_some_and(|wrapper| {
            wrapper.validator == crate::storage::foreign::ForeignDataValidator::Postgres
        })
        && let Err(error) = validate_postgres_foreign_options(
            &definition.options,
            PostgresForeignOptionContext::Mapping,
        )
    {
        return sql_fail(error);
    }
    let prior = match storage.alter_foreign_user_mapping(slot, definition, txn.txid) {
        Ok(prior) => prior,
        Err(error) => return sql_fail(error),
    };
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::UserMappingAltered {
            slot: slot as u32,
            prior,
        },
    ) {
        storage.rollback_foreign_mapping_alter(slot, prior);
        return sql_fail(error);
    }
    responder.command_complete("ALTER USER MAPPING")?;
    sql_ok()
}

fn mark_user_mapping_drop(
    storage: &mut Storage,
    txn: &mut TxnState,
    slot: usize,
) -> Result<(), SqlError> {
    storage.foreign_catalog_drop(
        crate::storage::foreign::ForeignObjectClass::Mapping,
        slot,
        txn.txid,
    );
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::UserMappingDropped(slot as u32),
    ) {
        storage.foreign_catalog_rollback_drop(
            crate::storage::foreign::ForeignObjectClass::Mapping,
            slot,
            txn.txid,
        );
        return Err(error);
    }
    Ok(())
}

pub fn drop_user_mapping(
    storage: &mut Storage,
    _wal: &mut Wal,
    txn: &mut TxnState,
    command: &super::ast::DropUserMapping<'_>,
    responder: &mut Responder,
) -> Outcome {
    let Some((server_slot, _)) = storage.foreign_server(command.server, txn.txid) else {
        if command.if_exists {
            responder.notice(
                sqlstate::SUCCESSFUL_COMPLETION,
                stack_format!(
                    128,
                    "server \"{}\" does not exist, skipping",
                    command.server
                )
                .as_str(),
            )?;
            responder.command_complete("DROP USER MAPPING")?;
            return sql_ok();
        }
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "server \"{}\" does not exist",
            command.server
        ));
    };
    let user = match resolve_foreign_mapping_user(storage, command.user, txn.txid) {
        Ok(user) => user,
        Err(error) => return sql_fail(error),
    };
    if let Err(error) = require_user_mapping_authority(storage, server_slot, user, txn.txid) {
        return sql_fail(error);
    }
    let Some((slot, _)) = storage.foreign_user_mapping(server_slot as u16, user, txn.txid) else {
        let user_name = mapping_user_name(storage, user, txn.txid);
        if command.if_exists {
            responder.notice(
                sqlstate::SUCCESSFUL_COMPLETION,
                stack_format!(
                    200,
                    "user mapping for \"{}\" does not exist for server \"{}\", skipping",
                    user_name.as_str(),
                    command.server
                )
                .as_str(),
            )?;
            responder.command_complete("DROP USER MAPPING")?;
            return sql_ok();
        }
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "user mapping for \"{}\" does not exist for server \"{}\"",
            user_name.as_str(),
            command.server
        ));
    };
    if let Err(error) = mark_user_mapping_drop(storage, txn, slot) {
        return sql_fail(error);
    }
    responder.command_complete("DROP USER MAPPING")?;
    sql_ok()
}

#[allow(clippy::too_many_arguments)]
fn drop_foreign_table_slot(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    scratch: &mut DmlScratch,
    seq_session: &crate::sql::guc::SeqSession,
    definition: crate::storage::foreign::ForeignTableDefinition,
    cascade: bool,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    let table = (*storage.table_def(definition.table as usize, txn.txid)).clone();
    let name = QualName {
        schema: Some(table.schema.as_str()),
        name: table.name.as_str(),
    };
    let statement = DropTable {
        names: core::slice::from_ref(&name),
        if_exists: false,
        cascade,
    };
    let outcome = responder.without_command_complete(|responder| {
        drop_table_kind_with_columns(
            storage,
            wal,
            txn,
            &statement,
            Some(crate::storage::TableKind::Foreign),
            "DROP FOREIGN TABLE",
            arena,
            RowTypeColumnCascade {
                scratch: &mut *scratch,
                seq_session,
            },
            responder,
        )
    });
    match outcome {
        Ok(Ok(())) => sql_ok(),
        Ok(Err(error)) => sql_fail(error),
        Err(error) => Err(error),
    }
}

#[allow(clippy::too_many_arguments)]
fn mark_foreign_server_drop(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    scratch: &mut DmlScratch,
    seq_session: &crate::sql::guc::SeqSession,
    slot: usize,
    cascade: bool,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    if let Err(error) = storage.require_not_extension_member(
        crate::storage::AccessObject {
            class: crate::storage::AccessClass::ForeignServer,
            slot: slot as u16,
        },
        txn.txid,
        "server",
    ) {
        return sql_fail(error);
    }
    if !cascade {
        if storage
            .first_user_mapping_for_server(slot as u16, txn.txid)
            .is_some()
            || storage
                .first_foreign_table_for_server(slot as u16, txn.txid)
                .is_some()
        {
            return sql_fail(sql_err!(
                sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                "cannot drop server {} because other objects depend on it",
                storage
                    .foreign_server_by_slot(slot, txn.txid)
                    .map_or(SqlName::EMPTY, |server| server.name)
                    .as_str()
            ));
        }
    } else {
        while let Some((mapping, _)) = storage.first_user_mapping_for_server(slot as u16, txn.txid)
        {
            if let Err(error) = mark_user_mapping_drop(storage, txn, mapping) {
                return sql_fail(error);
            }
        }
        while let Some((_, definition)) =
            storage.first_foreign_table_for_server(slot as u16, txn.txid)
        {
            match drop_foreign_table_slot(
                storage,
                wal,
                txn,
                &mut *scratch,
                seq_session,
                definition,
                true,
                arena,
                responder,
            ) {
                Ok(Ok(())) => {}
                other => return other,
            }
        }
    }
    storage.foreign_catalog_drop(
        crate::storage::foreign::ForeignObjectClass::Server,
        slot,
        txn.txid,
    );
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::ForeignServerDropped(slot as u32),
    ) {
        storage.foreign_catalog_rollback_drop(
            crate::storage::foreign::ForeignObjectClass::Server,
            slot,
            txn.txid,
        );
        return sql_fail(error);
    }
    sql_ok()
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn drop_foreign_server(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    scratch: &mut DmlScratch,
    seq_session: &crate::sql::guc::SeqSession,
    names: &[&str],
    if_exists: bool,
    cascade: bool,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    let report = (|| {
        let originals = arena
            .alloc_slice_with(names.len(), |_| DROPPED_NOTHING)
            .map_err(|_| arena_full())?;
        let mut count = 0;
        for name in names {
            match storage.foreign_server(name, txn.txid) {
                Some((slot, _)) => {
                    originals[count] = ObjectAddress::new(
                        super::catalog::PG_FOREIGN_SERVER_OID,
                        storage.foreign_server_entry(slot).oid(),
                        0,
                    );
                    count += 1;
                }
                None if if_exists => {}
                None => return Ok(None),
            }
        }
        dependency_report::report_drop(
            storage,
            txn.txid,
            &originals[..count],
            cascade,
            arena,
            responder,
        )
    })();
    run_reported_drop(report, responder, |responder| {
        drop_foreign_servers(
            storage,
            wal,
            txn,
            &mut *scratch,
            seq_session,
            names,
            if_exists,
            cascade,
            arena,
            responder,
        )
    })
}

#[allow(clippy::too_many_arguments)]
fn drop_foreign_servers(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    scratch: &mut DmlScratch,
    seq_session: &crate::sql::guc::SeqSession,
    names: &[&str],
    if_exists: bool,
    cascade: bool,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    for name in names {
        let Some((slot, _)) = storage.foreign_server(name, txn.txid) else {
            if if_exists {
                responder.notice(
                    sqlstate::SUCCESSFUL_COMPLETION,
                    stack_format!(128, "server \"{}\" does not exist, skipping", name).as_str(),
                )?;
                continue;
            }
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "server \"{}\" does not exist",
                name
            ));
        };
        if let Err(error) = require_foreign_owner(
            storage,
            crate::storage::foreign::ForeignObjectClass::Server,
            slot,
            txn.txid,
        ) {
            return sql_fail(error);
        }
        match mark_foreign_server_drop(
            storage,
            wal,
            txn,
            &mut *scratch,
            seq_session,
            slot,
            cascade,
            arena,
            responder,
        ) {
            Ok(Ok(())) => {}
            other => return other,
        }
    }
    responder.command_complete("DROP SERVER")?;
    sql_ok()
}

