#[allow(clippy::too_many_arguments)]
fn drop_foreign_data_wrappers(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    scratch: &mut DmlScratch,
    seq_session: &crate::sql::guc::SeqSession,
    names: &[&str],
    if_exists: bool,
    cascade: bool,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    for name in names {
        let Some((slot, _)) = storage.foreign_wrapper(name, txn.txid) else {
            if if_exists {
                responder.notice(
                    sqlstate::SUCCESSFUL_COMPLETION,
                    stack_format!(
                        128,
                        "foreign-data wrapper \"{}\" does not exist, skipping",
                        name
                    )
                    .as_str(),
                )?;
                continue;
            }
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "foreign-data wrapper \"{}\" does not exist",
                name
            ));
        };
        if let Err(error) = require_foreign_owner(
            storage,
            crate::storage::foreign::ForeignObjectClass::Wrapper,
            slot,
            txn.txid,
        ) {
            return sql_fail(error);
        }
        if let Err(error) = storage.require_not_extension_member(
            crate::storage::AccessObject {
                class: crate::storage::AccessClass::ForeignDataWrapper,
                slot: slot as u16,
            },
            txn.txid,
            "foreign-data wrapper",
        ) {
            return sql_fail(error);
        }
        if !cascade
            && storage
                .first_foreign_server_for_wrapper(slot as u16, txn.txid)
                .is_some()
        {
            return sql_fail(sql_err!(
                sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                "cannot drop foreign-data wrapper {} because other objects depend on it",
                name
            ));
        }
        if cascade {
            while let Some((server, _)) =
                storage.first_foreign_server_for_wrapper(slot as u16, txn.txid)
            {
                match mark_foreign_server_drop(
                    storage,
                    wal,
                    txn,
                    &mut *scratch,
                    seq_session,
                    server,
                    true,
                    arena,
                    responder,
                ) {
                    Ok(Ok(())) => {}
                    other => return other,
                }
            }
        }
        storage.foreign_catalog_drop(
            crate::storage::foreign::ForeignObjectClass::Wrapper,
            slot,
            txn.txid,
        );
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ForeignDataWrapperDropped(slot as u32),
        ) {
            storage.foreign_catalog_rollback_drop(
                crate::storage::foreign::ForeignObjectClass::Wrapper,
                slot,
                txn.txid,
            );
            return sql_fail(error);
        }
    }
    responder.command_complete("DROP FOREIGN DATA WRAPPER")?;
    sql_ok()
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn drop_foreign_table(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    scratch: &mut DmlScratch,
    statement: &DropTable<'_>,
    arena: &Arena,
    seq_session: &crate::sql::guc::SeqSession,
    responder: &mut Responder,
) -> Outcome {
    drop_table_kind_with_columns(
        storage,
        wal,
        txn,
        statement,
        Some(crate::storage::TableKind::Foreign),
        "DROP FOREIGN TABLE",
        arena,
        RowTypeColumnCascade {
            scratch,
            seq_session,
        },
        responder,
    )
}

pub(crate) struct ForeignTableAlterRuntime<'a> {
    pub(crate) scratch: &'a mut DmlScratch,
    pub(crate) arena: &'a Arena,
    pub(crate) sequence: &'a crate::sql::guc::SeqSession,
}

pub(crate) fn alter_foreign_table(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    statement: &AlterTable<'_>,
    runtime: ForeignTableAlterRuntime<'_>,
    responder: &mut Responder,
) -> Outcome {
    alter_foreign_table_as(
        storage,
        wal,
        txn,
        statement,
        runtime,
        responder,
        "ALTER FOREIGN TABLE",
    )
}

/// `ALTER FOREIGN TABLE`, or `ALTER TABLE` naming a foreign table, which
/// completes with its own tag.
fn alter_foreign_table_as(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    statement: &AlterTable<'_>,
    runtime: ForeignTableAlterRuntime<'_>,
    responder: &mut Responder,
    tag: &'static str,
) -> Outcome {
    let ForeignTableAlterRuntime {
        scratch,
        arena,
        sequence,
    } = runtime;
    let table =
        match storage.resolve_relation(statement.table.schema, statement.table.name, txn.txid) {
            Some(crate::storage::ResolvedRelation::Table(table))
                if storage.table_def(table, txn.txid).kind
                    == crate::storage::TableKind::Foreign =>
            {
                table
            }
            None if statement.if_exists => {
                responder.notice(
                    sqlstate::SUCCESSFUL_COMPLETION,
                    stack_format!(
                        160,
                        "relation \"{}\" does not exist, skipping",
                        statement.table.name
                    )
                    .as_str(),
                )?;
                responder.command_complete(tag)?;
                return sql_ok();
            }
            Some(_) => {
                return sql_fail(sql_err!(
                    sqlstate::WRONG_OBJECT_TYPE,
                    "\"{}\" is not a foreign table",
                    statement.table.name
                ));
            }
            None => return sql_fail(undefined_qual(&statement.table)),
        };
    if let Err(error) = storage.require_owner(
        storage.table_access_object(table, txn.txid),
        txn.txid,
        "foreign table",
    ) {
        return sql_fail(error);
    }
    if let Err(error) = require_alter_actions_supported(
        statement.actions,
        AlterRelationKind::ForeignTable,
        statement.table.name,
    ) {
        return sql_fail(error);
    }
    let Some((binding_slot, mut binding)) = storage.foreign_table(table as u16, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::INTERNAL_ERROR,
            "foreign table has no typed catalog binding"
        ));
    };
    let definition = (*storage.table_def(table, txn.txid)).clone();
    let mut ordinary = [AlterAction::DropDefault { column: "" }; 32];
    let mut ordinary_count = 0usize;
    let mut binding_changed = false;
    for action in statement.actions {
        match action {
            AlterAction::SetForeignOptions(actions) => {
                binding.options = match binding.options.alter(actions) {
                    Ok(options) => options,
                    Err(error) => return sql_fail(error),
                };
                binding_changed = true;
            }
            AlterAction::SetColumnForeignOptions { column, options } => {
                let Some(column) = definition.column_index(column) else {
                    return sql_fail(undefined_column(column));
                };
                binding.column_options = match binding.column_options.alter(column as u16, options)
                {
                    Ok(options) => options,
                    Err(error) => return sql_fail(error),
                };
                binding_changed = true;
            }
            other => {
                ordinary[ordinary_count] = *other;
                ordinary_count += 1;
            }
        }
    }
    let Some(server) = storage.foreign_server_by_slot(binding.server as usize, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "foreign table server does not exist"
        ));
    };
    if storage
        .foreign_wrapper_by_slot(server.wrapper as usize, txn.txid)
        .is_some_and(|wrapper| {
            wrapper.validator == crate::storage::foreign::ForeignDataValidator::Postgres
        })
    {
        if let Err(error) =
            validate_postgres_foreign_options(&binding.options, PostgresForeignOptionContext::Table)
        {
            return sql_fail(error);
        }
        for column in 0..definition.n_columns {
            let mut options = crate::storage::foreign::ForeignOptions::EMPTY;
            for option in binding.column_options.options_for(column as u16) {
                let parsed = super::ast::ForeignOption {
                    name: option.name.as_str(),
                    value: option.value.as_str(),
                };
                options = match options.alter(&[super::ast::ForeignOptionAction::Add(parsed)]) {
                    Ok(options) => options,
                    Err(error) => return sql_fail(error),
                };
            }
            if let Err(error) =
                validate_postgres_foreign_options(&options, PostgresForeignOptionContext::Column)
            {
                return sql_fail(error);
            }
        }
    }
    if ordinary_count != 0 {
        let ordinary_statement = AlterTable {
            table: statement.table,
            if_exists: statement.if_exists,
            only: statement.only,
            actions: &ordinary[..ordinary_count],
        };
        match alter_table_inner(
            storage,
            wal,
            txn,
            scratch,
            &ordinary_statement,
            arena,
            sequence,
            responder,
            false,
            Some(crate::storage::TableKind::Foreign),
            tag,
            AlterInheritanceScope::Direct,
        ) {
            Ok(Ok(())) => {}
            other => return other,
        }
    } else if let Err(error) = storage.lock_table(
        txn.txid,
        table,
        crate::sql::ast::TableLockMode::AccessExclusive,
        false,
    ) {
        return sql_fail(error);
    }
    if binding_changed {
        let prior = match storage.alter_foreign_table_binding(binding_slot, binding, txn.txid) {
            Ok(prior) => prior,
            Err(error) => return sql_fail(error),
        };
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ForeignTableAltered {
                slot: binding_slot as u32,
                prior,
            },
        ) {
            storage.rollback_foreign_table_alter(binding_slot, prior);
            return sql_fail(error);
        }
    }
    responder.command_complete(tag)?;
    sql_ok()
}

fn validate_partitioned_unique_keys<Definition0: crate::storage::DefinitionBacking>(
    def: &crate::storage::TableDefinition<Definition0>,
) -> Result<(), SqlError> {
    let Some(crate::storage::PartitionScheme { keys, n_keys, .. }) = def.partition.scheme else {
        return Ok(());
    };
    let includes_keys = |columns: &[u16]| {
        keys[..usize::from(n_keys)]
            .iter()
            .all(|key| columns.contains(key))
    };
    for (column, metadata) in def.columns().iter().enumerate() {
        if (metadata.unique || metadata.primary) && !includes_keys(&[column as u16]) {
            return Err(sql_err!(
                sqlstate::FEATURE_NOT_SUPPORTED,
                "unique constraint on partitioned table must include all partitioning columns"
            ));
        }
    }
    for unique in def.uniques() {
        if !includes_keys(unique.columns()) {
            return Err(sql_err!(
                sqlstate::FEATURE_NOT_SUPPORTED,
                "unique constraint on partitioned table must include all partitioning columns"
            ));
        }
    }
    for exclusion in def.exclusions() {
        let includes_equal_partition_keys = keys[..usize::from(n_keys)].iter().all(|key| {
            exclusion
                .columns()
                .iter()
                .position(|column| column == key)
                .is_some_and(|position| {
                    exclusion.operators[position] == crate::storage::ExclusionOperator::Equal
                })
        });
        if !includes_equal_partition_keys {
            return Err(sql_err!(
                sqlstate::FEATURE_NOT_SUPPORTED,
                "exclusion constraint on partitioned table must include all partitioning columns with equality operators"
            ));
        }
    }
    Ok(())
}

/// Resolves the parsed partition declaration while the parent definition is
/// available.  The durable table definition contains only column offsets,
/// typed values and a table slot; no later executor path parses SQL text.
fn build_partitioned_table_def(
    storage: &Storage,
    statement: &CreateTable,
    txid: u32,
    arena: &Arena,
) -> Result<TableDefBuilder, SqlError> {
    match statement.partition {
        PartitionClause::None => build_inherited_table_def(storage, statement, txid, arena),
        PartitionClause::By { strategy, columns } => {
            let mut def = build_inherited_table_def(storage, statement, txid, arena)?;
            def.partition.scheme = Some(resolve_partition_scheme(&def, strategy, columns)?);
            Ok(def)
        }
        PartitionClause::Of {
            parent,
            bound,
            subpartition,
        } => {
            let parent_slot = resolve_dml_table(storage, &parent, txid)?;
            storage.lock_table(
                txid,
                parent_slot,
                crate::sql::ast::TableLockMode::AccessExclusive,
                false,
            )?;
            let parent_def = (*storage.table_def(parent_slot, txid)).clone();
            let child_is_temporary =
                statement.persistence == crate::sql::ast::RelationPersistence::Temporary;
            let parent_is_temporary =
                parent_def.persistence == crate::storage::RelationPersistence::Temporary;
            if child_is_temporary != parent_is_temporary {
                return Err(sql_err!(
                    sqlstate::WRONG_OBJECT_TYPE,
                    "cannot create a {} relation as partition of {} relation \"{}\"",
                    if child_is_temporary {
                        "temporary"
                    } else {
                        "permanent"
                    },
                    if parent_is_temporary {
                        "temporary"
                    } else {
                        "permanent"
                    },
                    parent_def.name.as_str()
                ));
            }
            let Some(crate::storage::PartitionScheme {
                strategy,
                keys,
                n_keys,
            }) = parent_def.partition.scheme
            else {
                return Err(sql_err!(
                    sqlstate::WRONG_OBJECT_TYPE,
                    "relation \"{}\" is not partitioned",
                    parent.name
                ));
            };
            if !statement.columns.is_empty()
                || !statement.constraints.is_empty()
                || !statement.likes.is_empty()
            {
                return Err(sql_err!(
                    sqlstate::SYNTAX_ERROR,
                    "a partition cannot declare columns or table constraints"
                ));
            }
            for check in parent_def.checks() {
                ddl::require_convertible_check(&parent_def, check, arena)?;
            }
            let mut def = TableDefBuilder::from_definition(&parent_def);
            def.name = SqlName::parse(statement.name.name)?;
            def.schema = storage.creation_schema(
                statement.name.schema,
                statement.name.name,
                txid,
                crate::storage::SchemaObjectKind::Relation,
            )?;
            // A partition's not-null constraints keep their parent's names.
            for (column, name) in def
                .columns
                .iter_mut()
                .zip(def.not_null_names.iter_mut())
                .take(def.n_columns)
            {
                if column.not_null.is_required() {
                    column.not_null = crate::storage::NotNullOrigin::Inherited;
                } else {
                    column.not_null = crate::storage::NotNullOrigin::Nullable;
                    *name = None;
                }
            }
            for index in 0..def.n_uniques {
                let constraint = def.uniques[index];
                def.uniques[index].name = auto_key_name(
                    storage,
                    &def,
                    if constraint.kind.is_primary() {
                        &[]
                    } else {
                        constraint.columns()
                    },
                    if constraint.kind.is_primary() {
                        "pkey"
                    } else {
                        "key"
                    },
                    txid,
                    None,
                    crate::storage::GeneratedNameClass::IndexConstraint,
                )?;
            }
            for index in 0..def.n_exclusions {
                let constraint = def.exclusions[index];
                def.exclusions[index].name = auto_key_name(
                    storage,
                    &def,
                    constraint.columns(),
                    "excl",
                    txid,
                    None,
                    crate::storage::GeneratedNameClass::IndexConstraint,
                )?;
            }
            let resolved_bound = resolve_partition_bound(
                storage,
                strategy,
                keys,
                n_keys,
                bound,
                &parent_def,
                txid,
                arena,
            )?;
            validate_partition_bound(storage, parent_slot, resolved_bound, txid)?;
            validate_default_partition_rows(storage, parent_slot, resolved_bound, txid, arena)?;
            def.partition = PartitionDef::child(
                u16::try_from(parent_slot)
                    .map_err(|_| sql_err!(sqlstate::PROGRAM_LIMIT_EXCEEDED, "too many tables"))?,
                resolved_bound,
            );
            if let Some(by) = subpartition {
                def.partition.scheme =
                    Some(resolve_partition_scheme(&def, by.strategy, by.columns)?);
            }
            Ok(def)
        }
    }
}

/// PostgreSQL's notices for a column that several parents, or a parent and
/// the new table itself, define.
fn notify_inherited_column_merges(
    storage: &Storage,
    statement: &CreateTable,
    txid: u32,
    responder: &mut Responder,
) -> Result<Result<(), SqlError>, WireFull> {
    let crate::sql::ast::TableMembership::Inherits(parents) = statement.membership else {
        return Ok(Ok(()));
    };
    let parent_slot = |position: usize| resolve_dml_table(storage, &parents[position], txid);
    let defined_by_earlier_parent = |position: usize, column: &str| -> Result<bool, SqlError> {
        for earlier in 0..position {
            if storage
                .table_def(parent_slot(earlier)?, txid)
                .column_index(column)
                .is_some()
            {
                return Ok(true);
            }
        }
        Ok(false)
    };
    for position in 0..parents.len() {
        let parent = match parent_slot(position) {
            Ok(parent) => storage.table_def(parent, txid),
            Err(error) => return Ok(Err(error)),
        };
        for column in parent.columns() {
            match defined_by_earlier_parent(position, column.name.as_str()) {
                Ok(true) => responder.notice(
                    sqlstate::SUCCESSFUL_COMPLETION,
                    stack_format!(
                        160,
                        "merging multiple inherited definitions of column \"{}\"",
                        column.name.as_str()
                    )
                    .as_str(),
                )?,
                Ok(false) => {}
                Err(error) => return Ok(Err(error)),
            }
        }
    }
    for column in statement.columns {
        match defined_by_earlier_parent(parents.len(), column.name) {
            Ok(true) => responder.notice(
                sqlstate::SUCCESSFUL_COMPLETION,
                stack_format!(
                    160,
                    "merging column \"{}\" with inherited definition",
                    column.name
                )
                .as_str(),
            )?,
            Ok(false) => {}
            Err(error) => return Ok(Err(error)),
        }
    }
    Ok(Ok(()))
}

/// Builds the physical child row layout from its direct parents before adding
/// child-local columns.  Parent slots are recorded in the same durable image as
/// the copied layout, so a scan never infers inheritance from matching names.
fn build_inherited_table_def(
    storage: &Storage,
    statement: &CreateTable,
    txid: u32,
    arena: &Arena,
) -> Result<TableDefBuilder, SqlError> {
    let own = build_declared_table_def(storage, statement, txid, arena)?;
    let crate::sql::ast::TableMembership::Inherits(parents) = statement.membership else {
        return Ok(own);
    };
    let mut definition = own.clone();
    definition.n_columns = 0;
    definition.columns = [ColumnMeta::EMPTY; MAX_COLUMNS];
    definition.not_null_names = [None; MAX_COLUMNS];
    definition.inheritance = crate::storage::TableInheritance::NONE;
    for parent_name in parents {
        let parent = resolve_dml_table(storage, parent_name, txid)?;
        let parent_definition = storage.table_def(parent, txid);
        if parent_definition.persistence == crate::storage::RelationPersistence::Temporary
            && statement.persistence != crate::sql::ast::RelationPersistence::Temporary
        {
            return Err(sql_err!(
                sqlstate::WRONG_OBJECT_TYPE,
                "cannot inherit from temporary relation \"{}\"",
                parent_definition.name.as_str()
            ));
        }
        if parent_definition.kind != crate::storage::TableKind::Local {
            return Err(sql_err!(
                sqlstate::WRONG_OBJECT_TYPE,
                "cannot inherit from foreign table \"{}\"",
                parent_definition.name.as_str()
            ));
        }
        if parent_definition.partition.is_partitioned() {
            return Err(sql_err!(
                sqlstate::WRONG_OBJECT_TYPE,
                "cannot inherit from partitioned table \"{}\"",
                parent_definition.name.as_str()
            ));
        }
        for (parent_index, parent_column) in parent_definition.columns().iter().enumerate() {
            let mut inherited = *parent_column;
            inherited.not_null =
                if inherited.not_null.is_required() && inherited.not_null_inheritable {
                    crate::storage::NotNullOrigin::Inherited
                } else {
                    crate::storage::NotNullOrigin::Nullable
                };
            // A child has its own physical rows and its own identity-sequence
            // ownership. PostgreSQL does not make the parent's sequence an
            // implicit writable dependency of the child relation.
            // Ordinary inheritance shares column definitions and CHECKs, but
            // primary and unique keys remain local to their declaring table.
            inherited.primary = false;
            inherited.unique = false;
            inherited.auto_increment = false;
            inherited.is_identity = false;
            inherited.identity_always = false;
            if let Some(existing) = definition.column_index(inherited.name.as_str()) {
                let current = definition.columns[existing];
                if current.ctype != inherited.ctype
                    || current.type_mod != inherited.type_mod
                    || current.collation != inherited.collation
                {
                    return Err(sql_err!(
                        sqlstate::DATATYPE_MISMATCH,
                        "inherited column \"{}\" has a conflicting type definition",
                        inherited.name.as_str()
                    ));
                }
                if inherited.not_null.is_required() {
                    definition.columns[existing].not_null = inherited.not_null;
                    if definition.not_null_names[existing].is_none() {
                        definition.not_null_names[existing] =
                            parent_definition.not_null_names[parent_index];
                    }
                }
            } else {
                let mut count = definition.n_columns;
                push_column(&mut definition, &mut count, inherited)?;
                definition.n_columns = count;
                // An inherited not-null constraint keeps its parent's name.
                if inherited.not_null.is_required() {
                    definition.not_null_names[count - 1] =
                        parent_definition.not_null_names[parent_index];
                }
            }
        }
        inherit_table_checks(&parent_definition, &mut definition, false, arena)?;
        definition.inheritance.append(parent)?;
    }
    for (own_index, column) in own.columns().iter().enumerate() {
        if let Some(existing) = definition.column_index(column.name.as_str()) {
            let inherited = definition.columns[existing];
            if inherited.ctype != column.ctype
                || inherited.type_mod != column.type_mod
                || inherited.collation != column.collation
            {
                return Err(sql_err!(
                    sqlstate::DATATYPE_MISMATCH,
                    "inherited column \"{}\" has a conflicting type definition",
                    column.name.as_str()
                ));
            }
            definition.columns[existing].primary |= column.primary;
            definition.columns[existing].unique |= column.unique;
            // PostgreSQL lets the child declaration supply an explicit default
            // while the inherited type identity remains fixed.
            if !matches!(column.default, crate::storage::ColumnDefault::None) {
                definition.columns[existing].default = column.default;
            }
            if column.not_null.is_required() {
                if inherited.not_null.is_required()
                    && inherited.not_null_inheritable
                    && !column.not_null_inheritable
                {
                    return Err(sql_err!(
                        sqlstate::DATATYPE_MISMATCH,
                        "not-null constraint on inherited column \"{}\" must be inheritable",
                        column.name.as_str()
                    ));
                }
                definition.columns[existing].not_null =
                    definition.columns[existing].not_null.add_local();
                definition.columns[existing].not_null_inheritable = column.not_null_inheritable;
                // The child's own declaration names the merged constraint.
                definition.not_null_names[existing] = own.not_null_names[own_index];
            }
        } else {
            let mut count = definition.n_columns;
            push_column(&mut definition, &mut count, *column)?;
            definition.n_columns = count;
            definition.not_null_names[count - 1] = own.not_null_names[own_index];
        }
    }
    for index in 0..definition.n_uniques {
        definition.uniques[index].columns =
            remap_columns(&definition, &own, definition.uniques[index].columns())?;
    }
    for index in 0..definition.n_fkeys {
        definition.fkeys[index].columns =
            remap_columns(&definition, &own, definition.fkeys[index].columns())?;
        definition.fkeys[index].delete_set_cols =
            remap_columns(&definition, &own, definition.fkeys[index].delete_set_cols())?;
    }
    for index in 0..definition.n_fkeys {
        let key = definition.fkeys[index];
        if key.parent_schema == definition.schema && key.parent == definition.name {
            definition.fkeys[index].parent_cols =
                remap_columns(&definition, &own, key.parent_cols())?;
        }
    }
    for index in 0..definition.n_exclusions {
        definition.exclusions[index].columns =
            remap_columns(&definition, &own, definition.exclusions[index].columns())?;
    }
    Ok(definition)
}

/// Resolves `CREATE TABLE ... OF type` before table creation. The table stores
/// the resolved composite identity and copies its active attributes into the
/// physical row shape; later execution never reinterprets the type spelling.
fn build_declared_table_def(
    storage: &Storage,
    statement: &CreateTable,
    txid: u32,
    arena: &Arena,
) -> Result<TableDefBuilder, SqlError> {
    let crate::sql::ast::TableMembership::OfType(type_name) = statement.membership else {
        return build_def_with_likes(storage, statement, txid, arena);
    };
    if !statement.columns.is_empty() || !statement.likes.is_empty() {
        return Err(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "typed-table column options require a typed attribute alteration protocol"
        ));
    }
    let (composite, reference) = storage
        .composite_source(type_name.schema, type_name.name, txid)?
        .ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "type \"{}\" does not exist",
                type_name.name
            )
        })?;
    let mut definition = TableDefBuilder {
        name: SqlName::parse(statement.name.name)?,
        type_membership: crate::storage::TableTypeMembership::Composite(reference),
        ..TableDefBuilder::empty()
    };
    let mut count = 0;
    for field in composite.active_fields_for(txid) {
        push_column(
            &mut definition,
            &mut count,
            ColumnMeta {
                name: field.name,
                ctype: field.ctype,
                type_mod: field.type_mod,
                collation: field.collation,
                not_null: crate::storage::NotNullOrigin::local(field.not_null),
                user_type: field.user_type,
                ..ColumnMeta::EMPTY
            },
        )?;
    }
    definition.n_columns = count;
    Ok(definition)
}

/// PostgreSQL ordinary inheritance shares CHECK definitions and column
/// requirements but deliberately leaves keys, foreign keys, and exclusion
/// constraints local to each physical relation.
fn inherit_table_checks<Definition0: crate::storage::DefinitionBacking>(
    parent: &crate::storage::TableDefinition<Definition0>,
    child: &mut TableDefBuilder,
    require_existing: bool,
    arena: &Arena,
) -> Result<(), SqlError> {
    for inherited in parent.checks() {
        if let Some(existing) = child
            .checks()
            .iter()
            .find(|existing| existing.name == inherited.name)
        {
            if existing.expression != inherited.expression {
                return Err(sql_err!(
                    sqlstate::DUPLICATE_OBJECT,
                    "constraint \"{}\" conflicts with inherited constraint of the same name",
                    inherited.name.as_str()
                ));
            }
            continue;
        }
        if require_existing {
            return Err(sql_err!(
                sqlstate::DATATYPE_MISMATCH,
                "child table is missing constraint \"{}\"",
                inherited.name.as_str()
            ));
        }
        if child.n_checks == crate::storage::MAX_CHECKS {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many check constraints"
            ));
        }
        ddl::require_convertible_check(parent, inherited, arena)?;
        child.checks[child.n_checks] = *inherited;
        child.checks[child.n_checks].identity = None;
        child.n_checks += 1;
    }
    Ok(())
}

fn resolve_partition_scheme<Definition0: crate::storage::DefinitionBacking>(
    definition: &crate::storage::TableDefinition<Definition0>,
    strategy: PartitionStrategy,
    columns: &[&str],
) -> Result<crate::storage::PartitionScheme, SqlError> {
    if columns.is_empty() {
        return Err(sql_err!(
            sqlstate::INVALID_OBJECT_DEFINITION,
            "partition key must contain at least one column"
        ));
    }
    if columns.len() > crate::storage::MAX_PARTITION_KEYS {
        return Err(sql_err!(
            sqlstate::TOO_MANY_COLUMNS,
            "cannot partition using more than {} columns",
            crate::storage::MAX_PARTITION_KEYS
        ));
    }
    if strategy == PartitionStrategy::List && columns.len() != 1 {
        return Err(sql_err!(
            sqlstate::INVALID_OBJECT_DEFINITION,
            "cannot use list partition strategy with more than one column"
        ));
    }
    let mut keys = [0u16; crate::storage::MAX_PARTITION_KEYS];
    for (index, name) in columns.iter().enumerate() {
        keys[index] = definition.column_index(name).ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_COLUMN,
                "column \"{}\" named in partition key does not exist",
                name
            )
        })? as u16;
        if definition.columns()[usize::from(keys[index])]
            .default
            .is_generated()
        {
            return Err(sql_err!(
                sqlstate::INVALID_OBJECT_DEFINITION,
                "cannot use generated column in partition key"
            ));
        }
    }
    if strategy == PartitionStrategy::Hash
        && keys[..columns.len()].iter().any(|key| {
            !matches!(
                definition.columns.as_ref()[usize::from(*key)].ctype,
                ColType::Int2 | ColType::Int4 | ColType::Int8
            )
        })
    {
        return Err(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "HASH partitioning is supported for integer partition keys only"
        ));
    }
    Ok(crate::storage::PartitionScheme {
        strategy: match strategy {
            PartitionStrategy::Range => StoredPartitionStrategy::Range,
            PartitionStrategy::List => StoredPartitionStrategy::List,
            PartitionStrategy::Hash => StoredPartitionStrategy::Hash,
        },
        keys,
        n_keys: columns.len() as u8,
    })
}

fn validate_partition_bound(
    storage: &Storage,
    parent: usize,
    candidate: StoredPartitionBound,
    txid: u32,
) -> Result<(), SqlError> {
    for slot in 0..storage.table_count() {
        if !storage.table(slot).visible_to(txid) {
            continue;
        }
        let Some(crate::storage::PartitionAttachment {
            parent: sibling_parent,
            bound,
            ..
        }) = storage.table_def(slot, txid).partition.attachment
        else {
            continue;
        };
        if usize::from(sibling_parent) != parent || !partition_bounds_overlap(candidate, bound)? {
            continue;
        }
        return Err(sql_err!(
            sqlstate::INVALID_OBJECT_DEFINITION,
            "partition \"{}\" would overlap partition \"{}\"",
            storage.table_def(parent, txid).name.as_str(),
            storage.table_def(slot, txid).name.as_str()
        ));
    }
    Ok(())
}

/// Adding a bound also narrows the default partition's allowed rows. Lock its
/// tree before scanning; no current row may silently acquire the wrong home.
fn validate_default_partition_rows(
    storage: &Storage,
    parent: usize,
    bound: StoredPartitionBound,
    txid: u32,
    arena: &Arena,
) -> Result<(), SqlError> {
    if matches!(bound, StoredPartitionBound::Default) {
        return Ok(());
    }
    let parent_def = (*storage.table_def(parent, txid)).clone();
    let scheme = parent_def
        .partition
        .scheme
        .expect("partition parent has a scheme");
    for default in 0..storage.table_count() {
        if !storage.table(default).visible_to(txid) {
            continue;
        }
        let definition = (*storage.table_def(default, txid)).clone();
        if !definition.partition.attachment.is_some_and(|attachment| {
            usize::from(attachment.parent) == parent
                && attachment.state.routable()
                && matches!(attachment.bound, StoredPartitionBound::Default)
        }) {
            continue;
        }
        for candidate in 0..storage.table_count() {
            if storage.table(candidate).visible_to(txid)
                && (candidate == default
                    || storage.partition_descends_from(candidate, default, txid))
            {
                storage.lock_table(
                    txid,
                    candidate,
                    crate::sql::ast::TableLockMode::AccessExclusive,
                    false,
                )?;
            }
        }
        let read = storage.validation_read();
        for candidate in 0..storage.table_count() {
            if !storage.table(candidate).visible_to(txid)
                || storage
                    .table_def(candidate, txid)
                    .partition
                    .is_partitioned()
                || !(candidate == default
                    || storage.partition_descends_from(candidate, default, txid))
            {
                continue;
            }
            let physical = (*storage.table_def(candidate, txid)).clone();
            let mut schema = [ColType::Bool; MAX_COLUMNS];
            physical.schema(&mut schema);
            // SAFETY: bound comparison consumes each row and returns only an
            // owned error; no front-arena or row value escapes.
            unsafe {
                constraints::for_each_validation_row(
                    storage,
                    candidate,
                    txid,
                    read,
                    &schema[..physical.n_columns],
                    arena,
                    &mut |_, values| {
                        if crate::storage::PartitionRow::new(&physical, values)?
                            .keys(&parent_def, scheme)?
                            .matches(bound)?
                        {
                            return Err(sql_err!(
                                sqlstate::CHECK_VIOLATION,
                                "updated partition constraint for default partition \"{}\" would be violated by some row",
                                definition.name.as_str()
                            ));
                        }
                        Ok(())
                    },
                )?;
            }
        }
    }
    Ok(())
}

fn partition_bounds_overlap(
    left: StoredPartitionBound,
    right: StoredPartitionBound,
) -> Result<bool, SqlError> {
    use crate::sql::eval::compare_datums;
    use core::cmp::Ordering;
    match (left, right) {
        (StoredPartitionBound::Default, StoredPartitionBound::Default) => Ok(true),
        (StoredPartitionBound::Default, _) | (_, StoredPartitionBound::Default) => Ok(false),
        (
            StoredPartitionBound::Hash {
                modulus: lm,
                remainder: lr,
            },
            StoredPartitionBound::Hash {
                modulus: rm,
                remainder: rr,
            },
        ) => {
            let common = lm.min(rm);
            Ok(lr % common == rr % common)
        }
        (
            StoredPartitionBound::List {
                values: lv,
                n_values: ln,
            },
            StoredPartitionBound::List {
                values: rv,
                n_values: rn,
            },
        ) => {
            for left in &lv[..usize::from(ln)] {
                for right in &rv[..usize::from(rn)] {
                    if compare_datums(&left.as_datum(), &right.as_datum())?.is_eq() {
                        return Ok(true);
                    }
                }
            }
            Ok(false)
        }
        (
            StoredPartitionBound::Range {
                lower: ll,
                upper: lu,
                n_keys: ln,
            },
            StoredPartitionBound::Range {
                lower: rl,
                upper: ru,
                n_keys: rn,
            },
        ) if ln == rn => Ok(
            compare_partition_bound_tuples(&ll, &ru, ln)? == Ordering::Less
                && compare_partition_bound_tuples(&rl, &lu, ln)? == Ordering::Less,
        ),
        _ => Ok(false),
    }
}

fn compare_partition_bound_tuples(
    left: &[PartitionBoundValue; crate::storage::MAX_PARTITION_KEYS],
    right: &[PartitionBoundValue; crate::storage::MAX_PARTITION_KEYS],
    n_keys: u8,
) -> Result<core::cmp::Ordering, SqlError> {
    use core::cmp::Ordering;
    for index in 0..usize::from(n_keys) {
        let ordering = match (left[index], right[index]) {
            (PartitionBoundValue::MinValue, PartitionBoundValue::MinValue)
            | (PartitionBoundValue::MaxValue, PartitionBoundValue::MaxValue) => Ordering::Equal,
            (PartitionBoundValue::MinValue, _) | (_, PartitionBoundValue::MaxValue) => {
                Ordering::Less
            }
            (PartitionBoundValue::MaxValue, _) | (_, PartitionBoundValue::MinValue) => {
                Ordering::Greater
            }
            (PartitionBoundValue::Value(left), PartitionBoundValue::Value(right)) => {
                compare_datums(&left.as_datum(), &right.as_datum())?
            }
        };
        if !ordering.is_eq() {
            return Ok(ordering);
        }
    }
    Ok(Ordering::Equal)
}

fn row_trigger_when_passes<'a>(
    context: &TriggerExecContext<'_, 'a, '_>,
    trigger: &crate::storage::TriggerDef,
    definition: crate::storage::RelationDefinition<'_>,
    old: Option<&[Datum<'a>]>,
    new: Option<&[Datum<'a>]>,
) -> Result<bool, SqlError> {
    let Some(when) = trigger.when else {
        return Ok(true);
    };
    let source = context.arena.alloc_str(when.as_str()).map_err(|_| {
        sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "trigger WHEN predicate exceeds the statement arena"
        )
    })?;
    let condition = super::parser::parse_expr(source, context.arena)?;
    super::plpgsql_inputs::reject_atomic(
        super::plpgsql_inputs::Site {
            kind: super::plpgsql_inputs::Kind::Expression,
            key: core::ptr::from_ref(condition) as usize,
            position: 0,
            text: source,
            exception_variables: false,
        },
        context.storage(),
        context.txn.txid,
        &TriggerTransition {
            definition,
            old: TriggerRecordValue::of_row(old),
            new: TriggerRecordValue::of_row(new),
        },
        None,
        context.arena,
    )?;
    match eval_trigger_expression(
        context,
        condition,
        &TriggerTransition {
            definition,
            old: TriggerRecordValue::of_row(old),
            new: TriggerRecordValue::of_row(new),
        },
    )? {
        Datum::Bool(value) => Ok(value),
        Datum::Null => Ok(false),
        _ => Err(sql_err!(
            sqlstate::DATATYPE_MISMATCH,
            "trigger WHEN condition must be type boolean"
        )),
    }
}

/// Runs one firing of a PostgreSQL built-in trigger function. `old` and
/// `new` are a row firing's row images; the result says whether the row
/// proceeds.
fn fire_builtin_trigger(
    builtin: crate::storage::BuiltinTriggerFunction,
    trigger: &crate::storage::TriggerDef,
    event: u8,
    old: Option<&[Datum<'_>]>,
    new: Option<&[Datum<'_>]>,
) -> Result<bool, SqlError> {
    match builtin {
        crate::storage::BuiltinTriggerFunction::SuppressRedundantUpdates => {
            // PostgreSQL's trigfuncs.c checks in this order.
            let violation = |message| {
                sql_err!(
                    sqlstate::TRIGGER_PROTOCOL_VIOLATED,
                    "suppress_redundant_updates_trigger: must be called {}",
                    message
                )
            };
            if event != TriggerEvents::UPDATE {
                return Err(violation("on update"));
            }
            if trigger.timing != crate::sql::ast::TriggerTiming::Before {
                return Err(violation("before update"));
            }
            if trigger.level != crate::sql::ast::TriggerLevel::Row {
                return Err(violation("for each row"));
            }
            let (Some(old), Some(new)) = (old, new) else {
                return Err(sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "row UPDATE trigger firing has no old or new row"
                ));
            };
            Ok(old.len() != new.len()
                || old
                    .iter()
                    .zip(new)
                    .any(|(old, new)| !same_stored_value(old, new)))
        }
    }
}

/// Whether two column values are stored identically, as PostgreSQL's
/// `suppress_redundant_updates_trigger` compares tuple bytes: `1.5` and
/// `1.50` differ, and so do `0` and `-0` as floats.
fn same_stored_value(left: &Datum<'_>, right: &Datum<'_>) -> bool {
    match (left, right) {
        (Datum::Float4(left), Datum::Float4(right)) => left.to_bits() == right.to_bits(),
        (Datum::Float8(left), Datum::Float8(right)) => left.to_bits() == right.to_bits(),
        // Numeric equality compares values; storage keeps the display scale.
        (Datum::Numeric(left), Datum::Numeric(right)) => {
            left.sign == right.sign
                && left.weight == right.weight
                && left.dscale == right.dscale
                && left.digits == right.digits
        }
        _ => left == right,
    }
}

#[expect(
    clippy::too_many_arguments,
    reason = "a trigger firing carries its complete typed transition context"
)]
fn execute_row_trigger_body<'a, Definition0: crate::storage::DefinitionBacking>(
    context: &mut TriggerExecContext<'_, 'a, '_>,
    slot: u16,
    trigger: &crate::storage::TriggerDef,
    target: crate::storage::TriggerTarget,
    definition: &crate::storage::TableDefinition<Definition0>,
    event: u8,
    before: bool,
    old: Option<&[Datum<'a>]>,
    new: &mut Option<&mut [Datum<'a>]>,
    transition_rows: Option<TransitionRows<'a>>,
) -> Result<bool, SqlError> {
    if let crate::storage::TriggerFunction::Builtin(builtin) = trigger.function {
        return fire_builtin_trigger(builtin, trigger, event, old, new.as_deref());
    }
    // A BEFORE or INSTEAD OF row trigger can move to the engine; an AFTER
    // row trigger fired here belongs to a write without completion handoff.
    let movable = (before && transition_rows.is_none()).then_some(engine_triggers::MovableFiring {
        slot,
        target,
        event,
    });
    engine_triggers::fire(context, movable, old, new, |context, new| {
        execute_row_trigger_body_here(
            context,
            trigger,
            target,
            definition,
            event,
            before,
            old,
            new,
            transition_rows,
        )
    })
}

#[expect(
    clippy::too_many_arguments,
    reason = "a trigger firing carries its complete typed transition context"
)]
fn execute_row_trigger_body_here<'a, Definition0: crate::storage::DefinitionBacking>(
    context: &mut TriggerExecContext<'_, 'a, '_>,
    trigger: &crate::storage::TriggerDef,
    target: crate::storage::TriggerTarget,
    definition: &crate::storage::TableDefinition<Definition0>,
    event: u8,
    before: bool,
    old: Option<&[Datum<'a>]>,
    new: &mut Option<&mut [Datum<'a>]>,
    transition_rows: Option<TransitionRows<'a>>,
) -> Result<bool, SqlError> {
    let mut firing_context = context.for_trigger();
    let context = &mut firing_context;
    let (table_schema, table_name) = match target {
        crate::storage::TriggerTarget::Table(table) => {
            let target_definition = context
                .storage()
                .table_def(usize::from(table), context.txn.txid);
            (target_definition.schema, target_definition.name)
        }
        crate::storage::TriggerTarget::View(_) => (definition.schema, definition.name),
    };
    let mut firing = prepare_trigger_firing(
        context,
        trigger,
        TriggerRelationIdentity {
            target,
            schema: table_schema,
            name: table_name,
        },
        crate::storage::RelationDefinition::from_definition(definition),
        event,
        before,
        old,
        new.as_deref_mut(),
        transition_rows,
    )?;
    // A trigger body's effects cannot be repeated by a restart, so the
    // enclosing write reads synchronously from here on. A resumable row
    // rolls them back with the row instead.
    super::query::protect_replayable_effect();
    firing.execute(context)
}

#[expect(
    clippy::too_many_arguments,
    reason = "selected trigger construction carries its exact row and relation bindings"
)]
fn prepare_trigger_firing<'values, 'schema, 'rows>(
    context: &TriggerExecContext<'_, 'values, '_>,
    trigger: &crate::storage::TriggerDef,
    relation: TriggerRelationIdentity,
    definition: crate::storage::RelationDefinition<'schema>,
    event: u8,
    before: bool,
    old: Option<&'rows [Datum<'values>]>,
    new: Option<&'rows mut [Datum<'values>]>,
    transition_rows: Option<TransitionRows<'values>>,
) -> Result<trigger_firing::TriggerFiring<'values, 'schema, 'rows>, SqlError> {
    let crate::storage::TriggerFunction::Routine(function) = trigger.function else {
        return Err(sql_err!(
            sqlstate::INTERNAL_ERROR,
            "built-in trigger function reached the routine firing path"
        ));
    };
    let routine = context
        .storage()
        .routine_for(usize::from(function), context.txn.txid);
    let owner = crate::storage::SessionIdentity::bound(context.storage().capture_role_slot(
        routine.ownership.owner_to(context.txn.txid).into(),
        context.txn.txid,
    )?);
    let security = routine
        .attributes
        .security_definer
        .then(|| super::eval::funcs::system::enter_current_user(owner));
    let config = (!routine.configs().is_empty())
        .then(|| {
            super::guc::enter_active_routine_configs(
                context.storage(),
                context.txn.txid,
                routine.configs(),
            )
        })
        .transpose()?;
    let (program, code) = compile_plpgsql_execution(
        routine.body.as_str(),
        PlpgsqlProgramKind::Trigger,
        context.storage(),
        context.txn.txid,
        context.arena,
        &|name| routine_parameter_type(&routine, name),
    )?;
    let invocation = TriggerInvocation::new(
        context.storage(),
        trigger,
        relation,
        event,
        &routine,
        program.settings(super::guc::active_plpgsql_settings()?),
        context.arena,
    )?
    .with_input_sites(program.input_sites);
    let transition_relations = trigger_transition_relations(
        context.storage(),
        context.txn.txid,
        trigger,
        definition,
        transition_rows,
        context.arena,
    )?;
    let invocation = TriggerInvocation {
        materialized_relations: transition_relations,
        ..invocation
    };
    // `OLD`, and `NEW` unless it is the caller's BEFORE row, are records
    // local to this invocation.
    let arena = context.arena;
    let width = definition.n_columns;
    let local_row = |row: Option<&[Datum<'values>]>| match row {
        Some(row) => arena.alloc_slice_copy(row),
        None => arena.alloc_slice_with(width, |_| Datum::Null),
    };
    let old_assigned = old.is_some();
    let old = local_row(old).map_err(|_| super::query::arena_full_pub())?;
    let (new, new_assigned, caller_new) = match new {
        Some(row) if before => (row, true, true),
        row => {
            let assigned = row.is_some();
            let row =
                local_row(row.map(|row| &*row)).map_err(|_| super::query::arena_full_pub())?;
            (row, assigned, false)
        }
    };
    trigger_firing::TriggerFiring::new(
        context,
        code,
        program.locals,
        trigger_firing::FiringBinding {
            invocation,
            definition,
            rows: trigger_firing::TriggerRows {
                old: trigger_firing::TriggerRecord::new(old, old_assigned),
                new: trigger_firing::TriggerRecord::new(new, new_assigned),
                before: before && trigger.level == TriggerLevel::Row,
            },
            caller_new,
            level: trigger.level,
        },
        call_environment::CallEnvironment::new(config, security),
    )
}

#[expect(
    clippy::too_many_arguments,
    reason = "partition bound resolution needs the typed parent layout and statement coercion context"
)]
fn resolve_partition_bound<Definition0: crate::storage::DefinitionBacking>(
    storage: &Storage,
    strategy: StoredPartitionStrategy,
    keys: [u16; crate::storage::MAX_PARTITION_KEYS],
    n_keys: u8,
    bound: PartitionBound,
    parent: &crate::storage::TableDefinition<Definition0>,
    txid: u32,
    arena: &Arena,
) -> Result<StoredPartitionBound, SqlError> {
    let constant =
        |expression: &Expr, column: usize| -> Result<crate::storage::OwnedDatum, SqlError> {
            let catalog = super::query::storage_catalog(storage, arena, txid);
            let hooks = EvalHooks {
                catalog: Some(&catalog),
                ..NO_HOOKS
            };
            let value = eval_assignment(
                expression,
                &parent.columns()[column],
                storage,
                txid,
                arena,
                crate::sql::eval::NO_PARAMS,
                &NoColumns,
                &hooks,
            )?;
            crate::storage::OwnedDatum::from_datum(&value)
        };
    match (strategy, bound) {
        (_, PartitionBound::Default) => Ok(StoredPartitionBound::Default),
        (StoredPartitionStrategy::Range, PartitionBound::Range { from, to }) => {
            if from.len() != usize::from(n_keys) || to.len() != usize::from(n_keys) {
                return Err(sql_err!(
                    sqlstate::INVALID_OBJECT_DEFINITION,
                    "partition bound must specify every partition key column"
                ));
            }
            let mut lower = [PartitionBoundValue::Value(crate::storage::OwnedDatum::Null);
                crate::storage::MAX_PARTITION_KEYS];
            let mut upper = lower;
            for i in 0..usize::from(n_keys) {
                lower[i] = partition_range_value(from[i], usize::from(keys[i]), &constant)?;
                upper[i] = partition_range_value(to[i], usize::from(keys[i]), &constant)?;
            }
            let resolved = StoredPartitionBound::Range {
                lower,
                upper,
                n_keys,
            };
            if compare_partition_bound_tuples(&lower, &upper, n_keys)? != core::cmp::Ordering::Less
            {
                return Err(sql_err!(
                    sqlstate::INVALID_OBJECT_DEFINITION,
                    "empty range bound specified for partition"
                ));
            }
            Ok(resolved)
        }
        (StoredPartitionStrategy::List, PartitionBound::List { values }) => {
            if values.len() > crate::storage::MAX_PARTITION_LIST_VALUES {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "LIST partition bound exceeds {} values",
                    crate::storage::MAX_PARTITION_LIST_VALUES
                ));
            }
            let mut out =
                [crate::storage::OwnedDatum::Null; crate::storage::MAX_PARTITION_LIST_VALUES];
            for (i, value) in values.iter().enumerate() {
                out[i] = constant(value, usize::from(keys[0]))?;
            }
            Ok(StoredPartitionBound::List {
                values: out,
                n_values: values.len() as u8,
            })
        }
        (StoredPartitionStrategy::Hash, PartitionBound::Hash { modulus, remainder }) => {
            let modulus = eval_full(
                modulus,
                arena,
                crate::sql::eval::NO_PARAMS,
                &NoColumns,
                &NO_HOOKS,
            )?;
            let remainder = eval_full(
                remainder,
                arena,
                crate::sql::eval::NO_PARAMS,
                &NoColumns,
                &NO_HOOKS,
            )?;
            let (Datum::Int4(modulus), Datum::Int4(remainder)) = (modulus, remainder) else {
                return Err(sql_err!(
                    sqlstate::INVALID_OBJECT_DEFINITION,
                    "hash partition modulus and remainder must be integers"
                ));
            };
            if modulus <= 0 || remainder < 0 || remainder >= modulus {
                return Err(sql_err!(
                    sqlstate::INVALID_OBJECT_DEFINITION,
                    "invalid hash partition modulus or remainder"
                ));
            }
            Ok(StoredPartitionBound::Hash {
                modulus: modulus as u32,
                remainder: remainder as u32,
            })
        }
        _ => Err(sql_err!(
            sqlstate::INVALID_OBJECT_DEFINITION,
            "partition bound does not match partition strategy"
        )),
    }
}

fn partition_range_value(
    expression: &Expr,
    column: usize,
    constant: &impl Fn(&Expr, usize) -> Result<crate::storage::OwnedDatum, SqlError>,
) -> Result<PartitionBoundValue, SqlError> {
    match expression {
        Expr::Column {
            qualifier: None,
            name: "minvalue",
        } => Ok(PartitionBoundValue::MinValue),
        Expr::Column {
            qualifier: None,
            name: "maxvalue",
        } => Ok(PartitionBoundValue::MaxValue),
        _ => Ok(PartitionBoundValue::Value(constant(expression, column)?)),
    }
}

/// A table gets one primary key. A column-level `PRIMARY KEY` sets the column's
/// flag directly and never reaches [`attach_constraints`], so two of them — or
/// one alongside a key copied by `LIKE ... INCLUDING INDEXES` — is only caught
/// by counting the assembled definition.
fn reject_multiple_primary<Definition0: crate::storage::DefinitionBacking>(
    def: &crate::storage::TableDefinition<Definition0>,
) -> Result<(), SqlError> {
    let declared = def.columns().iter().filter(|c| c.primary).count()
        + def.uniques.as_ref()[..def.n_uniques]
            .iter()
            .filter(|k| k.kind.is_primary())
            .count();
    if declared > 1 {
        return Err(sql_err!(
            crate::sql::eval::sqlstate::INVALID_TABLE_DEFINITION,
            "multiple primary keys for table \"{}\" are not allowed",
            def.name.as_str()
        ));
    }
    Ok(())
}

/// The source table of a `LIKE`, or PostgreSQL's undefined-table error.
fn like_source<'s>(
    storage: &'s Storage,
    like: &LikeClause,
    txid: u32,
) -> Result<crate::storage::TableDefinitionRead<'s>, SqlError> {
    match resolve_dml_table(storage, &like.source, txid) {
        Ok(i) => Ok(storage.table_def(i, txid)),
        Err(e) => Err(e),
    }
}

/// [`build_def`] with each `LIKE source` element's columns spliced in where it
/// was written. A copied column always keeps its name, type and NOT NULL; the
/// rest of its properties follow the element's `INCLUDING` flags.
fn build_def_with_likes(
    storage: &Storage,
    statement: &CreateTable,
    txid: u32,
    arena: &Arena,
) -> Result<TableDefBuilder, SqlError> {
    if statement.likes.is_empty() {
        return build_def(statement.name.name, statement.columns, storage, txid, arena);
    }
    let mut def = TableDefBuilder {
        name: SqlName::parse(statement.name.name)?,
        ..TableDefBuilder::empty()
    };
    let mut n = 0usize;
    for position in 0..=statement.columns.len() {
        for like in statement.likes.iter().filter(|l| l.at == position) {
            let source = like_source(storage, like, txid)?;
            for column in source.columns() {
                let mut copied = *column;
                if !like.defaults && !copied.default.is_generated() {
                    copied.default = crate::storage::ColumnDefault::NONE;
                }
                if !like.indexes {
                    copied.unique = false;
                    copied.primary = false;
                }
                if !like.identity {
                    copied.auto_increment = false;
                    copied.is_identity = false;
                    copied.identity_always = false;
                }
                // Without INCLUDING GENERATED a generated column is copied as a
                // plain column (its generation expression is dropped).
                if !like.generated && copied.default.is_generated() {
                    copied.default = crate::storage::ColumnDefault::NONE;
                }
                if !like.storage {
                    copied.storage = ddl::default_column_storage(copied.ctype);
                }
                if !like.compression {
                    copied.compression = crate::sql::ast::ColumnCompression::Default;
                }
                push_column(&mut def, &mut n, copied)?;
            }
        }
        if let Some(column) = statement.columns.get(position) {
            push_column(
                &mut def,
                &mut n,
                build_column(column, storage, txid, arena)?,
            )?;
            if let Some(name) = column.not_null_name {
                def.set_not_null_constraint_name(n - 1, SqlName::parse(name)?);
            }
        }
    }
    def.n_columns = n;
    Ok(def)
}

fn capture_default_inputs(
    storage: &Storage,
    raw: &str,
    stored: &str,
    section: crate::storage::StoredInputSection,
    txid: u32,
    arena: &Arena,
) -> Result<crate::storage::StoredTypeInputs, SqlError> {
    let inputs = super::type_inputs::bindings_for_active_source(raw, arena)?.unwrap_or(&[]);
    let display = super::enum_values::checks::default_display(stored, arena)?;
    let inputs = super::type_inputs::rebase(
        raw,
        display,
        super::parser::StoredSqlKind::Expression,
        inputs,
        |name| Ok(super::type_inputs::target_oid(storage, txid, name)),
        arena,
    )?;
    storage.capture_definition_type_inputs(
        &[crate::storage::StoredInputSource {
            section,
            sql: display,
            bindings: inputs,
        }],
        txid,
    )
}

fn capture_view_default_inputs(
    storage: &Storage,
    previous: &crate::storage::ViewDef,
    columns: &crate::storage::ViewColumns,
    changed: usize,
    raw: Option<&str>,
    txid: u32,
    arena: &Arena,
) -> Result<crate::storage::StoredTypeInputs, SqlError> {
    let prior = previous.default_inputs_for(txid).detached_sections(arena)?;
    let sources = arena
        .alloc_slice_with(columns.len(), |column| crate::storage::StoredInputSource {
            section: crate::storage::StoredInputSection::ViewDefault((column + 1) as u16),
            sql: "",
            bindings: &[],
        })
        .map_err(|_| arena_full())?;
    for (index, output) in sources.iter_mut().enumerate() {
        let Some(source) = columns.default_sql(index) else {
            continue;
        };
        output.sql = super::enum_values::checks::default_display(source, arena)?;
        let inputs = if index == changed {
            match raw {
                Some(raw) => {
                    super::type_inputs::bindings_for_active_source(raw, arena)?.unwrap_or(&[])
                }
                None => &[],
            }
        } else {
            prior
                .binary_search_by_key(&output.section, |(section, _)| *section)
                .ok()
                .map_or(&[][..], |index| prior[index].1)
        };
        let old = if index == changed {
            raw.unwrap_or("")
        } else {
            previous
                .columns_for(txid)
                .default_sql(index)
                .ok_or_else(|| {
                    sql_err!(sqlstate::INTERNAL_ERROR, "view default source is missing")
                })?
        };
        let old = super::enum_values::checks::default_display(old, arena)?;
        output.bindings = super::type_inputs::rebase(
            old,
            output.sql,
            super::parser::StoredSqlKind::Expression,
            inputs,
            |name| Ok(super::type_inputs::target_oid(storage, txid, name)),
            arena,
        )?;
    }
    storage.capture_definition_type_inputs(sources, txid)
}

fn capture_created_table_inputs(
    storage: &Storage,
    definition: &mut TableDefBuilder,
    statement: &CreateTable<'_>,
    txid: u32,
    arena: &Arena,
) -> Result<(), SqlError> {
    definition.attributes.initialize(definition.n_columns)?;
    let sources = arena
        .alloc_slice_with(definition.n_columns, |column| {
            crate::storage::StoredInputSource {
                section: crate::storage::StoredInputSection::TableDefault(
                    definition.attribute_number(column),
                ),
                sql: "",
                bindings: &[],
            }
        })
        .map_err(|_| arena_full())?;
    for (column, output) in sources.iter_mut().enumerate() {
        let metadata = definition.columns[column];
        if metadata.default.constant().is_some() || metadata.default.expression().is_none() {
            continue;
        }
        output.sql = super::enum_values::checks::default_display(
            metadata
                .default
                .expression()
                .expect("expression-backed default")
                .as_str(),
            arena,
        )?;
        if let Some(raw) = statement
            .columns
            .iter()
            .find(|declared| declared.name == metadata.name.as_str())
            .and_then(|declared| declared.default_text.or(declared.generated_text))
        {
            let inputs = super::type_inputs::bindings_for_active_source(raw, arena)?.unwrap_or(&[]);
            output.bindings = if raw == output.sql {
                inputs
            } else {
                super::type_inputs::rebase(
                    raw,
                    output.sql,
                    super::parser::StoredSqlKind::Expression,
                    inputs,
                    |name| Ok(super::type_inputs::target_oid(storage, txid, name)),
                    arena,
                )?
            };
            continue;
        }
        for like in statement
            .likes
            .iter()
            .filter(|like| like.defaults || like.generated)
        {
            let source = like_source(storage, like, txid)?;
            let Some(old_column) = source.column_index(metadata.name.as_str()) else {
                continue;
            };
            if source.columns()[old_column].default != metadata.default {
                continue;
            }
            output.bindings = source.type_inputs.detached_bindings(
                crate::storage::StoredInputSection::TableDefault(
                    source.attribute_number(old_column),
                ),
                arena,
            )?;
            break;
        }
        if !output.bindings.is_empty() {
            continue;
        }
        for parent in definition.inheritance.parents_ref() {
            let source = storage.table_def(usize::from(*parent), txid);
            let Some(old_column) = source.column_index(metadata.name.as_str()) else {
                continue;
            };
            if source.columns()[old_column].default != metadata.default {
                continue;
            }
            output.bindings = source.type_inputs.detached_bindings(
                crate::storage::StoredInputSection::TableDefault(
                    source.attribute_number(old_column),
                ),
                arena,
            )?;
            break;
        }
        if output.bindings.is_empty() {
            output.bindings = inherited_domain_default_inputs(storage, &metadata, txid, arena)?;
        }
    }
    sources.sort_unstable_by_key(|source| source.section);
    let inputs = storage.capture_definition_type_inputs(sources, txid)?;
    definition.type_inputs = inputs;
    Ok(())
}

fn inherited_domain_default_inputs<'a>(
    storage: &Storage,
    column: &ColumnMeta,
    txid: u32,
    arena: &'a Arena,
) -> Result<&'a [super::type_inputs::Binding<'a>], SqlError> {
    let Some((crate::storage::NamedTypeKind::Domain, creation, false)) = storage
        .routine_type_oid(column.ctype, column.user_type, txid)
        .and_then(crate::storage::NamedTypeKind::from_oid)
    else {
        return Ok(&[]);
    };
    let target = crate::storage::TypeDefinitionTarget::by_creation(
        storage,
        crate::storage::NamedTypeKind::Domain,
        creation,
    )?;
    let domain = storage
        .read_domain_definition(target, txid)?
        .ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "column default domain source is unavailable"
            )
        })?;
    if domain.default_expr.as_ref() != column.default.expression() {
        return Ok(&[]);
    }
    domain
        .default_inputs
        .detached_bindings(crate::storage::StoredInputSection::DomainDefault, arena)
}

#[derive(Clone, Copy)]
struct TableInputOverride<'a> {
    column: usize,
    source: &'a str,
    inputs: &'a [super::type_inputs::Binding<'a>],
}

fn record_table_input_override<'a>(
    overrides: &mut ArenaList<'a, TableInputOverride<'a>>,
    column: usize,
    source: &'a str,
    arena: &'a Arena,
) -> Result<(), SqlError> {
    let inputs = if source.is_empty() {
        &[][..]
    } else {
        super::type_inputs::bindings_for_active_source(source, arena)?.unwrap_or(&[])
    };
    overrides
        .push(TableInputOverride {
            column,
            source,
            inputs,
        })
        .map_err(|_| arena_full())
}

fn refresh_table_type_inputs(
    storage: &Storage,
    previous: &crate::storage::TableDefinition<impl crate::storage::DefinitionBacking>,
    definition: &mut TableDefBuilder,
    overrides: &[TableInputOverride<'_>],
    txid: u32,
    arena: &Arena,
) -> Result<(), SqlError> {
    if previous.type_inputs.as_ref().bytes().is_empty()
        && overrides.iter().all(|input| input.inputs.is_empty())
    {
        definition.type_inputs = crate::storage::StoredTypeInputs::EMPTY;
        return Ok(());
    }
    let previous_sections = previous.type_inputs.as_ref().borrowed_sections(arena)?;
    let sources = arena
        .alloc_slice_with(definition.n_columns, |column| {
            crate::storage::StoredInputSource {
                section: crate::storage::StoredInputSection::TableDefault(
                    definition.attribute_number(column),
                ),
                sql: "",
                bindings: &[],
            }
        })
        .map_err(|_| arena_full())?;
    for (column, output) in sources.iter_mut().enumerate() {
        let metadata = definition.columns[column];
        let Some(source) = metadata
            .default
            .expression()
            .filter(|_| metadata.default.constant().is_none())
        else {
            continue;
        };
        output.sql = super::enum_values::checks::default_display(source.as_str(), arena)?;
        let (old_source, inputs) = if let Some(input) =
            overrides.iter().rev().find(|input| input.column == column)
        {
            (input.source, input.inputs)
        } else if let Some(old_column) =
            previous.attribute_column(definition.attribute_number(column))
        {
            let Some(old) = previous.columns()[old_column].default.expression() else {
                output.bindings = inherited_domain_default_inputs(storage, &metadata, txid, arena)?;
                continue;
            };
            (
                super::enum_values::checks::default_display(old.as_str(), arena)?,
                previous_sections
                    .binary_search_by_key(&output.section, |(section, _)| *section)
                    .ok()
                    .map_or(&[][..], |index| previous_sections[index].1),
            )
        } else {
            output.bindings = inherited_domain_default_inputs(storage, &metadata, txid, arena)?;
            continue;
        };
        output.bindings = if old_source == output.sql {
            inputs
        } else {
            super::type_inputs::rebase(
                old_source,
                output.sql,
                super::parser::StoredSqlKind::Expression,
                inputs,
                |name| Ok(super::type_inputs::target_oid(storage, txid, name)),
                arena,
            )?
        };
    }
    sources.sort_unstable_by_key(|source| source.section);
    if previous.type_inputs.as_ref().matches_sources(sources)? {
        definition.type_inputs = previous.type_inputs.as_ref().clone();
    } else {
        definition.type_inputs = storage.capture_definition_type_inputs(sources, txid)?;
    }
    Ok(())
}

/// Appends one column, rejecting a name already taken.
fn push_column(
    def: &mut TableDefBuilder,
    n: &mut usize,
    column: ColumnMeta,
) -> Result<(), SqlError> {
    if *n == crate::storage::MAX_RELATION_COLUMNS {
        return Err(sql_err!(
            sqlstate::TOO_MANY_COLUMNS,
            "tables can have at most {} columns",
            crate::storage::MAX_RELATION_COLUMNS
        ));
    }
    if def.columns[..*n]
        .iter()
        .any(|prev| prev.name == column.name)
    {
        return Err(sql_err!(
            sqlstate::DUPLICATE_COLUMN,
            "column \"{}\" specified more than once",
            column.name.as_str()
        ));
    }
    def.columns[*n] = column;
    *n += 1;
    Ok(())
}

/// Copies the CHECK constraints and multi-column keys of each `LIKE` source
/// that asked for them. Foreign keys are never copied, as in PostgreSQL.
fn copy_like_constraints(
    storage: &Storage,
    def: &mut TableDefBuilder,
    statement: &CreateTable,
    txid: u32,
    arena: &Arena,
) -> Result<(), SqlError> {
    for like in statement.likes {
        let source = (*like_source(storage, like, txid)?).clone();
        if like.constraints {
            for check in &source.checks[..source.n_checks] {
                if def.n_checks == crate::storage::MAX_CHECKS {
                    return Err(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "a table can have at most {} CHECK constraints",
                        crate::storage::MAX_CHECKS
                    ));
                }
                ddl::require_convertible_check(&source, check, arena)?;
                let mut copied = *check;
                copied.identity = None;
                def.checks[def.n_checks] = copied;
                def.n_checks += 1;
            }
        }
        if like.indexes {
            for key in &source.uniques[..source.n_uniques] {
                let columns = remap_columns(def, &source, &key.columns[..key.n_cols])?;
                let name = auto_key_name(
                    storage,
                    def,
                    if key.kind.is_primary() {
                        &[]
                    } else {
                        &columns[..key.n_cols]
                    },
                    if key.kind.is_primary() { "pkey" } else { "key" },
                    txid,
                    None,
                    crate::storage::GeneratedNameClass::IndexConstraint,
                )?;
                add_unique_key(
                    def,
                    name,
                    &columns,
                    key.n_cols,
                    key.kind,
                    match key.timing {
                        crate::storage::ConstraintTiming::NotDeferrable => {
                            crate::sql::ast::ConstraintTiming::NotDeferrable
                        }
                        crate::storage::ConstraintTiming::DeferrableImmediate => {
                            crate::sql::ast::ConstraintTiming::Deferrable(
                                crate::sql::ast::ConstraintMode::Immediate,
                            )
                        }
                        crate::storage::ConstraintTiming::DeferrableDeferred => {
                            crate::sql::ast::ConstraintTiming::Deferrable(
                                crate::sql::ast::ConstraintMode::Deferred,
                            )
                        }
                    },
                )?;
            }
            for source_exclusion in source.exclusions() {
                if def.n_exclusions == crate::storage::MAX_EXCLUSIONS {
                    return Err(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "a table can have at most {} exclusion constraints",
                        crate::storage::MAX_EXCLUSIONS
                    ));
                }
                let columns = remap_columns(def, &source, source_exclusion.columns())?;
                let mut exclusion = *source_exclusion;
                exclusion.columns[..source_exclusion.n_cols]
                    .copy_from_slice(&columns[..source_exclusion.n_cols]);
                exclusion.name = auto_key_name(
                    storage,
                    def,
                    &columns[..source_exclusion.n_cols],
                    "excl",
                    txid,
                    None,
                    crate::storage::GeneratedNameClass::IndexConstraint,
                )?;
                def.exclusions[def.n_exclusions] = exclusion;
                def.n_exclusions += 1;
            }
        }
    }
    Ok(())
}

/// Maps column positions in `source` onto the new table, which may have shifted
/// them by preceding columns.
fn remap_columns<
    Definition0: crate::storage::DefinitionBacking,
    Definition1: crate::storage::DefinitionBacking,
>(
    def: &crate::storage::TableDefinition<Definition0>,
    source: &crate::storage::TableDefinition<Definition1>,
    columns: &[u16],
) -> Result<[u16; crate::storage::MAX_INDEX_COLS], SqlError> {
    let mut out = [0u16; crate::storage::MAX_INDEX_COLS];
    for (slot, &c) in out.iter_mut().zip(columns) {
        let name = source.columns()[c as usize].name.as_str();
        match def.column_index(name) {
            Some(i) => *slot = i as u16,
            None => {
                return Err(sql_err!(
                    sqlstate::UNDEFINED_COLUMN,
                    "column \"{}\" does not exist",
                    name
                ));
            }
        }
    }
    Ok(out)
}

/// One source index, captured before the mutable borrow that creates its copy.
#[derive(Clone, Copy)]
struct CopiedIndex {
    method: crate::sql::ast::IndexAccessMethod,
    columns: [u16; crate::storage::MAX_INDEX_COLS],
    expressions: [Option<crate::util::StackStr<{ crate::storage::INDEX_EXPRESSION_MAX }>>;
        crate::storage::MAX_INDEX_COLS],
    include_columns: [u16; crate::storage::MAX_INDEX_COLS],
    collations: [crate::sql::ast::Collation; crate::storage::MAX_INDEX_COLS],
    explicit_collations: [bool; crate::storage::MAX_INDEX_COLS],
    operator_classes: [Option<crate::storage::IndexOperatorClass>; crate::storage::MAX_INDEX_COLS],
    resolved_operator_classes:
        [Option<crate::storage::IndexOperatorClass>; crate::storage::MAX_INDEX_COLS],
    operator_class_options:
        [crate::storage::IndexOperatorClassOptions; crate::storage::MAX_INDEX_COLS],
    descending: [bool; crate::storage::MAX_INDEX_COLS],
    nulls_first: [bool; crate::storage::MAX_INDEX_COLS],
    n_cols: usize,
    n_include_cols: usize,
    nulls_not_distinct: bool,
    predicate: Option<crate::util::StackStr<{ crate::storage::INDEX_PREDICATE_MAX }>>,
    options: crate::storage::IndexStorageOptions,
    tablespace: u16,
    unique: bool,
    source_schema: SqlName,
    source_name: SqlName,
}

impl CopiedIndex {
    const EMPTY: Self = Self {
        method: crate::sql::ast::IndexAccessMethod::Btree,
        columns: [0; crate::storage::MAX_INDEX_COLS],
        expressions: [None; crate::storage::MAX_INDEX_COLS],
        include_columns: [0; crate::storage::MAX_INDEX_COLS],
        collations: [crate::sql::ast::Collation::Default; crate::storage::MAX_INDEX_COLS],
        explicit_collations: [false; crate::storage::MAX_INDEX_COLS],
        operator_classes: [None; crate::storage::MAX_INDEX_COLS],
        resolved_operator_classes: [None; crate::storage::MAX_INDEX_COLS],
        operator_class_options: [crate::storage::IndexOperatorClassOptions::DEFAULT;
            crate::storage::MAX_INDEX_COLS],
        descending: [false; crate::storage::MAX_INDEX_COLS],
        nulls_first: [false; crate::storage::MAX_INDEX_COLS],
        n_cols: 0,
        n_include_cols: 0,
        nulls_not_distinct: false,
        predicate: None,
        options: crate::storage::IndexStorageOptions::DEFAULT,
        tablespace: 0,
        unique: false,
        source_schema: SqlName::EMPTY,
        source_name: SqlName::EMPTY,
    };
}

/// Recreates secondary indexes through the shared creation and cleanup boundary.
fn copy_like_indexes<Definition0: crate::storage::DefinitionBacking>(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    statement: &CreateTable,
    def: &crate::storage::TableDefinition<Definition0>,
    arena: &Arena,
) -> Result<(), SqlError> {
    use crate::storage::IndexDef;
    let table_slot = storage
        .find_visible(def.schema.as_str(), def.name.as_str(), txn.txid)
        .expect("new LIKE table is visible to its creator");
    for like in statement.likes.iter().filter(|l| l.indexes) {
        // Collected up front: creating one needs `storage` mutably.
        let source_def = (*storage.table_def(
            resolve_dml_table(storage, &like.source, txn.txid)?,
            txn.txid,
        ))
        .clone();
        let source_index_count = storage
            .indexes_for(
                source_def.schema.as_str(),
                source_def.name.as_str(),
                txn.txid,
            )
            .count();
        let copied = arena
            .alloc_slice_with(source_index_count, |_| CopiedIndex::EMPTY)
            .map_err(|_| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "LIKE indexes exceed the statement arena"
                )
            })?;
        for (copy, index) in copied.iter_mut().zip(storage.indexes_for(
            source_def.schema.as_str(),
            source_def.name.as_str(),
            txn.txid,
        )) {
            ddl::require_convertible_index(
                &source_def,
                &index,
                index.name_for(txn.txid).as_str(),
                arena,
            )?;
            *copy = CopiedIndex {
                method: index.method,
                columns: index.columns,
                expressions: index.expressions,
                include_columns: index.include_columns,
                collations: index.collations,
                explicit_collations: index.explicit_collations,
                operator_classes: index.operator_classes,
                resolved_operator_classes: index.resolved_operator_classes,
                operator_class_options: index.operator_class_options,
                descending: index.descending,
                nulls_first: index.nulls_first,
                n_cols: index.n_cols,
                n_include_cols: index.n_include_cols,
                nulls_not_distinct: index.nulls_not_distinct,
                predicate: index.predicate,
                options: index.mutable_for(txn.txid).options,
                tablespace: index.mutable_for(txn.txid).tablespace,
                unique: index.unique,
                source_schema: index.schema,
                source_name: index.name_for(txn.txid),
            };
        }
        let source = source_def;
        for index in copied {
            let columns = remap_columns(def, &source, &index.columns[..index.n_cols])?;
            let include_columns =
                remap_columns(def, &source, &index.include_columns[..index.n_include_cols])?;
            // `generateClonedIndexStmt` keeps the source index's column names.
            let name = copied_index_name(
                storage,
                def,
                &index.expressions[..index.n_cols],
                &columns[..index.n_cols],
                &include_columns[..index.n_include_cols],
                txn.txid,
                arena,
            )?;
            let slot = storage.create_index(
                IndexDef {
                    database: storage.current_database_oid(),
                    created_at: 0,
                    schema: def.schema,
                    name,
                    pending_name: None,
                    table: def.name,
                    relation: crate::storage::IndexRelationSource::Table,
                    table_binding: None,
                    pending_table: None,
                    method: index.method,
                    ownership: crate::storage::Ownership::BOOTSTRAP,
                    columns,
                    expressions: index.expressions,
                    include_columns,
                    collations: index.collations,
                    explicit_collations: index.explicit_collations,
                    operator_classes: index.operator_classes,
                    resolved_operator_classes: index.resolved_operator_classes,
                    operator_class_options: index.operator_class_options,
                    descending: index.descending,
                    nulls_first: index.nulls_first,
                    n_cols: index.n_cols,
                    n_include_cols: index.n_include_cols,
                    nulls_not_distinct: index.nulls_not_distinct,
                    predicate: index.predicate,
                    unique: index.unique,
                    mutable: crate::storage::IndexMutableDefinition {
                        options: index.options,
                        tablespace: index.tablespace,
                        ..crate::storage::IndexMutableDefinition::DEFAULT
                    },
                    pending_definition: None,
                    ddl_state: crate::storage::CatalogDdlState::Present,
                    pending_parent_drop_txid: None,
                },
                txn.txid,
            )?;
            finish_index_creation(storage, wal, txn, slot, table_slot, arena)?;
            if like.comments {
                copy_comment_if_present(
                    storage,
                    wal,
                    txn,
                    CommentIdentity {
                        class: crate::storage::CommentClass::Relation,
                        schema: index.source_schema,
                        name: index.source_name,
                        subid: 0,
                    },
                    CommentIdentity {
                        class: crate::storage::CommentClass::Relation,
                        schema: def.schema,
                        name,
                        subid: 0,
                    },
                )?;
            }
        }
    }
    Ok(())
}

fn copy_like_statistics<Definition0: crate::storage::DefinitionBacking>(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    statement: &CreateTable,
    target: &crate::storage::TableDefinition<Definition0>,
    target_slot: usize,
    arena: &Arena,
) -> Result<(), SqlError> {
    use crate::sql::ast::{StatisticsExpression, StatisticsKey};
    use crate::storage::{ExtendedStatisticsSpec, MAX_EXTENDED_STATISTICS_KEYS};

    for like in statement.likes.iter().filter(|like| like.statistics) {
        let source_slot = resolve_dml_table(storage, &like.source, txn.txid)?;
        let source_capacity = storage.extended_statistics_count();
        for source_statistics_slot in 0..source_capacity {
            let source = storage.extended_statistics(source_statistics_slot);
            if !source.visible_to(txn.txid) || usize::from(source.table) != source_slot {
                continue;
            }
            let definition = source.definition_for(txn.txid);
            let mut keys = [StatisticsKey::Column(""); MAX_EXTENDED_STATISTICS_KEYS];
            for (position, key) in source.keys_for(txn.txid).iter().enumerate() {
                keys[position] = match key {
                    crate::storage::ExtendedStatisticsKey::Column(column) => {
                        StatisticsKey::Column(column.as_str())
                    }
                    crate::storage::ExtendedStatisticsKey::Expression(source) => {
                        StatisticsKey::Expression(StatisticsExpression {
                            expression: crate::sql::parser::parse_expr(source.as_str(), arena)?,
                            source: source.as_str(),
                        })
                    }
                };
            }
            let name = generated_statistics_name(
                storage,
                target,
                &keys[..usize::from(source.n_keys)],
                txn.txid,
            )?;
            let slot = storage.create_extended_statistics(
                ExtendedStatisticsSpec {
                    creation: crate::storage::CatalogCreation::New,
                    schema: target.schema,
                    name,
                    table: target_slot as u16,
                    target: definition.target,
                    keys: source.keys,
                    n_keys: source.n_keys,
                    kinds: source.kinds,
                    expression_only: source.expression_only,
                },
                txn.txid,
            )?;
            if let Err(error) = stage_extended_statistics_definition(storage, wal, txn, slot) {
                storage.rollback_extended_statistics_create(slot);
                return Err(error);
            }
            if let Err(error) =
                txn.record_ddl(storage, super::txn::DdlUndo::StatisticsCreated(slot as u32))
            {
                storage.rollback_extended_statistics_create(slot);
                return Err(error);
            }
            if like.comments {
                copy_comment_if_present(
                    storage,
                    wal,
                    txn,
                    CommentIdentity {
                        class: crate::storage::CommentClass::Statistics,
                        schema: definition.schema,
                        name: definition.name,
                        subid: storage
                            .extended_statistics(source_statistics_slot)
                            .creation()
                            .get(),
                    },
                    CommentIdentity {
                        class: crate::storage::CommentClass::Statistics,
                        schema: target.schema,
                        name,
                        subid: storage.extended_statistics(slot).creation().get(),
                    },
                )?;
            }
        }
    }
    Ok(())
}

/// Copies the comment kinds PostgreSQL defines for `LIKE`: copied columns,
/// CHECK constraints, and copied NOT NULL constraints. Index and statistics
/// comments are staged alongside those catalog objects as they are created.
fn copy_like_comments<Definition0: crate::storage::DefinitionBacking>(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    statement: &CreateTable,
    target: &crate::storage::TableDefinition<Definition0>,
    target_slot: usize,
) -> Result<(), SqlError> {
    use crate::storage::CommentClass;

    let mut target_check = 0usize;
    for like in statement.likes {
        let source_slot = resolve_dml_table(storage, &like.source, txn.txid)?;
        let source = (*storage.table_def(source_slot, txn.txid)).clone();
        if like.comments {
            for column in 0..source.n_columns {
                let subid = u32::from(source.attribute_number(column));
                let source_comment = storage.comment_text(
                    CommentClass::Relation,
                    source.schema.as_str(),
                    source.name.as_str(),
                    subid,
                    txn.txid,
                );
                let Some(text) = source_comment else {
                    continue;
                };
                let source_column = source.columns()[column].name.as_str();
                let target_column = target.column_index(source_column).ok_or_else(|| {
                    sql_err!(
                        sqlstate::UNDEFINED_COLUMN,
                        "column \"{}\" does not exist",
                        source_column
                    )
                })?;
                let target_subid = u32::from(target.attribute_number(target_column));
                stage_comment(
                    storage,
                    wal,
                    txn,
                    CommentIdentity {
                        class: CommentClass::Relation,
                        schema: target.schema,
                        name: target.name,
                        subid: target_subid,
                    },
                    Some(text.as_str()),
                )?;
            }
        }
        if like.constraints {
            for check in source.checks() {
                let copied = target.checks().get(target_check).ok_or_else(|| {
                    sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "copied CHECK constraint is missing from target table"
                    )
                })?;
                target_check += 1;
                if like.comments {
                    copy_comment_if_present(
                        storage,
                        wal,
                        txn,
                        CommentIdentity {
                            class: CommentClass::Constraint,
                            schema: source.schema,
                            name: check.name,
                            subid: source_slot as u32,
                        },
                        CommentIdentity {
                            class: CommentClass::Constraint,
                            schema: target.schema,
                            name: copied.name,
                            subid: target_slot as u32,
                        },
                    )?;
                }
            }
        }
        if !like.comments {
            continue;
        }
        for source_column in source
            .columns()
            .iter()
            .filter(|column| column.not_null.is_required())
        {
            let target_column = target
                .column_index(source_column.name.as_str())
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::UNDEFINED_COLUMN,
                        "column \"{}\" does not exist",
                        source_column.name.as_str()
                    )
                })?;
            let source_name = source.not_null_names[source
                .column_index(source_column.name.as_str())
                .expect("source column exists")]
            .expect("required source column has a durable constraint name");
            let target_name = target.not_null_names.as_ref()[target_column]
                .expect("required target column has a durable constraint name");
            copy_comment_if_present(
                storage,
                wal,
                txn,
                CommentIdentity {
                    class: CommentClass::Constraint,
                    schema: source.schema,
                    name: source_name,
                    subid: source_slot as u32,
                },
                CommentIdentity {
                    class: CommentClass::Constraint,
                    schema: target.schema,
                    name: target_name,
                    subid: target_slot as u32,
                },
            )?;
        }
    }
    Ok(())
}

fn copy_comment_if_present(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    source: CommentIdentity,
    target: CommentIdentity,
) -> Result<(), SqlError> {
    let Some(text) = storage.comment_text(
        source.class,
        source.schema.as_str(),
        source.name.as_str(),
        source.subid,
        txn.txid,
    ) else {
        return Ok(());
    };
    stage_comment(storage, wal, txn, target, Some(text.as_str()))
}

/// The next value of a serial/identity column: a real sequence, as PostgreSQL
/// has it. Explicit inserts do not advance it, deletes and TRUNCATE do not
/// rewind it, and the advance survives a rollback (a consumed number stays
/// consumed). Recovery restores saved generator positions without inferring
/// them from stored row values.
fn next_auto_value<'x>(
    storage: &mut Storage,
    table_index: usize,
    col: usize,
    ctype: ColType,
    seq_session: &crate::sql::guc::SeqSession,
    txid: u32,
) -> Result<Datum<'x>, SqlError> {
    let def = storage.table_def(table_index, txid);
    let column = &def.columns()[col];
    if let Some(slot) = storage.generated_sequence_slot(
        def.schema.as_str(),
        def.name.as_str(),
        column.name.as_str(),
        crate::storage::GeneratedSequenceScope::PartitionRoot,
        txid,
    ) {
        let next = crate::sql::sequence::next_cached(storage, seq_session, slot, txid)?;
        return match ctype {
            ColType::Int8 => Ok(Datum::Int8(next)),
            ColType::Int2 => i16::try_from(next)
                .map(Datum::Int2)
                .map_err(|_| sql_err!(sqlstate::NUMERIC_OUT_OF_RANGE, "smallint out of range")),
            _ => i32::try_from(next)
                .map(Datum::Int4)
                .map_err(|_| sql_err!(sqlstate::NUMERIC_OUT_OF_RANGE, "integer out of range")),
        };
    }
    Err(sql_err!(
        sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
        "generated column \"{}\" has no generator sequence",
        column.name.as_str()
    ))
}

/// The unique constraint or index an `ON CONFLICT` clause arbitrates on.
/// `Any` (no target, DO NOTHING) treats a violation of *any* unique constraint
/// as the conflict; `Keys` restricts the conflict to rows equal on exactly
/// this column set, so a violation of a *different* unique falls through to a
/// normal 23505 — matching PostgreSQL, which uses the arbiter index alone.
#[expect(
    clippy::large_enum_variant,
    reason = "the fixed index-column array is bounded and cannot allocate after startup"
)]
enum Arbiter<'a> {
    Any,
    Keys {
        columns: [u16; crate::storage::MAX_INDEX_COLS],
        expressions: [Option<&'a Expr<'a>>; crate::storage::MAX_INDEX_COLS],
        n_columns: usize,
        nulls_not_distinct: bool,
    },
}

impl<'a> Arbiter<'a> {
    fn for_physical<
        Definition0: crate::storage::DefinitionBacking,
        Definition1: crate::storage::DefinitionBacking,
    >(
        &self,
        logical: &crate::storage::TableDefinition<Definition0>,
        physical: &crate::storage::TableDefinition<Definition1>,
    ) -> Result<Self, SqlError> {
        Ok(match self {
            Self::Any => Self::Any,
            Self::Keys {
                columns,
                expressions,
                n_columns,
                nulls_not_distinct,
            } => Self::Keys {
                columns: remap_columns(physical, logical, &columns[..*n_columns])?,
                expressions: *expressions,
                n_columns: *n_columns,
                nulls_not_distinct: *nulls_not_distinct,
            },
        })
    }
}

fn same_index_expression(stored: &str, target: &str) -> bool {
    let target = target.trim();
    stored == target
        || (target.starts_with('(')
            && target.ends_with(')')
            && stored == target[1..target.len() - 1].trim())
}

#[derive(Clone, Copy)]
struct PartialArbiter<'a> {
    columns: [u16; crate::storage::MAX_INDEX_COLS],
    expressions: [Option<&'a Expr<'a>>; crate::storage::MAX_INDEX_COLS],
    n_columns: usize,
    nulls_not_distinct: bool,
    predicate: Option<&'a Expr<'a>>,
}

/// Does some unique constraint/index on `def` cover exactly `want` (as a set,
/// order-independent)? Validates an `ON CONFLICT (columns)` inference target.
fn unique_arbiter_matches<Definition0: crate::storage::DefinitionBacking>(
    storage: &Storage,
    def: &crate::storage::TableDefinition<Definition0>,
    want: &[u16],
    txid: u32,
) -> Option<bool> {
    let same = |cols: &[u16]| cols.len() == want.len() && want.iter().all(|w| cols.contains(w));
    let mut matched = false;
    for (i, c) in def.columns().iter().enumerate() {
        if c.unique && same(&[i as u16]) {
            matched = true;
        }
    }
    for uk in def.uniques() {
        if !uk.timing.is_deferrable() && same(uk.columns()) {
            matched = true;
            if uk.kind.nulls_not_distinct() {
                return Some(true);
            }
        }
    }
    for index in storage
        .unique_indexes_for(def.schema.as_str(), def.name.as_str(), txid)
        .filter(|index| index.mutable_for(txid).immediate)
    {
        if index.predicate.is_none() && same(&index.columns[..index.n_cols]) {
            matched = true;
            if index.nulls_not_distinct {
                return Some(true);
            }
        }
    }
    matched.then_some(false)
}

/// Resolves `ON CONSTRAINT name` to the named immediate UNIQUE/PRIMARY KEY.
/// A unique index is inferable by its definition but is not a constraint.
fn arbiter_by_name<Definition0: crate::storage::DefinitionBacking>(
    def: &crate::storage::TableDefinition<Definition0>,
    name: &str,
) -> Result<Option<([u16; crate::storage::MAX_INDEX_COLS], usize, bool)>, SqlError> {
    let mut cols = [0u16; crate::storage::MAX_INDEX_COLS];
    for uk in def.uniques() {
        if uk.name.as_str() == name {
            if uk.timing.is_deferrable() {
                return Err(sql_err!(
                    sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                    "ON CONFLICT does not support deferrable unique constraints as arbiters"
                ));
            }
            let n = uk.n_cols;
            cols[..n].copy_from_slice(uk.columns());
            return Ok(Some((cols, n, uk.kind.nulls_not_distinct())));
        }
    }
    for (i, metadata) in def.columns().iter().enumerate() {
        if (metadata.primary || metadata.unique)
            && def
                .column_key_name(i)
                .is_some_and(|stored| stored.as_str() == name)
        {
            cols[0] = i as u16;
            return Ok(Some((cols, 1, false)));
        }
    }
    Ok(None)
}

/// Resolves an `ON CONFLICT` clause's arbiter, raising PostgreSQL's analysis
/// errors (a data-independent step: it runs even when no row conflicts).
fn resolve_arbiter<'a, Definition0: crate::storage::DefinitionBacking>(
    storage: &Storage,
    def: &crate::storage::TableDefinition<Definition0>,
    oc: &super::ast::OnConflict<'a>,
    txid: u32,
) -> Result<Arbiter<'a>, SqlError> {
    if let Some(assignments) = oc.update {
        for (name, expression) in assignments {
            let column = def.column_index(name).ok_or_else(|| {
                sql_err!(
                    sqlstate::UNDEFINED_COLUMN,
                    "column \"{}\" does not exist",
                    name
                )
            })?;
            if !matches!(expression, Expr::DefaultMarker) {
                reject_generated_write(def, column)?;
            }
        }
    }
    if !oc.target.is_empty() {
        if oc.target.iter().any(|target| target.column.is_none()) {
            for index in storage
                .unique_indexes_for(def.schema.as_str(), def.name.as_str(), txid)
                .filter(|index| index.mutable_for(txid).immediate)
            {
                if index.predicate.is_some() || index.n_cols != oc.target.len() {
                    continue;
                }
                let mut expressions = [None; crate::storage::MAX_INDEX_COLS];
                let matches = oc.target.iter().enumerate().all(|(position, target)| {
                    expressions[position] = target.column.map_or(Some(target.expression), |_| None);
                    match (target.column, index.expressions[position]) {
                        (Some(column), None) => {
                            def.column_index(column) == Some(index.columns[position] as usize)
                        }
                        (None, Some(source)) => {
                            same_index_expression(source.as_str(), target.expression_text)
                        }
                        _ => false,
                    }
                });
                if matches {
                    return Ok(Arbiter::Keys {
                        columns: index.columns,
                        expressions,
                        n_columns: index.n_cols,
                        nulls_not_distinct: index.nulls_not_distinct,
                    });
                }
            }
            return Err(sql_err!(
                sqlstate::INVALID_COLUMN_REFERENCE,
                "there is no unique or exclusion constraint matching the ON CONFLICT specification"
            ));
        }
        let mut want = [0u16; crate::storage::MAX_INDEX_COLS];
        let mut n = 0;
        let mut expressions = [None; crate::storage::MAX_INDEX_COLS];
        for target in oc.target {
            let Some(name) = target.column else {
                return Err(sql_err!(
                    sqlstate::INVALID_COLUMN_REFERENCE,
                    "there is no unique or exclusion constraint matching the ON CONFLICT specification"
                ));
            };
            let Some(index) = def.column_index(name) else {
                return Err(sql_err!(
                    sqlstate::UNDEFINED_COLUMN,
                    "column \"{}\" does not exist",
                    name
                ));
            };
            if n == crate::storage::MAX_INDEX_COLS {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "ON CONFLICT target has too many columns"
                ));
            }
            want[n] = index as u16;
            expressions[n] = None;
            n += 1;
        }
        if let Some(nulls_not_distinct) = unique_arbiter_matches(storage, def, &want[..n], txid) {
            return Ok(Arbiter::Keys {
                columns: want,
                expressions,
                n_columns: n,
                nulls_not_distinct,
            });
        }
        return Err(sql_err!(
            sqlstate::INVALID_COLUMN_REFERENCE,
            "there is no unique or exclusion constraint matching the ON CONFLICT specification"
        ));
    }
    if let Some(cname) = oc.constraint {
        if let Some((cols, n, nulls_not_distinct)) = arbiter_by_name(def, cname)? {
            return Ok(Arbiter::Keys {
                columns: cols,
                expressions: [None; crate::storage::MAX_INDEX_COLS],
                n_columns: n,
                nulls_not_distinct,
            });
        }
        return Err(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "constraint \"{}\" for table \"{}\" does not exist",
            cname,
            def.name.as_str()
        ));
    }
    if oc.update.is_some() {
        return Err(sql_err!(
            sqlstate::SYNTAX_ERROR,
            "ON CONFLICT DO UPDATE requires inference specification or constraint name"
        ));
    }
    Ok(Arbiter::Any)
}

#[derive(Clone, Copy)]
enum ConflictRowOrigin {
    Committed(u64),
    OwnCommand(u32),
}

struct ConflictRow<'arena> {
    rowid: u64,
    selected: PhysicalRow,
    origin: ConflictRowOrigin,
    bytes: &'arena [u8],
}

/// Captures the matched current row before releasing its original byte owner.
/// Ordinary query snapshots do not govern unique-key conflict detection.
#[allow(clippy::too_many_arguments)]
fn find_conflict<'a, Definition0: crate::storage::DefinitionBacking>(
    storage: &Storage,
    table_index: usize,
    def: &crate::storage::TableDefinition<Definition0>,
    schema: &[ColType],
    values: &[Datum],
    arbiter: &Arbiter<'a>,
    txid: u32,
    arena: &'a Arena,
) -> Result<Option<ConflictRow<'a>>, SqlError> {
    let partial_count = storage
        .unique_indexes_for(def.schema.as_str(), def.name.as_str(), txid)
        .filter(|index| index.mutable_for(txid).immediate)
        .filter(|index| {
            index.predicate.is_some()
                || index.expressions[..index.n_cols]
                    .iter()
                    .any(Option::is_some)
        })
        .count();
    let partial = arena
        .alloc_slice_with(partial_count, |_| None::<PartialArbiter<'a>>)
        .map_err(|_| crate::sql::eval::arena_full())?;
    let mut next_partial = 0usize;
    for index in storage
        .unique_indexes_for(def.schema.as_str(), def.name.as_str(), txid)
        .filter(|index| index.mutable_for(txid).immediate)
    {
        if index.predicate.is_none()
            && index.expressions[..index.n_cols]
                .iter()
                .all(Option::is_none)
        {
            continue;
        }
        let mut columns = [0u16; crate::storage::MAX_INDEX_COLS];
        columns[..index.n_cols].copy_from_slice(&index.columns[..index.n_cols]);
        let mut expressions = [None; crate::storage::MAX_INDEX_COLS];
        for (position, source) in index.expressions.iter().enumerate().take(index.n_cols) {
            if let Some(source) = source {
                let source = arena
                    .alloc_str(source.as_str())
                    .map_err(|_| crate::sql::eval::arena_full())?;
                expressions[position] = Some(crate::sql::parser::parse_expr(source, arena)?);
            }
        }
        let predicate = match index.predicate {
            Some(source) => {
                let source = arena
                    .alloc_str(source.as_str())
                    .map_err(|_| crate::sql::eval::arena_full())?;
                Some(crate::sql::parser::parse_expr(source, arena)?)
            }
            None => None,
        };
        partial[next_partial] = Some(PartialArbiter {
            columns,
            expressions,
            n_columns: index.n_cols,
            nulls_not_distinct: index.nulls_not_distinct,
            predicate,
        });
        next_partial += 1;
    }
    let mut found = None;
    let read = storage.validation_read();
    read.for_each_row_state(
        storage,
        table_index,
        &mut |rowid: u64, state: crate::storage::RowRead<'_>| {
            use core::ops::ControlFlow;
            crate::sql::query::check_timeout()?;
            let pending = state.pending_last();
            let Some(home) = read.visible_row_home(storage, table_index, rowid, state, txid)?
            else {
                return Ok(ControlFlow::Continue(()));
            };
            let origin = match home.snapshot().committed_lsn() {
                Some(lsn) => ConflictRowOrigin::Committed(lsn),
                None => ConflictRowOrigin::OwnCommand(
                    pending
                        .filter(|pending| pending.txid == txid)
                        .ok_or_else(|| {
                            sql_err!(
                                sqlstate::INTERNAL_ERROR,
                                "conflict row has no owning command"
                            )
                        })?
                        .cid,
                ),
            };
            let selected = PhysicalRow::local(table_index, rowid, home.snapshot());
            let matched = storage.with_row_bytes(table_index, rowid, home, |bytes| {
                // Index expression results never escape this evaluation. Original
                // bytes belong to a heap owner or spill scratch outside the arena.
                let mark = arena.mark();
                let hit = (|| -> Result<bool, SqlError> {
                    let mut other = [Datum::Null; MAX_COLUMNS];
                    rowenc::decode(bytes, schema, &mut other)?;
                    let key_hit = |cols: &[u16], nulls_not_distinct: bool| {
                        for &column in cols {
                            let column = column as usize;
                            if values[column].is_null() || other[column].is_null() {
                                if nulls_not_distinct
                                    && values[column].is_null()
                                    && other[column].is_null()
                                {
                                    continue;
                                }
                                return Ok(false);
                            }
                            if !compare_datums_collated(
                                storage,
                                txid,
                                def.columns()[column].collation,
                                &values[column],
                                &other[column],
                            )?
                            .is_eq()
                            {
                                return Ok(false);
                            }
                        }
                        Ok(true)
                    };
                    match arbiter {
                        // A named/inferred arbiter conflicts on its own columns only.
                        Arbiter::Keys {
                            columns,
                            expressions,
                            n_columns,
                            nulls_not_distinct,
                        } => {
                            if expressions[..*n_columns].iter().all(Option::is_none) {
                                key_hit(&columns[..*n_columns], *nulls_not_distinct)
                            } else {
                                let keys = crate::sql::exec::constraints::index_key_values(
                                    storage,
                                    txid,
                                    def,
                                    values,
                                    &columns[..*n_columns],
                                    &expressions[..*n_columns],
                                    arena,
                                )?;
                                let other_keys = crate::sql::exec::constraints::index_key_values(
                                    storage,
                                    txid,
                                    def,
                                    &other,
                                    &columns[..*n_columns],
                                    &expressions[..*n_columns],
                                    arena,
                                )?;
                                let collations =
                                    crate::sql::exec::constraints::index_key_collations(
                                        storage,
                                        txid,
                                        def,
                                        &columns[..*n_columns],
                                        &expressions[..*n_columns],
                                        arena,
                                    )?;
                                crate::sql::exec::constraints::key_values_equal(
                                    storage,
                                    txid,
                                    &collations[..*n_columns],
                                    &keys[..*n_columns],
                                    &other_keys[..*n_columns],
                                    *nulls_not_distinct,
                                )
                            }
                        }
                        // No target (DO NOTHING): any unique violation is a conflict.
                        Arbiter::Any => {
                            for (i, c) in def.columns().iter().enumerate() {
                                if c.unique && key_hit(&[i as u16], false)? {
                                    return Ok(true);
                                }
                            }
                            for uk in def.uniques() {
                                if !uk.timing.is_deferrable()
                                    && key_hit(uk.columns(), uk.kind.nulls_not_distinct())?
                                {
                                    return Ok(true);
                                }
                            }
                            for index in storage
                                .unique_indexes_for(def.schema.as_str(), def.name.as_str(), txid)
                                .filter(|index| index.mutable_for(txid).immediate)
                            {
                                if index.predicate.is_none()
                                    && index.expressions[..index.n_cols]
                                        .iter()
                                        .all(Option::is_none)
                                    && key_hit(
                                        &index.columns[..index.n_cols],
                                        index.nulls_not_distinct,
                                    )?
                                {
                                    return Ok(true);
                                }
                            }
                            for partial_index in partial.iter().flatten() {
                                let candidate_member =
                                    partial_index.predicate.map_or(Ok(true), |predicate| {
                                        crate::sql::exec::constraints::index_predicate_matches(
                                            storage, txid, def, values, predicate, arena,
                                        )
                                    })?;
                                let other_member =
                                    partial_index.predicate.map_or(Ok(true), |predicate| {
                                        crate::sql::exec::constraints::index_predicate_matches(
                                            storage, txid, def, &other, predicate, arena,
                                        )
                                    })?;
                                let candidate_keys =
                                    crate::sql::exec::constraints::index_key_values(
                                        storage,
                                        txid,
                                        def,
                                        values,
                                        &partial_index.columns[..partial_index.n_columns],
                                        &partial_index.expressions[..partial_index.n_columns],
                                        arena,
                                    )?;
                                let other_keys = crate::sql::exec::constraints::index_key_values(
                                    storage,
                                    txid,
                                    def,
                                    &other,
                                    &partial_index.columns[..partial_index.n_columns],
                                    &partial_index.expressions[..partial_index.n_columns],
                                    arena,
                                )?;
                                let collations =
                                    crate::sql::exec::constraints::index_key_collations(
                                        storage,
                                        txid,
                                        def,
                                        &partial_index.columns[..partial_index.n_columns],
                                        &partial_index.expressions[..partial_index.n_columns],
                                        arena,
                                    )?;
                                if candidate_member
                                    && other_member
                                    && crate::sql::exec::constraints::key_values_equal(
                                        storage,
                                        txid,
                                        &collations[..partial_index.n_columns],
                                        &candidate_keys[..partial_index.n_columns],
                                        &other_keys[..partial_index.n_columns],
                                        partial_index.nulls_not_distinct,
                                    )?
                                {
                                    return Ok(true);
                                }
                            }
                            Ok(false)
                        }
                    }
                })();
                // SAFETY: only a Boolean or owned error escapes expression work.
                unsafe { arena.rewind_to(mark) };
                if !hit? {
                    return Ok(None);
                }
                if let Some(pending) = pending.filter(|pending| pending.txid != txid) {
                    storage.wait_for_transaction(txid, pending.txid)?;
                    return Err(sql_err!(
                        sqlstate::INTERNAL_LOCK_WAIT,
                        "statement is waiting for a concurrent conflict-row writer"
                    ));
                }
                let retained = arena.alloc_slice_copy(bytes).map_err(|_| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "ON CONFLICT row exceeds the statement arena"
                    )
                })?;
                Ok(Some(&*retained))
            })?;
            if let Some(bytes) = matched {
                found = Some(ConflictRow {
                    rowid,
                    selected,
                    origin,
                    bytes,
                });
                return Ok(ControlFlow::Break(()));
            }
            Ok(ControlFlow::Continue(()))
        },
    )?;
    Ok(found)
}

/// Column lookup for ON CONFLICT DO UPDATE: `excluded.<col>` resolves to the
/// proposed row, target columns to the conflicting row, and trigger scope
/// names to the arena-owned outer snapshot.
struct ExcludedCtx<'o, 's, 'e, 'x, 'v, 'd> {
    def: crate::storage::RelationDefinition<'d>,
    /// `INSERT INTO t AS alias`: the target's only name.
    alias: Option<&'x str>,
    existing: &'e [Datum<'v>],
    excluded: &'x [Datum<'v>],
    outer: Option<&'o TriggerDmlSnapshot<'s>>,
}

impl<'o, 's, 'e, 'x, 'v, 'd> ColumnLookup<'v> for ExcludedCtx<'o, 's, 'e, 'x, 'v, 'd>
where
    's: 'v,
{
    fn column_type_oid(&self, qualifier: Option<&str>, name: &str) -> Option<i32> {
        self.outer?.column_type_oid(qualifier, name)
    }

    fn row_variable(&self, name: &str) -> Option<crate::sql::eval::RowVariable> {
        self.outer?.row_variable(name)
    }

    fn resolve_column_type(
        &self,
        qualifier: Option<&str>,
        name: &str,
    ) -> Result<ColType, SqlError> {
        if let Some(qualifier) = qualifier.filter(|value| value.eq_ignore_ascii_case("excluded")) {
            return self
                .def
                .column_index(name)
                .map(|index| self.def.columns()[index].ctype)
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::UNDEFINED_COLUMN,
                        "column {}.{} does not exist",
                        qualifier,
                        name
                    )
                });
        }
        if matches!(qualifier, Some(value) if value.eq_ignore_ascii_case("old") || value.eq_ignore_ascii_case("new"))
            || (qualifier.is_none() && self.def.column_index(name).is_none())
        {
            return self
                .outer
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::UNDEFINED_COLUMN,
                        "column \"{}\" does not exist",
                        name
                    )
                })?
                .resolve_column_type(qualifier, name);
        }
        RowCtx {
            def: self.def,
            values: self.existing,
            alias: self.alias,
        }
        .resolve_column_type(qualifier, name)
    }

    fn lookup(&self, qualifier: Option<&str>, name: &str) -> Result<Datum<'v>, SqlError> {
        if self.column_type_oid(qualifier, name).is_some() {
            return self
                .outer
                .expect("record field belongs to outer scope")
                .lookup(qualifier, name);
        }
        let src = if matches!(qualifier, Some(value) if value.eq_ignore_ascii_case("excluded")) {
            self.excluded
        } else if matches!(qualifier, Some(value) if value.eq_ignore_ascii_case("old") || value.eq_ignore_ascii_case("new"))
            || (qualifier.is_none() && self.def.column_index(name).is_none())
        {
            return self
                .outer
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::UNDEFINED_COLUMN,
                        "column \"{}\" does not exist",
                        name
                    )
                })?
                .lookup(qualifier, name);
        } else {
            if let Some(q) = qualifier
                && !crate::sql::eval::qualifier_answers_target(self.def, self.alias, q)
            {
                return Err(crate::sql::eval::unknown_target_qualifier(
                    self.def, self.alias, q,
                ));
            }
            self.existing
        };
        match (self.def.column_index(name), qualifier) {
            (Some(i), _) => Ok(src[i]),
            (None, Some(qualifier)) if qualifier.eq_ignore_ascii_case("excluded") => Err(sql_err!(
                sqlstate::UNDEFINED_COLUMN,
                "column {}.{} does not exist",
                qualifier,
                name
            )),
            (None, _) => Err(sql_err!(
                sqlstate::UNDEFINED_COLUMN,
                "column \"{}\" does not exist",
                name
            )),
        }
    }

    fn col_type(&self, qualifier: Option<&str>, name: &str) -> Option<ColType> {
        if matches!(qualifier, Some(value) if value.eq_ignore_ascii_case("old") || value.eq_ignore_ascii_case("new"))
        {
            self.outer.and_then(|outer| outer.col_type(qualifier, name))
        } else if matches!(qualifier, Some(value) if value.eq_ignore_ascii_case("excluded"))
            || self.def.column_index(name).is_some()
        {
            self.def
                .column_index(name)
                .map(|i| self.def.columns()[i].ctype)
        } else {
            self.outer.and_then(|outer| outer.col_type(qualifier, name))
        }
    }

    fn collation(&self, qualifier: Option<&str>, name: &str) -> crate::sql::ast::Collation {
        if matches!(qualifier, Some(value) if value.eq_ignore_ascii_case("old") || value.eq_ignore_ascii_case("new"))
        {
            self.outer
                .map(|outer| outer.collation(qualifier, name))
                .unwrap_or(crate::sql::ast::Collation::None)
        } else if matches!(qualifier, Some(value) if value.eq_ignore_ascii_case("excluded"))
            || self.def.column_index(name).is_some()
        {
            self.def
                .column_index(name)
                .map(|i| self.def.columns()[i].collation)
                .unwrap_or(crate::sql::ast::Collation::None)
        } else {
            self.outer
                .map(|outer| outer.collation(qualifier, name))
                .unwrap_or(crate::sql::ast::Collation::None)
        }
    }

    fn column_user_type(
        &self,
        qualifier: Option<&str>,
        name: &str,
    ) -> Option<crate::storage::UserTypeName> {
        if matches!(qualifier, Some(value) if value.eq_ignore_ascii_case("old") || value.eq_ignore_ascii_case("new"))
        {
            self.outer
                .and_then(|outer| outer.column_user_type(qualifier, name))
        } else if matches!(qualifier, Some(value) if value.eq_ignore_ascii_case("excluded"))
            || self.def.column_index(name).is_some()
        {
            self.def
                .column_index(name)
                .and_then(|i| self.def.columns()[i].user_type)
        } else {
            self.outer
                .and_then(|outer| outer.column_user_type(qualifier, name))
        }
    }
}

/// Takes `FOR UPDATE` strength on a row an update changes a unique key value
/// of, or moves to another partition (`new` is `None`). PostgreSQL's
/// `heap_update` compares the old and new key values, so an assignment that
/// keeps every key value (`SET id = id`) keeps `FOR NO KEY UPDATE` strength
/// and does not wait for `FOR KEY SHARE` holders such as referencing rows'
/// checks.
fn lock_key_change<Definition0: crate::storage::DefinitionBacking>(
    storage: &Storage,
    txn: &TxnState,
    row: PhysicalRow,
    definition: &crate::storage::TableDefinition<Definition0>,
    old: &[Datum<'_>],
    new: Option<&[Datum<'_>]>,
) -> Result<(), SqlError> {
    let changes_key = match new {
        None => true,
        Some(new) => (0..definition.n_columns).any(|column| {
            old[column] != new[column]
                && row_conflicts::is_key_column(storage, definition, column, txn.txid)
        }),
    };
    if !changes_key {
        return Ok(());
    }
    let (table, rowid, seen) = row.local_parts();
    // The held `FOR NO KEY UPDATE` lock keeps other writers off the row, so
    // only the strength changes.
    row_conflicts::lock_selected_row(
        storage,
        txn.txid,
        table,
        rowid,
        seen,
        crate::sql::ast::LockStrength::Update,
        crate::sql::ast::LockWait::Wait,
    )
    .map(|_| ())
}

fn update_lock_strength<Definition0: crate::storage::DefinitionBacking>(
    storage: &Storage,
    def: &crate::storage::TableDefinition<Definition0>,
    updated: ColumnSet,
    txid: u32,
) -> crate::sql::ast::LockStrength {
    let changes_key = (0..def.n_columns).any(|column| {
        updated.contains(column) && row_conflicts::is_key_column(storage, def, column, txid)
    });
    if changes_key {
        crate::sql::ast::LockStrength::Update
    } else {
        crate::sql::ast::LockStrength::NoKeyUpdate
    }
}

enum ConflictOutcome<'a> {
    Store,
    Skip,
    /// DO UPDATE applied; carries the arena-encoded updated row so RETURNING can
    /// project the post-update values (PostgreSQL returns the updated row).
    Updated {
        old: &'a [Datum<'a>],
        new: &'a [u8],
    },
}

/// Applies an ON CONFLICT clause to one candidate row, against the arbiter
/// already resolved once for the statement.
#[allow(clippy::too_many_arguments)]
fn handle_conflict<
    'a,
    'outer,
    'snapshot,
    Definition0: crate::storage::DefinitionBacking,
    Definition1: crate::storage::DefinitionBacking,
>(
    storage: &mut Storage,
    txn: &mut TxnState,
    assignment_casts: AssignmentCasts<'a>,
    row_target: crate::storage::TableDefinitionTarget,
    logical_table_index: usize,
    def: &crate::storage::TableDefinition<Definition0>,
    logical_definition: &crate::storage::TableDefinition<Definition1>,
    mapping: Option<crate::storage::RelationColumnMap<'a>>,
    schema: &[ColType],
    values: &[Datum<'a>],
    on_conflict: &Option<super::ast::OnConflict<'a>>,
    alias: Option<&'a str>,
    arbiter: &Arbiter<'a>,
    checks: &ParsedChecks,
    view_check: Option<ViewCheck<'a>>,
    row_security_using: Option<super::query::RowSecurityPlan<'a>>,
    row_security_check: Option<super::query::RowSecurityPlan<'a>>,
    arena: &'a Arena,
    params: &[Datum<'a>],
    services: &mut TriggerServices<'_>,
    responder: &mut Responder,
    outer: Option<&'outer TriggerDmlSnapshot<'snapshot>>,
    transition_capture: Option<&mut TransitionCapture<'a>>,
) -> Result<ConflictOutcome<'a>, SqlError>
where
    'snapshot: 'a,
{
    let seq_session = services.seq_session;
    let table_index = row_target.table();
    let Some(oc) = on_conflict else {
        return Ok(ConflictOutcome::Store);
    };
    let Some(conflict) = find_conflict(
        storage,
        table_index,
        def,
        schema,
        values,
        arbiter,
        txn.txid,
        arena,
    )?
    else {
        return Ok(ConflictOutcome::Store);
    };
    let rowid = conflict.rowid;
    if let Some(assigns) = oc.update {
        let mut updated_columns = ColumnSet::EMPTY;
        for (name, _) in assigns {
            let column = def.column_index(name).ok_or_else(|| {
                sql_err!(
                    sqlstate::UNDEFINED_COLUMN,
                    "column \"{}\" does not exist",
                    name
                )
            })?;
            updated_columns.insert(column);
        }
        let strength = update_lock_strength(storage, def, updated_columns, txn.txid);
        match storage.acquire_row_lock(
            table_index,
            rowid,
            txn.txid,
            strength,
            crate::sql::ast::LockWait::Wait,
        )? {
            crate::sql::lock::LockDecision::Acquired => {}
            crate::sql::lock::LockDecision::Waiting => {
                return Err(sql_err!(
                    sqlstate::INTERNAL_LOCK_WAIT,
                    "statement is waiting for a conflict-row lock"
                ));
            }
            crate::sql::lock::LockDecision::Skipped => {
                unreachable!("conflict update does not skip locked rows")
            }
        }
        if matches!(conflict.origin, ConflictRowOrigin::OwnCommand(command) if command >= txn.command_id())
        {
            return Err(sql_err!(
                sqlstate::CARDINALITY_VIOLATION,
                "ON CONFLICT DO UPDATE command cannot affect row a second time"
            ));
        }
    }
    if matches!(
        txn.isolation,
        crate::sql::ast::TransactionIsolation::RepeatableRead
            | crate::sql::ast::TransactionIsolation::Serializable
    ) && matches!(conflict.origin, ConflictRowOrigin::Committed(lsn) if txn.snapshot_lsn().is_some_and(|snapshot| lsn > snapshot))
    {
        return Err(sql_err!(
            sqlstate::SERIALIZATION_FAILURE,
            "could not serialize access due to concurrent update"
        ));
    }
    let Some(assigns) = oc.update else {
        return Ok(ConflictOutcome::Skip);
    };
    // `excluded` is the proposed row; target values use the captured conflict.
    let mut existing = [Datum::Null; MAX_COLUMNS];
    let mut new_values = [Datum::Null; MAX_COLUMNS];
    {
        rowenc::decode(conflict.bytes, schema, &mut existing)?;
        let logical_existing = partition_insert::logical_insert_values(
            mapping,
            logical_definition.n_columns,
            &existing[..def.n_columns],
            arena,
        )?;
        let logical_excluded = partition_insert::logical_insert_values(
            mapping,
            logical_definition.n_columns,
            values,
            arena,
        )?;
        let context = ExcludedCtx {
            def: crate::storage::RelationDefinition::from_definition(logical_definition),
            alias,
            existing: logical_existing,
            excluded: logical_excluded,
            outer,
        };
        let mut subquery_expressions: [Option<&Expr>; MAX_PROJ] = [None; MAX_PROJ];
        let mut subquery_expression_count = 0usize;
        if let Some(condition) = oc.update_where {
            subquery_expressions[subquery_expression_count] = Some(condition);
            subquery_expression_count += 1;
        }
        for (_, expression) in assigns {
            subquery_expressions[subquery_expression_count] = Some(expression);
            subquery_expression_count += 1;
        }
        let subqueries = super::query::subquery_hooks(
            &subquery_expressions[..subquery_expression_count],
            storage,
            txn.txid,
            arena,
            params,
            Some(&crate::sql::sequence::SeqEval::new(
                storage,
                seq_session,
                txn.txid,
            )),
        )?;
        let catalog = super::query::storage_catalog(storage, arena, txn.txid);
        let sequences = crate::sql::sequence::SeqEval::new(storage, seq_session, txn.txid);
        let hooks = EvalHooks {
            subs: Some(&subqueries),
            catalog: Some(&catalog),
            sequences: Some(&sequences),
            ..NO_HOOKS
        };
        if let Some(cond) = oc.update_where
            && !matches!(
                eval_full(cond, arena, params, &context, &hooks)?,
                Datum::Bool(true)
            )
        {
            return Ok(ConflictOutcome::Skip); // WHERE excluded this row
        }
        if let Some(plan) = row_security_using {
            let policy_row = RowCtx {
                def: crate::storage::RelationDefinition::from_definition(logical_definition),
                values: logical_existing,
                alias: None,
            };
            let catalog = super::query::storage_catalog(storage, arena, txn.txid);
            let sequences = crate::sql::sequence::SeqEval::new(storage, seq_session, txn.txid);
            let policy_hooks = EvalHooks {
                catalog: Some(&catalog),
                sequences: Some(&sequences),
                ..NO_HOOKS
            };
            if !super::query::row_security_passes(
                plan,
                &policy_row,
                storage,
                txn.txid,
                arena,
                params,
                &policy_hooks,
            )? {
                return Err(sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "new row violates row-level security policy for table \"{}\"",
                    def.name.as_str()
                ));
            }
        }
        let defaults = if assigns
            .iter()
            .any(|(_, expression)| matches!(expression, Expr::DefaultMarker))
        {
            Some(parse_defaults(
                logical_definition,
                arena,
                storage,
                txn.txid,
            )?)
        } else {
            None
        };
        new_values[..def.n_columns].copy_from_slice(&existing[..def.n_columns]);
        for (name, expression) in assigns {
            let Some(target) = def.column_index(name) else {
                return Err(crate::sql::error_position::at_reference(
                    sql_err!(
                        sqlstate::UNDEFINED_COLUMN,
                        "column \"{}\" of relation \"{}\" does not exist",
                        name,
                        def.name.as_str()
                    ),
                    name,
                ));
            };
            let v = if matches!(expression, Expr::DefaultMarker) {
                let logical_column = logical_definition
                    .column_index(name)
                    .expect("validated by arbiter");
                let column = &logical_definition.columns()[logical_column];
                if column.auto_increment {
                    next_auto_value(
                        storage,
                        logical_table_index,
                        logical_column,
                        column.ctype,
                        seq_session,
                        txn.txid,
                    )?
                } else {
                    let catalog = super::query::storage_catalog(storage, arena, txn.txid);
                    let sequences =
                        crate::sql::sequence::SeqEval::new(storage, seq_session, txn.txid);
                    let hooks = EvalHooks {
                        catalog: Some(&catalog),
                        sequences: Some(&sequences),
                        ..NO_HOOKS
                    };
                    let value = column_default_value(
                        storage,
                        txn.txid,
                        column,
                        defaults.as_ref().expect("DEFAULT expressions parsed")[logical_column],
                        arena,
                        &hooks,
                    )?;
                    detach_routine_datum(value, arena)?
                }
            } else {
                let catalog = super::query::storage_catalog(storage, arena, txn.txid);
                let sequences = crate::sql::sequence::SeqEval::new(storage, seq_session, txn.txid);
                let hooks = EvalHooks {
                    subs: Some(&subqueries),
                    catalog: Some(&catalog),
                    sequences: Some(&sequences),
                    ..NO_HOOKS
                };
                eval_prepared_assignment(
                    assignment_casts,
                    expression,
                    &def.columns()[target],
                    storage,
                    txn.txid,
                    arena,
                    params,
                    &context,
                    &hooks,
                )?
            };
            new_values[target] = v;
        }
    }
    let mut updated_columns = ColumnSet::EMPTY;
    for (name, _) in assigns {
        let column = def.column_index(name).expect("validated above");
        updated_columns.insert(column);
    }
    let generated = parse_generated(def, arena, storage, txn.txid)?;
    if !fire_partition_row_triggers(
        storage,
        txn,
        arena,
        services,
        responder,
        table_index,
        def,
        TriggerEvents::UPDATE,
        true,
        false,
        updated_columns,
        Some(&existing[..def.n_columns]),
        Some(&mut new_values[..def.n_columns]),
    )? {
        return Ok(ConflictOutcome::Skip);
    }
    compute_generated(def, &generated, &mut new_values, storage, txn.txid, arena)?;
    if let Some(plan) = row_security_check {
        let logical_new = partition_insert::logical_insert_values(
            mapping,
            logical_definition.n_columns,
            &new_values[..def.n_columns],
            arena,
        )?;
        let policy_row = RowCtx {
            def: crate::storage::RelationDefinition::from_definition(logical_definition),
            values: logical_new,
            alias: None,
        };
        let catalog = super::query::storage_catalog(storage, arena, txn.txid);
        let sequences = crate::sql::sequence::SeqEval::new(storage, seq_session, txn.txid);
        let policy_hooks = EvalHooks {
            catalog: Some(&catalog),
            sequences: Some(&sequences),
            ..NO_HOOKS
        };
        if !super::query::row_security_passes(
            plan,
            &policy_row,
            storage,
            txn.txid,
            arena,
            params,
            &policy_hooks,
        )? {
            return Err(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "new row violates row-level security policy for table \"{}\"",
                def.name.as_str()
            ));
        }
    }
    let view_values = if view_check.is_some() {
        partition_insert::logical_insert_values(
            mapping,
            logical_definition.n_columns,
            &new_values[..def.n_columns],
            arena,
        )?
    } else {
        &new_values[..def.n_columns]
    };
    enforce_view_check(
        view_check,
        logical_definition,
        view_values,
        ViewCheckContext {
            storage,
            txid: txn.txid,
            arena,
            params,
            seq_session,
        },
    )?;
    if let Err(error) =
        storage.validate_partition_target(table_index, def, &new_values[..def.n_columns], txn.txid)
    {
        if error.sqlstate == sqlstate::CHECK_VIOLATION {
            return Err(sql_err!(
                sqlstate::FEATURE_NOT_SUPPORTED,
                "invalid ON UPDATE specification"
            ));
        }
        return Err(error);
    }
    check_not_null(def, &new_values)?;
    enforce_row_constraints(
        storage,
        table_index,
        def,
        schema,
        &new_values[..def.n_columns],
        ConstraintRow::update(rowid),
        txn.txid,
        Some(txn),
        checks,
        arena,
        params,
        None,
    )?;
    if !dml_row_available(storage, txn, conflict.selected, "updated")? {
        return Ok(ConflictOutcome::Skip);
    }
    let len = rowenc::encoded_len(&new_values[..def.n_columns]);
    let new_bytes = arena.alloc_slice_with(len, |_| 0u8).map_err(|_| {
        sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "updated row exceeds the arena"
        )
    })?;
    rowenc::encode(&new_values[..def.n_columns], new_bytes);
    let new_image = storage.heap.append_image(new_bytes)?;
    txn.write_row(
        storage,
        row_target,
        rowid,
        txn.command_id(),
        Some(new_image),
        crate::storage::RowWriteStatistics::Tracked,
    )?;

    if referenced_key_changed(
        storage,
        def.schema.as_str(),
        def.name.as_str(),
        &existing[..def.n_columns],
        &new_values[..def.n_columns],
        txn.txid,
    )? {
        apply_fk_parent_actions(
            storage,
            txn,
            def.schema.as_str(),
            def.name.as_str(),
            &existing[..def.n_columns],
            Some(&new_values[..def.n_columns]),
            arena,
        )?;
    }
    fire_partition_row_triggers(
        storage,
        txn,
        arena,
        services,
        responder,
        table_index,
        def,
        TriggerEvents::UPDATE,
        false,
        false,
        updated_columns,
        Some(&existing[..def.n_columns]),
        Some(&mut new_values[..def.n_columns]),
    )?;
    if let Some(transition_capture) = transition_capture {
        let logical_old = partition_insert::logical_insert_values(
            mapping,
            logical_definition.n_columns,
            &existing[..def.n_columns],
            arena,
        )?;
        let logical_new = partition_insert::logical_insert_values(
            mapping,
            logical_definition.n_columns,
            &new_values[..def.n_columns],
            arena,
        )?;
        transition_capture.push_old(logical_old, arena)?;
        transition_capture.push_new(logical_new, arena)?;
    }
    let old = arena
        .alloc_slice_copy(&existing[..def.n_columns])
        .map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "conflict row exceeds the statement arena"
            )
        })?;
    Ok(ConflictOutcome::Updated {
        old: &*old,
        new: new_bytes,
    })
}

/// Assigns each omitted/defaulted auto-increment column its next value. A
/// column the statement set *explicitly* — even to NULL — is left alone, so
/// an explicit NULL falls through to the not-null check exactly as PostgreSQL
/// rejects it, and an explicit value never advances the sequence.
fn fill_auto_increment<Definition0: crate::storage::DefinitionBacking>(
    storage: &mut Storage,
    table_index: usize,
    def: &crate::storage::TableDefinition<Definition0>,
    values: &mut [Datum],
    explicit: &[bool; MAX_COLUMNS],
    seq_session: &crate::sql::guc::SeqSession,
    txid: u32,
) -> Result<(), SqlError> {
    if !def.columns().iter().any(|c| c.auto_increment) {
        return Ok(());
    }
    for i in 0..def.n_columns {
        let col = &def.columns()[i];
        if col.auto_increment && !explicit[i] && values[i].is_null() {
            values[i] = next_auto_value(storage, table_index, i, col.ctype, seq_session, txid)?;
        }
    }
    Ok(())
}

/// PostgreSQL names the kind of object a DROP could not find — `table "x" does
/// not exist`, not `relation` — while every other lookup says relation.
fn undefined_kind(kind: &str, name: &str) -> SqlError {
    sql_err!(
        sqlstate::UNDEFINED_TABLE,
        "{} \"{}\" does not exist",
        kind,
        name
    )
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn drop_table(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    scratch: &mut DmlScratch,
    statement: &DropTable,
    arena: &Arena,
    seq_session: &crate::sql::guc::SeqSession,
    responder: &mut Responder,
) -> Outcome {
    drop_table_kind_with_columns(
        storage,
        wal,
        txn,
        statement,
        Some(crate::storage::TableKind::Local),
        "DROP TABLE",
        arena,
        RowTypeColumnCascade {
            scratch,
            seq_session,
        },
        responder,
    )
}

/// The statement state an internal `ALTER TABLE ... DROP COLUMN` needs when a
/// dropped relation's row type is the type of another table's column.
pub(crate) struct RowTypeColumnCascade<'c> {
    scratch: &'c mut DmlScratch,
    seq_session: &'c crate::sql::guc::SeqSession,
}

impl RowTypeColumnCascade<'_> {
    fn reborrow(&mut self) -> RowTypeColumnCascade<'_> {
        RowTypeColumnCascade {
            scratch: self.scratch,
            seq_session: self.seq_session,
        }
    }
}

/// Columns of other tables whose declared type is `creation` (arrays first, as
/// PostgreSQL's dependency scan reports them), excluding tables in `excluded`.
fn row_type_column_users(
    storage: &Storage,
    txid: u32,
    creation: crate::storage::TypeCreation,
    excluded: &[usize],
    mut visit: impl FnMut(usize, SqlName, SqlName, bool) -> Result<(), SqlError>,
) -> Result<(), SqlError> {
    for array in [true, false] {
        for slot in 0..storage.table_count() {
            if excluded.contains(&slot) || !storage.table_slot_visible_to(slot, txid) {
                continue;
            }
            let definition = storage.table_def(slot, txid);
            for column in definition.columns() {
                let uses = if array {
                    column.ctype == ColType::Array(ArrElem::Composite(Some(creation)))
                } else {
                    column.ctype == ColType::Composite(Some(creation))
                };
                if uses {
                    visit(slot, definition.name, column.name, array)?;
                }
            }
        }
    }
    Ok(())
}

/// Whether a live composite attribute has the row type `creation` (`false`)
/// or its array type (`true`).
fn row_type_field_use(
    field: &crate::storage::CompositeFieldDef,
    creation: crate::storage::TypeCreation,
) -> Option<bool> {
    match field.ctype {
        _ if field.dropped => None,
        ColType::Composite(found) if found == Some(creation) => Some(false),
        ColType::Array(ArrElem::Composite(found)) if found == Some(creation) => Some(true),
        _ => None,
    }
}

/// Rejects a drop path that cannot cascade to other tables' columns of the
/// dropped relation's row type, unless those tables are dropped with it.
fn require_row_type_unused(
    storage: &Storage,
    txid: u32,
    relation: crate::storage::RowTypeRelation,
    dropped_with: impl Fn(SqlName) -> bool,
) -> Result<(), SqlError> {
    let (_, name) = storage.row_type_relation_name(relation, txid);
    let creation = storage.relation_row_type_creation(relation);
    if let Some(domain) = (0..storage.domain_count()).find(|slot| {
        storage.domain_slot_visible_to(*slot, txid)
            && !dropped_with(storage.domain_for(*slot, txid).schema)
            && matches!(
                storage.domain_for(*slot, txid).base,
                ColType::Composite(base) | ColType::Array(ArrElem::Composite(base))
                    if base == Some(creation)
            )
    }) {
        return Err(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "cannot drop {} because domain \"{}\" uses its row type",
            name.as_str(),
            storage.domain_for(domain, txid).name.as_str()
        ));
    }
    if let Some((composite, field)) =
        storage
            .composites_with_slots_visible_to(txid)
            .find_map(|(_, composite)| {
                (!dropped_with(composite.schema))
                    .then(|| {
                        composite
                            .fields()
                            .iter()
                            .find(|field| row_type_field_use(field, creation).is_some())
                            .map(|field| (composite.name, field.name))
                    })
                    .flatten()
            })
    {
        return Err(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "cannot drop {} because column \"{}.{}\" uses its row type",
            name.as_str(),
            composite.as_str(),
            field.as_str()
        ));
    }
    let excluded = match relation {
        crate::storage::RowTypeRelation::Table(table) => Some(table),
        crate::storage::RowTypeRelation::View(_) => None,
    };
    row_type_column_users(
        storage,
        txid,
        creation,
        excluded.as_slice(),
        |slot, user, column, _| {
            if dropped_with(storage.table_def(slot, txid).schema) {
                return Ok(());
            }
            Err(sql_err!(
                sqlstate::FEATURE_NOT_SUPPORTED,
                "cannot drop {} because column \"{}.{}\" uses its row type",
                name.as_str(),
                user.as_str(),
                column.as_str()
            ))
        },
    )
}

/// A relation's row type cannot contain itself, directly or through another
/// relation's row type.
fn require_not_own_member(
    storage: &Storage,
    txid: u32,
    table: usize,
    column: &ColumnMeta,
) -> Result<(), SqlError> {
    let own = storage.relation_row_type_creation(crate::storage::RowTypeRelation::Table(table));
    let mut pending = [None::<crate::storage::TypeCreation>; MAX_COLUMNS];
    let mut count = 0usize;
    let visit = |ctype: ColType,
                 pending: &mut [Option<crate::storage::TypeCreation>; MAX_COLUMNS],
                 count: &mut usize|
     -> Result<(), SqlError> {
        if let ColType::Composite(Some(creation))
        | ColType::Array(ArrElem::Composite(Some(creation))) = ctype
            && !pending[..*count].contains(&Some(creation))
        {
            *pending.get_mut(*count).ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "composite type nesting exceeds {} distinct types",
                    MAX_COLUMNS
                )
            })? = Some(creation);
            *count += 1;
        }
        Ok(())
    };
    visit(column.ctype, &mut pending, &mut count)?;
    let mut index = 0;
    while index < count {
        let creation = pending[index].expect("queued row type");
        index += 1;
        if creation == own {
            let relation = storage.table_def(table, txid);
            return Err(sql_err!(
                sqlstate::INVALID_TABLE_DEFINITION,
                "composite type {} cannot be made a member of itself",
                relation.name.as_str()
            ));
        }
        if let Some(definition) = storage.row_type_definition(creation, txid)? {
            for field in definition.active_fields() {
                visit(field.ctype, &mut pending, &mut count)?;
            }
        }
    }
    Ok(())
}

/// PostgreSQL cannot rewrite stored values of a relation's row type, so a
/// change that requires one is rejected while a column uses that type.
fn require_row_type_unaltered(storage: &Storage, txid: u32, table: usize) -> Result<(), SqlError> {
    let relation = storage.table_def(table, txid);
    let creation =
        storage.relation_row_type_creation(crate::storage::RowTypeRelation::Table(table));
    let kind = if relation.kind == crate::storage::TableKind::Foreign {
        "foreign table"
    } else {
        "table"
    };
    let fail = |user: SqlName, column: SqlName| {
        Err(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "cannot alter {} \"{}\" because column \"{}.{}\" uses its row type",
            kind,
            relation.name.as_str(),
            user.as_str(),
            column.as_str()
        ))
    };
    row_type_column_users(storage, txid, creation, &[], |_, user, column, _| {
        fail(user, column)
    })?;
    // A column of a composite type with an attribute of the row type stores
    // the row type's values too.
    for slot in 0..storage.table_count() {
        if !storage.table_slot_visible_to(slot, txid) {
            continue;
        }
        let definition = storage.table_def(slot, txid);
        for column in definition.columns() {
            if named_composite_contains(storage, txid, column.ctype, creation, 0)? {
                return fail(definition.name, column.name);
            }
        }
    }
    Ok(())
}

/// Whether `ctype` is a `CREATE TYPE ... AS` composite (or an array of one)
/// with an attribute, at any depth, of the type `creation` or its array.
fn named_composite_contains(
    storage: &Storage,
    txid: u32,
    ctype: ColType,
    creation: crate::storage::TypeCreation,
    depth: usize,
) -> Result<bool, SqlError> {
    let (ColType::Composite(Some(outer)) | ColType::Array(ArrElem::Composite(Some(outer)))) = ctype
    else {
        return Ok(false);
    };
    if outer == creation {
        return Ok(false);
    }
    let Some(slot) = storage
        .composites_with_slots_visible_to(txid)
        .find_map(|(slot, composite)| (composite.creation() == outer).then_some(slot))
    else {
        return Ok(false);
    };
    if depth >= MAX_COLUMNS {
        return Err(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "composite type nesting exceeds {} levels",
            MAX_COLUMNS
        ));
    }
    let composite = storage.composite_for(slot, txid);
    for field in composite.fields() {
        if field.dropped {
            continue;
        }
        if row_type_field_use(field, creation).is_some()
            || named_composite_contains(storage, txid, field.ctype, creation, depth + 1)?
        {
            return Ok(true);
        }
    }
    Ok(false)
}

/// PostgreSQL refuses to change the type of a column that a view, rule,
/// trigger, policy or SQL-standard routine body reads; the first such
/// dependent, oldest first, is named in the `DETAIL`.
fn require_column_type_unreferenced(
    storage: &Storage,
    txid: u32,
    table: usize,
    attribute: u16,
    column: &str,
    arena: &Arena,
) -> Result<(), SqlError> {
    use crate::sql::catalog::{
        PG_CLASS_OID, PG_POLICY_OID, PG_PROC_OID, PG_REWRITE_OID, PG_TRIGGER_OID,
    };
    let referenced = crate::sql::catalog::dependencies::ObjectAddress::new(
        PG_CLASS_OID,
        crate::sql::catalog::user_table_oid(storage, table),
        i32::from(attribute),
    );
    let mark = arena.mark();
    let mut first: Option<crate::sql::catalog::dependencies::ObjectAddress> = None;
    let walked =
        crate::sql::catalog::dependencies::for_each_dependency(storage, txid, arena, &mut |edge| {
            if edge.referenced == referenced
                && matches!(
                    edge.dependent.class,
                    PG_REWRITE_OID | PG_TRIGGER_OID | PG_POLICY_OID | PG_PROC_OID
                )
                && first.is_none_or(|current| {
                    crate::storage::OidBand::creation_order(edge.dependent.object)
                        < crate::storage::OidBand::creation_order(current.object)
                })
            {
                first = Some(edge.dependent);
            }
            Ok(())
        });
    // SAFETY: the visit kept only copied addresses.
    unsafe { arena.rewind_to(mark) };
    walked?;
    let Some(dependent) = first else {
        return Ok(());
    };
    let usage = match dependent.class {
        PG_REWRITE_OID => "by a view or rule",
        PG_TRIGGER_OID => "in a trigger definition",
        PG_POLICY_OID => "in a policy definition",
        _ => "by a function or procedure",
    };
    let description = dependency_report::describe(storage, txid, dependent, arena)?;
    let error = crate::sql::eval::with_detail(
        sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "cannot alter type of a column used {}",
            usage
        ),
        format_args!("{} depends on column \"{}\"", description, column),
    );
    // SAFETY: the diagnostic copied the description.
    unsafe { arena.rewind_to(mark) };
    Err(error)
}

/// Domains over a relation's row type or its array type.
fn row_type_domains<'a>(
    storage: &Storage,
    txid: u32,
    creation: crate::storage::TypeCreation,
    arena: &'a Arena,
) -> Result<Option<&'a mut [bool]>, SqlError> {
    let mut found = false;
    let selected = dependency_flags(arena, storage.domain_count())?;
    for (slot, selected) in selected.iter_mut().enumerate() {
        if storage.domain_slot_visible_to(slot, txid)
            && matches!(
                storage.domain_for(slot, txid).base,
                ColType::Composite(base) | ColType::Array(ArrElem::Composite(base))
                    if base == Some(creation)
            )
        {
            *selected = true;
            found = true;
        }
    }
    Ok(found.then_some(selected))
}

/// Drops the domains over a dropped relation's row type, which the
/// statement's dependency report already listed. Without the statement state
/// a domain drop needs, such a domain fails the drop with `0A000`.
#[allow(clippy::too_many_arguments)]
fn drop_row_type_domains(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    (relation_kind, relation_name): (&str, SqlName),
    creation: crate::storage::TypeCreation,
    dropped_schema: &dyn Fn(SqlName) -> bool,
    cascade: bool,
    columns: RowTypeColumnCascade<'_>,
    arena: &Arena,
    responder: &mut Responder,
) -> Result<(), SqlError> {
    let Some(selected) = row_type_domains(storage, txn.txid, creation, arena)? else {
        return Ok(());
    };
    // Domains in a schema the statement drops go with their schema.
    for (slot, selected) in selected.iter_mut().enumerate() {
        if *selected && dropped_schema(storage.domain_for(slot, txn.txid).schema) {
            *selected = false;
        }
    }
    if !selected.iter().any(|selected| *selected) {
        return Ok(());
    }
    if !cascade {
        return Err(sql_err!(
            sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
            "cannot drop {} {} because other objects depend on it",
            relation_kind,
            relation_name.as_str()
        ));
    }
    let RowTypeColumnCascade {
        scratch,
        seq_session,
    } = columns;
    drop_domain_selection(
        storage,
        wal,
        txn,
        scratch,
        selected,
        None,
        true,
        1,
        arena,
        seq_session,
        responder,
    )
}

/// Cascades a dropped relation's row type to the composite attributes, other
/// tables' columns and domains that use it, as PostgreSQL's dependency walk
/// does.
#[allow(clippy::too_many_arguments)]
fn drop_row_type_users(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    relation_kind_name: (&str, SqlName),
    relation: crate::storage::RowTypeRelation,
    excluded: &[usize],
    dropped_schema: &dyn Fn(SqlName) -> bool,
    cascade: bool,
    mut columns: RowTypeColumnCascade<'_>,
    arena: &Arena,
    responder: &mut Responder,
) -> Result<(), SqlError> {
    let creation = storage.relation_row_type_creation(relation);
    drop_row_type_columns(
        storage,
        wal,
        txn,
        relation_kind_name,
        creation,
        excluded,
        dropped_schema,
        cascade,
        columns.reborrow(),
        arena,
        responder,
    )?;
    drop_row_type_domains(
        storage,
        wal,
        txn,
        relation_kind_name,
        creation,
        dropped_schema,
        cascade,
        columns,
        arena,
        responder,
    )
}

/// Reports or cascades to other tables' columns of a dropped relation's row type.
#[allow(clippy::too_many_arguments)]
fn drop_row_type_columns(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    (relation_kind, relation_name): (&str, SqlName),
    creation: crate::storage::TypeCreation,
    excluded: &[usize],
    dropped_schema: &dyn Fn(SqlName) -> bool,
    cascade: bool,
    columns: RowTypeColumnCascade<'_>,
    arena: &Arena,
    responder: &mut Responder,
) -> Result<(), SqlError> {
    use core::fmt::Write as _;
    // Tables in a schema the statement drops go with their schema.
    let schema_tables = (0..storage.table_count())
        .filter(|slot| {
            storage.table_slot_visible_to(*slot, txn.txid)
                && dropped_schema(storage.table_def(*slot, txn.txid).schema)
        })
        .count();
    let all_excluded = arena
        .alloc_slice_with(excluded.len() + schema_tables, |_| usize::MAX)
        .map_err(|_| arena_full())?;
    all_excluded[..excluded.len()].copy_from_slice(excluded);
    for (target, slot) in
        all_excluded[excluded.len()..]
            .iter_mut()
            .zip((0..storage.table_count()).filter(|slot| {
                storage.table_slot_visible_to(*slot, txn.txid)
                    && dropped_schema(storage.table_def(*slot, txn.txid).schema)
            }))
    {
        *target = slot;
    }
    let excluded = &*all_excluded;
    let mut detail =
        crate::util::StackStr::<{ crate::sql::eval::MAX_DIAGNOSTIC_DETAIL_BYTES }>::new();
    let mut count = 0usize;
    // Attributes of composite types come first: PostgreSQL drops each such
    // attribute and keeps the composite type.
    let mut composite_users = false;
    for (_, composite) in storage.composites_with_slots_visible_to(txn.txid) {
        if dropped_schema(composite.schema) {
            continue;
        }
        for field in composite.fields() {
            let Some(array) = row_type_field_use(field, creation) else {
                continue;
            };
            let line = if cascade {
                stack_format!(
                    192,
                    "drop cascades to column {} of composite type {}",
                    field.name.as_str(),
                    composite.name.as_str()
                )
            } else {
                stack_format!(
                    192,
                    "column {} of composite type {} depends on type {}{}",
                    field.name.as_str(),
                    composite.name.as_str(),
                    relation_name.as_str(),
                    if array { "[]" } else { "" }
                )
            };
            if count != 0 {
                let _ = detail.write_char('\n');
            }
            let _ = detail.write_str(line.as_str());
            count += 1;
            composite_users = true;
        }
    }
    row_type_column_users(
        storage,
        txn.txid,
        creation,
        excluded,
        |_, table, column, array| {
            let line = if cascade {
                stack_format!(
                    192,
                    "drop cascades to column {} of table {}",
                    column.as_str(),
                    table.as_str()
                )
            } else {
                stack_format!(
                    192,
                    "column {} of table {} depends on type {}{}",
                    column.as_str(),
                    table.as_str(),
                    relation_name.as_str(),
                    if array { "[]" } else { "" }
                )
            };
            if count != 0 {
                let _ = detail.write_char('\n');
            }
            let _ = detail.write_str(line.as_str());
            count += 1;
            Ok(())
        },
    )?;
    if count == 0 {
        return Ok(());
    }
    if detail.is_truncated() {
        return Err(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "row type dependency report exceeds its fixed buffer"
        ));
    }
    if !cascade {
        crate::sql::eval::stash_diagnostic(
            Some(detail),
            Some(crate::util::StackStr::from_str(
                "Use DROP ... CASCADE to drop the dependent objects too.",
            )),
        );
        return Err(sql_err!(
            sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
            "cannot drop {} {} because other objects depend on it",
            relation_kind,
            relation_name.as_str()
        ));
    }
    dependency_report::send_cascade_lines(responder, detail.as_str(), count)?;
    while let Some(slot) = composite_users
        .then(|| {
            storage
                .composites_with_slots_visible_to(txn.txid)
                .find_map(|(slot, composite)| {
                    (!dropped_schema(composite.schema)
                        && composite
                            .fields()
                            .iter()
                            .any(|field| row_type_field_use(field, creation).is_some()))
                    .then_some(slot)
                })
        })
        .flatten()
    {
        cascade_drop_composite_fields(storage, wal, txn, slot, |field| {
            Ok(row_type_field_use(field, creation).is_some())
        })?;
    }
    let RowTypeColumnCascade {
        scratch,
        seq_session,
    } = columns;
    loop {
        let mut target = None;
        row_type_column_users(storage, txn.txid, creation, excluded, |slot, _, _, _| {
            target.get_or_insert(slot);
            Ok(())
        })?;
        let Some(slot) = target else {
            return Ok(());
        };
        let definition = storage.table_def(slot, txn.txid);
        let (schema, name) = (definition.schema, definition.name);
        let mut names = [SqlName::EMPTY; MAX_COLUMNS];
        let mut selected = 0;
        for column in definition.columns() {
            if matches!(column.ctype,
                ColType::Composite(found) | ColType::Array(ArrElem::Composite(found))
                    if found == Some(creation))
            {
                names[selected] = column.name;
                selected += 1;
            }
        }
        drop(definition);
        responder.without_command_complete(|responder| {
            cascade_drop_type_column(
                storage,
                wal,
                txn,
                scratch,
                schema,
                name,
                &names[..selected],
                arena,
                seq_session,
                responder,
            )
        })?;
    }
}

#[allow(clippy::too_many_arguments)]
fn drop_table_kind_with_columns(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    statement: &DropTable,
    expected_kind: Option<crate::storage::TableKind>,
    tag: &'static str,
    arena: &Arena,
    mut row_type_columns: RowTypeColumnCascade<'_>,
    responder: &mut Responder,
) -> Outcome {
    let report = (|| {
        let originals = arena
            .alloc_slice_with(statement.names.len(), |_| DROPPED_NOTHING)
            .map_err(|_| arena_full())?;
        let mut count = 0;
        for name in statement.names {
            let Some(crate::storage::ResolvedRelation::Table(slot)) =
                storage.resolve_relation(name.schema, name.name, txn.txid)
            else {
                if statement.if_exists
                    && storage
                        .sequence_on_path(name.schema, name.name, txn.txid)
                        .is_none()
                    && storage
                        .resolve_relation(name.schema, name.name, txn.txid)
                        .is_none()
                {
                    continue;
                }
                return Ok(None);
            };
            let definition = storage.table_def(slot, txn.txid);
            if storage
                .matview_slot(
                    definition.schema.as_str(),
                    definition.name.as_str(),
                    txn.txid,
                )
                .is_some()
                || expected_kind.is_some_and(|kind| definition.kind != kind)
                || !may_drop(
                    storage,
                    crate::storage::AccessClass::Table,
                    slot,
                    txn.txid,
                    "table",
                )
            {
                return Ok(None);
            }
            originals[count] = ObjectAddress::new(
                super::catalog::PG_CLASS_OID,
                super::catalog::user_table_oid(storage, slot),
                0,
            );
            count += 1;
        }
        dependency_report::report_drop(
            storage,
            txn.txid,
            &originals[..count],
            statement.cascade,
            arena,
            responder,
        )
    })();
    run_reported_drop(report, responder, |responder| {
        let mut selected_tables = [usize::MAX; 16];
        let mut selected_table_count = 0usize;
        for name in statement.names {
            if let Some(crate::storage::ResolvedRelation::Table(slot)) =
                storage.resolve_relation(name.schema, name.name, txn.txid)
                && storage
                    .matview_slot(
                        storage.table_def(slot, txn.txid).schema.as_str(),
                        storage.table_def(slot, txn.txid).name.as_str(),
                        txn.txid,
                    )
                    .is_none()
                && !selected_tables[..selected_table_count].contains(&slot)
            {
                if selected_table_count == selected_tables.len() {
                    return sql_fail(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many tables in one DROP statement"
                    ));
                }
                selected_tables[selected_table_count] = slot;
                selected_table_count += 1;
            }
        }
        for name in statement.names {
            // A DROP whose qualifier names no schema is PostgreSQL's 3F000 (a
            // SELECT of the same spelling is 42P01 — the codes really differ).
            if let Some(schema) = name.schema
                && schema != "pg_temp"
                && storage.find_schema_visible(schema, txn.txid).is_none()
                && !statement.if_exists
            {
                return sql_fail(sql_err!(
                    sqlstate::INVALID_SCHEMA_NAME,
                    "schema \"{}\" does not exist",
                    schema
                ));
            }
            // A relation of another kind is a type error (42809) with a hint
            // naming its own DROP, which IF EXISTS does not suppress.
            let expected = if expected_kind == Some(crate::storage::TableKind::Foreign) {
                RelationKindName::ForeignTable
            } else {
                RelationKindName::Table
            };
            // Internal callers (no expected kind) drop foreign and local tables
            // alike, but never a materialized view's backing table.
            if (expected_kind.is_some()
                || RelationKindName::of(storage, name, txn.txid)
                    == Some(RelationKindName::MaterializedView))
                && let Some(error) = RelationKindName::wrong_kind(storage, name, txn.txid, expected)
            {
                return sql_fail(error);
            }
            match storage.resolve_relation(name.schema, name.name, txn.txid) {
                Some(crate::storage::ResolvedRelation::Table(index)) => {
                    if let Err(error) = storage.require_not_extension_member(
                        crate::storage::AccessObject {
                            class: crate::storage::AccessClass::Table,
                            slot: index as u16,
                        },
                        txn.txid,
                        "table",
                    ) {
                        return sql_fail(error);
                    }
                    if let Err(error) = storage.require_owner(
                        crate::storage::AccessObject {
                            class: crate::storage::AccessClass::Table,
                            slot: index as u16,
                        },
                        txn.txid,
                        "table",
                    ) {
                        return sql_fail(error);
                    }
                    if let Err(error) = storage.lock_table(
                        txn.txid,
                        index,
                        crate::sql::ast::TableLockMode::AccessExclusive,
                        false,
                    ) {
                        return sql_fail(error);
                    }
                    if let Err(error) = super::cursor::require_table_idle(index, name.name, tag) {
                        return sql_fail(error);
                    }
                    if let Some(other) = storage.table(index).ddl_locked_by_other(txn.txid) {
                        if let Err(error) = storage.wait_for_transaction(txn.txid, other) {
                            return sql_fail(error);
                        }
                        return sql_fail(sql_err!(
                            crate::sql::eval::sqlstate::INTERNAL_LOCK_WAIT,
                            "statement is waiting for concurrent DDL on \"{}\"",
                            name.name
                        ));
                    }
                    let def = (*storage.table_def(index, txn.txid)).clone();
                    // Partitions are internal dependencies of their parent. Drop
                    // the deepest visible child first through the ordinary DROP
                    // path so its indexes, triggers, sequences, WAL, and undo state
                    // receive exactly the same treatment as an explicit DROP.
                    loop {
                        let child = (0..storage.table_count()).find_map(|candidate| {
                            if !storage.table(candidate).visible_to(txn.txid) {
                                return None;
                            }
                            let definition = storage.table_def(candidate, txn.txid);
                            let partition = definition
                                .partition
                                .attachment
                                .is_some_and(|attachment| usize::from(attachment.parent) == index);
                            let inheritance = definition.inheritance.contains(index);
                            (partition || inheritance).then_some((candidate, inheritance))
                        });
                        let Some((child, ordinary_inheritance)) = child else {
                            break;
                        };
                        if ordinary_inheritance && !statement.cascade {
                            return sql_fail(sql_err!(
                                sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                                "cannot drop table {} because other objects depend on it",
                                def.name.as_str()
                            ));
                        }
                        let child_def = (*storage.table_def(child, txn.txid)).clone();
                        let child_name = QualName {
                            schema: Some(
                                if child_def.persistence
                                    == crate::storage::RelationPersistence::Temporary
                                {
                                    "pg_temp"
                                } else {
                                    child_def.schema.as_str()
                                },
                            ),
                            name: child_def.name.as_str(),
                        };
                        let child_drop = DropTable {
                            names: core::slice::from_ref(&child_name),
                            if_exists: false,
                            cascade: statement.cascade,
                        };
                        let outcome = responder.without_command_complete(|responder| {
                            drop_table_kind_with_columns(
                                storage,
                                wal,
                                txn,
                                &child_drop,
                                None,
                                tag,
                                arena,
                                row_type_columns.reborrow(),
                                responder,
                            )
                        });
                        match outcome {
                            Ok(Ok(())) => {}
                            Ok(Err(error)) => return sql_fail(error),
                            Err(error) => return Err(error),
                        }
                    }
                    if let Err(error) = drop_row_type_users(
                        storage,
                        wal,
                        txn,
                        ("table", def.name),
                        crate::storage::RowTypeRelation::Table(index),
                        &selected_tables[..selected_table_count],
                        &|_| false,
                        statement.cascade,
                        row_type_columns.reborrow(),
                        arena,
                        responder,
                    ) {
                        return sql_fail(error);
                    }
                    let root = |dependency: &crate::storage::StoredQueryDependency| {
                        dependency.class == crate::storage::DependencyClass::Table
                            && dependency.slot as usize == index
                    };
                    let closure = stored_query_dependent_closure(storage, txn.txid, arena, root);
                    let StoredDependencyClosure {
                        views: dependent_views,
                        matviews: dependent_matviews,
                        routines: dependent_routines,
                        rules: dependent_rules,
                    } = match closure {
                        Ok(closure) => closure,
                        Err(error) => return sql_fail(error),
                    };
                    // A rule of a table this statement also drops goes with
                    // that table, as PostgreSQL drops the listed objects
                    // together.
                    for (slot, selected) in dependent_rules.iter_mut().enumerate() {
                        if *selected
                            && let crate::storage::RuleTarget::Table(table) =
                                storage.rule(slot).definition_for(txn.txid).target
                            && selected_tables[..selected_table_count].contains(&usize::from(table))
                        {
                            *selected = false;
                        }
                    }
                    let policy_root = PolicyDependencySelection::Catalog {
                        class: crate::storage::DependencyClass::Table,
                        slot: index,
                    };
                    let has_dependents = dependent_views.iter().any(|selected| *selected)
                        || dependent_matviews.iter().any(|selected| *selected)
                        || dependent_routines.iter().any(|selected| *selected)
                        || dependent_rules.iter().any(|selected| *selected)
                        || policy_dependents_exist(
                            storage,
                            txn.txid,
                            policy_root,
                            dependent_views,
                            dependent_matviews,
                            dependent_routines,
                        );
                    if has_dependents && !statement.cascade {
                        if let Err(error) = report_stored_query_dependents(
                            storage,
                            txn.txid,
                            StoredQueryRoot {
                                class: crate::storage::DependencyClass::Table,
                                slot: index,
                                kind: "table",
                                schema: def.schema,
                                name: def.name,
                                suffix: crate::util::StackStr::new(),
                            },
                            StoredQuerySelection {
                                views: dependent_views,
                                matviews: dependent_matviews,
                                routines: dependent_routines,
                                rules: dependent_rules,
                                policy_root: Some(policy_root),
                            },
                            false,
                            arena,
                            responder,
                        ) {
                            return sql_fail(error);
                        }
                        return sql_fail(sql_err!(
                            sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                            "cannot drop table {} because other objects depend on it",
                            def.name.as_str()
                        ));
                    }
                    if statement.cascade {
                        if let Err(error) = report_stored_query_dependents(
                            storage,
                            txn.txid,
                            StoredQueryRoot {
                                class: crate::storage::DependencyClass::Table,
                                slot: index,
                                kind: "table",
                                schema: def.schema,
                                name: def.name,
                                suffix: crate::util::StackStr::new(),
                            },
                            StoredQuerySelection {
                                views: dependent_views,
                                matviews: dependent_matviews,
                                routines: dependent_routines,
                                rules: dependent_rules,
                                policy_root: Some(policy_root),
                            },
                            true,
                            arena,
                            responder,
                        ) {
                            return sql_fail(error);
                        }
                        if let Err(error) = drop_policy_dependents(
                            storage,
                            wal,
                            txn,
                            policy_root,
                            dependent_views,
                            dependent_matviews,
                            dependent_routines,
                        ) {
                            return sql_fail(error);
                        }
                        if let Err(error) = drop_selected_stored_queries_with_columns(
                            storage,
                            wal,
                            txn,
                            StoredQuerySelectionDrop {
                                views: dependent_views,
                                matviews: dependent_matviews,
                                routines: dependent_routines,
                                rules: dependent_rules,
                            },
                            ViewRowTypeColumnCascade {
                                columns: row_type_columns.reborrow(),
                                arena,
                                responder: &mut *responder,
                            },
                        ) {
                            return sql_fail(error);
                        }
                    }
                    loop {
                        let inbound = (0..storage.table_count()).find_map(|child| {
                            if !storage.table(child).visible_to(txn.txid)
                                || selected_tables[..selected_table_count].contains(&child)
                            {
                                return None;
                            }
                            storage
                                .table_def(child, txn.txid)
                                .fkeys()
                                .iter()
                                .position(|foreign_key| {
                                    foreign_key.parent_schema == def.schema
                                        && foreign_key.parent == def.name
                                })
                                .map(|foreign_key| (child, foreign_key))
                        });
                        let Some((child, foreign_key)) = inbound else {
                            break;
                        };
                        let (child_target, child_definition) =
                            storage.select_table_definition(child, txn.txid);
                        let constraint = child_definition.fkeys()[foreign_key].name;
                        if !statement.cascade {
                            return sql_fail(sql_err!(
                                sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                                "cannot drop table {} because other objects depend on it",
                                def.name.as_str()
                            ));
                        }
                        let lsn = storage.bump_lsn();
                        if let Err(error) = wal.stage_reserved(
                            txn.txid,
                            lsn,
                            &WalOp::DropTableFk {
                                schema: child_definition.schema.as_str(),
                                table: child_definition.name.as_str(),
                                fk_name: constraint.as_str(),
                            },
                        ) {
                            return sql_fail(error);
                        }
                        let mut updated = TableDefBuilder::from_definition(&child_definition);
                        if !drop_named_constraint(&mut updated, constraint.as_str()) {
                            return sql_fail(sql_err!(
                                sqlstate::INTERNAL_ERROR,
                                "inbound foreign key vanished during DROP TABLE"
                            ));
                        }
                        let mut identity_mapping = [None; MAX_COLUMNS];
                        for (column, target) in identity_mapping
                            .iter_mut()
                            .enumerate()
                            .take(child_definition.n_columns)
                        {
                            *target = Some(child_definition.columns()[column].name);
                        }
                        if let Err(error) = txn.write_table_definition(
                            storage,
                            child_target,
                            updated,
                            &identity_mapping,
                            false,
                            crate::storage::ColumnSet::EMPTY,
                        ) {
                            return sql_fail(error);
                        }
                    }
                    // Owned serial/identity sequences are internal dependencies:
                    // dropping their table drops them in the same transaction.
                    for sequence_index in 0..storage.sequence_count() {
                        let sequence = storage.sequence_for(sequence_index, txn.txid);
                        if !sequence.visible_to(txn.txid)
                            || !matches!(
                                sequence.owner,
                                Some(owner)
                                    if owner.table_schema == def.schema && owner.table == def.name
                            )
                        {
                            continue;
                        }
                        let (sequence_schema, sequence_name) = (sequence.schema, sequence.name);
                        let wal_result = if sequence.persistence
                            == crate::storage::RelationPersistence::Temporary
                        {
                            Ok(())
                        } else {
                            let lsn = storage.bump_lsn();
                            wal.stage_reserved(
                                txn.txid,
                                lsn,
                                &WalOp::DropSequence {
                                    identity: storage.sequence_position(sequence_index),
                                    schema: sequence_schema.as_str(),
                                    name: sequence_name.as_str(),
                                },
                            )
                        };
                        if let Err(error) = wal_result {
                            return sql_fail(error);
                        }
                        match storage.drop_sequence(
                            sequence_schema.as_str(),
                            sequence_name.as_str(),
                            txn.txid,
                        ) {
                            Ok(Some(slot)) => {
                                if let Err(error) = txn.record_sequence_change(storage, slot) {
                                    return sql_fail(error);
                                }
                            }
                            Ok(None) => {}
                            Err(error) => return sql_fail(error),
                        }
                    }
                    loop {
                        let statistics_slot = {
                            storage
                                .extended_statistics_for_table(index, txn.txid)
                                .map(|(slot, _)| slot)
                                .next()
                        };
                        let Some(statistics_slot) = statistics_slot else {
                            break;
                        };
                        let definition = storage
                            .extended_statistics(statistics_slot)
                            .definition_for(txn.txid);
                        if let Err(error) =
                            storage.drop_extended_statistics(statistics_slot, txn.txid)
                        {
                            return sql_fail(error);
                        }
                        if def.persistence != crate::storage::RelationPersistence::Temporary {
                            let lsn = storage.bump_lsn();
                            if let Err(error) = wal.stage_reserved(
                                txn.txid,
                                lsn,
                                &WalOp::DropExtendedStatistics {
                                    schema: definition.schema.as_str(),
                                    name: definition.name.as_str(),
                                },
                            ) {
                                storage
                                    .rollback_extended_statistics_drop(statistics_slot, txn.txid);
                                return sql_fail(error);
                            }
                        }
                        if let Err(error) = txn.record_ddl(
                            storage,
                            super::txn::DdlUndo::StatisticsDropped(statistics_slot as u32),
                        ) {
                            storage.rollback_extended_statistics_drop(statistics_slot, txn.txid);
                            return sql_fail(error);
                        }
                    }
                    let trigger_target = crate::storage::TriggerTarget::Table(index as u16);
                    loop {
                        let trigger = storage.triggers_with_slots_visible_to(txn.txid).find_map(
                            |(slot, trigger)| (trigger.target == trigger_target).then_some(slot),
                        );
                        let Some(slot) = trigger else { break };
                        if let Err(error) = storage.drop_trigger(slot, txn.txid) {
                            return sql_fail(error);
                        }
                        if let Err(error) = txn
                            .record_ddl(storage, super::txn::DdlUndo::TriggerDropped(slot as u32))
                        {
                            storage.rollback_trigger_drop(slot, txn.txid);
                            return sql_fail(error);
                        }
                    }
                    let wal_result =
                        if def.persistence == crate::storage::RelationPersistence::Temporary {
                            Ok(())
                        } else {
                            let lsn = storage.bump_lsn();
                            wal.stage_reserved(
                                txn.txid,
                                lsn,
                                &WalOp::DropTable {
                                    identity: storage.table_position(index),
                                    schema: def.schema.as_str(),
                                    name: def.name.as_str(),
                                },
                            )
                        };
                    if let Err(e) = wal_result {
                        return sql_fail(e);
                    }
                    let dropped = match storage.drop_table_in(index, txn.txid) {
                        Ok(undo) => undo,
                        Err(error) => return sql_fail(error),
                    };
                    if let Err(e) = txn.record_table_drop(storage, dropped) {
                        return sql_fail(e);
                    }
                    // A table's indexes are dropped with it (no separate journal
                    // record; DropTable replay re-applies this).
                    storage.drop_indexes_for(index, txn.txid);
                }
                _ if statement.if_exists => {
                    // PostgreSQL's skip notice carries SQLSTATE 00000.
                    responder.notice(
                        crate::sql::eval::sqlstate::SUCCESSFUL_COMPLETION,
                        stack_format!(128, "table \"{}\" does not exist, skipping", name.name)
                            .as_str(),
                    )?;
                }
                _ => return sql_fail(undefined_kind("table", name.name)),
            }
        }
        responder.command_complete(tag)?;
        sql_ok()
    })
}

/// CREATE SCHEMA [IF NOT EXISTS]: registers a schema in the catalog,
/// journaled and transactional like table DDL.
pub fn create_schema(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    name: &str,
    authorization: Option<&str>,
    if_not_exists: bool,
    responder: &mut Responder,
) -> Outcome {
    let authorized_owner = if let Some(written) = authorization {
        let role = resolve_role_name(written);
        let Some(owner) = storage.find_role_visible(role.as_str(), txn.txid) else {
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                role.as_str()
            ));
        };
        let Some(current) = storage.current_role_slot(txn.txid) else {
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            ));
        };
        if !storage.role(current).attributes_to(txn.txid).superuser
            && current != owner
            && !storage.role_can_set(current, owner, txn.txid)
        {
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "must be able to SET ROLE \"{}\"",
                role.as_str()
            ));
        }
        Some(owner)
    } else {
        None
    };
    if name.starts_with("pg_") {
        let mut detail =
            crate::util::StackStr::<{ crate::sql::eval::MAX_DIAGNOSTIC_DETAIL_BYTES }>::new();
        let _ = core::fmt::Write::write_str(
            &mut detail,
            "The prefix \"pg_\" is reserved for system schemas.",
        );
        crate::sql::eval::stash_diagnostic(Some(detail), None);
        return sql_fail(sql_err!(
            crate::sql::eval::sqlstate::RESERVED_NAME,
            "unacceptable schema name \"{}\"",
            name
        ));
    }
    let taken_by_system = name == "information_schema";
    let created = if taken_by_system {
        Err(sql_err!(
            crate::sql::eval::sqlstate::DUPLICATE_SCHEMA,
            "schema \"{}\" already exists",
            name
        ))
    } else {
        let sqlname = match SqlName::parse(name) {
            Ok(n) => n,
            Err(e) => return sql_fail(e),
        };
        storage.create_schema_in(sqlname, txn.txid)
    };
    match created {
        Ok(slot) => {
            if let Some(owner) = authorized_owner
                && let Err(error) = storage.set_schema_owner(slot, owner, txn.txid)
            {
                storage.rollback_schema_create(slot);
                return sql_fail(error);
            }
            let lsn = storage.bump_lsn();
            if let Err(e) = wal.stage_reserved(
                txn.txid,
                lsn,
                &WalOp::CreateSchema {
                    identity: storage
                        .schema_def(slot)
                        .identity()
                        .expect("created schema retains its identity"),
                    name,
                },
            ) {
                storage.rollback_schema_create(slot);
                return sql_fail(e);
            }
            if let Err(e) = txn.record_ddl(storage, super::txn::DdlUndo::SchemaCreated(slot as u32))
            {
                storage.rollback_schema_create(slot);
                return sql_fail(e);
            }
            if let Err(error) = apply_default_privileges_to_new_object(
                storage,
                txn,
                crate::storage::AccessObject {
                    class: crate::storage::AccessClass::Schema,
                    slot: slot as u16,
                },
            ) {
                return sql_fail(error);
            }
        }
        Err(e) if e.sqlstate == crate::sql::eval::sqlstate::DUPLICATE_SCHEMA && if_not_exists => {
            responder.notice(
                crate::sql::eval::sqlstate::DUPLICATE_SCHEMA,
                stack_format!(128, "schema \"{}\" already exists, skipping", name).as_str(),
            )?;
        }
        Err(e) => return sql_fail(e),
    }
    responder.command_complete("CREATE SCHEMA")?;
    sql_ok()
}

/// ALTER SCHEMA keeps the object identity at its catalog slot. Ownership uses
/// the shared ACL transition; rename is journaled as a distinct namespace
/// operation so recovery never expresses it as a drop/create pair.
pub fn alter_schema(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    name: &str,
    action: crate::sql::ast::AlterSchemaAction<'_>,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    match action {
        crate::sql::ast::AlterSchemaAction::OwnerTo(role) => alter_owner(
            storage,
            txn,
            crate::sql::ast::AlterOwnerKind::Schema,
            &QualName::bare(name),
            role,
            false,
            responder,
        ),
        crate::sql::ast::AlterSchemaAction::RenameTo(new_name) => {
            let Some(slot) = storage.find_schema_visible(name, txn.txid) else {
                return sql_fail(sql_err!(
                    sqlstate::INVALID_SCHEMA_NAME,
                    "schema \"{}\" does not exist",
                    name
                ));
            };
            if matches!(new_name, "pg_catalog" | "pg_toast" | "information_schema")
                || storage.find_schema_visible(new_name, txn.txid).is_some()
            {
                return sql_fail(sql_err!(
                    sqlstate::DUPLICATE_SCHEMA,
                    "schema \"{}\" already exists",
                    new_name
                ));
            }
            let object = crate::storage::AccessObject {
                class: crate::storage::AccessClass::Schema,
                slot: slot as u16,
            };
            if let Err(error) = storage.require_owner(object, txn.txid, "schema") {
                return sql_fail(error);
            }
            let Some(role) = storage.current_role_slot(txn.txid) else {
                return sql_fail(sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "current role is not present in the role catalog"
                ));
            };
            if !storage.has_current_database_create_privilege(role, txn.txid) {
                return sql_fail(sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "permission denied for database"
                ));
            }
            if new_name.starts_with("pg_") {
                return sql_fail(sql_err!(
                    sqlstate::RESERVED_NAME,
                    "unacceptable schema name \"{}\"",
                    new_name
                ));
            }
            let new_name = match SqlName::parse(new_name) {
                Ok(name) => name,
                Err(error) => return sql_fail(error),
            };
            let prior_name = storage.schema_def_for(slot, txn.txid).name;
            // Sequence literals in column defaults are textual at the SQL
            // boundary. Rebind them while the old namespace still resolves,
            // then move the whole catalog identity as one WAL operation.
            for sequence_slot in 0..storage.sequence_count() {
                let (schema, sequence_name, visible) = {
                    let sequence = storage.sequence_for(sequence_slot, txn.txid);
                    (
                        sequence.schema,
                        sequence.name,
                        sequence.visible_to(txn.txid),
                    )
                };
                if schema != prior_name || !visible {
                    continue;
                }
                if let Err(error) = rewrite_sequence_default_references(
                    storage,
                    wal,
                    txn,
                    sequence_slot,
                    new_name,
                    sequence_name,
                    arena,
                ) {
                    return sql_fail(error);
                }
            }
            if let Err(error) = schema::rename(storage, txn, slot, new_name, arena) {
                return sql_fail(error);
            }
            let lsn = storage.bump_lsn();
            if let Err(error) = wal.stage_reserved(
                txn.txid,
                lsn,
                &WalOp::RenameSchema {
                    identity: storage
                        .schema_def(slot)
                        .identity()
                        .expect("renamed schema retains its identity"),
                    name: prior_name.as_str(),
                    new_name: new_name.as_str(),
                },
            ) {
                return sql_fail(error);
            }
            responder.command_complete("ALTER SCHEMA")?;
            sql_ok()
        }
    }
}

fn rewrite_object_acl_owner(
    storage: &mut Storage,
    txn: &mut TxnState,
    object: crate::storage::AccessObject,
    old_owner: u16,
    new_owner: u16,
) -> Result<(), SqlError> {
    if old_owner == new_owner {
        return Ok(());
    }
    let acl_count = storage.acl_entry_count();
    for slot in 0..acl_count {
        let entry = storage.acl_entry(slot);
        if entry.object != object || entry.object.slot == u16::MAX {
            continue;
        }
        let (grantee, grantor) = storage.acl_identity(slot, txn.txid);
        if grantee != old_owner && grantor != old_owner {
            continue;
        }
        let prior = storage.change_acl_identity(
            slot,
            if grantee == old_owner {
                new_owner
            } else {
                grantee
            },
            if grantor == old_owner {
                new_owner
            } else {
                grantor
            },
            txn.txid,
        )?;
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ObjectAclChanged {
                slot: slot as u32,
                prior,
            },
        ) {
            storage
                .restore_acl_pending(slot, prior)
                .expect("transaction owns its object ACL undo");
            return Err(error);
        }
    }
    let column_acl_count = storage.column_acl_entry_count();
    for slot in 0..column_acl_count {
        let entry = storage.column_acl_entry(slot);
        if entry.target.relation() != object {
            continue;
        }
        let (grantee, grantor) = storage.column_acl_identity(slot, txn.txid);
        if grantee != old_owner && grantor != old_owner {
            continue;
        }
        let prior = storage.change_column_acl_identity(
            slot,
            if grantee == old_owner {
                new_owner
            } else {
                grantee
            },
            if grantor == old_owner {
                new_owner
            } else {
                grantor
            },
            txn.txid,
        );
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ColumnAclChanged {
                slot: slot as u32,
                prior,
            },
        ) {
            storage.restore_column_acl_pending(slot, prior);
            return Err(error);
        }
    }
    Ok(())
}

fn preserve_object_acl(
    storage: &mut Storage,
    txn: &mut TxnState,
    old_object: crate::storage::AccessObject,
    new_object: crate::storage::AccessObject,
) -> Result<(), SqlError> {
    let acl_count = storage.acl_entry_count();
    for acl_slot in 0..acl_count {
        let entry = storage.acl_entry(acl_slot);
        if entry.object != old_object {
            continue;
        }
        let (grantee, grantor) = storage.acl_identity(acl_slot, txn.txid);
        let (privileges, grant_options) = storage.acl_state(acl_slot, txn.txid);
        let (changed, prior) = storage.change_acl(
            new_object,
            grantee,
            grantor,
            privileges,
            grant_options,
            crate::storage::ObjectAclWrite::Exact {
                transaction: txn.txid,
                order: storage
                    .object_acl_order(acl_slot, txn.txid)
                    .ok_or_else(|| {
                        sql_err!(
                            sqlstate::INTERNAL_ERROR,
                            "copied object ACL has no grant order"
                        )
                    })?,
            },
        )?;
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ObjectAclChanged {
                slot: changed as u32,
                prior,
            },
        ) {
            storage
                .restore_acl_pending(changed, prior)
                .expect("transaction owns its object ACL undo");
            return Err(error);
        }
    }
    let column_acl_count = storage.column_acl_entry_count();
    for acl_slot in 0..column_acl_count {
        let entry = storage.column_acl_entry(acl_slot);
        if entry.target.relation() != old_object {
            continue;
        }
        let (grantee, grantor) = storage.column_acl_identity(acl_slot, txn.txid);
        let (privileges, grant_options) = storage.column_acl_state(acl_slot, txn.txid);
        let target = crate::storage::ColumnPrivilegeTarget::new(new_object, entry.target.column())?;
        let (changed, prior) = storage.change_column_acl(
            target,
            grantee,
            grantor,
            privileges,
            grant_options,
            txn.txid,
        )?;
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ColumnAclChanged {
                slot: changed as u32,
                prior,
            },
        ) {
            storage.restore_column_acl_pending(changed, prior);
            return Err(error);
        }
    }
    Ok(())
}

fn remap_table_column_acls(
    storage: &mut Storage,
    txn: &mut TxnState,
    object: crate::storage::AccessObject,
    mapping: &[u16; MAX_COLUMNS],
) -> Result<(), SqlError> {
    let entry_count = storage.column_acl_entry_count();
    for slot in 0..entry_count {
        let entry = storage.column_acl_entry(slot);
        if entry.target.relation() != object {
            continue;
        }
        let old_column = entry.target.column() as usize;
        let new_column = mapping.get(old_column).copied().unwrap_or(u16::MAX);
        if new_column == entry.target.column() {
            continue;
        }
        let (grantee, grantor) = storage.column_acl_identity(slot, txn.txid);
        let (privileges, grant_options) = storage.column_acl_state(slot, txn.txid);
        let (changed, prior) = storage.change_column_acl(
            entry.target,
            grantee,
            grantor,
            crate::storage::PrivilegeSet::NONE,
            crate::storage::PrivilegeSet::NONE,
            txn.txid,
        )?;
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ColumnAclChanged {
                slot: changed as u32,
                prior,
            },
        ) {
            storage.restore_column_acl_pending(changed, prior);
            return Err(error);
        }
        if new_column == u16::MAX || privileges.0 == 0 {
            continue;
        }
        let target = crate::storage::ColumnPrivilegeTarget::new(object, new_column)?;
        let (changed, prior) = storage.change_column_acl(
            target,
            grantee,
            grantor,
            privileges,
            grant_options,
            txn.txid,
        )?;
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ColumnAclChanged {
                slot: changed as u32,
                prior,
            },
        ) {
            storage.restore_column_acl_pending(changed, prior);
            return Err(error);
        }
    }
    Ok(())
}

fn materialized_view_access_object(
    storage: &Storage,
    name: &QualName,
    txid: u32,
) -> Result<Option<crate::storage::AccessObject>, SqlError> {
    use crate::storage::{AccessClass, AccessObject, ResolvedRelation};
    match storage.resolve_relation(name.schema, name.name, txid) {
        Some(ResolvedRelation::Table(table)) => {
            let definition = storage.table_def(table, txid);
            let Some(slot) =
                storage.matview_slot(definition.schema.as_str(), definition.name.as_str(), txid)
            else {
                return Err(sql_err!(
                    sqlstate::WRONG_OBJECT_TYPE,
                    "\"{}\" is not a materialized view",
                    name.name
                ));
            };
            Ok(Some(AccessObject {
                class: AccessClass::MaterializedView,
                slot: slot as u16,
            }))
        }
        Some(_) => Err(sql_err!(
            sqlstate::WRONG_OBJECT_TYPE,
            "\"{}\" is not a materialized view",
            name.name
        )),
        None => Ok(None),
    }
}

pub fn alter_materialized_view_extension_dependency(
    storage: &mut Storage,
    txn: &mut TxnState,
    name: &QualName,
    extension: &str,
    enabled: bool,
    responder: &mut Responder,
) -> Outcome {
    let object = match materialized_view_access_object(storage, name, txn.txid) {
        Ok(Some(object)) => object,
        Ok(None) => return sql_fail(undefined_qual(name)),
        Err(error) => return sql_fail(error),
    };
    if let Err(error) = storage.require_owner(object, txn.txid, "materialized view") {
        return sql_fail(error);
    }
    if let Err(error) = set_extension_dependency(
        storage,
        txn,
        extension,
        object,
        crate::storage::ExtensionDependencyKind::Automatic,
        enabled,
    ) {
        return sql_fail(error);
    }
    responder.command_complete("ALTER MATERIALIZED VIEW")?;
    sql_ok()
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn alter_materialized_view(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    scratch: &mut DmlScratch,
    name: QualName<'_>,
    if_exists: bool,
    action: crate::sql::ast::AlterMaterializedViewAction<'_>,
    arena: &Arena,
    seq_session: &crate::sql::guc::SeqSession,
    responder: &mut Responder,
) -> Outcome {
    let table = match storage.resolve_relation(name.schema, name.name, txn.txid) {
        Some(crate::storage::ResolvedRelation::Table(table))
            if storage.matview_slot_for_table(table, txn.txid).is_some() =>
        {
            table
        }
        Some(_) => {
            return sql_fail(sql_err!(
                sqlstate::WRONG_OBJECT_TYPE,
                "\"{}\" is not a materialized view",
                name.name
            ));
        }
        None if if_exists => {
            responder.notice(
                sqlstate::SUCCESSFUL_COMPLETION,
                stack_format!(160, "relation \"{}\" does not exist, skipping", name.name).as_str(),
            )?;
            responder.command_complete("ALTER MATERIALIZED VIEW")?;
            return sql_ok();
        }
        None => return sql_fail(undefined_qual(&name)),
    };
    let action = match action {
        crate::sql::ast::AlterMaterializedViewAction::RenameTo(name) => {
            crate::sql::ast::AlterAction::RenameTable(name)
        }
        crate::sql::ast::AlterMaterializedViewAction::SetSchema(schema) => {
            crate::sql::ast::AlterAction::SetSchema(schema)
        }
        crate::sql::ast::AlterMaterializedViewAction::TableActions(actions) => {
            let statement = crate::sql::ast::AlterTable {
                table: name,
                if_exists: false,
                only: false,
                actions,
            };
            return alter_table_inner(
                storage,
                wal,
                txn,
                scratch,
                &statement,
                arena,
                seq_session,
                responder,
                true,
                Some(crate::storage::TableKind::Local),
                "ALTER MATERIALIZED VIEW",
                AlterInheritanceScope::Direct,
            );
        }
    };
    let statement = crate::sql::ast::AlterTable {
        table: name,
        if_exists: false,
        only: false,
        actions: core::slice::from_ref(&action),
    };
    debug_assert_eq!(
        storage.matview_table(
            storage
                .matview_slot_for_table(table, txn.txid)
                .expect("checked materialized view"),
        ),
        table
    );
    alter_table_inner(
        storage,
        wal,
        txn,
        scratch,
        &statement,
        arena,
        seq_session,
        responder,
        true,
        Some(crate::storage::TableKind::Local),
        "ALTER MATERIALIZED VIEW",
        AlterInheritanceScope::Direct,
    )
}

pub(super) fn alter_owner_target(
    storage: &Storage,
    txid: u32,
    kind: crate::sql::ast::AlterOwnerKind,
    name: &QualName,
) -> Result<Option<crate::storage::AccessObject>, SqlError> {
    use crate::sql::ast::AlterOwnerKind;
    use crate::storage::{AccessClass, AccessObject};
    let relation = || storage.resolve_relation(name.schema, name.name, txid);
    Ok(match kind {
        AlterOwnerKind::Schema => {
            storage
                .find_schema_visible(name.name, txid)
                .map(|slot| AccessObject {
                    class: AccessClass::Schema,
                    slot: slot as u16,
                })
        }
        AlterOwnerKind::Type => storage
            .resolve_alter_type_target(name.schema, name.name, txid)
            .map(crate::storage::AlterTypeTarget::access_object),
        AlterOwnerKind::Domain => (match name.schema {
            Some(schema) => storage.domain_slot(schema, name.name, txid),
            None => storage.resolve_domain_slot(name.name, txid),
        })
        .map(|slot| AccessObject {
            class: AccessClass::Domain,
            slot: slot as u16,
        }),
        AlterOwnerKind::Table | AlterOwnerKind::ForeignTable => match relation() {
            Some(crate::storage::ResolvedRelation::Table(slot)) => {
                let definition = storage.table_def(slot, txid);
                storage
                    .matview_slot(definition.schema.as_str(), definition.name.as_str(), txid)
                    .map_or(
                        Some(AccessObject {
                            class: AccessClass::Table,
                            slot: slot as u16,
                        }),
                        |matview| {
                            Some(AccessObject {
                                class: AccessClass::MaterializedView,
                                slot: matview as u16,
                            })
                        },
                    )
            }
            Some(crate::storage::ResolvedRelation::View(slot)) => Some(AccessObject {
                class: AccessClass::View,
                slot: slot as u16,
            }),
            Some(_) => {
                return Err(sql_err!(
                    sqlstate::WRONG_OBJECT_TYPE,
                    "\"{}\" is not a table",
                    name.name
                ));
            }
            None => match resolve_sequence(storage, name, txid) {
                Ok(Some(slot)) => Some(AccessObject {
                    class: AccessClass::Sequence,
                    slot: slot as u16,
                }),
                Ok(None) => None,
                Err(error) => return Err(error),
            },
        },
        AlterOwnerKind::View => match relation() {
            Some(crate::storage::ResolvedRelation::View(slot)) => Some(AccessObject {
                class: AccessClass::View,
                slot: slot as u16,
            }),
            Some(_) => {
                return Err(sql_err!(
                    sqlstate::WRONG_OBJECT_TYPE,
                    "\"{}\" is not a view",
                    name.name
                ));
            }
            None => None,
        },
        AlterOwnerKind::MaterializedView => materialized_view_access_object(storage, name, txid)?,
        AlterOwnerKind::Sequence => match resolve_sequence(storage, name, txid) {
            Ok(Some(slot)) => Some(AccessObject {
                class: AccessClass::Sequence,
                slot: slot as u16,
            }),
            Ok(None) => None,
            Err(error) => return Err(error),
        },
        AlterOwnerKind::Statistics => storage
            .extended_statistics_slot_on_path(name.schema, name.name, txid)
            .map(|slot| AccessObject {
                class: AccessClass::Statistics,
                slot: slot as u16,
            }),
    })
}

pub fn alter_owner(
    storage: &mut Storage,
    txn: &mut TxnState,
    kind: crate::sql::ast::AlterOwnerKind,
    name: &QualName,
    role: &str,
    if_exists: bool,
    responder: &mut Responder,
) -> Outcome {
    use crate::sql::ast::AlterOwnerKind;
    use crate::storage::{AccessClass, AccessObject};
    let (noun, tag) = match kind {
        AlterOwnerKind::Schema => ("schema", "ALTER SCHEMA"),
        AlterOwnerKind::Type => ("type", "ALTER TYPE"),
        AlterOwnerKind::Domain => ("domain", "ALTER DOMAIN"),
        AlterOwnerKind::Table => ("table", "ALTER TABLE"),
        AlterOwnerKind::ForeignTable => ("foreign table", "ALTER FOREIGN TABLE"),
        AlterOwnerKind::View => ("view", "ALTER VIEW"),
        AlterOwnerKind::MaterializedView => ("materialized view", "ALTER MATERIALIZED VIEW"),
        AlterOwnerKind::Sequence => ("sequence", "ALTER SEQUENCE"),
        AlterOwnerKind::Statistics => ("statistics object", "ALTER STATISTICS"),
    };
    let object = match alter_owner_target(storage, txn.txid, kind, name) {
        Ok(object) => object,
        Err(error) => return sql_fail(error),
    };
    let Some(object) = object else {
        if if_exists {
            responder.notice(
                sqlstate::SUCCESSFUL_COMPLETION,
                stack_format!(160, "{} \"{}\" does not exist, skipping", noun, name.name).as_str(),
            )?;
            responder.command_complete(tag)?;
            return sql_ok();
        }
        return sql_fail(match kind {
            AlterOwnerKind::Schema => sql_err!(
                sqlstate::INVALID_SCHEMA_NAME,
                "schema \"{}\" does not exist",
                name.name
            ),
            AlterOwnerKind::Type | AlterOwnerKind::Domain => {
                sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "type \"{}\" does not exist",
                    name.name
                )
            }
            AlterOwnerKind::Sequence => undefined_kind("sequence", name.name),
            AlterOwnerKind::Statistics => sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "statistics object \"{}\" does not exist",
                name.name
            ),
            _ => undefined_qual(name),
        });
    };
    if object.class == AccessClass::Statistics
        && let Err(error) =
            storage.require_extended_statistics_mutation(usize::from(object.slot), txn.txid)
    {
        return sql_fail(error);
    }
    let role = resolve_role_name(role);
    let Some(new_owner) = storage.find_role_visible(role.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            role.as_str()
        ));
    };
    if let Err(error) = storage.role_reference_ready(new_owner, txn.txid) {
        return sql_fail(error);
    }
    if matches!(
        object.class,
        AccessClass::Table
            | AccessClass::View
            | AccessClass::MaterializedView
            | AccessClass::Sequence
    ) && let Err(error) = storage.require_owner(object, txn.txid, noun)
    {
        return sql_fail(error);
    }
    if storage.object_owner(object, txn.txid) == new_owner
        && !(object.class == AccessClass::Schema
            && storage
                .schema_def_for(usize::from(object.slot), txn.txid)
                .has_database_owner(txn.txid))
    {
        responder.command_complete(tag)?;
        return sql_ok();
    }
    let current = super::eval::funcs::system::current_user_owned();
    let Some(current_role) = storage.find_role_visible(current.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            current.as_str()
        ));
    };
    let superuser = storage.role(current_role).attributes_to(txn.txid).superuser;
    if !superuser
        && !storage.role_has_privileges_of(
            current_role,
            storage.object_owner(object, txn.txid),
            txn.txid,
        )
    {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be owner of {} {}",
            noun,
            name.name
        ));
    }
    if !superuser
        && current_role != new_owner
        && !storage.role_can_set(current_role, new_owner, txn.txid)
    {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be able to SET ROLE \"{}\"",
            role.as_str()
        ));
    }
    if !superuser && object.class != AccessClass::Schema {
        let (schema, _) = storage.access_object_name(object);
        if let Err(error) = storage.require_schema_create_as(schema.as_str(), new_owner, txn.txid) {
            return sql_fail(error);
        }
    }
    if object.class == AccessClass::Schema
        && !storage.has_current_database_create_privilege(current_role, txn.txid)
    {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied for database {}",
            storage.current_database_name(txn.txid).as_str()
        ));
    }
    let old_owner = storage.object_owner(object, txn.txid) as u16;
    let prior = if object.class == AccessClass::Schema {
        match storage.set_schema_owner(usize::from(object.slot), new_owner, txn.txid) {
            Ok(prior) => prior,
            Err(error) => return sql_fail(error),
        }
    } else {
        storage.set_object_owner(object, new_owner, txn.txid)
    };
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::ObjectOwnerChanged { object, prior },
    ) {
        storage.restore_object_owner(object, prior);
        return sql_fail(error);
    }
    if let Err(error) = rewrite_object_acl_owner(storage, txn, object, old_owner, new_owner as u16)
    {
        return sql_fail(error);
    }
    if object.class == AccessClass::MaterializedView {
        let backing = AccessObject {
            class: AccessClass::Table,
            slot: storage.matview_table(usize::from(object.slot)) as u16,
        };
        let backing_old_owner = storage.object_owner(backing, txn.txid) as u16;
        let backing_prior = storage.set_object_owner(backing, new_owner, txn.txid);
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ObjectOwnerChanged {
                object: backing,
                prior: backing_prior,
            },
        ) {
            storage.restore_object_owner(backing, backing_prior);
            return sql_fail(error);
        }
        if let Err(error) =
            rewrite_object_acl_owner(storage, txn, backing, backing_old_owner, new_owner as u16)
        {
            return sql_fail(error);
        }
    }
    let index_table = match object.class {
        AccessClass::Table => Some(usize::from(object.slot)),
        AccessClass::MaterializedView => Some(storage.matview_table(usize::from(object.slot))),
        _ => None,
    };
    if let Some(table) = index_table {
        for slot in 0..storage.index_count() {
            if storage.index_table_slot_to(slot, txn.txid) != Some(table)
                || storage
                    .index_visible_to(slot, txn.txid)
                    .is_none_or(|index| !index.mutable_for(txn.txid).kind.live())
            {
                continue;
            }
            let index = AccessObject {
                class: AccessClass::Index,
                slot: u16::try_from(slot).expect("index capacity fits access-object positions"),
            };
            let old_owner = storage.object_owner(index, txn.txid) as u16;
            if usize::from(old_owner) == new_owner {
                continue;
            }
            let prior = storage.set_object_owner(index, new_owner, txn.txid);
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::ObjectOwnerChanged {
                    object: index,
                    prior,
                },
            ) {
                storage.restore_object_owner(index, prior);
                return sql_fail(error);
            }
            if let Err(error) =
                rewrite_object_acl_owner(storage, txn, index, old_owner, new_owner as u16)
            {
                return sql_fail(error);
            }
        }
    }
    responder.command_complete(tag)?;
    sql_ok()
}

pub fn alter_large_object_owner(
    storage: &mut Storage,
    txn: &mut TxnState,
    oid: crate::sql::ast::LargeObjectId,
    role: &str,
    responder: &mut Responder,
) -> Outcome {
    use crate::storage::{AccessClass, AccessObject};
    let Some(slot) = storage.large_object_slot(oid, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "large object {} does not exist",
            oid.get()
        ));
    };
    let object = AccessObject {
        class: AccessClass::LargeObject,
        slot: slot as u16,
    };
    let role = resolve_role_name(role);
    let Some(new_owner) = storage.find_role_visible(role.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            role.as_str()
        ));
    };
    if let Err(error) = storage.role_reference_ready(new_owner, txn.txid) {
        return sql_fail(error);
    }
    let current = super::eval::funcs::system::current_user_owned();
    let Some(current_role) = storage.find_role_visible(current.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            current.as_str()
        ));
    };
    let superuser = storage.role(current_role).attributes_to(txn.txid).superuser;
    if !superuser && storage.object_owner(object, txn.txid) != current_role {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be owner of large object {}",
            oid.get()
        ));
    }
    if !superuser
        && current_role != new_owner
        && !storage.role_can_set(current_role, new_owner, txn.txid)
    {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be able to SET ROLE \"{}\"",
            role.as_str()
        ));
    }
    let old_owner = storage.object_owner(object, txn.txid) as u16;
    let prior = storage.set_object_owner(object, new_owner, txn.txid);
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::ObjectOwnerChanged { object, prior },
    ) {
        storage.restore_object_owner(object, prior);
        return sql_fail(error);
    }
    if let Err(error) = rewrite_object_acl_owner(storage, txn, object, old_owner, new_owner as u16)
    {
        return sql_fail(error);
    }
    responder.command_complete("ALTER LARGE OBJECT")?;
    sql_ok()
}

fn resolve_role_name(written: &str) -> crate::util::StackStr<64> {
    match written {
        "current_role" | "current_user" => super::eval::funcs::system::current_user_owned(),
        "session_user" => super::eval::funcs::system::session_user_owned(),
        _ => crate::util::StackStr::from_str(written),
    }
}

/// PostgreSQL's `check_rolespec_name`: a role written by name in the
/// reserved `pg_` namespace cannot be altered, whether or not it exists.
fn require_alterable_role_name(
    specification: crate::sql::ast::RoleSpecification<'_>,
) -> Result<(), SqlError> {
    match specification {
        crate::sql::ast::RoleSpecification::Name(name) if name.starts_with("pg_") => {
            Err(reserved_role_name(name, "Cannot alter reserved roles."))
        }
        _ => Ok(()),
    }
}

fn reserved_role_name(name: &str, detail: &str) -> SqlError {
    crate::sql::eval::with_detail(
        sql_err!(
            sqlstate::RESERVED_NAME,
            "role name \"{}\" is reserved",
            name
        ),
        format_args!("{detail}"),
    )
}

const RESERVED_ROLE_PREFIX_DETAIL: &str = "Role names starting with \"pg_\" are reserved.";

fn resolve_role_specification(
    specification: crate::sql::ast::RoleSpecification<'_>,
) -> crate::util::StackStr<64> {
    match specification {
        crate::sql::ast::RoleSpecification::Name(name) => crate::util::StackStr::from_str(name),
        crate::sql::ast::RoleSpecification::CurrentRole
        | crate::sql::ast::RoleSpecification::CurrentUser => {
            super::eval::funcs::system::current_user_owned()
        }
        crate::sql::ast::RoleSpecification::SessionUser => {
            super::eval::funcs::system::session_user_owned()
        }
    }
}

fn require_create_role(storage: &Storage, txid: u32) -> Result<(), SqlError> {
    let current = super::eval::funcs::system::current_user_owned();
    let allowed = storage
        .find_role_visible(current.as_str(), txid)
        .is_some_and(|slot| {
            let attributes = storage.role(slot).attributes_to(txid);
            attributes.superuser || attributes.create_role
        });
    if allowed {
        Ok(())
    } else {
        Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied to create role"
        ))
    }
}

/// PostgreSQL's `check_role_membership_authorization`: `pg_database_owner`
/// has only its implicit member, a superuser role is changed only by a
/// superuser, and any other role needs the ADMIN option.
fn require_role_membership_authority(
    storage: &Storage,
    current: usize,
    role: usize,
    grant: bool,
    txid: u32,
) -> Result<(), SqlError> {
    let name = storage.role_name(role, txid);
    if grant && role == crate::storage::PredefinedRole::DatabaseOwner.slot() {
        return Err(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "role \"{}\" cannot have explicit members",
            name.as_str()
        ));
    }
    if storage.role(current).attributes_to(txid).superuser {
        return Ok(());
    }
    let action = if grant { "grant" } else { "revoke" };
    let denied = || {
        sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied to {} role \"{}\"",
            action,
            name.as_str()
        )
    };
    if storage.role(role).attributes_to(txid).superuser {
        return Err(crate::sql::eval::with_detail(
            denied(),
            format_args!(
                "Only roles with the SUPERUSER attribute may {action} roles with the SUPERUSER attribute."
            ),
        ));
    }
    if !storage.role_can_admin(current, role, txid) {
        return Err(crate::sql::eval::with_detail(
            denied(),
            format_args!(
                "Only roles with the ADMIN option on role \"{}\" may {action} this role.",
                name.as_str()
            ),
        ));
    }
    Ok(())
}

fn require_role_attribute_authority(
    storage: &Storage,
    txid: u32,
    options: &crate::sql::ast::RoleOptions<'_>,
) -> Result<(), SqlError> {
    let current = super::eval::funcs::system::current_user_owned();
    let slot = storage
        .find_role_visible(current.as_str(), txid)
        .ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                current.as_str()
            )
        })?;
    let attributes = storage.role(slot).attributes_to(txid);
    if !attributes.superuser
        && (options.superuser == Some(true)
            || options.replication == Some(true)
            || options.bypass_row_level_security == Some(true))
    {
        return Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be superuser to alter superuser, replication, or bypassrls attributes"
        ));
    }
    if !attributes.superuser && options.create_database == Some(true) && !attributes.create_database
    {
        return Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied to grant CREATEDB"
        ));
    }
    Ok(())
}

fn apply_role_options(
    mut attributes: crate::storage::RoleAttributes,
    role_name: &str,
    password_encryption: crate::sql::guc::PasswordEncryption,
    options: &crate::sql::ast::RoleOptions<'_>,
) -> Result<crate::storage::RoleAttributes, SqlError> {
    if let Some(value) = options.superuser {
        attributes.superuser = value;
    }
    if let Some(value) = options.inherit {
        attributes.inherit = value;
    }
    if let Some(value) = options.create_role {
        attributes.create_role = value;
    }
    if let Some(value) = options.create_database {
        attributes.create_database = value;
    }
    if let Some(value) = options.can_login {
        attributes.can_login = value;
    }
    if let Some(value) = options.replication {
        attributes.replication = value;
    }
    if let Some(value) = options.bypass_row_level_security {
        attributes.bypass_row_level_security = value;
    }
    if let Some(value) = options.connection_limit {
        if value < -1 {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "invalid connection limit: {}",
                value
            ));
        }
        attributes.connection_limit = value;
    }
    if let Some(password) = options.password {
        attributes.password = if let Some(password) = password {
            let credential = match password {
                crate::sql::ast::RolePasswordSpec::Plaintext(password) => {
                    if password.len() > crate::storage::ROLE_PASSWORD_MAX {
                        return Err(sql_err!(
                            sqlstate::PROGRAM_LIMIT_EXCEEDED,
                            "role password exceeds {} bytes",
                            crate::storage::ROLE_PASSWORD_MAX
                        ));
                    }
                    match password_encryption {
                        crate::sql::guc::PasswordEncryption::ScramSha256 => {
                            let mut salt = [0u8; 16];
                            if unsafe { libc::getentropy(salt.as_mut_ptr().cast(), salt.len()) }
                                != 0
                            {
                                return Err(sql_err!(
                                    sqlstate::IO_ERROR,
                                    "could not generate role password salt"
                                ));
                            }
                            crate::storage::RoleCredential::Scram(
                                crate::pg::auth::ScramServer::derive(
                                    password,
                                    salt,
                                    crate::pg::auth::SCRAM_ITERATIONS,
                                ),
                            )
                        }
                        crate::sql::guc::PasswordEncryption::Md5 => {
                            let verifier = crate::storage::Md5Verifier::derive(password, role_name)
                                .ok_or_else(|| {
                                    sql_err!(
                                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                                        "role password exceeds bounded MD5 input"
                                    )
                                })?;
                            crate::storage::RoleCredential::Md5(verifier)
                        }
                    }
                }
                crate::sql::ast::RolePasswordSpec::ScramVerifier(verifier) => {
                    crate::storage::RoleCredential::Scram(verifier)
                }
                crate::sql::ast::RolePasswordSpec::Md5Verifier(verifier) => {
                    crate::storage::RoleCredential::Md5(verifier)
                }
            };
            Some(credential)
        } else {
            None
        };
    }
    if let Some(valid_until) = options.valid_until {
        crate::sql::datetime::parse_timestamp(valid_until, true)?;
        let value = crate::util::StackStr::from_str(valid_until);
        if value.is_truncated() {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "VALID UNTIL value exceeds {} bytes",
                crate::storage::ROLE_VALID_UNTIL_MAX
            ));
        }
        attributes.valid_until = Some(value);
    }
    Ok(attributes)
}

pub struct CreateRoleRequest<'a> {
    pub name: &'a str,
    pub options: &'a crate::sql::ast::RoleOptions<'a>,
    pub memberships: &'a crate::sql::ast::RoleMembershipClauses<'a>,
}

pub fn create_role(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    request: CreateRoleRequest<'_>,
    guc: &crate::sql::guc::GucState,
    responder: &mut Responder,
) -> Outcome {
    if let Err(error) = require_create_role(storage, txn.txid) {
        return sql_fail(error);
    }
    if let Err(error) = require_role_attribute_authority(storage, txn.txid, request.options) {
        return sql_fail(error);
    }
    let name = match SqlName::parse(request.name) {
        Ok(name) => name,
        Err(error) => return sql_fail(error),
    };
    let attributes = match apply_role_options(
        crate::storage::RoleAttributes::ORDINARY,
        name.as_str(),
        guc.password_encryption(),
        request.options,
    ) {
        Ok(attributes) => attributes,
        Err(error) => return sql_fail(error),
    };
    if name.as_str().starts_with("pg_") {
        return sql_fail(reserved_role_name(
            name.as_str(),
            RESERVED_ROLE_PREFIX_DETAIL,
        ));
    }
    let (slot, prior) = match storage.create_role(name, attributes, txn.txid) {
        Ok(result) => result,
        Err(error) => return sql_fail(error),
    };
    let lsn = storage.bump_lsn();
    if let Err(error) = wal.stage_reserved(
        txn.txid,
        lsn,
        &WalOp::UpsertRole {
            slot: slot as u16,
            oid: storage.role(slot).oid(),
            name: name.as_str(),
            attributes,
        },
    ) {
        storage.rollback_role_change(slot, prior);
        return sql_fail(error);
    }
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::RoleChanged {
            slot: slot as u32,
            prior,
        },
    ) {
        storage.rollback_role_change(slot, prior);
        return sql_fail(error);
    }
    if request.options.sysid.is_some() {
        responder.notice(
            sqlstate::SUCCESSFUL_COMPLETION,
            "SYSID can no longer be specified",
        )?;
    }
    let current = storage
        .current_role_slot(txn.txid)
        .expect("CREATE ROLE privilege check resolved current role");
    let current_is_superuser = storage.role(current).attributes_to(txn.txid).superuser;
    let membership_count = request
        .memberships
        .in_roles
        .len()
        .saturating_add(request.memberships.role_members.len())
        .saturating_add(request.memberships.admin_members.len())
        .saturating_add(usize::from(!current_is_superuser));
    if membership_count >= txn.ddl_capacity() {
        return sql_fail(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "too many role memberships in one statement"
        ));
    }
    if !current_is_superuser
        && let Err(error) = stage_role_membership(
            storage,
            wal,
            txn,
            slot,
            current,
            usize::from(crate::storage::BOOTSTRAP_ROLE),
            crate::storage::RoleMembershipOptions {
                admin: true,
                inherit: false,
                set: false,
            },
        )
    {
        return sql_fail(error);
    }
    let grantor = current;
    for written in request.memberships.in_roles {
        let resolved = crate::util::StackStr::<64>::from_str(written);
        let Some(parent) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                resolved.as_str()
            ));
        };
        if let Err(error) =
            require_role_membership_authority(storage, grantor, parent, true, txn.txid)
        {
            return sql_fail(error);
        }
        if let Err(error) = stage_role_membership(
            storage,
            wal,
            txn,
            parent,
            slot,
            grantor,
            crate::storage::RoleMembershipOptions {
                inherit: attributes.inherit,
                ..crate::storage::RoleMembershipOptions::DEFAULT
            },
        ) {
            return sql_fail(error);
        }
    }
    for (members, admin) in [
        (request.memberships.role_members, false),
        (request.memberships.admin_members, true),
    ] {
        for written in members {
            let resolved = crate::util::StackStr::<64>::from_str(written);
            let Some(member) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
                return sql_fail(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "role \"{}\" does not exist",
                    resolved.as_str()
                ));
            };
            if member == crate::storage::PredefinedRole::DatabaseOwner.slot() {
                return sql_fail(sql_err!(
                    sqlstate::FEATURE_NOT_SUPPORTED,
                    "role \"{}\" cannot be a member of any role",
                    resolved.as_str()
                ));
            }
            if let Err(error) = stage_role_membership(
                storage,
                wal,
                txn,
                slot,
                member,
                grantor,
                crate::storage::RoleMembershipOptions {
                    admin,
                    inherit: storage.role(member).attributes_to(txn.txid).inherit,
                    ..crate::storage::RoleMembershipOptions::DEFAULT
                },
            ) {
                return sql_fail(error);
            }
        }
    }
    if request.options.password.is_some()
        && matches!(
            attributes.password,
            Some(crate::storage::RoleCredential::Md5(_))
        )
    {
        responder.warning("01P01", "setting an MD5-encrypted password")?;
    }
    responder.command_complete("CREATE ROLE")?;
    sql_ok()
}

fn stage_role_membership(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    role: usize,
    member: usize,
    grantor: usize,
    options: crate::storage::RoleMembershipOptions,
) -> Result<(), SqlError> {
    if role == member || storage.role_is_member_of(role, member, txn.txid) {
        return Err(sql_err!(
            sqlstate::INVALID_GRANT_OPERATION,
            "role \"{}\" is a member of role \"{}\"",
            storage.role_name(role, txn.txid).as_str(),
            storage.role_name(member, txn.txid).as_str()
        ));
    }
    let (membership, prior) =
        storage.change_role_membership(role, member, grantor, options, true, txn.txid)?;

    let lsn = storage.bump_lsn();
    if let Err(error) = wal.stage_reserved(
        txn.txid,
        lsn,
        &WalOp::UpsertRoleMembership {
            identity: storage
                .role_membership(membership)
                .position(membership, txn.txid),
            role: storage.role(role).oid(),
            member: storage.role(member).oid(),
            grantor: storage.role(grantor).oid(),
            options,
        },
    ) {
        storage.rollback_role_membership_change(membership, prior);
        return Err(error);
    }
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::RoleMembershipChanged {
            slot: membership as u32,
            prior,
        },
    ) {
        storage.rollback_role_membership_change(membership, prior);
        return Err(error);
    }
    Ok(())
}

pub fn alter_role(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    specification: crate::sql::ast::RoleSpecification<'_>,
    options: &crate::sql::ast::RoleOptions<'_>,
    guc: &crate::sql::guc::GucState,
    responder: &mut Responder,
) -> Outcome {
    if let Err(error) = require_alterable_role_name(specification) {
        return sql_fail(error);
    }
    let resolved = resolve_role_specification(specification);
    let Some(slot) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            resolved.as_str()
        ));
    };
    let current = super::eval::funcs::system::current_user_owned();
    let current_slot = storage
        .find_role_visible(current.as_str(), txn.txid)
        .expect("CREATE ROLE privilege check resolved current role");
    let current_attributes = storage.role(current_slot).attributes_to(txn.txid);
    let target_attributes = storage.role(slot).attributes_to(txn.txid);
    if !current_attributes.superuser {
        if current_slot != slot
            && (!current_attributes.create_role
                || target_attributes.superuser
                || !storage.role_can_admin(current_slot, slot, txn.txid))
        {
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to alter role \"{}\"",
                resolved.as_str()
            ));
        }
        if current_slot == slot
            && (options.superuser.is_some()
                || options.inherit.is_some()
                || options.create_role.is_some()
                || options.create_database.is_some()
                || options.can_login.is_some()
                || options.replication.is_some()
                || options.bypass_row_level_security.is_some()
                || options.connection_limit.is_some())
        {
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to alter role attributes"
            ));
        }
    }
    if let Err(error) = require_role_attribute_authority(storage, txn.txid, options) {
        return sql_fail(error);
    }
    let attributes = match apply_role_options(
        storage.role(slot).attributes_to(txn.txid),
        storage.role_name(slot, txn.txid).as_str(),
        guc.password_encryption(),
        options,
    ) {
        Ok(attributes) => attributes,
        Err(error) => return sql_fail(error),
    };
    let prior = match storage.alter_role(slot, attributes, txn.txid) {
        Ok(prior) => prior,
        Err(error) => return sql_fail(error),
    };
    let lsn = storage.bump_lsn();
    if let Err(error) = wal.stage_reserved(
        txn.txid,
        lsn,
        &WalOp::UpsertRole {
            slot: slot as u16,
            oid: storage.role(slot).oid(),
            name: storage.role_name(slot, txn.txid).as_str(),
            attributes,
        },
    ) {
        storage.rollback_role_change(slot, prior);
        return sql_fail(error);
    }
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::RoleChanged {
            slot: slot as u32,
            prior,
        },
    ) {
        storage.rollback_role_change(slot, prior);
        return sql_fail(error);
    }
    if options.password.is_some()
        && matches!(
            attributes.password,
            Some(crate::storage::RoleCredential::Md5(_))
        )
    {
        responder.warning("01P01", "setting an MD5-encrypted password")?;
    }
    responder.command_complete("ALTER ROLE")?;
    sql_ok()
}

#[allow(clippy::too_many_arguments)]
pub fn alter_role_setting(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    written_role: Option<crate::sql::ast::RoleSpecification<'_>>,
    written_database: Option<&str>,
    action: crate::sql::ast::RoleSettingAction<'_>,
    guc: &crate::sql::guc::GucState,
    responder: &mut Responder,
) -> Outcome {
    if let Some(specification) = written_role
        && let Err(error) = require_alterable_role_name(specification)
    {
        return sql_fail(error);
    }
    let database = match written_database {
        Some(name) => {
            let Some(slot) = storage.database_slot(name, txn.txid) else {
                return sql_fail(sql_err!(
                    sqlstate::INVALID_CATALOG_NAME,
                    "database \"{}\" does not exist",
                    name
                ));
            };
            Some(storage.database(slot).oid)
        }
        None => None,
    };
    if written_role.is_none() && database.is_none() {
        return sql_fail(sql_err!(
            sqlstate::SYNTAX_ERROR,
            "ALTER ROLE ALL requires IN DATABASE"
        ));
    }
    let current_name = super::eval::funcs::system::current_user_owned();
    let current = storage
        .find_role_visible(current_name.as_str(), txn.txid)
        .expect("current SQL role exists");
    let current_attributes = storage.role(current).attributes_to(txn.txid);
    let scope = if let Some(specification) = written_role {
        let resolved = resolve_role_specification(specification);
        let Some(role) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                resolved.as_str()
            ));
        };
        if !current_attributes.superuser
            && role != current
            && (!current_attributes.create_role || !storage.role_can_admin(current, role, txn.txid))
        {
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to alter role \"{}\"",
                resolved.as_str()
            ));
        }
        if let Some(database) = database {
            crate::storage::RoleSettingScope::RoleInDatabase {
                role: role as u16,
                database,
            }
        } else {
            crate::storage::RoleSettingScope::RoleAllDatabases(role as u16)
        }
    } else {
        if !current_attributes.superuser {
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to alter database role settings"
            ));
        }
        crate::storage::RoleSettingScope::AllRolesInDatabase(database.expect("checked above"))
    };

    let result = match action {
        crate::sql::ast::RoleSettingAction::Set { name, value } => {
            let name = match super::guc::canonical_setting_name(name) {
                Ok(name) => name,
                Err(error) => return sql_fail(error),
            };
            let value = match value {
                crate::sql::ast::RoutineConfigValue::Current => {
                    match super::guc::SettingAuthorization::set(storage, name.as_str(), txn.txid)
                        .and_then(|authorization| guc.capture_setting_value(authorization))
                    {
                        Ok(value) => Some(value),
                        Err(error) => return sql_fail(error),
                    }
                }
                crate::sql::ast::RoutineConfigValue::Default => {
                    // PostgreSQL validates removals only when this scope already has settings.
                    if storage
                        .role_settings()
                        .any(|(_, setting)| setting.visible_to(txn.txid) && setting.scope == scope)
                        && let Err(error) =
                            super::guc::SettingAuthorization::set(storage, name.as_str(), txn.txid)
                                .and_then(|authorization| {
                                    guc.validate_setting_value(authorization, None)
                                })
                    {
                        return sql_fail(error);
                    }
                    None
                }
                crate::sql::ast::RoutineConfigValue::Value(value) => {
                    match super::guc::SettingAuthorization::set(storage, name.as_str(), txn.txid)
                        .and_then(|authorization| {
                            guc.validate_setting_value(authorization, Some(value))
                        }) {
                        Ok(()) => Some(crate::util::StackStr::from_str(value)),
                        Err(error) => return sql_fail(error),
                    }
                }
            };
            if value
                .as_ref()
                .is_some_and(crate::util::StackStr::is_truncated)
            {
                return sql_fail(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "role setting value exceeds {} bytes",
                    crate::storage::ROLE_SETTING_VALUE_MAX
                ));
            }
            stage_role_setting(storage, wal, txn, scope, name, value)
        }
        crate::sql::ast::RoleSettingAction::Reset(name) => {
            if let Some(name) = name
                && storage
                    .role_settings()
                    .any(|(_, setting)| setting.visible_to(txn.txid) && setting.scope == scope)
                && let Err(error) = super::guc::SettingAuthorization::set(storage, name, txn.txid)
                    .and_then(|authorization| guc.validate_setting_value(authorization, None))
            {
                return sql_fail(error);
            }
            let mut result = Ok(());
            loop {
                let next = storage.role_settings().find_map(|(slot, setting)| {
                    (setting.visible_to(txn.txid)
                        && setting.scope == scope
                        && name.is_none_or(|name| setting.name.as_str().eq_ignore_ascii_case(name)))
                    .then_some((slot, setting))
                });
                let Some((_, setting)) = next else { break };
                if let Err(error) = stage_role_setting(storage, wal, txn, scope, setting.name, None)
                {
                    result = Err(error);
                    break;
                }
            }
            result
        }
    };
    if let Err(error) = result {
        return sql_fail(error);
    }
    responder.command_complete("ALTER ROLE")?;
    sql_ok()
}

fn stage_role_setting(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    scope: crate::storage::RoleSettingScope,
    name: SqlName,
    value: Option<crate::util::StackStr<{ crate::storage::ROLE_SETTING_VALUE_MAX }>>,
) -> Result<(), SqlError> {
    if value.is_none()
        && !storage.role_settings().any(|(_, setting)| {
            setting.visible_to(txn.txid) && setting.scope == scope && setting.name == name
        })
    {
        return Ok(());
    }
    let (slot, prior) = storage.change_role_setting(scope, name, value, txn.txid)?;
    let (role, database) = match scope {
        crate::storage::RoleSettingScope::RoleAllDatabases(role) => {
            (Some(storage.role_name(role as usize, txn.txid)), None)
        }
        crate::storage::RoleSettingScope::RoleInDatabase { role, database } => (
            Some(storage.role_name(role as usize, txn.txid)),
            Some(database.get()),
        ),
        crate::storage::RoleSettingScope::AllRolesInDatabase(database) => {
            (None, Some(database.get()))
        }
    };
    let lsn = storage.bump_lsn();
    if let Err(error) = wal.stage_reserved(
        txn.txid,
        lsn,
        &WalOp::SetRoleSetting {
            role: role.as_ref().map(|role| role.as_str()),
            database,
            name: name.as_str(),
            value: value.as_ref().map(|value| value.as_str()),
        },
    ) {
        storage.rollback_role_setting(slot, prior);
        return Err(error);
    }
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::RoleSettingChanged {
            slot: slot as u32,
            prior,
        },
    ) {
        storage.rollback_role_setting(slot, prior);
        return Err(error);
    }
    Ok(())
}

fn stage_system_setting(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    name: SqlName,
    value: Option<crate::util::StackStr<{ crate::storage::ROLE_SETTING_VALUE_MAX }>>,
) -> Result<(), SqlError> {
    let Some((slot, prior)) = storage.change_system_setting(name, value, txn.txid)? else {
        return Ok(());
    };
    let lsn = storage.bump_lsn();
    if let Err(error) = wal.stage_reserved(
        txn.txid,
        lsn,
        &WalOp::SetSystemSetting {
            name: name.as_str(),
            value: value.as_ref().map(|value| value.as_str()),
        },
    ) {
        storage.rollback_system_setting(slot, prior);
        return Err(error);
    }
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::SystemSettingChanged {
            slot: slot as u32,
            prior,
        },
    ) {
        storage.rollback_system_setting(slot, prior);
        return Err(error);
    }
    Ok(())
}

pub fn alter_system(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    name: Option<&str>,
    raw: Option<&str>,
    guc: &crate::sql::guc::GucState,
    responder: &mut Responder,
) -> Outcome {
    let current = storage
        .current_role_slot(txn.txid)
        .expect("current role exists");
    if name.is_none() && !storage.role(current).attributes_to(txn.txid).superuser {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied to perform ALTER SYSTEM RESET ALL"
        ));
    }
    let authorization = match name
        .map(|name| super::guc::SettingAuthorization::alter_system(storage, name, txn.txid))
        .transpose()
    {
        Ok(authorization) => authorization,
        Err(error) => return sql_fail(error),
    };
    match (authorization, raw) {
        (Some(authorization), Some(raw)) => {
            let name = match super::guc::canonical_setting_name(authorization.name()) {
                Ok(name) => name,
                Err(error) => return sql_fail(error),
            };
            let value = match guc.validate_setting_value(authorization, Some(raw)) {
                Ok(()) => crate::util::StackStr::from_str(raw),
                Err(error) => return sql_fail(error),
            };
            if value.is_truncated() {
                return sql_fail(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "system setting value is too long"
                ));
            }
            if let Err(error) = stage_system_setting(storage, wal, txn, name, Some(value)) {
                return sql_fail(error);
            }
        }
        (Some(authorization), None) => {
            if let Err(error) = guc.validate_system_reset(authorization) {
                return sql_fail(error);
            }
            let name = match super::guc::canonical_setting_name(authorization.name()) {
                Ok(name) => name,
                Err(error) => return sql_fail(error),
            };
            if let Err(error) = stage_system_setting(storage, wal, txn, name, None) {
                return sql_fail(error);
            }
        }
        (None, None) => {
            let mut targets = [SqlName::EMPTY; crate::storage::MAX_SYSTEM_SETTINGS];
            let mut count = 0;
            for (_, setting) in storage.system_settings() {
                if setting.visible_to(txn.txid) {
                    targets[count] = setting.name;
                    count += 1;
                }
            }
            for &name in &targets[..count] {
                if let Err(error) = stage_system_setting(storage, wal, txn, name, None) {
                    return sql_fail(error);
                }
            }
        }
        (None, Some(_)) => unreachable!("parser gives ALTER SYSTEM SET a name"),
    }
    responder.command_complete("ALTER SYSTEM")?;
    sql_ok()
}

pub fn rename_role(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    specification: crate::sql::ast::RoleSpecification<'_>,
    new_name: &str,
    responder: &mut Responder,
) -> Outcome {
    let resolved = resolve_role_specification(specification);
    let Some(slot) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            resolved.as_str()
        ));
    };
    if resolved.as_str() == super::eval::funcs::system::session_user_owned().as_str() {
        return sql_fail(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "session user cannot be renamed"
        ));
    }
    if resolved.as_str() == super::eval::funcs::system::current_user_owned().as_str() {
        return sql_fail(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "current user cannot be renamed"
        ));
    }
    // PostgreSQL 18.6 RenameRole: reserved names, then a taken new name,
    // then the caller's authority.
    for name in [resolved.as_str(), new_name] {
        if name.starts_with("pg_") {
            return sql_fail(reserved_role_name(name, RESERVED_ROLE_PREFIX_DETAIL));
        }
    }
    let new_name = match SqlName::parse(new_name) {
        Ok(name) => name,
        Err(error) => return sql_fail(error),
    };
    if storage
        .find_role_visible(new_name.as_str(), txn.txid)
        .is_some()
    {
        return sql_fail(sql_err!(
            sqlstate::DUPLICATE_OBJECT,
            "role \"{}\" already exists",
            new_name.as_str()
        ));
    }
    let current = storage.current_role_slot(txn.txid);
    let current_attributes = current.map(|current| storage.role(current).attributes_to(txn.txid));
    if !current_attributes.is_some_and(|attributes| attributes.superuser) {
        let denied = sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied to rename role"
        );
        if storage.role(slot).attributes_to(txn.txid).superuser {
            return sql_fail(crate::sql::eval::with_detail(
                denied,
                format_args!(
                    "Only roles with the SUPERUSER attribute may rename roles with the SUPERUSER attribute."
                ),
            ));
        }
        if !current_attributes.is_some_and(|attributes| attributes.create_role)
            || !current.is_some_and(|current| storage.role_can_admin(current, slot, txn.txid))
        {
            return sql_fail(crate::sql::eval::with_detail(
                denied,
                format_args!(
                    "Only roles with the CREATEROLE attribute and the ADMIN option on role \"{}\" may rename this role.",
                    resolved.as_str()
                ),
            ));
        }
    }
    let old_name = storage.role(slot).name_to(txn.txid);
    let prior = match storage.rename_role(slot, new_name, txn.txid) {
        Ok(prior) => prior,
        Err(error) => return sql_fail(error),
    };
    let lsn = storage.bump_lsn();
    if let Err(error) = wal.stage_reserved(
        txn.txid,
        lsn,
        &WalOp::RenameRole {
            name: old_name.as_str(),
            new_name: new_name.as_str(),
        },
    ) {
        storage.rollback_role_change(slot, prior);
        return sql_fail(error);
    }
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::RoleChanged {
            slot: slot as u32,
            prior,
        },
    ) {
        storage.rollback_role_change(slot, prior);
        return sql_fail(error);
    }
    responder.command_complete("ALTER ROLE")?;
    sql_ok()
}

/// PostgreSQL's `DETAIL` for a role that objects still depend on: one line
/// per object in the current database (`owner of table t`, `privileges for
/// function f(integer)`), at most 100, then a count of the rest.
fn role_dependency_detail(
    storage: &Storage,
    role: usize,
    txid: u32,
    arena: &Arena,
) -> Result<
    Option<crate::util::StackStr<{ crate::sql::eval::MAX_DIAGNOSTIC_DETAIL_BYTES }>>,
    SqlError,
> {
    use core::fmt::Write;
    const MAX_REPORTED_DEPENDENCIES: usize = 100;
    let mark = arena.mark();
    let result = (|| {
        let catalog = super::query::storage_catalog(storage, arena, txid);
        let mut detail =
            crate::util::StackStr::<{ crate::sql::eval::MAX_DIAGNOSTIC_DETAIL_BYTES }>::new();
        let mut reported = 0usize;
        let mut unreported = 0usize;
        for dependency in super::catalog::shared_dependencies(storage, txid, arena)? {
            if usize::from(dependency.role) != role || dependency.database.is_some() {
                continue;
            }
            let Some(description) = super::eval::funcs::system::describe_object_text(
                &catalog,
                dependency.class,
                dependency.object,
                dependency.sub,
                arena,
            )?
            else {
                continue;
            };
            let prefix = match dependency.kind {
                b'o' => "owner of ",
                b'r' => "target of ",
                _ => "privileges for ",
            };
            let separator = if reported == 0 { "" } else { "\n" };
            if reported == MAX_REPORTED_DEPENDENCIES
                || detail.len() + separator.len() + prefix.len() + description.len()
                    > crate::sql::eval::MAX_DIAGNOSTIC_DETAIL_BYTES - 64
            {
                unreported += 1;
                continue;
            }
            let _ = write!(detail, "{separator}{prefix}{description}");
            reported += 1;
        }
        if unreported != 0 {
            let _ = write!(
                detail,
                "\nand {} other object{} (see server log for list)",
                unreported,
                if unreported == 1 { "" } else { "s" }
            );
        }
        for &(database, count) in
            super::catalog::other_database_role_dependencies(storage, txid, role, arena)?
        {
            let Some(name) = storage
                .database_slot_by_oid(database, txid)
                .map(|slot| storage.database_definition(slot, txid).name)
            else {
                continue;
            };
            let _ = write!(
                detail,
                "{}{} object{} in database {}",
                if reported == 0 && unreported == 0 {
                    ""
                } else {
                    "\n"
                },
                count,
                if count == 1 { "" } else { "s" },
                name.as_str()
            );
            reported += 1;
        }
        Ok((reported != 0).then_some(detail))
    })();
    // The detail was copied out of the workspace.
    unsafe { arena.rewind_to(mark) };
    result
}

#[expect(
    clippy::too_many_arguments,
    reason = "DROP ROLE reads session identities and describes dependents"
)]
pub fn drop_role(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    guc: &crate::sql::guc::GucState,
    names: &[&str],
    if_exists: bool,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    if require_create_role(storage, txn.txid).is_err() {
        return sql_fail(crate::sql::eval::with_detail(
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to drop role"
            ),
            format_args!(
                "Only roles with the CREATEROLE attribute and the ADMIN option on the target roles may drop roles."
            ),
        ));
    }
    let current = storage.current_role_slot(txn.txid);
    let current_superuser =
        current.is_some_and(|current| storage.role(current).attributes_to(txn.txid).superuser);
    let protected = [
        current,
        storage.session_role_slot(guc.current_identity().source(), txn.txid),
    ];
    let session = storage.session_role_slot(guc.session_identity().source(), txn.txid);
    for written in names {
        let resolved = crate::util::StackStr::<64>::from_str(written);
        let Some(slot) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
            if if_exists {
                responder.notice(
                    sqlstate::SUCCESSFUL_COMPLETION,
                    stack_format!(
                        128,
                        "role \"{}\" does not exist, skipping",
                        resolved.as_str()
                    )
                    .as_str(),
                )?;
                continue;
            }
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                resolved.as_str()
            ));
        };
        if protected.contains(&Some(slot)) {
            return sql_fail(sql_err!(
                sqlstate::OBJECT_IN_USE,
                "current user cannot be dropped"
            ));
        }
        if session == Some(slot) {
            return sql_fail(sql_err!(
                sqlstate::OBJECT_IN_USE,
                "session user cannot be dropped"
            ));
        }
        if !current_superuser {
            let denied = sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to drop role"
            );
            if storage.role(slot).attributes_to(txn.txid).superuser {
                return sql_fail(crate::sql::eval::with_detail(
                    denied,
                    format_args!(
                        "Only roles with the SUPERUSER attribute may drop roles with the SUPERUSER attribute."
                    ),
                ));
            }
            if !current.is_some_and(|current| storage.role_can_admin(current, slot, txn.txid)) {
                return sql_fail(crate::sql::eval::with_detail(
                    denied,
                    format_args!(
                        "Only roles with the CREATEROLE attribute and the ADMIN option on role \"{}\" may drop this role.",
                        resolved.as_str()
                    ),
                ));
            }
        }
        if let Err(error) = storage.lock_role_for_drop(slot, txn.txid) {
            return sql_fail(error);
        }
        let membership_count = (0..storage.role_membership_count())
            .filter(|membership_slot| {
                let membership = storage.role_membership(*membership_slot);
                membership.visible_to(txn.txid)
                    && (membership.role as usize == slot || membership.member as usize == slot)
            })
            .count();
        let setting_count = storage
            .role_settings()
            .filter(|(_, setting)| {
                setting.visible_to(txn.txid)
                    && setting
                        .scope
                        .role()
                        .is_some_and(|role| role as usize == slot)
            })
            .count();
        if membership_count + setting_count + 1 > txn.ddl_capacity() {
            return sql_fail(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "dropping role \"{}\" changes too many role memberships",
                resolved.as_str()
            ));
        }
        // PostgreSQL removes memberships that name a dropped role.  Make each
        // removal a normal transactional catalog transition so WAL/recovery
        // and savepoint rollback cannot retain a dangling role slot.
        for membership_slot in 0..storage.role_membership_count() {
            let membership = storage.role_membership(membership_slot);
            if !membership.visible_to(txn.txid)
                || (membership.role as usize != slot && membership.member as usize != slot)
            {
                continue;
            }

            let (changed_slot, prior) = match storage.change_role_membership(
                membership.role as usize,
                membership.member as usize,
                membership.grantor as usize,
                membership.options_to(txn.txid),
                false,
                txn.txid,
            ) {
                Ok(changed) => changed,
                Err(error) => return sql_fail(error),
            };
            let lsn = storage.bump_lsn();
            if let Err(error) = wal.stage_reserved(
                txn.txid,
                lsn,
                &WalOp::DropRoleMembership {
                    identity: storage
                        .role_membership(changed_slot)
                        .position(changed_slot, txn.txid),
                },
            ) {
                storage.rollback_role_membership_change(changed_slot, prior);
                return sql_fail(error);
            }
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::RoleMembershipChanged {
                    slot: changed_slot as u32,
                    prior,
                },
            ) {
                storage.rollback_role_membership_change(changed_slot, prior);
                return sql_fail(error);
            }
        }
        loop {
            let setting = storage.role_settings().find_map(|(_, setting)| {
                (setting.visible_to(txn.txid)
                    && setting
                        .scope
                        .role()
                        .is_some_and(|role| role as usize == slot))
                .then_some(setting)
            });
            let Some(setting) = setting else { break };
            if let Err(error) =
                stage_role_setting(storage, wal, txn, setting.scope, setting.name, None)
            {
                return sql_fail(error);
            }
        }
    }
    // Membership cleanup covers the complete target set before grantor and
    // object dependencies are checked, including duplicate role names.
    for written in names {
        let Some(slot) = storage.find_role_visible(written, txn.txid) else {
            continue;
        };
        let resolved = crate::util::StackStr::<64>::from_str(written);
        let dependency = match storage.role_object_dependency(slot, txn.txid) {
            Ok(dependency) => dependency,
            Err(error) => return sql_fail(error),
        };
        if dependency.is_some() {
            match role_dependency_detail(storage, slot, txn.txid, arena) {
                Ok(Some(detail)) => super::eval::stash_diagnostic(Some(detail), None),
                Ok(None) => {}
                Err(error) => return sql_fail(error),
            }
            return sql_fail(sql_err!(
                sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                "role \"{}\" cannot be dropped because some objects depend on it",
                resolved.as_str()
            ));
        }
        let name = storage.role_name(slot, txn.txid);
        let prior = match storage.drop_role_in(slot, txn.txid) {
            Ok(prior) => prior,
            Err(error) => return sql_fail(error),
        };
        let lsn = storage.bump_lsn();
        if let Err(error) = wal.stage_reserved(
            txn.txid,
            lsn,
            &WalOp::DropRole {
                name: name.as_str(),
            },
        ) {
            storage.rollback_role_change(slot, prior);
            return sql_fail(error);
        }
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::RoleChanged {
                slot: slot as u32,
                prior,
            },
        ) {
            storage.rollback_role_change(slot, prior);
            return sql_fail(error);
        }
    }
    responder.command_complete("DROP ROLE")?;
    sql_ok()
}

pub fn set_role(
    storage: &Storage,
    txn: &TxnState,
    guc: &crate::sql::guc::GucState,
    role: Option<&str>,
    local: bool,
    reset: bool,
    responder: &mut Responder,
) -> Outcome {
    let Some(written) = role else {
        guc.reset_role(local);
        super::eval::funcs::system::set_current_user(
            guc.current_identity().refresh(storage, txn.txid),
        );
        responder.command_complete(if reset { "RESET" } else { "SET" })?;
        return sql_ok();
    };
    let resolved = resolve_role_name(written);
    let Some(target) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            resolved.as_str()
        ));
    };
    let current_slot = storage.session_role_slot(guc.session_identity().source(), txn.txid);
    let current_superuser =
        current_slot.is_some_and(|slot| storage.role(slot).attributes_to(txn.txid).superuser);
    if !current_superuser
        && !current_slot.is_some_and(|member| storage.role_can_set(member, target, txn.txid))
    {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied to set role \"{}\"",
            resolved.as_str()
        ));
    }
    let target = match storage.capture_role_slot(target, txn.txid) {
        Ok(role) => crate::storage::SessionIdentity::bound(role),
        Err(error) => return sql_fail(error),
    };
    guc.set_role(target, local);
    super::eval::funcs::system::set_current_user(target);
    responder.command_complete("SET")?;
    sql_ok()
}

pub fn set_session_authorization(
    storage: &Storage,
    txn: &TxnState,
    guc: &crate::sql::guc::GucState,
    role: Option<&str>,
    local: bool,
    reset: bool,
    responder: &mut Responder,
) -> Outcome {
    if role.is_none() {
        guc.reset_session_authorization(local);
        super::eval::funcs::system::set_session_user(
            guc.session_identity().refresh(storage, txn.txid),
        );
        super::eval::funcs::system::set_current_user(
            guc.current_identity().refresh(storage, txn.txid),
        );
        responder.command_complete(if reset { "RESET" } else { "SET" })?;
        return sql_ok();
    }
    let Some(authenticated_slot) =
        storage.session_role_slot(guc.authenticated_identity().source(), txn.txid)
    else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "authenticated role \"{}\" no longer exists",
            guc.authenticated_user()
        ));
    };
    let authenticated_superuser = storage
        .role(authenticated_slot)
        .attributes_to(txn.txid)
        .superuser;

    let target_name = role.expect("the reset/default case returned above");
    let Some(target) = storage.find_role_visible(target_name, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            target_name
        ));
    };
    if !authenticated_superuser && target != authenticated_slot {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied to set session authorization \"{}\"",
            target_name
        ));
    }

    if reset {
        guc.reset_session_authorization(local);
    } else {
        let canonical = match storage.capture_role_slot(target, txn.txid) {
            Ok(role) => crate::storage::SessionIdentity::bound(role),
            Err(error) => return sql_fail(error),
        };
        guc.set_session_authorization(canonical, local);
    }
    super::eval::funcs::system::set_session_user(guc.session_identity().refresh(storage, txn.txid));
    super::eval::funcs::system::set_current_user(guc.current_identity().refresh(storage, txn.txid));
    responder.command_complete(if reset { "RESET" } else { "SET" })?;
    sql_ok()
}

pub struct GrantRoleRequest<'a> {
    pub syntax: crate::sql::ast::RoleMembershipSyntax,
    pub roles: &'a [&'a str],
    pub members: &'a [&'a str],
    pub options: crate::sql::ast::RoleMembershipPatch,
    pub grantor: Option<&'a str>,
}

pub fn grant_role(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    request: GrantRoleRequest<'_>,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    let GrantRoleRequest {
        syntax,
        roles,
        members,
        options,
        grantor: written_grantor,
    } = request;
    if roles.len().saturating_mul(members.len()) > txn.ddl_capacity() {
        return sql_fail(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "too many role memberships in one statement (limit {})",
            txn.ddl_capacity()
        ));
    }
    let current = super::eval::funcs::system::current_user_owned();
    let Some(current_slot) = storage.find_role_visible(current.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            current.as_str()
        ));
    };
    let current_superuser = storage.role(current_slot).attributes_to(txn.txid).superuser;
    let selected_grantor = if let Some(written) = written_grantor {
        let resolved = resolve_role_name(written);
        let Some(slot) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                resolved.as_str()
            ));
        };
        if !current_superuser && !storage.role_has_privileges_of(current_slot, slot, txn.txid) {
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to grant privileges as role \"{}\"",
                resolved.as_str()
            ));
        }
        Some(slot)
    } else {
        None
    };
    let role_slots = match arena.alloc_slice_with(roles.len(), |_| (0usize, 0usize)) {
        Ok(slots) => slots,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let member_slots = match arena.alloc_slice_with(members.len(), |_| 0usize) {
        Ok(slots) => slots,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    // PostgreSQL resolves every recipient before the first granted role.
    for (index, written) in members.iter().enumerate() {
        let resolved = resolve_role_name(written);
        let Some(slot) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                resolved.as_str()
            ));
        };
        member_slots[index] = slot;
    }
    for (index, written) in roles.iter().enumerate() {
        let resolved = resolve_role_name(written);
        let Some(slot) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                resolved.as_str()
            ));
        };
        if let Err(error) =
            require_role_membership_authority(storage, current_slot, slot, true, txn.txid)
        {
            return sql_fail(error);
        }
        let grantor = if let Some(grantor) = selected_grantor {
            let direct_admin = (0..storage.role_membership_count()).any(|membership| {
                let membership = storage.role_membership(membership);
                membership.visible_to(txn.txid)
                    && usize::from(membership.role) == slot
                    && usize::from(membership.member) == grantor
                    && membership.options_to(txn.txid).admin
            });
            if grantor != 0 && !direct_admin {
                return sql_fail(sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "permission denied to grant privileges as role \"{}\"",
                    storage.role_name(grantor, txn.txid).as_str()
                ));
            }
            grantor
        } else {
            match storage.role_membership_grantor(current_slot, slot, txn.txid, arena) {
                Ok(grantor) => grantor,
                Err(error) => return sql_fail(error),
            }
        };
        role_slots[index] = (slot, grantor);
    }
    for &(role, grantor) in &*role_slots {
        if let Err(error) = storage.lock_role_memberships(role, txn.txid) {
            return sql_fail(error);
        }
        for &member in &*member_slots {
            if member == crate::storage::PredefinedRole::DatabaseOwner.slot() {
                return sql_fail(sql_err!(
                    sqlstate::FEATURE_NOT_SUPPORTED,
                    "role \"{}\" cannot be a member of any role",
                    storage.role_name(member, txn.txid).as_str()
                ));
            }
            if role == member || storage.role_is_member_of(role, member, txn.txid) {
                return sql_fail(sql_err!(
                    sqlstate::INVALID_GRANT_OPERATION,
                    "role \"{}\" is a member of role \"{}\"",
                    storage.role_name(role, txn.txid).as_str(),
                    storage.role_name(member, txn.txid).as_str()
                ));
            }
        }
        if options.admin == Some(true)
            && let Err(error) =
                storage.validate_role_admin_grants(role, grantor, member_slots, txn.txid, arena)
        {
            return sql_fail(error);
        }
        for &member in &*member_slots {
            let existing = storage.find_role_membership_visible(role, member, grantor, txn.txid);
            let base = existing.map_or_else(
                || crate::storage::RoleMembershipOptions {
                    admin: false,
                    inherit: storage.role(member).attributes_to(txn.txid).inherit,
                    set: true,
                },
                |slot| storage.role_membership(slot).options_to(txn.txid),
            );
            let membership_options = crate::storage::RoleMembershipOptions {
                admin: options.admin.unwrap_or(base.admin),
                inherit: options.inherit.unwrap_or(base.inherit),
                set: options.set.unwrap_or(base.set),
            };
            if existing.is_some() && membership_options == base {
                responder.notice(sqlstate::SUCCESSFUL_COMPLETION, stack_format!(320,
                    "role \"{}\" has already been granted membership in role \"{}\" by role \"{}\"",
                    storage.role_name(member, txn.txid).as_str(), storage.role_name(role, txn.txid).as_str(),
                    storage.role_name(grantor, txn.txid).as_str()).as_str())?;
                continue;
            }
            let (slot, prior) = match storage.change_role_membership(
                role,
                member,
                grantor,
                membership_options,
                true,
                txn.txid,
            ) {
                Ok(changed) => changed,
                Err(error) => return sql_fail(error),
            };
            let lsn = storage.bump_lsn();

            let operation = WalOp::UpsertRoleMembership {
                identity: storage.role_membership(slot).position(slot, txn.txid),
                role: storage.role(role).oid(),
                member: storage.role(member).oid(),
                grantor: storage.role(grantor).oid(),
                options: membership_options,
            };
            if let Err(error) = wal.stage_reserved(txn.txid, lsn, &operation) {
                storage.rollback_role_membership_change(slot, prior);
                return sql_fail(error);
            }
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::RoleMembershipChanged {
                    slot: slot as u32,
                    prior,
                },
            ) {
                storage.rollback_role_membership_change(slot, prior);
                return sql_fail(error);
            }
        }
    }
    responder.command_complete(syntax.grant_tag())?;
    sql_ok()
}

pub struct RevokeRoleRequest<'a> {
    pub syntax: crate::sql::ast::RoleMembershipSyntax,
    pub roles: &'a [&'a str],
    pub members: &'a [&'a str],
    pub option: Option<crate::sql::ast::RoleMembershipOption>,
    pub grantor: Option<&'a str>,
    pub cascade: bool,
}

pub fn revoke_role(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    request: RevokeRoleRequest<'_>,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    let RevokeRoleRequest {
        syntax,
        roles,
        members,
        option,
        grantor: written_grantor,
        cascade,
    } = request;
    if roles.len().saturating_mul(members.len()) > txn.ddl_capacity() {
        return sql_fail(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "too many role memberships in one statement (limit {})",
            txn.ddl_capacity()
        ));
    }
    let current = super::eval::funcs::system::current_user_owned();
    let Some(current_slot) = storage.find_role_visible(current.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            current.as_str()
        ));
    };
    let current_superuser = storage.role(current_slot).attributes_to(txn.txid).superuser;
    let selected_grantor = if let Some(written) = written_grantor {
        let resolved = resolve_role_name(written);
        let Some(slot) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                resolved.as_str()
            ));
        };
        if !current_superuser && !storage.role_has_privileges_of(current_slot, slot, txn.txid) {
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to revoke privileges granted by role \"{}\"",
                resolved.as_str()
            ));
        }
        Some(slot)
    } else {
        None
    };
    for role_name in roles {
        let role_name = resolve_role_name(role_name);
        let Some(role) = storage.find_role_visible(role_name.as_str(), txn.txid) else {
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                role_name.as_str()
            ));
        };
        if let Err(error) = storage.lock_role_memberships(role, txn.txid) {
            return sql_fail(error);
        }
        if let Err(error) =
            require_role_membership_authority(storage, current_slot, role, false, txn.txid)
        {
            return sql_fail(error);
        }
        for member_name in members {
            let member_name = resolve_role_name(member_name);
            let Some(member) = storage.find_role_visible(member_name.as_str(), txn.txid) else {
                return sql_fail(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "role \"{}\" does not exist",
                    member_name.as_str()
                ));
            };
            let grantor = match selected_grantor {
                Some(grantor) => grantor,
                None => {
                    match storage.role_membership_grantor(current_slot, role, txn.txid, arena) {
                        Ok(grantor) => grantor,
                        Err(error) => return sql_fail(error),
                    }
                }
            };
            let Some(existing) =
                storage.find_role_membership_visible(role, member, grantor, txn.txid)
            else {
                responder.warning(
                    sqlstate::WARNING,
                    stack_format!(
                        320,
                        "role \"{}\" has not been granted membership in role \"{}\" by role \"{}\"",
                        member_name.as_str(),
                        role_name.as_str(),
                        storage.role_name(grantor, txn.txid).as_str()
                    )
                    .as_str(),
                )?;
                continue;
            };
            let old_options = storage.role_membership(existing).options_to(txn.txid);
            let (exists, options) = match option {
                Some(crate::sql::ast::RoleMembershipOption::Admin) => (
                    true,
                    crate::storage::RoleMembershipOptions {
                        admin: false,
                        ..old_options
                    },
                ),
                Some(crate::sql::ast::RoleMembershipOption::Inherit) => (
                    true,
                    crate::storage::RoleMembershipOptions {
                        inherit: false,
                        ..old_options
                    },
                ),
                Some(crate::sql::ast::RoleMembershipOption::Set) => (
                    true,
                    crate::storage::RoleMembershipOptions {
                        set: false,
                        ..old_options
                    },
                ),
                None => (false, old_options),
            };
            let loses_admin = old_options.admin
                && (!exists || !options.admin)
                && !storage.role_can_admin_excluding(member, role, existing, txn.txid);
            if loses_admin && storage.role_has_grants_from(role, member, txn.txid) && !cascade {
                return sql_fail(sql_err!(
                    sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                    "dependent role privileges exist"
                ));
            }
            let row_grantor = storage.role_membership(existing).grantor as usize;
            let (slot, prior) = match storage.change_role_membership(
                role,
                member,
                row_grantor,
                options,
                exists,
                txn.txid,
            ) {
                Ok(changed) => changed,
                Err(error) => return sql_fail(error),
            };
            let lsn = storage.bump_lsn();

            let operation = if exists {
                WalOp::UpsertRoleMembership {
                    identity: storage.role_membership(slot).position(slot, txn.txid),
                    role: storage.role(role).oid(),
                    member: storage.role(member).oid(),
                    grantor: storage.role(row_grantor).oid(),
                    options,
                }
            } else {
                WalOp::DropRoleMembership {
                    identity: storage.role_membership(slot).position(slot, txn.txid),
                }
            };
            if let Err(error) = wal.stage_reserved(txn.txid, lsn, &operation) {
                storage.rollback_role_membership_change(slot, prior);
                return sql_fail(error);
            }
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::RoleMembershipChanged {
                    slot: slot as u32,
                    prior,
                },
            ) {
                storage.rollback_role_membership_change(slot, prior);
                return sql_fail(error);
            }
            if loses_admin
                && cascade
                && let Err(error) =
                    cascade_role_membership_grants(storage, wal, txn, role, member, arena)
            {
                return sql_fail(error);
            }
        }
    }
    responder.command_complete(syntax.revoke_tag())?;
    sql_ok()
}

fn cascade_role_membership_grants(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    role: usize,
    first_grantor: usize,
    arena: &Arena,
) -> Result<(), SqlError> {
    let queue = arena
        .alloc_slice_with(storage.role_count(), |_| 0u16)
        .map_err(|_| super::query::arena_full_pub())?;
    let queued = arena
        .alloc_slice_with(storage.role_count(), |_| false)
        .map_err(|_| super::query::arena_full_pub())?;
    let dependent = arena
        .alloc_slice_with(storage.role_membership_count(), |_| usize::MAX)
        .map_err(|_| super::query::arena_full_pub())?;
    queue[0] = first_grantor as u16;
    queued[first_grantor] = true;
    let mut at = 0usize;
    let mut count = 1usize;
    while at < count {
        let lost_grantor = queue[at] as usize;
        at += 1;
        let mut dependent_count = 0usize;
        for slot in 0..storage.role_membership_count() {
            let membership = storage.role_membership(slot);
            if membership.visible_to(txn.txid)
                && membership.role as usize == role
                && membership.grantor as usize == lost_grantor
            {
                dependent[dependent_count] = slot;
                dependent_count += 1;
            }
        }
        for &slot in &dependent[..dependent_count] {
            let membership = storage.role_membership(slot);
            if !membership.visible_to(txn.txid) {
                continue;
            }
            let member = membership.member as usize;
            let options = membership.options_to(txn.txid);
            let grantor = membership.grantor as usize;
            let propagates =
                options.admin && !storage.role_can_admin_excluding(member, role, slot, txn.txid);
            let (changed, prior) =
                storage.change_role_membership(role, member, grantor, options, false, txn.txid)?;

            let lsn = storage.bump_lsn();
            if let Err(error) = wal.stage_reserved(
                txn.txid,
                lsn,
                &WalOp::DropRoleMembership {
                    identity: storage.role_membership(changed).position(changed, txn.txid),
                },
            ) {
                storage.rollback_role_membership_change(changed, prior);
                return Err(error);
            }
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::RoleMembershipChanged {
                    slot: changed as u32,
                    prior,
                },
            ) {
                storage.rollback_role_membership_change(changed, prior);
                return Err(error);
            }
            if propagates && !queued[member] {
                queue[count] = member as u16;
                queued[member] = true;
                count += 1;
            }
        }
    }
    Ok(())
}

fn privilege_mask(
    privileges: &[crate::sql::ast::PrivilegeSpec<'_>],
    class: crate::storage::AccessClass,
    columns: bool,
) -> Result<crate::storage::PrivilegeSet, SqlError> {
    use crate::sql::ast::Privilege;
    use crate::storage::{AccessClass, PrivilegeSet};
    let object_allowed = match class {
        AccessClass::Table | AccessClass::View | AccessClass::MaterializedView => {
            PrivilegeSet::TABLE_ALL
        }
        AccessClass::Sequence => PrivilegeSet::SEQUENCE_ALL,
        AccessClass::Schema => PrivilegeSet::SCHEMA_ALL,
        AccessClass::Domain | AccessClass::Enum | AccessClass::Composite => PrivilegeSet::TYPE_ALL,
        AccessClass::Index => PrivilegeSet::NONE,
        AccessClass::Routine | AccessClass::BuiltinRoutine => PrivilegeSet::FUNCTION_ALL,
        AccessClass::LargeObject => PrivilegeSet::LARGE_OBJECT_ALL,
        AccessClass::ForeignDataWrapper | AccessClass::ForeignServer | AccessClass::Language => {
            PrivilegeSet::USAGE
        }
        AccessClass::Tablespace => PrivilegeSet::CREATE,
        AccessClass::Database => PrivilegeSet::DATABASE_ALL,
        AccessClass::Statistics
        | AccessClass::Extension
        | AccessClass::Trigger
        | AccessClass::EventTrigger => PrivilegeSet::NONE,
    };
    let allowed = if columns {
        if !matches!(
            class,
            AccessClass::Table | AccessClass::View | AccessClass::MaterializedView
        ) {
            return Err(sql_err!(
                sqlstate::INVALID_GRANT_OPERATION,
                "column privileges require a table or view"
            ));
        }
        PrivilegeSet::SELECT
            .union(PrivilegeSet::INSERT)
            .union(PrivilegeSet::UPDATE)
            .union(PrivilegeSet::REFERENCES)
    } else {
        object_allowed
    };
    let mut result = PrivilegeSet::NONE;
    for specification in privileges {
        if specification.columns.is_empty() == columns {
            continue;
        }
        let bit = match specification.privilege {
            Privilege::All => allowed,
            Privilege::Select => PrivilegeSet::SELECT,
            Privilege::Insert => PrivilegeSet::INSERT,
            Privilege::Update => PrivilegeSet::UPDATE,
            Privilege::Delete => PrivilegeSet::DELETE,
            Privilege::Truncate => PrivilegeSet::TRUNCATE,
            Privilege::References => PrivilegeSet::REFERENCES,
            Privilege::Trigger => PrivilegeSet::TRIGGER,
            Privilege::Usage => PrivilegeSet::USAGE,
            Privilege::Create => PrivilegeSet::CREATE,
            Privilege::Execute => PrivilegeSet::EXECUTE,
            Privilege::Maintain => PrivilegeSet::MAINTAIN,
            Privilege::Connect => PrivilegeSet::CONNECT,
            Privilege::Temporary => PrivilegeSet::TEMPORARY,
            Privilege::Set | Privilege::AlterSystem => PrivilegeSet::NONE,
        };
        if !allowed.contains(bit) {
            return Err(sql_err!(
                sqlstate::INVALID_GRANT_OPERATION,
                "invalid privilege type for this object"
            ));
        }
        result = result.union(bit);
    }
    Ok(result)
}

fn privilege_object_noun(class: crate::storage::AccessClass) -> &'static str {
    use crate::storage::AccessClass;
    match class {
        AccessClass::Database => "database",
        AccessClass::Schema => "schema",
        AccessClass::Sequence => "sequence",
        AccessClass::Routine | AccessClass::BuiltinRoutine => "function",
        AccessClass::LargeObject => "large object",
        AccessClass::Domain | AccessClass::Enum | AccessClass::Composite => "type",
        AccessClass::Language => "language",
        AccessClass::Tablespace => "tablespace",
        _ => "relation",
    }
}

fn default_privilege_mask(
    privileges: &[crate::sql::ast::Privilege],
    class: crate::storage::DefaultPrivilegeClass,
) -> Result<crate::storage::PrivilegeSet, SqlError> {
    use crate::sql::ast::Privilege;
    use crate::storage::PrivilegeSet;
    let allowed = class.all_privileges();
    let mut result = PrivilegeSet::NONE;
    for privilege in privileges {
        let bit = match privilege {
            Privilege::All => allowed,
            Privilege::Select => PrivilegeSet::SELECT,
            Privilege::Insert => PrivilegeSet::INSERT,
            Privilege::Update => PrivilegeSet::UPDATE,
            Privilege::Delete => PrivilegeSet::DELETE,
            Privilege::Truncate => PrivilegeSet::TRUNCATE,
            Privilege::References => PrivilegeSet::REFERENCES,
            Privilege::Trigger => PrivilegeSet::TRIGGER,
            Privilege::Usage => PrivilegeSet::USAGE,
            Privilege::Create => PrivilegeSet::CREATE,
            Privilege::Execute => PrivilegeSet::EXECUTE,
            Privilege::Maintain => PrivilegeSet::MAINTAIN,
            Privilege::Connect => PrivilegeSet::CONNECT,
            Privilege::Temporary => PrivilegeSet::TEMPORARY,
            Privilege::Set | Privilege::AlterSystem => PrivilegeSet::NONE,
        };
        if !allowed.contains(bit) {
            return Err(sql_err!(
                sqlstate::INVALID_GRANT_OPERATION,
                "invalid privilege type {} for this object",
                match privilege {
                    Privilege::Select => "SELECT",
                    Privilege::Insert => "INSERT",
                    Privilege::Update => "UPDATE",
                    Privilege::Delete => "DELETE",
                    Privilege::Truncate => "TRUNCATE",
                    Privilege::References => "REFERENCES",
                    Privilege::Trigger => "TRIGGER",
                    Privilege::Usage => "USAGE",
                    Privilege::Create => "CREATE",
                    Privilege::Execute => "EXECUTE",
                    Privilege::Maintain => "MAINTAIN",
                    Privilege::Connect => "CONNECT",
                    Privilege::Temporary => "TEMPORARY",
                    Privilege::Set => "SET",
                    Privilege::AlterSystem => "ALTER SYSTEM",
                    Privilege::All => "ALL",
                }
            ));
        }
        result = result.union(bit);
    }
    Ok(result)
}

pub fn alter_default_privileges(
    storage: &mut Storage,
    txn: &mut TxnState,
    roles: &[&str],
    schemas: &[&str],
    action: crate::sql::ast::DefaultPrivilegeAction<'_>,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    use crate::sql::ast::{DefaultPrivilegeAction, DefaultPrivilegeObjectKind};
    use crate::storage::{DEFAULT_ACL_ALL_SCHEMAS, DefaultPrivilegeClass, PUBLIC_ROLE};

    let (privileges, kind, grantees, grant, grant_option_only, grant_option) = match action {
        DefaultPrivilegeAction::Grant {
            privileges,
            kind,
            grantees,
            grant_option,
        } => (privileges, kind, grantees, true, false, grant_option),
        DefaultPrivilegeAction::Revoke {
            grant_option_only,
            privileges,
            kind,
            grantees,
            cascade: _,
        } => (privileges, kind, grantees, false, grant_option_only, false),
    };
    let class = match kind {
        DefaultPrivilegeObjectKind::Tables => DefaultPrivilegeClass::Table,
        DefaultPrivilegeObjectKind::Sequences => DefaultPrivilegeClass::Sequence,
        DefaultPrivilegeObjectKind::Functions => DefaultPrivilegeClass::Function,
        DefaultPrivilegeObjectKind::Types => DefaultPrivilegeClass::Type,
        DefaultPrivilegeObjectKind::Schemas => DefaultPrivilegeClass::Schema,
    };
    let requested = match default_privilege_mask(privileges, class) {
        Ok(mask) => mask,
        Err(error) => return sql_fail(error),
    };

    let current_name = super::eval::funcs::system::current_user_owned();
    let Some(current) = storage.find_role_visible(current_name.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            current_name.as_str()
        ));
    };
    let current_superuser = storage.role(current).attributes_to(txn.txid).superuser;

    let owner_slots = match arena.alloc_slice_with(roles.len().max(1), |_| 0u16) {
        Ok(slots) => slots,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let owner_count = if roles.is_empty() {
        owner_slots[0] = current as u16;
        1
    } else {
        for (index, written) in roles.iter().enumerate() {
            let resolved = resolve_role_name(written);
            let Some(owner) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
                return sql_fail(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "role \"{}\" does not exist",
                    resolved.as_str()
                ));
            };
            if !current_superuser && !storage.role_has_privileges_of(current, owner, txn.txid) {
                return sql_fail(sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "permission denied to change default privileges"
                ));
            }
            owner_slots[index] = owner as u16;
        }
        roles.len()
    };

    let mut schema_slots = [DEFAULT_ACL_ALL_SCHEMAS; crate::storage::MAX_PUBLICATION_SCHEMAS];
    let schema_count = if schemas.is_empty() {
        1
    } else {
        for (index, name) in schemas.iter().enumerate() {
            let Some(slot) = storage.find_schema_visible(name, txn.txid) else {
                return sql_fail(sql_err!(
                    sqlstate::INVALID_SCHEMA_NAME,
                    "schema \"{}\" does not exist",
                    name
                ));
            };
            schema_slots[index] = slot as u16;
        }
        schemas.len()
    };
    if owner_count
        .saturating_mul(schema_count)
        .saturating_mul(grantees.len())
        > txn.ddl_capacity()
    {
        return sql_fail(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "too many default privilege changes in one statement"
        ));
    }

    for owner in &owner_slots[..owner_count] {
        for schema in &schema_slots[..schema_count] {
            for written in grantees {
                let grantee = if written.eq_ignore_ascii_case("public") {
                    PUBLIC_ROLE
                } else {
                    let resolved = resolve_role_name(written);
                    let Some(slot) = storage.find_role_visible(resolved.as_str(), txn.txid) else {
                        return sql_fail(sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "role \"{}\" does not exist",
                            resolved.as_str()
                        ));
                    };
                    slot as u16
                };
                let (old_privileges, old_options) =
                    storage.default_acl_effective(*owner, *schema, class, grantee, txn.txid);
                let (new_privileges, new_options) = if grant {
                    (
                        old_privileges.union(requested),
                        if grant_option {
                            old_options.union(requested)
                        } else {
                            old_options
                        },
                    )
                } else if grant_option_only {
                    (old_privileges, old_options.without(requested))
                } else {
                    (
                        old_privileges.without(requested),
                        old_options.without(requested),
                    )
                };
                let baseline = Storage::default_acl_baseline(*owner, *schema, class, grantee);
                let defined = (new_privileges, new_options) != baseline;
                let Some((slot, prior)) = (match storage.change_default_acl(
                    crate::storage::DefaultAclKey {
                        owner: *owner,
                        schema: *schema,
                        class,
                        grantee,
                    },
                    defined,
                    new_privileges,
                    new_options,
                    txn.txid,
                ) {
                    Ok(change) => change,
                    Err(error) => return sql_fail(error),
                }) else {
                    continue;
                };
                if let Err(error) = txn.record_ddl(
                    storage,
                    super::txn::DdlUndo::DefaultAclChanged {
                        slot: slot as u32,
                        prior,
                    },
                ) {
                    storage.restore_default_acl_pending(slot, prior);
                    return sql_fail(error);
                }
            }
        }
    }
    responder.command_complete("ALTER DEFAULT PRIVILEGES")?;
    sql_ok()
}

fn apply_default_privileges_to_new_object(
    storage: &mut Storage,
    txn: &mut TxnState,
    object: crate::storage::AccessObject,
) -> Result<(), SqlError> {
    use crate::storage::{
        AccessClass, DEFAULT_ACL_ALL_SCHEMAS, DefaultPrivilegeClass, PUBLIC_ROLE, PrivilegeSet,
    };
    let class = match object.class {
        AccessClass::Table | AccessClass::View | AccessClass::MaterializedView => {
            DefaultPrivilegeClass::Table
        }
        AccessClass::Sequence => DefaultPrivilegeClass::Sequence,
        AccessClass::Schema => DefaultPrivilegeClass::Schema,
        AccessClass::Domain | AccessClass::Enum => DefaultPrivilegeClass::Type,
        AccessClass::Index => return Ok(()),
        AccessClass::Routine => DefaultPrivilegeClass::Function,
        AccessClass::Composite => DefaultPrivilegeClass::Type,
        AccessClass::Tablespace => return Ok(()),
        AccessClass::Database => return Ok(()),
        AccessClass::Statistics => return Ok(()),
        AccessClass::Extension
        | AccessClass::Trigger
        | AccessClass::EventTrigger
        | AccessClass::LargeObject
        | AccessClass::ForeignDataWrapper
        | AccessClass::ForeignServer
        | AccessClass::Language
        | AccessClass::BuiltinRoutine => return Ok(()),
    };
    let owner = storage.object_owner(object, txn.txid) as u16;
    let schema = if object.class == AccessClass::Schema {
        DEFAULT_ACL_ALL_SCHEMAS
    } else {
        let (schema, _) = storage.access_object_name_to(object, txn.txid);
        storage
            .find_schema_visible(schema.as_str(), txn.txid)
            .map_or(DEFAULT_ACL_ALL_SCHEMAS, |slot| slot as u16)
    };
    let customized = storage.default_acl_entries().any(|(_, entry)| {
        entry.owner == owner
            && entry.class == class
            && (entry.schema == DEFAULT_ACL_ALL_SCHEMAS || entry.schema == schema)
            && storage
                .default_acl_state(
                    entry.owner,
                    entry.schema,
                    entry.class,
                    entry.grantee,
                    txn.txid,
                )
                .0
    });

    // PostgreSQL places a customized PUBLIC default before the owner entry,
    // followed by named grantees. Preserve that construction order because
    // aclitem arrays expose it, unlike grants made after object creation.
    for role_index in 0..storage.role_count() + 2 {
        let grantee = match role_index {
            0 => PUBLIC_ROLE,
            1 => owner,
            index => {
                let index = index - 2;
                if index == owner as usize || !storage.role(index).visible_to(txn.txid) {
                    continue;
                }
                index as u16
            }
        };
        let (global_defined, _, _) =
            storage.default_acl_state(owner, DEFAULT_ACL_ALL_SCHEMAS, class, grantee, txn.txid);
        let (global_privileges, global_options) =
            storage.default_acl_effective(owner, DEFAULT_ACL_ALL_SCHEMAS, class, grantee, txn.txid);
        let (schema_defined, schema_privileges, schema_options) =
            if schema == DEFAULT_ACL_ALL_SCHEMAS {
                (false, PrivilegeSet::NONE, PrivilegeSet::NONE)
            } else {
                storage.default_acl_state(owner, schema, class, grantee, txn.txid)
            };
        let privileges = global_privileges.union(schema_privileges);
        let grant_options = global_options.union(schema_options);
        let built_in_without_row = grantee == owner
            || (grantee == PUBLIC_ROLE
                && class.default_public_privileges().0 != PrivilegeSet::NONE.0);
        if !global_defined
            && !schema_defined
            && (privileges.0 == 0 || (built_in_without_row && !customized))
        {
            continue;
        }
        let (slot, prior) = storage.change_acl(
            object,
            grantee,
            owner,
            privileges,
            grant_options,
            crate::storage::ObjectAclWrite::Change {
                transaction: txn.txid,
            },
        )?;
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ObjectAclChanged {
                slot: slot as u32,
                prior,
            },
        ) {
            storage
                .restore_acl_pending(slot, prior)
                .expect("transaction owns its object ACL undo");
            return Err(error);
        }
    }
    Ok(())
}

fn resolve_owned_roles(
    storage: &Storage,
    txid: u32,
    names: &[&str],
    output: &mut [u16],
) -> Result<usize, SqlError> {
    let current_name = super::eval::funcs::system::current_user_owned();
    let current = storage
        .find_role_visible(current_name.as_str(), txid)
        .ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                current_name.as_str()
            )
        })?;
    let superuser = storage.role(current).attributes_to(txid).superuser;
    let mut count = 0usize;
    for written in names {
        let resolved = resolve_role_name(written);
        let role = storage
            .find_role_visible(resolved.as_str(), txid)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "role \"{}\" does not exist",
                    resolved.as_str()
                )
            })?;
        if !superuser && !storage.role_has_privileges_of(current, role, txid) {
            return Err(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to drop objects"
            ));
        }
        if storage.role(role).oid() == crate::storage::RoleOid::BOOTSTRAP {
            return Err(sql_err!(
                sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                "cannot change objects owned by a role required by the database system"
            ));
        }
        storage.role_reference_ready(role, txid)?;
        let role = role as u16;
        if !output[..count].contains(&role) {
            output[count] = role;
            count += 1;
        }
    }
    Ok(count)
}

pub fn reassign_owned(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    roles: &[&str],
    new_owner: &str,
    arena: &Arena,
    responder: &mut Responder,
) -> Outcome {
    use crate::storage::{AccessClass, AccessObject};
    let source_roles = match arena.alloc_slice_with(roles.len(), |_| 0u16) {
        Ok(slots) => slots,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let source_count = match resolve_owned_roles(storage, txn.txid, roles, source_roles) {
        Ok(count) => count,
        Err(error) => return sql_fail(error),
    };
    let resolved_owner = resolve_role_name(new_owner);
    let Some(target) = storage.find_role_visible(resolved_owner.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            resolved_owner.as_str()
        ));
    };
    if let Err(error) = storage.role_reference_ready(target, txn.txid) {
        return sql_fail(error);
    }
    let current_name = super::eval::funcs::system::current_user_owned();
    let current = storage
        .find_role_visible(current_name.as_str(), txn.txid)
        .expect("current role was resolved with the source roles");
    if !storage.role(current).attributes_to(txn.txid).superuser
        && !storage.role_has_privileges_of(current, target, txn.txid)
    {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied to reassign objects"
        ));
    }

    // A rewritten object must leave the source set. Besides avoiding needless
    // catalog versions, this makes each catalog's find-and-rewrite loop finish.
    let source_count = {
        let mut count = 0;
        for index in 0..source_count {
            let role = source_roles[index];
            if usize::from(role) != target {
                source_roles[count] = role;
                count += 1;
            }
        }
        count
    };
    let classes = [
        AccessClass::Table,
        AccessClass::View,
        AccessClass::MaterializedView,
        AccessClass::Sequence,
        AccessClass::Schema,
        AccessClass::Domain,
        AccessClass::Enum,
        AccessClass::Composite,
        AccessClass::Index,
        AccessClass::Routine,
        AccessClass::BuiltinRoutine,
        AccessClass::Statistics,
        AccessClass::Tablespace,
        AccessClass::Extension,
        AccessClass::EventTrigger,
        AccessClass::ForeignDataWrapper,
        AccessClass::ForeignServer,
    ];
    let mut changes = 0usize;
    for class in classes {
        for slot in 0..storage.access_class_slots(class) {
            let object = AccessObject {
                class,
                slot: slot as u16,
            };
            if storage.access_object_visible_to(object, txn.txid)
                && source_roles[..source_count]
                    .contains(&(storage.object_owner(object, txn.txid) as u16))
            {
                changes += 1;
            }
        }
    }
    let source_oids = match arena.alloc_slice_with(source_count, |index| {
        storage.role_oid(usize::from(source_roles[index]))
    }) {
        Ok(oids) => oids,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let source_owns_catalog = |owner: i32| source_oids.contains(&owner);
    changes += storage
        .operators_visible_to(txn.txid)
        .filter(|(_, definition)| source_owns_catalog(definition.owner))
        .count();
    changes += storage
        .operator_families_visible_to(txn.txid)
        .filter(|(_, definition)| source_owns_catalog(definition.owner))
        .count();
    changes += storage
        .operator_classes_visible_to(txn.txid)
        .filter(|(_, definition)| source_owns_catalog(definition.owner))
        .count();
    changes += storage
        .collations_visible_to(txn.txid)
        .filter(|(_, definition)| source_owns_catalog(definition.owner))
        .count();
    changes += storage
        .conversions_visible_to(txn.txid)
        .filter(|(_, definition)| source_owns_catalog(definition.owner))
        .count();
    changes += storage
        .text_search_objects_visible_to(txn.txid)
        .filter(|(_, definition)| definition.owner().is_some_and(source_owns_catalog))
        .count();
    if changes > txn.ddl_capacity().saturating_sub(txn.ddl().len()) {
        return sql_fail(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "too many objects to reassign in one transaction"
        ));
    }
    for class in classes {
        for slot in 0..storage.access_class_slots(class) {
            let object = AccessObject {
                class,
                slot: slot as u16,
            };
            if !storage.access_object_visible_to(object, txn.txid)
                || !source_roles[..source_count]
                    .contains(&(storage.object_owner(object, txn.txid) as u16))
            {
                continue;
            }
            let old_owner = storage.object_owner(object, txn.txid) as u16;
            let prior = if class == AccessClass::Tablespace {
                match storage.set_tablespace_owner(slot, target, txn.txid) {
                    Ok(prior) => prior,
                    Err(error) => return sql_fail(error),
                }
            } else if class == AccessClass::Schema {
                match storage.set_schema_owner(slot, target, txn.txid) {
                    Ok(prior) => prior,
                    Err(error) => return sql_fail(error),
                }
            } else if class == AccessClass::Extension {
                match storage.set_extension_owner(slot, target, txn.txid) {
                    Ok(prior) => prior,
                    Err(error) => return sql_fail(error),
                }
            } else if matches!(
                class,
                AccessClass::ForeignDataWrapper | AccessClass::ForeignServer
            ) {
                let foreign_class = if class == AccessClass::ForeignDataWrapper {
                    crate::storage::foreign::ForeignObjectClass::Wrapper
                } else {
                    crate::storage::foreign::ForeignObjectClass::Server
                };
                match storage.stage_foreign_catalog_owner(
                    foreign_class,
                    slot,
                    target as u16,
                    txn.txid,
                ) {
                    Ok(prior) => prior,
                    Err(error) => return sql_fail(error),
                }
            } else {
                storage.set_object_owner(object, target, txn.txid)
            };
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::ObjectOwnerChanged { object, prior },
            ) {
                storage.restore_object_owner(object, prior);
                return sql_fail(error);
            }
            if let Err(error) =
                rewrite_object_acl_owner(storage, txn, object, old_owner, target as u16)
            {
                return sql_fail(error);
            }
        }
    }
    let target_oid = storage.role_oid(target);
    loop {
        let found = storage
            .operators_visible_to(txn.txid)
            .find_map(|(slot, definition)| source_owns_catalog(definition.owner).then_some(slot));
        let Some(slot) = found else { break };
        let mut definition = storage.operator_for(slot, txn.txid);
        definition.owner = target_oid;
        if let Err(error) = stage_operator(storage, wal, txn, slot, definition) {
            return sql_fail(error);
        }
    }
    loop {
        let found = storage
            .operator_families_visible_to(txn.txid)
            .find_map(|(slot, definition)| source_owns_catalog(definition.owner).then_some(slot));
        let Some(slot) = found else { break };
        let mut definition = storage.operator_family_for(slot, txn.txid);
        definition.owner = target_oid;
        if let Err(error) = stage_operator_family(storage, wal, txn, slot, definition) {
            return sql_fail(error);
        }
    }
    loop {
        let found = storage
            .operator_classes_visible_to(txn.txid)
            .find_map(|(slot, definition)| source_owns_catalog(definition.owner).then_some(slot));
        let Some(slot) = found else { break };
        let mut definition = storage.operator_class_for(slot, txn.txid);
        definition.owner = target_oid;
        if let Err(error) = stage_operator_class(storage, wal, txn, slot, definition) {
            return sql_fail(error);
        }
    }
    loop {
        let found = storage
            .collations_visible_to(txn.txid)
            .find_map(|(slot, definition)| source_owns_catalog(definition.owner).then_some(slot));
        let Some(slot) = found else { break };
        let mut definition = storage.collation(slot).definition_for(txn.txid);
        definition.owner = target_oid;
        let prior = match storage.alter_collation(slot, definition, txn.txid) {
            Ok(prior) => prior,
            Err(error) => return sql_fail(error),
        };
        let lsn = storage.bump_lsn();
        if let Err(error) = wal.stage_reserved(
            txn.txid,
            lsn,
            &WalOp::SetCollation {
                slot: slot as u8,
                created_at: storage.collation(slot).created_at,
                definition,
            },
        ) {
            storage.rollback_collation_alter(slot, prior);
            return sql_fail(error);
        }
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::CollationAltered {
                slot: slot as u32,
                prior,
            },
        ) {
            storage.rollback_collation_alter(slot, prior);
            return sql_fail(error);
        }
    }
    loop {
        let found = storage
            .conversions_visible_to(txn.txid)
            .find_map(|(slot, definition)| source_owns_catalog(definition.owner).then_some(slot));
        let Some(slot) = found else { break };
        let mut definition = storage.conversion(slot).definition_for(txn.txid);
        definition.owner = target_oid;
        let prior = match storage.alter_conversion(slot, definition, txn.txid) {
            Ok(prior) => prior,
            Err(error) => return sql_fail(error),
        };
        let lsn = storage.bump_lsn();
        if let Err(error) = wal.stage_reserved(
            txn.txid,
            lsn,
            &WalOp::SetConversion {
                slot: slot as u8,
                created_at: storage.conversion(slot).created_at,
                definition,
            },
        ) {
            storage.rollback_conversion_alter(slot, prior);
            return sql_fail(error);
        }
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ConversionAltered {
                slot: slot as u32,
                prior,
            },
        ) {
            storage.rollback_conversion_alter(slot, prior);
            return sql_fail(error);
        }
    }
    loop {
        let found =
            storage
                .text_search_objects_visible_to(txn.txid)
                .find_map(|(slot, definition)| {
                    definition
                        .owner()
                        .is_some_and(source_owns_catalog)
                        .then_some(slot)
                });
        let Some(slot) = found else { break };
        let mut definition = storage.text_search_object(slot).definition_for(txn.txid);
        if !definition.set_owner(target_oid) {
            return sql_fail(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "owned text-search object has no owner"
            ));
        }
        if let Err(error) = stage_text_search_alter(storage, wal, txn, slot, definition) {
            return sql_fail(error);
        }
    }
    responder.command_complete("REASSIGN OWNED")?;
    sql_ok()
}

fn run_as_role<T>(role: crate::storage::SessionIdentity, operation: impl FnOnce() -> T) -> T {
    let _role = super::eval::funcs::system::enter_current_user(role);
    operation()
}

fn record_acl_removal(
    storage: &mut Storage,
    txn: &mut TxnState,
    slot: usize,
) -> Result<crate::storage::PrivilegeSet, SqlError> {
    let entry = storage.acl_entry(slot);
    let (grantee, grantor) = storage.acl_identity(slot, txn.txid);
    let (_, grant_options) = storage.acl_state(slot, txn.txid);
    let (changed, prior) = storage.change_acl(
        entry.object,
        grantee,
        grantor,
        crate::storage::PrivilegeSet::NONE,
        crate::storage::PrivilegeSet::NONE,
        crate::storage::ObjectAclWrite::Change {
            transaction: txn.txid,
        },
    )?;
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::ObjectAclChanged {
            slot: changed as u32,
            prior,
        },
    ) {
        storage
            .restore_acl_pending(changed, prior)
            .expect("transaction owns its object ACL undo");
        return Err(error);
    }
    Ok(grant_options)
}

fn drop_owned_privileges(
    storage: &mut Storage,
    txn: &mut TxnState,
    roles: &[u16],
    arena: &Arena,
) -> Result<(), SqlError> {
    use crate::storage::{PUBLIC_ROLE, PrivilegeSet};
    let graph_capacity = storage.acl_entry_count().max(1);
    let queue_objects = arena
        .alloc_slice_with(graph_capacity, |_| crate::storage::AccessObject {
            class: crate::storage::AccessClass::Table,
            slot: 0,
        })
        .map_err(|_| super::query::arena_full_pub())?;
    let queue_roles = arena
        .alloc_slice_with(graph_capacity, |_| 0u16)
        .map_err(|_| super::query::arena_full_pub())?;
    let queue_privileges = arena
        .alloc_slice_with(graph_capacity, |_| PrivilegeSet::NONE)
        .map_err(|_| super::query::arena_full_pub())?;
    let dependent = arena
        .alloc_slice_with(graph_capacity, |_| 0usize)
        .map_err(|_| super::query::arena_full_pub())?;
    let column_capacity = storage.column_acl_entry_count().max(1);
    let column_dependent = arena
        .alloc_slice_with(column_capacity, |_| 0usize)
        .map_err(|_| super::query::arena_full_pub())?;
    let column_queue_roles = arena
        .alloc_slice_with(column_capacity, |_| 0u16)
        .map_err(|_| super::query::arena_full_pub())?;
    let column_queue_privileges = arena
        .alloc_slice_with(column_capacity, |_| PrivilegeSet::NONE)
        .map_err(|_| super::query::arena_full_pub())?;
    let mut column_scratch = ColumnAclCascadeScratch {
        dependent: column_dependent,
        roles: column_queue_roles,
        privileges: column_queue_privileges,
    };
    let mut queue_count = 0usize;

    for slot in 0..storage.acl_entry_count() {
        let entry = storage.acl_entry(slot);
        let (grantee, grantor) = storage.acl_identity(slot, txn.txid);
        let (privileges, _) = storage.acl_state(slot, txn.txid);
        if privileges.0 == 0
            || !storage.access_object_visible_to(entry.object, txn.txid)
            || (!roles.contains(&grantee) && !roles.contains(&grantor))
        {
            continue;
        }
        let lost_options = record_acl_removal(storage, txn, slot)?;
        if grantee != PUBLIC_ROLE && lost_options.0 != 0 {
            if queue_count == queue_objects.len() {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "privilege dependency graph exceeds {} entries",
                    queue_objects.len()
                ));
            }
            queue_objects[queue_count] = entry.object;
            queue_roles[queue_count] = grantee;
            queue_privileges[queue_count] = lost_options;
            queue_count += 1;
        }
    }
    let mut at = 0usize;
    while at < queue_count {
        let object = queue_objects[at];
        let grantor = queue_roles[at];
        let lost = queue_privileges[at];
        at += 1;
        let dependent_count =
            storage.dependent_acl_slots(object, grantor, lost, txn.txid, &mut *dependent);
        for slot in dependent[..dependent_count].iter().copied() {
            let entry = storage.acl_entry(slot);
            let (grantee, _) = storage.acl_identity(slot, txn.txid);
            let (privileges, _) = storage.acl_state(slot, txn.txid);
            if privileges.0 == 0 {
                continue;
            }
            let recursively_lost = record_acl_removal(storage, txn, slot)?;
            if grantee != PUBLIC_ROLE && recursively_lost.0 != 0 {
                if queue_count == queue_objects.len() {
                    return Err(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "privilege dependency graph exceeds {} entries",
                        queue_objects.len()
                    ));
                }
                queue_objects[queue_count] = entry.object;
                queue_roles[queue_count] = grantee;
                queue_privileges[queue_count] = recursively_lost;
                queue_count += 1;
            }
        }
    }

    let column_acl_count = storage.column_acl_entry_count();
    for slot in 0..column_acl_count {
        let entry = storage.column_acl_entry(slot);
        let (grantee, grantor) = storage.column_acl_identity(slot, txn.txid);
        let (privileges, grant_options) = storage.column_acl_state(slot, txn.txid);
        if privileges.0 == 0
            || !storage.access_object_visible_to(entry.target.relation(), txn.txid)
            || (!roles.contains(&grantee) && !roles.contains(&grantor))
        {
            continue;
        }
        revoke_dependent_column_privileges(
            storage,
            txn,
            entry.target,
            grantee,
            grant_options,
            true,
            &mut column_scratch,
        )?;
        let (changed, prior) = storage.change_column_acl(
            entry.target,
            grantee,
            grantor,
            PrivilegeSet::NONE,
            PrivilegeSet::NONE,
            txn.txid,
        )?;
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ColumnAclChanged {
                slot: changed as u32,
                prior,
            },
        ) {
            storage.restore_column_acl_pending(changed, prior);
            return Err(error);
        }
    }

    let default_count = storage.default_acl_entry_count();
    for slot in 0..default_count {
        let entry = storage.default_acl_entry(slot);
        if entry.database != storage.current_database_oid() {
            continue;
        }
        let (defined, _, _) = storage.default_acl_state(
            entry.owner,
            entry.schema,
            entry.class,
            entry.grantee,
            txn.txid,
        );
        if !defined || (!roles.contains(&entry.owner) && !roles.contains(&entry.grantee)) {
            continue;
        }
        let Some((changed, prior)) = storage.change_default_acl(
            crate::storage::DefaultAclKey {
                owner: entry.owner,
                schema: entry.schema,
                class: entry.class,
                grantee: entry.grantee,
            },
            false,
            PrivilegeSet::NONE,
            PrivilegeSet::NONE,
            txn.txid,
        )?
        else {
            continue;
        };
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::DefaultAclChanged {
                slot: changed as u32,
                prior,
            },
        ) {
            storage.restore_default_acl_pending(changed, prior);
            return Err(error);
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn drop_owned(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    scratch: &mut DmlScratch,
    roles: &[&str],
    cascade: bool,
    arena: &Arena,
    seq_session: &crate::sql::guc::SeqSession,
    responder: &mut Responder,
) -> Outcome {
    use crate::storage::{AccessClass, AccessObject, DependencyClass};
    let owned_roles = match arena.alloc_slice_with(roles.len(), |_| 0u16) {
        Ok(slots) => slots,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let owned_role_count = match resolve_owned_roles(storage, txn.txid, roles, owned_roles) {
        Ok(count) => count,
        Err(error) => return sql_fail(error),
    };
    let owned_roles = &owned_roles[..owned_role_count];
    // A built-in routine given to the role cannot be dropped with it.
    for slot in 0..storage.access_class_slots(AccessClass::BuiltinRoutine) {
        let object = AccessObject {
            class: AccessClass::BuiltinRoutine,
            slot: slot as u16,
        };
        if storage.access_object_visible_to(object, txn.txid)
            && owned_roles.contains(&(storage.object_owner(object, txn.txid) as u16))
            && let Some(routine) = storage.builtin_routine_entry(slot).routine
        {
            return sql_fail(routine_lookup::builtin_drop_error(routine.signature()));
        }
    }
    if let Err(error) = drop_owned_privileges(storage, txn, owned_roles, arena) {
        return sql_fail(error);
    }

    let tables = match dependency_flags(arena, storage.table_count()) {
        Ok(values) => values,
        Err(error) => return sql_fail(error),
    };
    let views = match dependency_flags(arena, storage.view_count()) {
        Ok(values) => values,
        Err(error) => return sql_fail(error),
    };
    let matviews = match dependency_flags(arena, storage.matview_count()) {
        Ok(values) => values,
        Err(error) => return sql_fail(error),
    };
    let sequences = match arena.alloc_slice_with(storage.sequence_count(), |_| false) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let domains = match arena.alloc_slice_with(storage.domain_count(), |_| false) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let enums = match arena.alloc_slice_with(storage.enum_count(), |_| false) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let composites = match arena.alloc_slice_with(storage.composite_count(), |_| false) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let routines = match dependency_flags(arena, storage.routine_count()) {
        Ok(values) => values,
        Err(error) => return sql_fail(error),
    };
    let operators = match dependency_flags(arena, storage.operator_count()) {
        Ok(values) => values,
        Err(error) => return sql_fail(error),
    };
    let collations = match arena.alloc_slice_with(storage.collation_capacity(), |_| false) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let conversions = match arena.alloc_slice_with(storage.conversion_capacity(), |_| false) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let text_search_objects =
        match arena.alloc_slice_with(storage.text_search_object_capacity(), |_| false) {
            Ok(values) => values,
            Err(_) => return sql_fail(super::query::arena_full_pub()),
        };
    let statistics = match arena.alloc_slice_with(storage.extended_statistics_count(), |_| false) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let event_triggers = match arena.alloc_slice_with(storage.event_trigger_capacity(), |_| false) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let schemas = match dependency_flags(arena, storage.schema_count()) {
        Ok(values) => values,
        Err(error) => return sql_fail(error),
    };
    let foreign_servers = match dependency_flags(
        arena,
        storage.access_class_slots(AccessClass::ForeignServer),
    ) {
        Ok(values) => values,
        Err(error) => return sql_fail(error),
    };
    let foreign_wrappers = match dependency_flags(
        arena,
        storage.access_class_slots(AccessClass::ForeignDataWrapper),
    ) {
        Ok(values) => values,
        Err(error) => return sql_fail(error),
    };
    for (class, selected) in [
        (AccessClass::Table, &mut tables[..]),
        (AccessClass::View, &mut views[..]),
        (AccessClass::MaterializedView, &mut matviews[..]),
        (AccessClass::Sequence, &mut sequences[..]),
        (AccessClass::Domain, &mut domains[..]),
        (AccessClass::Enum, &mut enums[..]),
        (AccessClass::Composite, &mut composites[..]),
        (AccessClass::Routine, &mut routines[..]),
        (AccessClass::Statistics, &mut statistics[..]),
        (AccessClass::EventTrigger, &mut event_triggers[..]),
        (AccessClass::Schema, &mut schemas[..]),
        (AccessClass::ForeignServer, &mut foreign_servers[..]),
        (AccessClass::ForeignDataWrapper, &mut foreign_wrappers[..]),
    ] {
        for (slot, selected) in selected
            .iter_mut()
            .enumerate()
            .take(storage.access_class_slots(class))
        {
            let object = AccessObject {
                class,
                slot: slot as u16,
            };
            *selected = storage.access_object_visible_to(object, txn.txid)
                && owned_roles.contains(&(storage.object_owner(object, txn.txid) as u16));
        }
    }
    for (slot, definition) in storage.operators_visible_to(txn.txid) {
        if let Some(selected) = operators.get_mut(slot) {
            *selected = owned_roles
                .iter()
                .any(|role| storage.role_oid(usize::from(*role)) == definition.owner);
        }
    }
    for (slot, definition) in storage.collations_visible_to(txn.txid) {
        collations[slot] = owned_roles
            .iter()
            .any(|role| storage.role_oid(usize::from(*role)) == definition.owner);
    }
    for (slot, definition) in storage.conversions_visible_to(txn.txid) {
        conversions[slot] = owned_roles
            .iter()
            .any(|role| storage.role_oid(usize::from(*role)) == definition.owner);
    }
    for (slot, definition) in storage.text_search_objects_visible_to(txn.txid) {
        text_search_objects[slot] = definition.owner().is_some_and(|owner| {
            owned_roles
                .iter()
                .any(|role| storage.role_oid(usize::from(*role)) == owner)
        });
    }

    let root = |dependency: &crate::storage::StoredQueryDependency| match dependency.class {
        DependencyClass::Table => tables
            .get(dependency.slot as usize)
            .copied()
            .unwrap_or(false),
        DependencyClass::View => views
            .get(dependency.slot as usize)
            .copied()
            .unwrap_or(false),
        DependencyClass::Domain => domains
            .get(dependency.slot as usize)
            .copied()
            .unwrap_or(false),
        DependencyClass::Enum => enums
            .get(dependency.slot as usize)
            .copied()
            .unwrap_or(false),
        DependencyClass::Composite => composites
            .get(dependency.slot as usize)
            .copied()
            .unwrap_or(false),
        DependencyClass::Sequence => sequences
            .get(dependency.slot as usize)
            .copied()
            .unwrap_or(false),
        DependencyClass::Routine => routines
            .get(dependency.slot as usize)
            .copied()
            .unwrap_or(false),
        DependencyClass::Operator => operators
            .get(dependency.slot as usize)
            .copied()
            .unwrap_or(false),
        DependencyClass::Collation => collations
            .get(dependency.slot as usize)
            .copied()
            .unwrap_or(false),
        DependencyClass::TextSearchConfiguration => text_search_objects
            .get(dependency.slot as usize)
            .copied()
            .unwrap_or(false),
    };
    let StoredDependencyClosure {
        views: dependent_views,
        matviews: dependent_matviews,
        routines: dependent_routines,
        rules: dependent_rules,
    } = match stored_query_dependent_closure(storage, txn.txid, arena, root) {
        Ok(selection) => selection,
        Err(error) => return sql_fail(error),
    };
    let has_policy_dependents =
        storage
            .policies_with_slots_visible_to(txn.txid)
            .any(|(slot, policy)| {
                policy_depends_on_owned_selection(
                    storage,
                    txn.txid,
                    slot,
                    &policy,
                    tables,
                    views,
                    sequences,
                    domains,
                    enums,
                    composites,
                    routines,
                    operators,
                    text_search_objects,
                    dependent_views,
                    dependent_matviews,
                    dependent_routines,
                )
            });
    if !cascade
        && (dependent_views
            .iter()
            .zip(views.iter())
            .any(|(dependent, owned)| *dependent && !*owned)
            || dependent_matviews
                .iter()
                .zip(matviews.iter())
                .any(|(dependent, owned)| *dependent && !*owned)
            || dependent_routines
                .iter()
                .zip(routines.iter())
                .any(|(dependent, owned)| *dependent && !*owned)
            || has_policy_dependents)
    {
        return sql_fail(sql_err!(
            sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
            "cannot drop owned objects because other objects depend on them"
        ));
    }
    if cascade {
        for slot in 0..storage.policy_count() {
            let selected = {
                let policy = storage.policy(slot);
                policy.visible_to(txn.txid)
                    && policy_depends_on_owned_selection(
                        storage,
                        txn.txid,
                        slot,
                        &policy,
                        tables,
                        views,
                        sequences,
                        domains,
                        enums,
                        composites,
                        routines,
                        operators,
                        text_search_objects,
                        dependent_views,
                        dependent_matviews,
                        dependent_routines,
                    )
            };
            if selected && let Err(error) = drop_policy_slot(storage, wal, txn, slot) {
                return sql_fail(error);
            }
        }
    }
    if cascade {
        for (selected, dependent) in views.iter_mut().zip(dependent_views.iter()) {
            *selected |= *dependent;
        }
        for (selected, dependent) in matviews.iter_mut().zip(dependent_matviews.iter()) {
            *selected |= *dependent;
        }
        for (selected, dependent) in routines.iter_mut().zip(dependent_routines.iter()) {
            *selected |= *dependent;
        }
    }
    if let Err(error) = drop_selected_stored_queries_with_columns(
        storage,
        wal,
        txn,
        StoredQuerySelectionDrop {
            views,
            matviews,
            routines,
            rules: dependent_rules,
        },
        ViewRowTypeColumnCascade {
            columns: RowTypeColumnCascade {
                scratch: &mut *scratch,
                seq_session,
            },
            arena,
            responder,
        },
    ) {
        return sql_fail(error);
    }

    for (slot, selected) in event_triggers.iter().copied().enumerate().rev() {
        if !selected
            || storage.event_trigger_slot(
                storage
                    .event_trigger(slot)
                    .definition_for(txn.txid)
                    .name
                    .as_str(),
                txn.txid,
            ) != Some(slot)
        {
            continue;
        }
        let definition = storage.event_trigger(slot).definition_for(txn.txid);
        let owner = storage.role_name(
            usize::from(definition.ownership.owner_to(txn.txid)),
            txn.txid,
        );
        let owner = match storage.capture_role(owner.as_str(), txn.txid) {
            Ok(role) => crate::storage::SessionIdentity::bound(role),
            Err(error) => return sql_fail(error),
        };
        let outcome = run_as_role(owner, || {
            responder.without_command_complete(|responder| {
                drop_event_trigger(
                    storage,
                    wal,
                    txn,
                    definition.name.as_str(),
                    false,
                    cascade,
                    responder,
                )
            })
        });
        match outcome {
            Ok(Ok(())) => {}
            Ok(Err(error)) => return sql_fail(error),
            Err(error) => return Err(error),
        }
    }

    let owned_oids = match arena.alloc_slice_with(owned_roles.len(), |index| {
        storage.role_oid(usize::from(owned_roles[index]))
    }) {
        Ok(oids) => oids,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let owned_catalog = |owner: i32| owned_oids.contains(&owner);
    loop {
        let owned = storage
            .operator_classes_visible_to(txn.txid)
            .find_map(|(slot, definition)| owned_catalog(definition.owner).then_some(slot));
        let Some(slot) = owned else { break };
        if let Err(error) = stage_operator_class_drop(storage, wal, txn, slot, cascade) {
            return sql_fail(error);
        }
    }
    loop {
        let owned = storage
            .operator_families_visible_to(txn.txid)
            .find_map(|(slot, definition)| owned_catalog(definition.owner).then_some(slot));
        let Some(slot) = owned else { break };
        let family_oid = storage.operator_family(slot).oid();
        let has_dependents = storage
            .operator_classes_visible_to(txn.txid)
            .any(|(_, class)| class.family == family_oid);
        if has_dependents && !cascade {
            return sql_fail(sql_err!(
                sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                "cannot drop owned operator family because operator classes depend on it"
            ));
        }
        loop {
            let dependent = storage
                .operator_classes_visible_to(txn.txid)
                .find_map(|(slot, class)| (class.family == family_oid).then_some(slot));
            let Some(class) = dependent else { break };
            if let Err(error) = stage_operator_class_drop(storage, wal, txn, class, true) {
                return sql_fail(error);
            }
        }
        if let Err(error) = stage_operator_family_drop(storage, wal, txn, slot) {
            return sql_fail(error);
        }
    }
    loop {
        let owned = storage
            .operators_visible_to(txn.txid)
            .find_map(|(slot, definition)| owned_catalog(definition.owner).then_some(slot));
        let Some(slot) = owned else { break };
        let operator_oid = storage.operator(slot).oid();
        if operator_has_dependents(storage, txn.txid, operator_oid) && !cascade {
            return sql_fail(sql_err!(
                sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                "cannot drop owned operator because other objects depend on it"
            ));
        }
        if let Err(error) = cascade_operator_dependencies(
            storage,
            wal,
            txn,
            &mut *scratch,
            seq_session,
            &mut *responder,
            operator_oid,
            arena,
        ) {
            return sql_fail(error);
        }
        if let Err(error) = stage_operator_drop(storage, wal, txn, slot) {
            return sql_fail(error);
        }
    }

    for (slot, selected) in statistics
        .iter()
        .copied()
        .enumerate()
        .take(storage.extended_statistics_count())
        .rev()
    {
        let object = AccessObject {
            class: AccessClass::Statistics,
            slot: slot as u16,
        };
        if !selected || !storage.access_object_visible_to(object, txn.txid) {
            continue;
        }
        let (schema, name) = storage.access_object_name_to(object, txn.txid);
        let owner = storage.role_name(storage.object_owner(object, txn.txid), txn.txid);
        let qualified = QualName {
            schema: Some(schema.as_str()),
            name: name.as_str(),
        };
        let owner = match storage.capture_role(owner.as_str(), txn.txid) {
            Ok(role) => crate::storage::SessionIdentity::bound(role),
            Err(error) => return sql_fail(error),
        };
        let outcome = run_as_role(owner, || {
            responder.without_command_complete(|responder| {
                drop_statistics(
                    storage,
                    wal,
                    txn,
                    core::slice::from_ref(&qualified),
                    false,
                    cascade,
                    responder,
                )
            })
        });
        match outcome {
            Ok(Ok(())) => {}
            Ok(Err(error)) => return sql_fail(error),
            Err(error) => return Err(error),
        }
    }

    // A CASCADE of an owned schema removes every contained object, including
    // objects owned by another role. RESTRICT postpones schemas until their
    // owned contents have been removed and lets the ordinary dependency
    // preflight reject any survivors.
    if cascade {
        for (slot, selected) in schemas
            .iter()
            .copied()
            .enumerate()
            .take(storage.access_class_slots(AccessClass::Schema))
        {
            if !selected
                || !storage.access_object_visible_to(
                    AccessObject {
                        class: AccessClass::Schema,
                        slot: slot as u16,
                    },
                    txn.txid,
                )
            {
                continue;
            }
            let schema = storage.schema_def_for(slot, txn.txid).name;
            let owner = storage.role_name(
                storage.object_owner(
                    AccessObject {
                        class: AccessClass::Schema,
                        slot: slot as u16,
                    },
                    txn.txid,
                ),
                txn.txid,
            );
            let owner = match storage.capture_role(owner.as_str(), txn.txid) {
                Ok(role) => crate::storage::SessionIdentity::bound(role),
                Err(error) => return sql_fail(error),
            };
            let outcome = run_as_role(owner, || {
                responder.without_command_complete(|responder| {
                    drop_schema(
                        storage,
                        wal,
                        txn,
                        scratch,
                        SchemaDropTarget::Named {
                            names: &[schema.as_str()],
                            if_exists: false,
                            cascade: true,
                        },
                        arena,
                        seq_session,
                        responder,
                    )
                })
            });
            match outcome {
                Ok(Ok(())) => {}
                Ok(Err(error)) => return sql_fail(error),
                Err(error) => return Err(error),
            }
        }
    }

    let table_schemas = match arena.alloc_slice_with(storage.table_count(), |_| SqlName::EMPTY) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let table_names = match arena.alloc_slice_with(storage.table_count(), |_| SqlName::EMPTY) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let mut table_name_count = 0usize;
    for (slot, selected) in tables
        .iter()
        .copied()
        .enumerate()
        .take(storage.table_count())
    {
        if !selected || !storage.table(slot).visible_to(txn.txid) {
            continue;
        }
        let definition = (*storage.table_def(slot, txn.txid)).clone();
        if definition
            .partition
            .attachment
            .is_some_and(|attachment| tables[usize::from(attachment.parent)])
        {
            continue;
        }
        if storage
            .matview_slot(
                definition.schema.as_str(),
                definition.name.as_str(),
                txn.txid,
            )
            .is_none()
        {
            table_schemas[table_name_count] = definition.schema;
            table_names[table_name_count] = definition.name;
            table_name_count += 1;
        }
    }
    if table_name_count != 0 {
        let qualified = match arena.alloc_slice_with(storage.table_count(), |_| QualName::bare(""))
        {
            Ok(values) => values,
            Err(_) => return sql_fail(super::query::arena_full_pub()),
        };
        for index in 0..table_name_count {
            qualified[index] = QualName {
                schema: Some(table_schemas[index].as_str()),
                name: table_names[index].as_str(),
            };
        }
        let statement = DropTable {
            names: &qualified[..table_name_count],
            if_exists: false,
            cascade,
        };
        let outcome = responder.without_command_complete(|responder| {
            drop_table_kind_with_columns(
                storage,
                wal,
                txn,
                &statement,
                None,
                "DROP TABLE",
                arena,
                RowTypeColumnCascade {
                    scratch: &mut *scratch,
                    seq_session,
                },
                responder,
            )
        });
        match outcome {
            Ok(Ok(())) => {}
            Ok(Err(error)) => return sql_fail(error),
            Err(error) => return Err(error),
        }
    }

    for (class, selected) in [
        (AccessClass::Sequence, &sequences[..]),
        (AccessClass::Domain, &domains[..]),
        (AccessClass::Enum, &enums[..]),
        (AccessClass::Composite, &composites[..]),
        (AccessClass::ForeignServer, &foreign_servers[..]),
        (AccessClass::ForeignDataWrapper, &foreign_wrappers[..]),
    ] {
        for (slot, selected) in selected
            .iter()
            .copied()
            .enumerate()
            .take(storage.access_class_slots(class))
            .rev()
        {
            let object = AccessObject {
                class,
                slot: slot as u16,
            };
            if !selected || !storage.access_object_visible_to(object, txn.txid) {
                continue;
            }
            let (schema, name) = storage.access_object_name_to(object, txn.txid);
            let owner = storage.role_name(storage.object_owner(object, txn.txid), txn.txid);
            let qualified = QualName {
                schema: Some(schema.as_str()),
                name: name.as_str(),
            };
            let owner = match storage.capture_role(owner.as_str(), txn.txid) {
                Ok(role) => crate::storage::SessionIdentity::bound(role),
                Err(error) => return sql_fail(error),
            };
            let outcome = run_as_role(owner, || {
                responder.without_command_complete(|responder| match class {
                    AccessClass::Sequence => drop_sequence(
                        storage,
                        wal,
                        txn,
                        &mut *scratch,
                        seq_session,
                        core::slice::from_ref(&qualified),
                        false,
                        cascade,
                        arena,
                        responder,
                    ),
                    AccessClass::Domain => drop_domain(
                        storage,
                        wal,
                        txn,
                        scratch,
                        core::slice::from_ref(&qualified),
                        false,
                        cascade,
                        arena,
                        seq_session,
                        responder,
                    ),
                    AccessClass::Enum | AccessClass::Composite => drop_type(
                        storage,
                        wal,
                        txn,
                        scratch,
                        core::slice::from_ref(&qualified),
                        false,
                        cascade,
                        arena,
                        seq_session,
                        responder,
                    ),
                    AccessClass::ForeignServer => drop_foreign_server(
                        storage,
                        wal,
                        txn,
                        &mut *scratch,
                        seq_session,
                        core::slice::from_ref(&name.as_str()),
                        false,
                        cascade,
                        arena,
                        responder,
                    ),
                    AccessClass::ForeignDataWrapper => drop_foreign_data_wrapper(
                        storage,
                        wal,
                        txn,
                        &mut *scratch,
                        seq_session,
                        core::slice::from_ref(&name.as_str()),
                        false,
                        cascade,
                        arena,
                        responder,
                    ),
                    _ => unreachable!(),
                })
            });
            match outcome {
                Ok(Ok(())) => {}
                Ok(Err(error)) => return sql_fail(error),
                Err(error) => return Err(error),
            }
        }
    }

    // Check surviving index entries after their owning relations.
    for slot in (0..storage.access_class_slots(AccessClass::Index)).rev() {
        let object = AccessObject {
            class: AccessClass::Index,
            slot: slot as u16,
        };
        if !storage.access_object_visible_to(object, txn.txid)
            || !owned_roles.contains(&(storage.object_owner(object, txn.txid) as u16))
        {
            continue;
        }
        let (schema, name) = storage.access_object_name_to(object, txn.txid);
        let owner = storage.role_name(storage.object_owner(object, txn.txid), txn.txid);
        let qualified = QualName {
            schema: Some(schema.as_str()),
            name: name.as_str(),
        };
        let owner = match storage.capture_role(owner.as_str(), txn.txid) {
            Ok(role) => crate::storage::SessionIdentity::bound(role),
            Err(error) => return sql_fail(error),
        };
        let outcome = run_as_role(owner, || {
            responder.without_command_complete(|responder| {
                drop_index(
                    storage,
                    wal,
                    txn,
                    DropIndexCommand {
                        names: core::slice::from_ref(&qualified),
                        arena,
                        if_exists: false,
                        build: crate::sql::ast::IndexBuildMode::Blocking,
                        cascade,
                    },
                    responder,
                )
            })
        });
        match outcome {
            Ok(Ok(())) => {}
            Ok(Err(error)) => return sql_fail(error),
            Err(error) => return Err(error),
        }
    }

    for slot in (0..storage.access_class_slots(AccessClass::Routine)).rev() {
        let object = Storage::routine_access_object(slot);
        if !storage.access_object_visible_to(object, txn.txid)
            || !owned_roles.contains(&(storage.object_owner(object, txn.txid) as u16))
        {
            continue;
        }
        let routine = storage.routine(slot);
        let mut signature = [0_u8; ROUTINE_SIGNATURE_WAL_BYTES];
        let signature = match encode_routine_signature(routine.arguments(), &mut signature) {
            Ok(signature) => signature,
            Err(error) => return sql_fail(error),
        };
        let lsn = storage.bump_lsn();
        if let Err(error) = wal.stage_reserved(
            txn.txid,
            lsn,
            &WalOp::DropRoutine {
                identity: storage.routine_position(slot),
                schema: routine.schema_for(txn.txid).as_str(),
                name: routine.name_for(txn.txid).as_str(),
                argument_signature: signature,
            },
        ) {
            return sql_fail(error);
        }
        let target = match storage.prepare_routine_edit(slot, txn.txid) {
            Ok(target) => target,
            Err(error) => return sql_fail(error),
        };
        let change = match storage.drop_routine(target, txn.txid) {
            Ok(change) => change,
            Err(error) => return sql_fail(error),
        };
        if let Err(error) = txn.record_routine_change(storage, change) {
            return sql_fail(error);
        }
    }

    for (slot, selected) in collations.iter().copied().enumerate().rev() {
        if !selected || !storage.collation(slot).visible_to(txn.txid) {
            continue;
        }
        let definition = storage.collation(slot).definition_for(txn.txid);
        let owner = match storage.role_slot_by_oid(definition.owner, txn.txid) {
            Some(owner) => storage.role_name(owner, txn.txid),
            None => {
                return sql_fail(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "collation owner does not exist"
                ));
            }
        };
        let qualified = QualName {
            schema: Some(definition.schema.as_str()),
            name: definition.name.as_str(),
        };
        let owner = match storage.capture_role(owner.as_str(), txn.txid) {
            Ok(role) => crate::storage::SessionIdentity::bound(role),
            Err(error) => return sql_fail(error),
        };
        let outcome = run_as_role(owner, || {
            responder.without_command_complete(|responder| {
                drop_collation(
                    storage,
                    &mut *wal,
                    txn,
                    scratch,
                    &qualified,
                    false,
                    cascade,
                    arena,
                    seq_session,
                    responder,
                )
            })
        });
        match outcome {
            Ok(Ok(())) => {}
            Ok(Err(error)) => return sql_fail(error),
            Err(error) => return Err(error),
        }
    }
    for (slot, selected) in conversions.iter().copied().enumerate().rev() {
        if !selected || !storage.conversion(slot).visible_to(txn.txid) {
            continue;
        }
        let definition = storage.conversion(slot).definition_for(txn.txid);
        let owner = match storage.role_slot_by_oid(definition.owner, txn.txid) {
            Some(owner) => storage.role_name(owner, txn.txid),
            None => {
                return sql_fail(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "conversion owner does not exist"
                ));
            }
        };
        let qualified = QualName {
            schema: Some(definition.schema.as_str()),
            name: definition.name.as_str(),
        };
        let owner = match storage.capture_role(owner.as_str(), txn.txid) {
            Ok(role) => crate::storage::SessionIdentity::bound(role),
            Err(error) => return sql_fail(error),
        };
        let outcome = run_as_role(owner, || {
            responder.without_command_complete(|responder| {
                drop_conversion(
                    storage, &mut *wal, txn, &qualified, false, cascade, responder,
                )
            })
        });
        match outcome {
            Ok(Ok(())) => {}
            Ok(Err(error)) => return sql_fail(error),
            Err(error) => return Err(error),
        }
    }
    for (slot, selected) in text_search_objects.iter().copied().enumerate().rev() {
        if !selected || !storage.text_search_object(slot).visible_to(txn.txid) {
            continue;
        }
        if let Err(error) = drop_text_search_slot(
            storage,
            wal,
            txn,
            &mut *scratch,
            seq_session,
            &mut *responder,
            slot,
            cascade,
            arena,
        ) {
            return sql_fail(error);
        }
    }

    if !cascade {
        for (slot, selected) in schemas
            .iter()
            .copied()
            .enumerate()
            .take(storage.access_class_slots(AccessClass::Schema))
            .rev()
        {
            let object = AccessObject {
                class: AccessClass::Schema,
                slot: slot as u16,
            };
            if !selected || !storage.access_object_visible_to(object, txn.txid) {
                continue;
            }
            let schema = storage.schema_def_for(slot, txn.txid).name;
            let owner = storage.role_name(storage.object_owner(object, txn.txid), txn.txid);
            let owner = match storage.capture_role(owner.as_str(), txn.txid) {
                Ok(role) => crate::storage::SessionIdentity::bound(role),
                Err(error) => return sql_fail(error),
            };
            let outcome = run_as_role(owner, || {
                responder.without_command_complete(|responder| {
                    drop_schema(
                        storage,
                        wal,
                        txn,
                        scratch,
                        SchemaDropTarget::Named {
                            names: &[schema.as_str()],
                            if_exists: false,
                            cascade: false,
                        },
                        arena,
                        seq_session,
                        responder,
                    )
                })
            });
            match outcome {
                Ok(Ok(())) => {}
                Ok(Err(error)) => return sql_fail(error),
                Err(error) => return Err(error),
            }
        }
    }
    responder.command_complete("DROP OWNED")?;
    sql_ok()
}

fn add_privilege_object(
    objects: &mut [crate::storage::AccessObject],
    count: &mut usize,
    object: crate::storage::AccessObject,
) -> Result<(), SqlError> {
    if objects[..*count].contains(&object) {
        return Ok(());
    }
    if *count == objects.len() {
        return Err(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "too many objects in one privilege statement (limit {})",
            objects.len()
        ));
    }
    objects[*count] = object;
    *count += 1;
    Ok(())
}

fn privilege_object_capacity(
    storage: &Storage,
    target: crate::sql::ast::PrivilegeTarget<'_>,
) -> usize {
    use crate::sql::ast::{PrivilegeObjectKind, PrivilegeTarget};
    match target {
        PrivilegeTarget::Parameters(_) => 0,
        PrivilegeTarget::LargeObjects(oids) => oids.len(),
        PrivilegeTarget::Routines { identities, .. } => identities.len(),
        PrivilegeTarget::Objects { kind, names } => match kind {
            PrivilegeObjectKind::AllTablesInSchema => {
                storage.table_count().saturating_add(storage.view_count())
            }
            PrivilegeObjectKind::AllSequencesInSchema => storage.sequence_count(),
            PrivilegeObjectKind::AllFunctionsInSchema
            | PrivilegeObjectKind::AllProceduresInSchema
            | PrivilegeObjectKind::AllRoutinesInSchema => storage.routine_count(),
            _ => names.len(),
        },
    }
}

fn resolve_privilege_objects(
    storage: &Storage,
    target: crate::sql::ast::PrivilegeTarget<'_>,
    txid: u32,
    objects: &mut [crate::storage::AccessObject],
) -> Result<usize, SqlError> {
    use crate::sql::ast::{PrivilegeObjectKind, PrivilegeTarget};
    use crate::storage::{AccessClass, AccessObject};
    let mut count = 0usize;
    match target {
        PrivilegeTarget::Parameters(_) => {
            unreachable!("parameter privileges use their typed executor")
        }
        PrivilegeTarget::LargeObjects(oids) => {
            for oid in oids {
                let Some(slot) = storage.large_object_slot(*oid, txid) else {
                    return Err(sql_err!(
                        sqlstate::UNDEFINED_OBJECT,
                        "large object {} does not exist",
                        oid.get()
                    ));
                };
                add_privilege_object(
                    objects,
                    &mut count,
                    AccessObject {
                        class: AccessClass::LargeObject,
                        slot: slot as u16,
                    },
                )?;
            }
        }
        PrivilegeTarget::Routines { kind, identities } => {
            for identity in identities {
                let object = match lookup_routine(storage, txid, kind, identity)? {
                    Ok(RoutineTarget::Stored(slot)) => Storage::routine_access_object(slot),
                    // Each database has its own copy of a built-in's privileges.
                    Ok(RoutineTarget::Builtin(signature)) => AccessObject {
                        class: AccessClass::BuiltinRoutine,
                        slot: storage.ensure_builtin_routine(
                            crate::storage::BuiltinRoutineOid::parse(signature.oid)
                                .expect("a resolved built-in routine has a catalog OID"),
                        )?,
                    },
                    Err(miss) => return Err(miss.error(storage, txid, kind, identity)),
                };
                add_privilege_object(objects, &mut count, object)?;
            }
        }
        PrivilegeTarget::Objects { kind, names } => {
            for name in names {
                match kind {
                    PrivilegeObjectKind::Table => {
                        let object = match storage.resolve_relation(name.schema, name.name, txid) {
                            Some(crate::storage::ResolvedRelation::Table(slot)) => {
                                let definition = storage.table_def(slot, txid);
                                match storage.matview_slot(
                                    definition.schema.as_str(),
                                    definition.name.as_str(),
                                    txid,
                                ) {
                                    Some(matview) => AccessObject {
                                        class: AccessClass::MaterializedView,
                                        slot: matview as u16,
                                    },
                                    None => AccessObject {
                                        class: AccessClass::Table,
                                        slot: slot as u16,
                                    },
                                }
                            }
                            Some(crate::storage::ResolvedRelation::View(slot)) => AccessObject {
                                class: AccessClass::View,
                                slot: slot as u16,
                            },
                            _ => return Err(undefined_qual(name)),
                        };
                        add_privilege_object(objects, &mut count, object)?;
                    }
                    PrivilegeObjectKind::Sequence => {
                        let Some(slot) = resolve_sequence(storage, name, txid)? else {
                            return Err(undefined_kind("sequence", name.name));
                        };
                        add_privilege_object(
                            objects,
                            &mut count,
                            AccessObject {
                                class: AccessClass::Sequence,
                                slot: slot as u16,
                            },
                        )?;
                    }
                    PrivilegeObjectKind::Schema => {
                        let Some(slot) = storage.find_schema_visible(name.name, txid) else {
                            return Err(sql_err!(
                                sqlstate::INVALID_SCHEMA_NAME,
                                "schema \"{}\" does not exist",
                                name.name
                            ));
                        };
                        add_privilege_object(
                            objects,
                            &mut count,
                            AccessObject {
                                class: AccessClass::Schema,
                                slot: slot as u16,
                            },
                        )?;
                    }
                    PrivilegeObjectKind::Tablespace => {
                        let Some(slot) = storage.tablespace_slot(name.name, txid) else {
                            return Err(sql_err!(
                                sqlstate::UNDEFINED_OBJECT,
                                "tablespace \"{}\" does not exist",
                                name.name
                            ));
                        };
                        add_privilege_object(
                            objects,
                            &mut count,
                            AccessObject {
                                class: AccessClass::Tablespace,
                                slot: slot as u16,
                            },
                        )?;
                    }
                    PrivilegeObjectKind::Database => {
                        let Some(slot) = storage.database_slot(name.name, txid) else {
                            return Err(sql_err!(
                                sqlstate::INVALID_CATALOG_NAME,
                                "database \"{}\" does not exist",
                                name.name
                            ));
                        };
                        add_privilege_object(
                            objects,
                            &mut count,
                            AccessObject {
                                class: AccessClass::Database,
                                slot: slot as u16,
                            },
                        )?;
                    }
                    PrivilegeObjectKind::Type => {
                        let domain = match name.schema {
                            Some(schema) => storage.domain_slot(schema, name.name, txid),
                            None => storage.resolve_domain_slot(name.name, txid),
                        };
                        let enumeration = match name.schema {
                            Some(schema) => storage.enum_slot(schema, name.name, txid),
                            None => storage.resolve_enum_slot(name.name, txid),
                        };
                        let composite = match name.schema {
                            Some(schema) => storage.composite_slot(schema, name.name, txid),
                            None => storage.resolve_composite_slot(name.name, txid),
                        };
                        let object = domain
                            .map(|slot| AccessObject {
                                class: AccessClass::Domain,
                                slot: slot as u16,
                            })
                            .or_else(|| {
                                enumeration.map(|slot| AccessObject {
                                    class: AccessClass::Enum,
                                    slot: slot as u16,
                                })
                            })
                            .or_else(|| {
                                composite.map(|slot| AccessObject {
                                    class: AccessClass::Composite,
                                    slot: slot as u16,
                                })
                            })
                            .ok_or_else(|| {
                                sql_err!(
                                    sqlstate::UNDEFINED_OBJECT,
                                    "type \"{}\" does not exist",
                                    name.name
                                )
                            })?;
                        add_privilege_object(objects, &mut count, object)?;
                    }
                    PrivilegeObjectKind::ProceduralLanguage => {
                        let Some(oid) = crate::sql::catalog::procedural_language_oid(name.name)
                        else {
                            return Err(sql_err!(
                                sqlstate::UNDEFINED_OBJECT,
                                "language \"{}\" does not exist",
                                name.name
                            ));
                        };
                        let slot = u16::try_from(oid).map_err(|_| {
                            sql_err!(
                                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                                "language OID {} cannot be represented by the fixed ACL identity",
                                oid
                            )
                        })?;
                        add_privilege_object(
                            objects,
                            &mut count,
                            AccessObject {
                                class: AccessClass::Language,
                                slot,
                            },
                        )?;
                    }
                    PrivilegeObjectKind::ForeignDataWrapper => {
                        let Some((slot, _)) = storage.foreign_wrapper(name.name, txid) else {
                            return Err(sql_err!(
                                sqlstate::UNDEFINED_OBJECT,
                                "foreign-data wrapper \"{}\" does not exist",
                                name.name
                            ));
                        };
                        add_privilege_object(
                            objects,
                            &mut count,
                            AccessObject {
                                class: AccessClass::ForeignDataWrapper,
                                slot: slot as u16,
                            },
                        )?;
                    }
                    PrivilegeObjectKind::ForeignServer => {
                        let Some((slot, _)) = storage.foreign_server(name.name, txid) else {
                            return Err(sql_err!(
                                sqlstate::UNDEFINED_OBJECT,
                                "server \"{}\" does not exist",
                                name.name
                            ));
                        };
                        add_privilege_object(
                            objects,
                            &mut count,
                            AccessObject {
                                class: AccessClass::ForeignServer,
                                slot: slot as u16,
                            },
                        )?;
                    }
                    PrivilegeObjectKind::AllTablesInSchema => {
                        let schema = name.name;
                        if storage.find_schema_visible(schema, txid).is_none() {
                            return Err(sql_err!(
                                sqlstate::INVALID_SCHEMA_NAME,
                                "schema \"{}\" does not exist",
                                schema
                            ));
                        }
                        for slot in 0..storage.table_count() {
                            if !storage.table(slot).visible_to(txid) {
                                continue;
                            }
                            let definition = storage.table_def(slot, txid);
                            if definition.schema.as_str() != schema {
                                continue;
                            }
                            let object = storage
                                .matview_slot(schema, definition.name.as_str(), txid)
                                .map_or(
                                    AccessObject {
                                        class: AccessClass::Table,
                                        slot: slot as u16,
                                    },
                                    |matview| AccessObject {
                                        class: AccessClass::MaterializedView,
                                        slot: matview as u16,
                                    },
                                );
                            add_privilege_object(objects, &mut count, object)?;
                        }
                        for (slot, view) in storage.views_with_slots() {
                            if view.visible_to(txid) && view.schema.as_str() == schema {
                                add_privilege_object(
                                    objects,
                                    &mut count,
                                    AccessObject {
                                        class: AccessClass::View,
                                        slot: slot as u16,
                                    },
                                )?;
                            }
                        }
                    }
                    PrivilegeObjectKind::AllSequencesInSchema => {
                        let schema = name.name;
                        if storage.find_schema_visible(schema, txid).is_none() {
                            return Err(sql_err!(
                                sqlstate::INVALID_SCHEMA_NAME,
                                "schema \"{}\" does not exist",
                                schema
                            ));
                        }
                        for slot in 0..storage.sequence_count() {
                            let sequence = storage.sequence_for(slot, txid);
                            if sequence.visible_to(txid) && sequence.schema.as_str() == schema {
                                add_privilege_object(
                                    objects,
                                    &mut count,
                                    AccessObject {
                                        class: AccessClass::Sequence,
                                        slot: slot as u16,
                                    },
                                )?;
                            }
                        }
                    }
                    PrivilegeObjectKind::AllFunctionsInSchema
                    | PrivilegeObjectKind::AllProceduresInSchema
                    | PrivilegeObjectKind::AllRoutinesInSchema => {
                        let schema = name.name;
                        if storage.find_schema_visible(schema, txid).is_none() {
                            return Err(sql_err!(
                                sqlstate::INVALID_SCHEMA_NAME,
                                "schema \"{}\" does not exist",
                                schema
                            ));
                        }
                        for slot in 0..storage.routine_count() {
                            let routine = storage.routine(slot);
                            let selected = match kind {
                                PrivilegeObjectKind::AllFunctionsInSchema => {
                                    !matches!(routine.kind, crate::storage::RoutineKind::Procedure)
                                }
                                PrivilegeObjectKind::AllProceduresInSchema => {
                                    matches!(routine.kind, crate::storage::RoutineKind::Procedure)
                                }
                                PrivilegeObjectKind::AllRoutinesInSchema => true,
                                _ => unreachable!("schema routine target is closed"),
                            };
                            if selected
                                && routine.visible_to(txid)
                                && routine.schema_for(txid).as_str() == schema
                            {
                                add_privilege_object(
                                    objects,
                                    &mut count,
                                    Storage::routine_access_object(slot),
                                )?;
                            }
                        }
                    }
                }
            }
        }
    }
    for object in &objects[..count] {
        let table = match object.class {
            AccessClass::Table => Some(usize::from(object.slot)),
            AccessClass::MaterializedView => Some(usize::from(
                storage.matview(usize::from(object.slot)).backing_table,
            )),
            AccessClass::View => {
                storage.lock_object(
                    txid,
                    crate::storage::ObjectLockTarget::View(usize::from(object.slot)),
                    crate::sql::ast::TableLockMode::AccessShare,
                    false,
                )?;
                None
            }
            _ => None,
        };
        if let Some(table) = table {
            let (source, _) = storage.select_table_definition(table, txid);
            storage.lock_table(
                txid,
                table,
                crate::sql::ast::TableLockMode::AccessShare,
                false,
            )?;
            source.validate(storage)?;
        }
    }
    Ok(count)
}

fn column_privilege_target(
    storage: &Storage,
    relation: crate::storage::AccessObject,
    name: &str,
    txid: u32,
    arena: &crate::mem::arena::Arena,
) -> Result<crate::storage::ColumnPrivilegeTarget, SqlError> {
    let column = match relation.class {
        crate::storage::AccessClass::Table => relation.slot as usize,
        crate::storage::AccessClass::MaterializedView => {
            let (schema, table) = storage.access_object_name_to(relation, txid);
            storage
                .find_table(schema.as_str(), table.as_str())
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::UNDEFINED_TABLE,
                        "materialized view \"{}\" does not have a table row",
                        table.as_str()
                    )
                })?
        }
        crate::storage::AccessClass::View => {
            let view = storage.view(relation.slot as usize);
            let mut descriptions = [super::types::ColDesc::new("", 0, 0); super::exec::MAX_PROJ];
            let count = super::catalog::describe_view(&view, txid, arena, &mut descriptions)?;
            let column = descriptions[..count]
                .iter()
                .position(|description| description.name == name)
                .ok_or_else(|| {
                    crate::sql::error_position::at_reference(
                        sql_err!(
                            sqlstate::UNDEFINED_COLUMN,
                            "column \"{}\" of relation \"{}\" does not exist",
                            name,
                            view.name_for(txid).as_str()
                        ),
                        name,
                    )
                })?;
            return crate::storage::ColumnPrivilegeTarget::new(relation, column as u16);
        }
        _ => {
            return Err(sql_err!(
                sqlstate::INVALID_GRANT_OPERATION,
                "column privileges require a table or view"
            ));
        }
    };
    let definition = storage.table_def(column, txid);
    let column = definition.column_index(name).ok_or_else(|| {
        crate::sql::error_position::at_reference(
            sql_err!(
                sqlstate::UNDEFINED_COLUMN,
                "column \"{}\" of relation \"{}\" does not exist",
                name,
                definition.name.as_str()
            ),
            name,
        )
    })?;
    crate::storage::ColumnPrivilegeTarget::new(relation, column as u16)
}

fn materialize_public_acl_default(
    storage: &mut Storage,
    txn: &mut TxnState,
    object: crate::storage::AccessObject,
) -> Result<(), SqlError> {
    let owner = storage.object_owner(object, txn.txid) as u16;
    let mut acl_defined = false;
    let mut owner_defined = false;
    for (slot, entry) in storage.acl_entries() {
        if entry.object != object
            || entry.object.slot == u16::MAX
            || storage.object_acl_order(slot, txn.txid).is_none()
        {
            continue;
        }
        acl_defined = true;
        let (grantee, grantor) = storage.acl_identity(slot, txn.txid);
        owner_defined |= grantee == owner && grantor == owner;
    }
    let owner_privileges = if owner_defined {
        crate::storage::PrivilegeSet::NONE
    } else {
        crate::storage::all_object_privileges(object.class)
    };
    let public_privileges = if acl_defined {
        crate::storage::PrivilegeSet::NONE
    } else {
        storage.object_default_public_privileges(object)
    };
    // PostgreSQL's initial ACL places PUBLIC before the owner when present,
    // and initdb's predefined-role grants (at most one per routine) after it.
    let initial = [
        (crate::storage::PUBLIC_ROLE, public_privileges),
        (owner, owner_privileges),
    ];
    let role_grants = crate::storage::PredefinedRole::ALL
        .into_iter()
        .filter(|_| !acl_defined)
        .map(|role| {
            (
                role.slot() as u16,
                storage.object_default_role_privileges(object, role.slot()),
            )
        });
    let mut ordered =
        [(0u16, crate::storage::PrivilegeSet::NONE); 2 + crate::storage::PREDEFINED_ROLE_COUNT];
    let mut count = 0;
    for entry in initial.into_iter().chain(role_grants) {
        ordered[count] = entry;
        count += 1;
    }
    for (grantee, privileges) in ordered[..count].iter().copied() {
        if privileges.0 == 0 {
            continue;
        }
        let (slot, prior) = storage.change_acl(
            object,
            grantee,
            owner,
            privileges,
            crate::storage::PrivilegeSet::NONE,
            crate::storage::ObjectAclWrite::Change {
                transaction: txn.txid,
            },
        )?;
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::ObjectAclChanged {
                slot: slot as u32,
                prior,
            },
        ) {
            storage
                .restore_acl_pending(slot, prior)
                .expect("transaction owns its object ACL undo");
            return Err(error);
        }
    }
    Ok(())
}

struct ColumnAclCascadeScratch<'a> {
    dependent: &'a mut [usize],
    roles: &'a mut [u16],
    privileges: &'a mut [crate::storage::PrivilegeSet],
}

fn revoke_dependent_column_privileges(
    storage: &mut Storage,
    txn: &mut TxnState,
    target: crate::storage::ColumnPrivilegeTarget,
    grantor: u16,
    lost_options: crate::storage::PrivilegeSet,
    cascade: bool,
    scratch: &mut ColumnAclCascadeScratch<'_>,
) -> Result<(), SqlError> {
    if lost_options.0 == 0 || grantor == crate::storage::PUBLIC_ROLE {
        return Ok(());
    }
    let dependent_count = storage.dependent_column_acl_slots(
        target,
        grantor,
        lost_options,
        txn.txid,
        &mut *scratch.dependent,
    );
    if dependent_count != 0 && !cascade {
        return Err(sql_err!(
            sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
            "dependent privileges exist"
        ));
    }
    if !cascade {
        return Ok(());
    }
    scratch.roles[0] = grantor;
    scratch.privileges[0] = lost_options;
    let mut queue_len = 1usize;
    let mut queue_at = 0usize;
    while queue_at < queue_len {
        let downstream_grantor = scratch.roles[queue_at];
        let lost = scratch.privileges[queue_at];
        queue_at += 1;
        let dependent_count = storage.dependent_column_acl_slots(
            target,
            downstream_grantor,
            lost,
            txn.txid,
            &mut *scratch.dependent,
        );
        for dependent_slot in &scratch.dependent[..dependent_count] {
            let entry = storage.column_acl_entry(*dependent_slot);
            let (dependent_grantee, dependent_grantor) =
                storage.column_acl_identity(*dependent_slot, txn.txid);
            let (dependent_privileges, dependent_options) =
                storage.column_acl_state(*dependent_slot, txn.txid);
            let recursively_lost = crate::storage::PrivilegeSet(dependent_options.0 & lost.0);
            let (slot, prior) = storage.change_column_acl(
                entry.target,
                dependent_grantee,
                dependent_grantor,
                dependent_privileges.without(lost),
                dependent_options.without(lost),
                txn.txid,
            )?;
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::ColumnAclChanged {
                    slot: slot as u32,
                    prior,
                },
            ) {
                storage.restore_column_acl_pending(slot, prior);
                return Err(error);
            }
            if dependent_grantee != crate::storage::PUBLIC_ROLE && recursively_lost.0 != 0 {
                if queue_len == scratch.roles.len() {
                    return Err(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "column privilege dependency graph exceeds {} entries",
                        scratch.roles.len()
                    ));
                }
                scratch.roles[queue_len] = dependent_grantee;
                scratch.privileges[queue_len] = recursively_lost;
                queue_len += 1;
            }
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
pub fn grant_privileges(
    storage: &mut Storage,
    txn: &mut TxnState,
    arena: &crate::mem::arena::Arena,
    privileges: &[crate::sql::ast::PrivilegeSpec<'_>],
    target: crate::sql::ast::PrivilegeTarget<'_>,
    grantees: &[&str],
    grant_option: bool,
    written_grantor: Option<&str>,
    responder: &mut Responder,
) -> Outcome {
    use crate::storage::{AccessClass, AccessObject, PUBLIC_ROLE};
    let objects =
        match arena.alloc_slice_with(privilege_object_capacity(storage, target).max(1), |_| {
            AccessObject {
                class: AccessClass::Table,
                slot: 0,
            }
        }) {
            Ok(objects) => objects,
            Err(_) => return sql_fail(super::query::arena_full_pub()),
        };
    let object_count = match resolve_privilege_objects(storage, target, txn.txid, objects) {
        Ok(count) => count,
        Err(error) => return sql_fail(error),
    };
    let current = super::eval::funcs::system::current_user_owned();
    let Some(grantor) = storage.find_role_visible(current.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            current.as_str()
        ));
    };
    if let Some(written) = written_grantor {
        let resolved = resolve_role_name(written);
        if resolved.as_str() != current.as_str() {
            return sql_fail(sql_err!(
                sqlstate::INVALID_GRANT_OPERATION,
                "GRANTED BY must specify the current user"
            ));
        }
    }
    if object_count.saturating_mul(grantees.len()) > txn.ddl_capacity() {
        return sql_fail(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "too many privilege changes in one statement"
        ));
    }
    for object in &objects[..object_count] {
        if let Err(error) = materialize_public_acl_default(storage, txn, *object) {
            return sql_fail(error);
        }
        let requested = match privilege_mask(privileges, object.class, false) {
            Ok(mask) => mask,
            Err(error) => return sql_fail(error),
        };
        if requested.0 != 0
            && !storage.has_object_grant_option(*object, grantor, requested, txn.txid)
        {
            let (_, name) = storage.access_object_name(*object);
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied for {} {}",
                privilege_object_noun(object.class),
                name.as_str()
            ));
        }
        let acl_grantor = acl_grantor(storage, *object, grantor, txn.txid);
        for name in grantees {
            let grantee = if name.eq_ignore_ascii_case("public") {
                PUBLIC_ROLE
            } else {
                let Some(slot) = storage.find_role_visible(name, txn.txid) else {
                    return sql_fail(sql_err!(
                        sqlstate::UNDEFINED_OBJECT,
                        "role \"{}\" does not exist",
                        name
                    ));
                };
                slot as u16
            };
            if requested.0 != 0 {
                let (old_privileges, old_options) =
                    storage.acl_from(*object, grantee, acl_grantor as u16, txn.txid);
                let new_options = if grant_option {
                    old_options.union(requested)
                } else {
                    old_options
                };
                let (slot, prior) = match storage.change_acl(
                    *object,
                    grantee,
                    acl_grantor as u16,
                    old_privileges.union(requested),
                    new_options,
                    crate::storage::ObjectAclWrite::Change {
                        transaction: txn.txid,
                    },
                ) {
                    Ok(change) => change,
                    Err(error) => return sql_fail(error),
                };
                if let Err(error) = txn.record_ddl(
                    storage,
                    super::txn::DdlUndo::ObjectAclChanged {
                        slot: slot as u32,
                        prior,
                    },
                ) {
                    storage
                        .restore_acl_pending(slot, prior)
                        .expect("transaction owns its object ACL undo");
                    return sql_fail(error);
                }
            }
            for specification in privileges
                .iter()
                .filter(|specification| !specification.columns.is_empty())
            {
                let requested = match privilege_mask(
                    core::slice::from_ref(specification),
                    object.class,
                    true,
                ) {
                    Ok(requested) => requested,
                    Err(error) => return sql_fail(error),
                };
                for column in specification.columns {
                    let target =
                        match column_privilege_target(storage, *object, column, txn.txid, arena) {
                            Ok(target) => target,
                            Err(error) => return sql_fail(error),
                        };
                    if !storage.has_column_grant_option(target, grantor, requested, txn.txid) {
                        return sql_fail(sql_err!(
                            sqlstate::INSUFFICIENT_PRIVILEGE,
                            "permission denied for column {}",
                            column
                        ));
                    }
                    let (old_privileges, old_options) =
                        storage.column_acl_from(target, grantee, acl_grantor as u16, txn.txid);
                    let new_options = if grant_option {
                        old_options.union(requested)
                    } else {
                        old_options
                    };
                    let (slot, prior) = match storage.change_column_acl(
                        target,
                        grantee,
                        acl_grantor as u16,
                        old_privileges.union(requested),
                        new_options,
                        txn.txid,
                    ) {
                        Ok(change) => change,
                        Err(error) => return sql_fail(error),
                    };
                    if let Err(error) = txn.record_ddl(
                        storage,
                        super::txn::DdlUndo::ColumnAclChanged {
                            slot: slot as u32,
                            prior,
                        },
                    ) {
                        storage.restore_column_acl_pending(slot, prior);
                        return sql_fail(error);
                    }
                }
            }
        }
    }
    responder.command_complete("GRANT")?;
    sql_ok()
}

#[allow(clippy::too_many_arguments)]
pub fn revoke_privileges(
    storage: &mut Storage,
    txn: &mut TxnState,
    arena: &crate::mem::arena::Arena,
    grant_option_only: bool,
    privileges: &[crate::sql::ast::PrivilegeSpec<'_>],
    target: crate::sql::ast::PrivilegeTarget<'_>,
    grantees: &[&str],
    written_grantor: Option<&str>,
    cascade: bool,
    responder: &mut Responder,
) -> Outcome {
    use crate::storage::{AccessClass, AccessObject, PUBLIC_ROLE};
    let objects =
        match arena.alloc_slice_with(privilege_object_capacity(storage, target).max(1), |_| {
            AccessObject {
                class: AccessClass::Table,
                slot: 0,
            }
        }) {
            Ok(objects) => objects,
            Err(_) => return sql_fail(super::query::arena_full_pub()),
        };
    let object_count = match resolve_privilege_objects(storage, target, txn.txid, objects) {
        Ok(count) => count,
        Err(error) => return sql_fail(error),
    };
    let object_graph_capacity = storage
        .acl_entry_count()
        .saturating_add(object_count.saturating_mul(2))
        .max(1);
    let dependent = match arena.alloc_slice_with(object_graph_capacity, |_| 0usize) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let queue_roles = match arena.alloc_slice_with(object_graph_capacity, |_| 0u16) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let queue_privileges = match arena.alloc_slice_with(object_graph_capacity, |_| {
        crate::storage::PrivilegeSet::NONE
    }) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let column_graph_capacity = storage.column_acl_entry_count().max(1);
    let targets = match arena.alloc_slice_with(column_graph_capacity, |_| {
        crate::storage::ColumnPrivilegeTarget::new(
            AccessObject {
                class: AccessClass::Table,
                slot: 0,
            },
            0,
        )
        .expect("table access objects accept column privileges")
    }) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let column_dependent = match arena.alloc_slice_with(column_graph_capacity, |_| 0usize) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let column_queue_roles = match arena.alloc_slice_with(column_graph_capacity, |_| 0u16) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let column_queue_privileges = match arena.alloc_slice_with(column_graph_capacity, |_| {
        crate::storage::PrivilegeSet::NONE
    }) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let mut column_scratch = ColumnAclCascadeScratch {
        dependent: column_dependent,
        roles: column_queue_roles,
        privileges: column_queue_privileges,
    };
    let current = super::eval::funcs::system::current_user_owned();
    let Some(grantor) = storage.find_role_visible(current.as_str(), txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "role \"{}\" does not exist",
            current.as_str()
        ));
    };
    if let Some(written) = written_grantor {
        let resolved = resolve_role_name(written);
        if resolved.as_str() != current.as_str() {
            return sql_fail(sql_err!(
                sqlstate::INVALID_GRANT_OPERATION,
                "GRANTED BY must specify the current user"
            ));
        }
    }
    for object in &objects[..object_count] {
        if let Err(error) = materialize_public_acl_default(storage, txn, *object) {
            return sql_fail(error);
        }
        let requested = match privilege_mask(privileges, object.class, false) {
            Ok(mask) => mask,
            Err(error) => return sql_fail(error),
        };
        if requested.0 != 0
            && !storage.has_object_grant_option(*object, grantor, requested, txn.txid)
        {
            let (_, name) = storage.access_object_name(*object);
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied for {} {}",
                privilege_object_noun(object.class),
                name.as_str()
            ));
        }
        let acl_grantor = acl_grantor(storage, *object, grantor, txn.txid);
        for name in grantees {
            let grantee = if name.eq_ignore_ascii_case("public") {
                PUBLIC_ROLE
            } else {
                let Some(slot) = storage.find_role_visible(name, txn.txid) else {
                    return sql_fail(sql_err!(
                        sqlstate::UNDEFINED_OBJECT,
                        "role \"{}\" does not exist",
                        name
                    ));
                };
                slot as u16
            };
            let (old_privileges, old_options) =
                storage.acl_from(*object, grantee, acl_grantor as u16, txn.txid);
            let removed_options = crate::storage::PrivilegeSet(old_options.0 & requested.0);
            let removed_column_options = crate::storage::PrivilegeSet(
                removed_options.0
                    & crate::storage::PrivilegeSet::SELECT
                        .union(crate::storage::PrivilegeSet::INSERT)
                        .union(crate::storage::PrivilegeSet::UPDATE)
                        .union(crate::storage::PrivilegeSet::REFERENCES)
                        .0,
            );
            if grantee != PUBLIC_ROLE
                && removed_column_options.0 != 0
                && matches!(
                    object.class,
                    crate::storage::AccessClass::Table
                        | crate::storage::AccessClass::View
                        | crate::storage::AccessClass::MaterializedView
                )
            {
                let target_count = storage.column_acl_targets(*object, txn.txid, targets);
                for target in &targets[..target_count] {
                    if let Err(error) = revoke_dependent_column_privileges(
                        storage,
                        txn,
                        *target,
                        grantee,
                        removed_column_options,
                        cascade,
                        &mut column_scratch,
                    ) {
                        return sql_fail(error);
                    }
                }
            }
            if grantee != PUBLIC_ROLE && removed_options.0 != 0 {
                let dependent_count = storage.dependent_acl_slots(
                    *object,
                    grantee,
                    removed_options,
                    txn.txid,
                    dependent,
                );
                if dependent_count != 0 && !cascade {
                    return sql_fail(sql_err!(
                        sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                        "dependent privileges exist"
                    ));
                }
                if cascade {
                    queue_roles[0] = grantee;
                    queue_privileges[0] = removed_options;
                    let mut queue_len = 1usize;
                    let mut queue_at = 0usize;
                    while queue_at < queue_len {
                        let downstream_grantor = queue_roles[queue_at];
                        let lost_options = queue_privileges[queue_at];
                        queue_at += 1;
                        let dependent_count = storage.dependent_acl_slots(
                            *object,
                            downstream_grantor,
                            lost_options,
                            txn.txid,
                            &mut *dependent,
                        );
                        for dependent_slot in &dependent[..dependent_count] {
                            let entry = storage.acl_entry(*dependent_slot);
                            let (dependent_grantee, dependent_grantor) =
                                storage.acl_identity(*dependent_slot, txn.txid);
                            let (dependent_privileges, dependent_options) =
                                storage.acl_state(*dependent_slot, txn.txid);
                            let recursively_lost =
                                crate::storage::PrivilegeSet(dependent_options.0 & lost_options.0);
                            let (slot, prior) = match storage.change_acl(
                                entry.object,
                                dependent_grantee,
                                dependent_grantor,
                                dependent_privileges.without(lost_options),
                                dependent_options.without(lost_options),
                                crate::storage::ObjectAclWrite::Change {
                                    transaction: txn.txid,
                                },
                            ) {
                                Ok(change) => change,
                                Err(error) => return sql_fail(error),
                            };
                            if let Err(error) = txn.record_ddl(
                                storage,
                                super::txn::DdlUndo::ObjectAclChanged {
                                    slot: slot as u32,
                                    prior,
                                },
                            ) {
                                storage
                                    .restore_acl_pending(slot, prior)
                                    .expect("transaction owns its object ACL undo");
                                return sql_fail(error);
                            }
                            if dependent_grantee != PUBLIC_ROLE && recursively_lost.0 != 0 {
                                if queue_len == queue_roles.len() {
                                    return sql_fail(sql_err!(
                                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                                        "privilege dependency graph exceeds {} entries",
                                        queue_roles.len()
                                    ));
                                }
                                queue_roles[queue_len] = dependent_grantee;
                                queue_privileges[queue_len] = recursively_lost;
                                queue_len += 1;
                            }
                        }
                    }
                }
            }
            let new_privileges = if grant_option_only {
                old_privileges
            } else {
                old_privileges.without(requested)
            };
            let new_options = old_options.without(requested);
            if requested.0 != 0 && (new_privileges != old_privileges || new_options != old_options)
            {
                let (slot, prior) = match storage.change_acl(
                    *object,
                    grantee,
                    acl_grantor as u16,
                    new_privileges,
                    new_options,
                    crate::storage::ObjectAclWrite::Change {
                        transaction: txn.txid,
                    },
                ) {
                    Ok(change) => change,
                    Err(error) => return sql_fail(error),
                };
                if let Err(error) = txn.record_ddl(
                    storage,
                    super::txn::DdlUndo::ObjectAclChanged {
                        slot: slot as u32,
                        prior,
                    },
                ) {
                    storage
                        .restore_acl_pending(slot, prior)
                        .expect("transaction owns its object ACL undo");
                    return sql_fail(error);
                }
            }
            for specification in privileges
                .iter()
                .filter(|specification| !specification.columns.is_empty())
            {
                let requested = match privilege_mask(
                    core::slice::from_ref(specification),
                    object.class,
                    true,
                ) {
                    Ok(requested) => requested,
                    Err(error) => return sql_fail(error),
                };
                for column in specification.columns {
                    let target =
                        match column_privilege_target(storage, *object, column, txn.txid, arena) {
                            Ok(target) => target,
                            Err(error) => return sql_fail(error),
                        };
                    if !storage.has_column_grant_option(target, grantor, requested, txn.txid) {
                        return sql_fail(sql_err!(
                            sqlstate::INSUFFICIENT_PRIVILEGE,
                            "permission denied for column {}",
                            column
                        ));
                    }
                    let (old_privileges, old_options) =
                        storage.column_acl_from(target, grantee, acl_grantor as u16, txn.txid);
                    let removed_options = crate::storage::PrivilegeSet(old_options.0 & requested.0);
                    if let Err(error) = revoke_dependent_column_privileges(
                        storage,
                        txn,
                        target,
                        grantee,
                        removed_options,
                        cascade,
                        &mut column_scratch,
                    ) {
                        return sql_fail(error);
                    }
                    let new_privileges = if grant_option_only {
                        old_privileges
                    } else {
                        old_privileges.without(requested)
                    };
                    let (slot, prior) = match storage.change_column_acl(
                        target,
                        grantee,
                        acl_grantor as u16,
                        new_privileges,
                        old_options.without(requested),
                        txn.txid,
                    ) {
                        Ok(change) => change,
                        Err(error) => return sql_fail(error),
                    };
                    if let Err(error) = txn.record_ddl(
                        storage,
                        super::txn::DdlUndo::ColumnAclChanged {
                            slot: slot as u32,
                            prior,
                        },
                    ) {
                        storage.restore_column_acl_pending(slot, prior);
                        return sql_fail(error);
                    }
                }
            }
        }
    }
    responder.command_complete("REVOKE")?;
    sql_ok()
}

fn parameter_acl_grantee(storage: &Storage, written: &str, txid: u32) -> Result<u16, SqlError> {
    if written.eq_ignore_ascii_case("public") {
        return Ok(crate::storage::PUBLIC_ROLE);
    }
    storage
        .find_role_visible(written, txid)
        .map(|slot| slot as u16)
        .ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                written
            )
        })
}

fn parameter_acl_grantor(
    storage: &Storage,
    txn: &TxnState,
    written: Option<&str>,
) -> Result<usize, SqlError> {
    let current = super::eval::funcs::system::current_user_owned();
    let grantor = storage
        .find_role_visible(current.as_str(), txn.txid)
        .ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "role \"{}\" does not exist",
                current.as_str()
            )
        })?;
    if let Some(written) = written {
        let resolved = resolve_role_name(written);
        if resolved.as_str() != current.as_str() {
            return Err(sql_err!(
                sqlstate::INVALID_GRANT_OPERATION,
                "GRANTED BY must specify the current user"
            ));
        }
    }
    Ok(grantor)
}

fn ensure_parameter_acl_target(parameter: crate::sql::ast::ParameterName) -> Result<(), SqlError> {
    if crate::sql::guc::knows_parameter(parameter.as_str())
        || crate::sql::guc::is_valid_custom_parameter(parameter.as_str())
    {
        Ok(())
    } else {
        Err(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "unrecognized configuration parameter \"{}\"",
            parameter.as_str()
        ))
    }
}

pub struct ParameterPrivilegeTarget<'a> {
    pub privileges: crate::sql::ast::ParameterPrivileges,
    pub names: &'a [crate::sql::ast::ParameterName],
    pub grantees: &'a [&'a str],
    pub grantor: Option<&'a str>,
}

pub struct ParameterGrantCommand<'a> {
    pub target: ParameterPrivilegeTarget<'a>,
    pub grant_option: bool,
}

pub struct ParameterRevokeCommand<'a> {
    pub target: ParameterPrivilegeTarget<'a>,
    pub grant_option_only: bool,
    pub cascade: bool,
}

pub fn grant_parameter_privileges(
    storage: &mut Storage,
    txn: &mut TxnState,
    command: ParameterGrantCommand<'_>,
    responder: &mut Responder,
) -> Outcome {
    let grantor = match parameter_acl_grantor(storage, txn, command.target.grantor) {
        Ok(grantor) => grantor,
        Err(error) => return sql_fail(error),
    };
    if command
        .target
        .names
        .len()
        .saturating_mul(command.target.grantees.len())
        > txn.ddl_capacity()
    {
        return sql_fail(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "too many parameter privilege changes in one statement"
        ));
    }
    for parameter in command.target.names {
        if let Err(error) = ensure_parameter_acl_target(*parameter) {
            return sql_fail(error);
        }
        let can_grant = storage.role(grantor).attributes_to(txn.txid).superuser
            || storage.has_parameter_grant_option(
                *parameter,
                grantor,
                command.target.privileges,
                txn.txid,
            );
        if !can_grant {
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied for parameter \"{}\"",
                parameter.as_str()
            ));
        }
        for written in command.target.grantees {
            let grantee = match parameter_acl_grantee(storage, written, txn.txid) {
                Ok(grantee) => grantee,
                Err(error) => return sql_fail(error),
            };
            let (old_privileges, old_options) =
                storage.parameter_acl_from(*parameter, grantee, grantor as u16, txn.txid);
            let prior = match storage.change_parameter_acl(
                *parameter,
                grantee,
                grantor as u16,
                old_privileges.union(command.target.privileges),
                if command.grant_option {
                    old_options.union(command.target.privileges)
                } else {
                    old_options
                },
                txn.txid,
            ) {
                Ok(change) => change,
                Err(error) => return sql_fail(error),
            };
            if let Err(error) =
                txn.record_ddl(storage, super::txn::DdlUndo::ParameterAclChanged { prior })
            {
                storage
                    .restore_parameter_acl_pending(prior)
                    .expect("transaction owns its parameter ACL undo");
                return sql_fail(error);
            }
        }
    }
    responder.command_complete("GRANT")?;
    sql_ok()
}

struct ParameterAclCascadeScratch<'a> {
    roles: &'a mut [u16],
    privileges: &'a mut [crate::sql::ast::ParameterPrivileges],
    dependent: &'a mut [usize],
}

fn cascade_parameter_acl_grants(
    storage: &mut Storage,
    txn: &mut TxnState,
    parameter: crate::sql::ast::ParameterName,
    source_role: u16,
    lost: crate::sql::ast::ParameterPrivileges,
    cascade: bool,
    scratch: &mut ParameterAclCascadeScratch<'_>,
) -> Result<(), SqlError> {
    let mut count = 1usize;
    let mut at = 0usize;
    scratch.roles[0] = source_role;
    scratch.privileges[0] = lost;
    while at < count {
        let grantor = scratch.roles[at];
        let lost = scratch.privileges[at];
        at += 1;
        let dependent_count = storage.dependent_parameter_acl_slots(
            parameter,
            grantor,
            lost,
            txn.txid,
            &mut *scratch.dependent,
        );
        if dependent_count != 0 && !cascade {
            return Err(sql_err!(
                sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                "dependent parameter privileges exist"
            ));
        }
        for slot in &scratch.dependent[..dependent_count] {
            let entry = storage.parameter_acl_entry(*slot);
            let (grantee, grantor) = storage.parameter_acl_identity(*slot, txn.txid);
            let (old_privileges, old_options) = storage.parameter_acl_state(*slot, txn.txid);
            let removed = crate::sql::ast::ParameterPrivileges::from_bits(
                old_privileges.bits() & lost.bits(),
            )
            .expect("intersection of parameter privilege bits is valid");
            let prior = storage.change_parameter_acl(
                entry.parameter,
                grantee,
                grantor,
                old_privileges.without(removed),
                old_options.without(removed),
                txn.txid,
            )?;
            if let Err(error) =
                txn.record_ddl(storage, super::txn::DdlUndo::ParameterAclChanged { prior })
            {
                storage
                    .restore_parameter_acl_pending(prior)
                    .expect("transaction owns its parameter ACL undo");
                return Err(error);
            }
            if grantee != crate::storage::PUBLIC_ROLE
                && !storage.has_parameter_grant_option(
                    entry.parameter,
                    grantee as usize,
                    removed,
                    txn.txid,
                )
            {
                if count == scratch.roles.len() {
                    return Err(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "parameter privilege dependency graph exceeds {} entries",
                        scratch.roles.len()
                    ));
                }
                scratch.roles[count] = grantee;
                scratch.privileges[count] = removed;
                count += 1;
            }
        }
    }
    Ok(())
}

pub fn revoke_parameter_privileges(
    storage: &mut Storage,
    txn: &mut TxnState,
    arena: &Arena,
    command: ParameterRevokeCommand<'_>,
    responder: &mut Responder,
) -> Outcome {
    let graph_capacity = storage
        .parameter_acl_entry_count()
        .saturating_add(command.target.names.len())
        .max(1);
    let roles = match arena.alloc_slice_with(graph_capacity, |_| 0u16) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let privileges = match arena.alloc_slice_with(graph_capacity, |_| {
        crate::sql::ast::ParameterPrivileges::NONE
    }) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let dependent = match arena.alloc_slice_with(graph_capacity, |_| usize::MAX) {
        Ok(values) => values,
        Err(_) => return sql_fail(super::query::arena_full_pub()),
    };
    let mut scratch = ParameterAclCascadeScratch {
        roles,
        privileges,
        dependent,
    };
    let grantor = match parameter_acl_grantor(storage, txn, command.target.grantor) {
        Ok(grantor) => grantor,
        Err(error) => return sql_fail(error),
    };
    for parameter in command.target.names {
        if let Err(error) = ensure_parameter_acl_target(*parameter) {
            return sql_fail(error);
        }
        let can_revoke = storage.role(grantor).attributes_to(txn.txid).superuser
            || storage.has_parameter_grant_option(
                *parameter,
                grantor,
                command.target.privileges,
                txn.txid,
            );
        if !can_revoke {
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied for parameter \"{}\"",
                parameter.as_str()
            ));
        }
        for written in command.target.grantees {
            let grantee = match parameter_acl_grantee(storage, written, txn.txid) {
                Ok(grantee) => grantee,
                Err(error) => return sql_fail(error),
            };
            let (old_privileges, old_options) =
                storage.parameter_acl_from(*parameter, grantee, grantor as u16, txn.txid);
            if old_privileges.bits() == 0 && old_options.bits() == 0 {
                continue;
            }
            let (new_privileges, new_options) = if command.grant_option_only {
                (
                    old_privileges,
                    old_options.without(command.target.privileges),
                )
            } else {
                (
                    old_privileges.without(command.target.privileges),
                    old_options.without(command.target.privileges),
                )
            };
            let prior = match storage.change_parameter_acl(
                *parameter,
                grantee,
                grantor as u16,
                new_privileges,
                new_options,
                txn.txid,
            ) {
                Ok(change) => change,
                Err(error) => return sql_fail(error),
            };
            if let Err(error) =
                txn.record_ddl(storage, super::txn::DdlUndo::ParameterAclChanged { prior })
            {
                storage
                    .restore_parameter_acl_pending(prior)
                    .expect("transaction owns its parameter ACL undo");
                return sql_fail(error);
            }
            let removed_options = crate::sql::ast::ParameterPrivileges::from_bits(
                old_options.bits() & command.target.privileges.bits(),
            )
            .expect("intersection of parameter privilege bits is valid");
            if removed_options.bits() != 0
                && grantee != crate::storage::PUBLIC_ROLE
                && !storage.has_parameter_grant_option(
                    *parameter,
                    grantee as usize,
                    removed_options,
                    txn.txid,
                )
                && let Err(error) = cascade_parameter_acl_grants(
                    storage,
                    txn,
                    *parameter,
                    grantee,
                    removed_options,
                    command.cascade,
                    &mut scratch,
                )
            {
                return sql_fail(error);
            }
        }
    }
    responder.command_complete("REVOKE")?;
    sql_ok()
}

fn acl_grantor(
    storage: &Storage,
    object: crate::storage::AccessObject,
    current: usize,
    txid: u32,
) -> usize {
    if storage.role(current).attributes_to(txid).superuser {
        storage.object_owner(object, txid)
    } else {
        current
    }
}

/// One object a DROP SCHEMA sweeps up, for dependency reports and the
/// cascaded drops.
#[derive(Clone, Copy)]
enum SchemaObject {
    Table(usize),
    View(usize),
    Routine(usize),
    Collation(usize),
    Conversion(usize),
    TextSearch(usize),
    Matview {
        table: usize,
        catalog: usize,
    },
    Sequence(usize),
    Domain(usize),
    Enum(usize),
    Composite(usize),
    Operator(usize),
    OperatorFamily(usize),
    OperatorClass(usize),
    Statistics(usize),
    Policy {
        slot: usize,
        root_schema: SqlName,
        root_class: Option<crate::storage::DependencyClass>,
        root_slot: usize,
    },
    /// An inbound foreign key on a table that itself survives.
    InboundFk {
        table: usize,
        fk_index: usize,
    },
}

pub(crate) enum SchemaDropTarget<'a> {
    Named {
        names: &'a [&'a str],
        if_exists: bool,
        cascade: bool,
    },
    TemporaryObjects,
}

/// Drop selected schemas or clear this connection's temporary objects using
/// the same dependency graph, fixed undo capacity and transactional rollback.
/// Temporary cleanup retains its namespace and emits no durable drop records.
/// Named RESTRICT refuses non-empty schemas; CASCADE also removes dependents.
#[allow(clippy::too_many_arguments)]
pub(crate) fn drop_schema(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    scratch: &mut DmlScratch,
    target: SchemaDropTarget<'_>,
    arena: &Arena,
    seq_session: &crate::sql::guc::SeqSession,
    responder: &mut Responder,
) -> Outcome {
    use core::fmt::Write as _;
    let (names, if_exists, cascade, temporary) = match target {
        SchemaDropTarget::Named {
            names,
            if_exists,
            cascade,
        } => (names, if_exists, cascade, None),
        SchemaDropTarget::TemporaryObjects => {
            let schema = match storage.temporary_schema() {
                Ok(schema) => schema,
                Err(error) => return sql_fail(error),
            };
            // The private namespace survives clearing its contents.
            (&[][..], false, true, Some(schema))
        }
    };
    // Objects in the schemas being dropped go with their schema rather than
    // through another relation's row-type cascade.
    let dropped_schema = |schema: SqlName| {
        names.iter().any(|name| *name == schema.as_str()) || temporary == Some(schema)
    };
    let slots = match arena.alloc_slice_with(names.len(), |_| usize::MAX) {
        Ok(slots) => slots,
        Err(_) => return sql_fail(arena_full()),
    };
    let mut n_slots = 0usize;
    for name in names {
        if *name == "pg_catalog" || *name == "information_schema" {
            return sql_fail(sql_err!(
                crate::sql::eval::sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                "cannot drop schema {} because it is required by the database system",
                name
            ));
        }
        match storage.find_schema_visible(name, txn.txid) {
            Some(slot) => {
                if let Err(error) = storage.require_not_extension_member(
                    crate::storage::AccessObject {
                        class: crate::storage::AccessClass::Schema,
                        slot: slot as u16,
                    },
                    txn.txid,
                    "schema",
                ) {
                    return sql_fail(error);
                }
                if let Err(error) = storage.require_owner(
                    crate::storage::AccessObject {
                        class: crate::storage::AccessClass::Schema,
                        slot: slot as u16,
                    },
                    txn.txid,
                    "schema",
                ) {
                    return sql_fail(error);
                }
                if !slots[..n_slots].contains(&slot) {
                    slots[n_slots] = slot;
                    n_slots += 1;
                }
            }
            None if if_exists => {
                responder.notice(
                    crate::sql::eval::sqlstate::SUCCESSFUL_COMPLETION,
                    stack_format!(128, "schema \"{}\" does not exist, skipping", name).as_str(),
                )?;
            }
            None => {
                return sql_fail(sql_err!(
                    sqlstate::INVALID_SCHEMA_NAME,
                    "schema \"{}\" does not exist",
                    name
                ));
            }
        }
    }
    let report = if temporary.is_some() {
        Ok(None)
    } else {
        (|| {
            let originals = arena
                .alloc_slice_with(n_slots, |_| DROPPED_NOTHING)
                .map_err(|_| arena_full())?;
            for (original, slot) in originals.iter_mut().zip(&slots[..n_slots]) {
                *original = ObjectAddress::new(
                    super::catalog::PG_NAMESPACE_OID,
                    super::catalog::namespace_oid_for_slot(storage, *slot),
                    0,
                );
            }
            dependency_report::report_drop(storage, txn.txid, originals, cascade, arena, responder)
        })()
    };
    run_reported_drop(report, responder, |responder| {
        let selected_schema = temporary.or_else(|| {
            slots[..n_slots]
                .first()
                .map(|&slot| storage.schema_def_for(slot, txn.txid).name)
        });
        // Everything the drop sweeps up, across all listed schemas.
        let schema_transaction = txn.txid;
        let in_listed = |storage: &Storage, schema: &str| {
            temporary.is_some_and(|selected| selected.as_str() == schema)
                || slots[..n_slots].iter().any(|&slot| {
                    storage
                        .schema_def_for(slot, schema_transaction)
                        .name
                        .as_str()
                        == schema
                })
        };
        let type_uses_listed_schema =
            |storage: &Storage, base: ColType, txid: u32| -> Result<bool, SqlError> {
                use crate::storage::NamedTypeKind;
                let (kind, creation) = match base {
                    ColType::Enum(creation)
                    | ColType::Array(super::types::ArrElem::Enum(creation)) => (
                        NamedTypeKind::Enum,
                        crate::storage::TypeCreation::require(creation)?,
                    ),
                    ColType::Composite(creation)
                    | ColType::Array(super::types::ArrElem::Composite(creation)) => (
                        NamedTypeKind::Composite,
                        crate::storage::TypeCreation::require(creation)?,
                    ),
                    _ => return Ok(false),
                };
                // A relation's row type lives in its relation's schema.
                if kind == NamedTypeKind::Composite
                    && let Some(relation) = storage.row_type_relation(creation, txid)
                {
                    let (schema, _) = storage.row_type_relation_name(relation, txid);
                    return Ok(in_listed(storage, schema.as_str()));
                }
                let target =
                    crate::storage::TypeDefinitionTarget::by_creation(storage, kind, creation)?;
                let schema = match kind {
                    NamedTypeKind::Enum => {
                        storage
                            .read_enum_definition(target, txid)?
                            .ok_or_else(|| {
                                sql_err!(sqlstate::UNDEFINED_OBJECT, "enum type no longer exists")
                            })?
                            .schema
                    }
                    NamedTypeKind::Composite => {
                        storage
                            .read_composite_definition(target, txid)?
                            .ok_or_else(|| {
                                sql_err!(
                                    sqlstate::UNDEFINED_OBJECT,
                                    "composite type no longer exists"
                                )
                            })?
                            .schema
                    }
                    NamedTypeKind::Domain => {
                        unreachable!("selected enum or composite representation")
                    }
                };
                Ok(in_listed(storage, schema.as_str()))
            };

        let objects =
            match arena.alloc_slice_with(storage.schema_drop_object_count(txn.txid), |_| None) {
                Ok(objects) => objects,
                Err(_) => return sql_fail(arena_full()),
            };
        let mut n_objects = 0usize;
        let mut push = |o: SchemaObject, n_objects: &mut usize| -> Result<(), SqlError> {
            if *n_objects == objects.len() {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "DROP SCHEMA sweeps up more than {} objects",
                    objects.len()
                ));
            }
            objects[*n_objects] = Some(o);
            *n_objects += 1;
            Ok(())
        };
        #[derive(Clone, Copy)]
        struct TableDropSelection {
            source: crate::storage::TableDefinitionTarget,
            mode: Option<crate::sql::ast::TableLockMode>,
        }
        let table_locks =
            match arena.alloc_slice_with(storage.table_count(), |_| None::<TableDropSelection>) {
                Ok(locks) => locks,
                Err(_) => return sql_fail(arena_full()),
            };
        for (t, selected) in table_locks.iter_mut().enumerate() {
            if !storage.table_slot_visible_to(t, txn.txid) {
                continue;
            }
            let (source, schema, name) = {
                let definitions = storage.table_definition_images();
                let (source, definition) = match definitions.selection(storage, t, txn.txid) {
                    Ok(selection) => selection,
                    Err(error) => return sql_fail(error),
                };
                (source, definition.schema, definition.name)
            };
            // Keep the original identity/revision for lock validation, releasing
            // the wide image before the next table or any catalog callback.
            *selected = Some(TableDropSelection { source, mode: None });
            if !in_listed(storage, schema.as_str()) {
                continue;
            }
            let object = match storage.matview_slot(schema.as_str(), name.as_str(), txn.txid) {
                Some(catalog) => SchemaObject::Matview { table: t, catalog },
                None => SchemaObject::Table(t),
            };
            if let Err(e) = push(object, &mut n_objects) {
                return sql_fail(e);
            }
        }
        for v in 0..storage.view_count() {
            if storage.view(v).visible_to(txn.txid)
                && in_listed(storage, storage.view(v).schema.as_str())
                && let Err(e) = push(SchemaObject::View(v), &mut n_objects)
            {
                return sql_fail(e);
            }
        }
        for routine in 0..storage.routine_count() {
            let definition = storage.routine_for(routine, txn.txid);
            if definition.visible_to(txn.txid)
                && in_listed(storage, definition.schema_for(txn.txid).as_str())
                && let Err(error) = push(SchemaObject::Routine(routine), &mut n_objects)
            {
                return sql_fail(error);
            }
        }
        for (slot, definition) in storage.collations_visible_to(txn.txid) {
            if in_listed(storage, definition.schema.as_str())
                && let Err(error) = push(SchemaObject::Collation(slot), &mut n_objects)
            {
                return sql_fail(error);
            }
        }
        for (slot, definition) in storage.conversions_visible_to(txn.txid) {
            if in_listed(storage, definition.schema.as_str())
                && let Err(error) = push(SchemaObject::Conversion(slot), &mut n_objects)
            {
                return sql_fail(error);
            }
        }
        for (slot, definition) in storage.text_search_objects_visible_to(txn.txid) {
            if in_listed(storage, definition.schema().as_str())
                && let Err(error) = push(SchemaObject::TextSearch(slot), &mut n_objects)
            {
                return sql_fail(error);
            }
        }
        for sequence in 0..storage.sequence_count() {
            let sequence_definition = storage.sequence_for(sequence, txn.txid);
            if sequence_definition.visible_to(txn.txid)
                && in_listed(storage, sequence_definition.schema.as_str())
                && sequence_definition.owner.is_none()
                && let Err(e) = push(SchemaObject::Sequence(sequence), &mut n_objects)
            {
                return sql_fail(e);
            }
        }
        let schema_domains = match arena.alloc_slice_with(storage.domain_count(), |_| false) {
            Ok(values) => values,
            Err(_) => return sql_fail(arena_full()),
        };
        for (domain, selected) in schema_domains
            .iter_mut()
            .enumerate()
            .take(storage.domain_count())
        {
            if storage.domain_slot_visible_to(domain, txn.txid)
                && in_listed(
                    storage,
                    storage.domain_for(domain, txn.txid).schema.as_str(),
                )
            {
                *selected = true;
                if let Err(e) = push(SchemaObject::Domain(domain), &mut n_objects) {
                    return sql_fail(e);
                }
            }
        }
        for enumeration in 0..storage.enum_count() {
            if storage.enum_slot_visible_to(enumeration, txn.txid)
                && in_listed(
                    storage,
                    storage.enum_for(enumeration, txn.txid).schema.as_str(),
                )
                && let Err(e) = push(SchemaObject::Enum(enumeration), &mut n_objects)
            {
                return sql_fail(e);
            }
        }
        for composite in 0..storage.composite_count() {
            let definition = storage.composite_for(composite, txn.txid);
            if storage.composite_slot_visible_to(composite, txn.txid)
                && in_listed(storage, definition.schema.as_str())
                && let Err(error) = push(SchemaObject::Composite(composite), &mut n_objects)
            {
                return sql_fail(error);
            }
        }
        for (operator, definition) in storage.operators_visible_to(txn.txid) {
            if in_listed(storage, definition.schema.as_str())
                && let Err(error) = push(SchemaObject::Operator(operator), &mut n_objects)
            {
                return sql_fail(error);
            }
        }
        for (family, definition) in storage.operator_families_visible_to(txn.txid) {
            if in_listed(storage, definition.schema.as_str())
                && let Err(error) = push(SchemaObject::OperatorFamily(family), &mut n_objects)
            {
                return sql_fail(error);
            }
        }
        for (class, definition) in storage.operator_classes_visible_to(txn.txid) {
            if in_listed(storage, definition.schema.as_str())
                && let Err(error) = push(SchemaObject::OperatorClass(class), &mut n_objects)
            {
                return sql_fail(error);
            }
        }
        for (statistics, definition) in storage.extended_statistics_visible(txn.txid) {
            let mutable = definition.definition_for(txn.txid);
            if (in_listed(storage, mutable.schema.as_str())
                || (cascade
                    && in_listed(
                        storage,
                        storage
                            .table_def(usize::from(definition.table), txn.txid)
                            .schema
                            .as_str(),
                    )))
                && let Err(error) = push(SchemaObject::Statistics(statistics), &mut n_objects)
            {
                return sql_fail(error);
            }
        }
        if cascade {
            // Include contained domain arrays before dependent columns and queries.
            loop {
                let mut changed = false;
                for domain_slot in 0..storage.domain_count() {
                    if !storage.domain_slot_visible_to(domain_slot, txn.txid)
                        || schema_domains[domain_slot]
                    {
                        continue;
                    }
                    let domain = storage.domain_for(domain_slot, txn.txid);
                    let parent_in_schema = match selected_domain_dependency(
                        storage,
                        domain_slot,
                        schema_domains,
                        txn.txid,
                    ) {
                        Ok(parent) => parent.is_some(),
                        Err(error) => return sql_fail(error),
                    };
                    let type_in_schema =
                        match type_uses_listed_schema(storage, domain.base, txn.txid) {
                            Ok(selected) => selected,
                            Err(error) => return sql_fail(error),
                        };
                    if parent_in_schema || type_in_schema {
                        if let Err(error) = push(SchemaObject::Domain(domain_slot), &mut n_objects)
                        {
                            return sql_fail(error);
                        }
                        schema_domains[domain_slot] = true;
                        changed = true;
                    }
                }
                if !changed {
                    break;
                }
            }
            loop {
                let mut dependent = None;
                for table in 0..storage.table_count() {
                    if !storage.table_slot_visible_to(table, txn.txid) {
                        continue;
                    }
                    let def = storage.table_def(table, txn.txid);
                    if in_listed(storage, def.schema.as_str()) {
                        continue;
                    }
                    let mut uses_schema_type = false;
                    for column in def.columns() {
                        let result = match storage.bind_routine_result(
                            crate::storage::RoutineResult {
                                ctype: column.ctype,
                                user_type: column.user_type,
                            },
                            txn.txid,
                        ) {
                            Ok(result) => result,
                            Err(error) => return sql_fail(error),
                        };
                        let Some(identity) = result.user_type else {
                            continue;
                        };
                        if in_listed(storage, identity.schema.as_str()) {
                            uses_schema_type = true;
                            break;
                        }
                        let domain_slot = match storage.domain_reference_slot(identity, txn.txid) {
                            Ok(Some(slot)) => slot,
                            Ok(None) => continue,
                            Err(error) => return sql_fail(error),
                        };
                        let parent_in_schema = match selected_domain_dependency(
                            storage,
                            domain_slot,
                            schema_domains,
                            txn.txid,
                        ) {
                            Ok(parent) => parent.is_some(),
                            Err(error) => return sql_fail(error),
                        };
                        let type_in_schema = match type_uses_listed_schema(
                            storage,
                            storage.domain_for(domain_slot, txn.txid).base,
                            txn.txid,
                        ) {
                            Ok(selected) => selected,
                            Err(error) => return sql_fail(error),
                        };
                        if parent_in_schema || type_in_schema {
                            uses_schema_type = true;
                            break;
                        }
                    }
                    if !uses_schema_type {
                        continue;
                    }
                    dependent = Some(table);
                    break;
                }
                let Some(table_slot) = dependent else {
                    break;
                };
                let def = storage.table_def(table_slot, txn.txid);
                let (table_schema, table) = (def.schema, def.name);
                let mut columns = [SqlName::EMPTY; MAX_COLUMNS];
                let mut column_count = 0;
                for column in def.columns() {
                    let result = match storage.bind_routine_result(
                        crate::storage::RoutineResult {
                            ctype: column.ctype,
                            user_type: column.user_type,
                        },
                        txn.txid,
                    ) {
                        Ok(result) => result,
                        Err(error) => return sql_fail(error),
                    };
                    let directly_in_schema = result
                        .user_type
                        .is_some_and(|identity| in_listed(storage, identity.schema.as_str()));
                    let domain_slot = match result
                        .user_type
                        .map(|identity| storage.domain_reference_slot(identity, txn.txid))
                        .transpose()
                    {
                        Ok(slot) => slot.flatten(),
                        Err(error) => return sql_fail(error),
                    };
                    let through_domain = if let Some(domain_slot) = domain_slot {
                        let parent_in_schema = match selected_domain_dependency(
                            storage,
                            domain_slot,
                            schema_domains,
                            txn.txid,
                        ) {
                            Ok(parent) => parent.is_some(),
                            Err(error) => return sql_fail(error),
                        };
                        let type_in_schema = match type_uses_listed_schema(
                            storage,
                            storage.domain_for(domain_slot, txn.txid).base,
                            txn.txid,
                        ) {
                            Ok(selected) => selected,
                            Err(error) => return sql_fail(error),
                        };
                        parent_in_schema || type_in_schema
                    } else {
                        false
                    };
                    if directly_in_schema || through_domain {
                        columns[column_count] = column.name;
                        column_count += 1;
                    }
                }
                drop(def);
                if let Err(error) = cascade_drop_type_column(
                    storage,
                    wal,
                    txn,
                    scratch,
                    table_schema,
                    table,
                    &columns[..column_count],
                    arena,
                    seq_session,
                    responder,
                ) {
                    return sql_fail(error);
                }
            }
            // Stored queries outside the dropped schemas follow their resolved
            // dependencies transitively, exactly as pg_depend drives CASCADE.
            if n_objects > 0 {
                let closure =
                    stored_query_dependent_closure(storage, txn.txid, arena, |dependency| {
                        in_listed(storage, dependency.schema.as_str())
                            || (dependency.class == crate::storage::DependencyClass::Domain
                                && schema_domains[usize::from(dependency.slot)])
                    });
                let StoredDependencyClosure {
                    views: dependent_views,
                    matviews: dependent_matviews,
                    routines: dependent_routines,
                    rules: _dependent_rules,
                } = match closure {
                    Ok(closure) => closure,
                    Err(error) => return sql_fail(error),
                };
                for (view_slot, &is_dependent) in dependent_views
                    .iter()
                    .enumerate()
                    .take(storage.view_count())
                {
                    let view = storage.view(view_slot);
                    if is_dependent
                        && view.visible_to(txn.txid)
                        && !in_listed(storage, view.schema.as_str())
                        && let Err(error) = push(SchemaObject::View(view_slot), &mut n_objects)
                    {
                        return sql_fail(error);
                    }
                }
                for (matview_slot, &is_dependent) in dependent_matviews
                    .iter()
                    .enumerate()
                    .take(storage.matview_count())
                {
                    if !is_dependent || !storage.matview(matview_slot).visible_to(txn.txid) {
                        continue;
                    }
                    let table = storage.matview_table(matview_slot);
                    let definition = storage.table_def(table, txn.txid);
                    if in_listed(storage, definition.schema.as_str()) {
                        continue;
                    }
                    if let Err(error) = push(
                        SchemaObject::Matview {
                            table,
                            catalog: matview_slot,
                        },
                        &mut n_objects,
                    ) {
                        return sql_fail(error);
                    }
                }
                for (routine_slot, &is_dependent) in dependent_routines
                    .iter()
                    .enumerate()
                    .take(storage.routine_count())
                {
                    let routine = storage.routine_for(routine_slot, txn.txid);
                    if is_dependent
                        && storage
                            .routine_identity_for(routine_slot, txn.txid)
                            .is_some()
                        && !in_listed(storage, routine.schema_for(txn.txid).as_str())
                        && let Err(error) =
                            push(SchemaObject::Routine(routine_slot), &mut n_objects)
                    {
                        return sql_fail(error);
                    }
                }
                for policy_slot in 0..storage.policy_count() {
                    let policy = storage.policy(policy_slot);
                    if !policy.visible_to(txn.txid)
                        || in_listed(
                            storage,
                            storage
                                .table_def(usize::from(policy.table), txn.txid)
                                .schema
                                .as_str(),
                        )
                    {
                        continue;
                    }
                    let dependencies = storage.policy_dependencies(policy_slot, txn.txid);
                    let direct_dependency = dependencies
                        .entries()
                        .iter()
                        .find(|dependency| {
                            in_listed(storage, dependency.schema.as_str())
                                || (dependency.class == crate::storage::DependencyClass::Domain
                                    && schema_domains[usize::from(dependency.slot)])
                        })
                        .copied();
                    if (direct_dependency.is_some()
                        || policy_depends_on_selected_stored_query(
                            storage,
                            txn.txid,
                            dependencies.view(),
                            dependent_views,
                            dependent_matviews,
                            dependent_routines,
                        ))
                        && let Err(error) = push(
                            SchemaObject::Policy {
                                slot: policy_slot,
                                root_schema: direct_dependency
                                    .map(|dependency| dependency.schema)
                                    .unwrap_or_else(|| {
                                        selected_schema
                                            .expect("dependent object has a selected schema")
                                    }),
                                root_class: direct_dependency.map(|dependency| dependency.class),
                                root_slot: direct_dependency
                                    .map_or(usize::MAX, |dependency| usize::from(dependency.slot)),
                            },
                            &mut n_objects,
                        )
                    {
                        return sql_fail(error);
                    }
                }
            }
        }
        if !cascade && n_objects > 0 {
            let StoredDependencyClosure {
                views: dependent_views,
                matviews: dependent_matviews,
                routines: dependent_routines,
                rules: _dependent_rules,
            } = match stored_query_dependent_closure(storage, txn.txid, arena, |dependency| {
                in_listed(storage, dependency.schema.as_str())
                    || (dependency.class == crate::storage::DependencyClass::Domain
                        && schema_domains[usize::from(dependency.slot)])
            }) {
                Ok(closure) => closure,
                Err(error) => return sql_fail(error),
            };
            for policy_slot in 0..storage.policy_count() {
                let policy = storage.policy(policy_slot);
                if !policy.visible_to(txn.txid)
                    || in_listed(
                        storage,
                        storage
                            .table_def(usize::from(policy.table), txn.txid)
                            .schema
                            .as_str(),
                    )
                {
                    continue;
                }
                let dependencies = storage.policy_dependencies(policy_slot, txn.txid);
                let direct_dependency = dependencies
                    .entries()
                    .iter()
                    .find(|dependency| {
                        in_listed(storage, dependency.schema.as_str())
                            || (dependency.class == crate::storage::DependencyClass::Domain
                                && schema_domains[usize::from(dependency.slot)])
                    })
                    .copied();
                if (direct_dependency.is_some()
                    || policy_depends_on_selected_stored_query(
                        storage,
                        txn.txid,
                        dependencies.view(),
                        dependent_views,
                        dependent_matviews,
                        dependent_routines,
                    ))
                    && let Err(error) = push(
                        SchemaObject::Policy {
                            slot: policy_slot,
                            root_schema: direct_dependency
                                .map(|dependency| dependency.schema)
                                .unwrap_or_else(|| {
                                    selected_schema.expect("dependent object has a selected schema")
                                }),
                            root_class: direct_dependency.map(|dependency| dependency.class),
                            root_slot: direct_dependency
                                .map_or(usize::MAX, |dependency| usize::from(dependency.slot)),
                        },
                        &mut n_objects,
                    )
                {
                    return sql_fail(error);
                }
            }
        }
        // Inbound foreign keys: a surviving table referencing a dropped one loses
        // the constraint (PostgreSQL drops the constraint, not the table).
        for t in 0..storage.table_count() {
            let def = storage.table_def(t, txn.txid);
            if !storage.table_slot_visible_to(t, txn.txid)
                || in_listed(storage, def.schema.as_str())
            {
                continue;
            }
            for f in 0..def.n_fkeys {
                if in_listed(storage, def.fkeys[f].parent_schema.as_str())
                    && let Err(e) = push(
                        SchemaObject::InboundFk {
                            table: t,
                            fk_index: f,
                        },
                        &mut n_objects,
                    )
                {
                    return sql_fail(e);
                }
            }
        }
        // PostgreSQL walks the listed schemas in reverse, and reports each
        // schema's dependents in OID (creation) order; a severed constraint
        // sorts with its child table, after it.
        let schema_rank = |storage: &Storage, schema: &str| -> usize {
            if temporary.is_some_and(|selected| selected.as_str() == schema) {
                return 1;
            }
            slots[..n_slots]
                .iter()
                .position(|&slot| storage.schema_def_for(slot, txn.txid).name.as_str() == schema)
                .map(|p| n_slots - p)
                .unwrap_or(0)
        };
        let sort_key = |storage: &Storage, o: &SchemaObject| -> (usize, u64, u8) {
            match o {
                SchemaObject::Table(t) => {
                    let (schema, created_at) = {
                        let def = storage.table_def(*t, txn.txid);
                        (def.schema, def.identity().created_at)
                    };
                    (schema_rank(storage, schema.as_str()), created_at, 0)
                }
                SchemaObject::View(v) => {
                    let view = storage.view(*v);
                    (
                        schema_rank(storage, view.schema.as_str()),
                        view.created_at,
                        0,
                    )
                }
                SchemaObject::Routine(routine) => {
                    let routine = storage.routine_for(*routine, txn.txid);
                    (
                        schema_rank(storage, routine.schema_for(txn.txid).as_str()),
                        routine.created_at,
                        0,
                    )
                }
                SchemaObject::Collation(slot) => {
                    let state = storage.collation(*slot);
                    let definition = state.definition_for(txn.txid);
                    (
                        schema_rank(storage, definition.schema.as_str()),
                        state.created_at,
                        0,
                    )
                }
                SchemaObject::Conversion(slot) => {
                    let state = storage.conversion(*slot);
                    let definition = state.definition_for(txn.txid);
                    (
                        schema_rank(storage, definition.schema.as_str()),
                        state.created_at,
                        0,
                    )
                }
                SchemaObject::TextSearch(slot) => {
                    let state = storage.text_search_object(*slot);
                    let definition = state.definition_for(txn.txid);
                    (
                        schema_rank(storage, definition.schema().as_str()),
                        state.created_at,
                        0,
                    )
                }
                SchemaObject::Matview { table, .. } => {
                    let (schema, created_at) = {
                        let def = storage.table_def(*table, txn.txid);
                        (def.schema, def.identity().created_at)
                    };
                    (schema_rank(storage, schema.as_str()), created_at, 0)
                }
                SchemaObject::Sequence(sequence) => {
                    let sequence = storage.sequence_for(*sequence, txn.txid);
                    (
                        schema_rank(storage, sequence.schema.as_str()),
                        sequence.created_at,
                        0,
                    )
                }
                SchemaObject::Domain(domain) => {
                    let domain = storage.domain_for(*domain, txn.txid);
                    (
                        schema_rank(storage, domain.schema.as_str()),
                        domain.created_at,
                        0,
                    )
                }
                SchemaObject::Enum(enumeration) => {
                    let enumeration = storage.enum_for(*enumeration, txn.txid);
                    (
                        schema_rank(storage, enumeration.schema.as_str()),
                        enumeration.created_at,
                        0,
                    )
                }
                SchemaObject::Composite(composite) => {
                    let definition = storage.composite_for(*composite, txn.txid);
                    (
                        schema_rank(storage, definition.schema.as_str()),
                        definition.created_at,
                        0,
                    )
                }
                SchemaObject::Operator(operator) => {
                    let definition = storage.operator_for(*operator, txn.txid);
                    (
                        schema_rank(storage, definition.schema.as_str()),
                        storage.operator(*operator).created_at,
                        0,
                    )
                }
                SchemaObject::OperatorFamily(family) => {
                    let definition = storage.operator_family_for(*family, txn.txid);
                    (
                        schema_rank(storage, definition.schema.as_str()),
                        storage.operator_family(*family).created_at,
                        0,
                    )
                }
                SchemaObject::OperatorClass(class) => {
                    let definition = storage.operator_class_for(*class, txn.txid);
                    (
                        schema_rank(storage, definition.schema.as_str()),
                        storage.operator_class(*class).created_at,
                        0,
                    )
                }
                SchemaObject::Statistics(statistics) => {
                    let definition = storage.extended_statistics(*statistics);
                    let mutable = definition.definition_for(txn.txid);
                    (
                        schema_rank(storage, mutable.schema.as_str()),
                        definition.created_at,
                        0,
                    )
                }
                SchemaObject::Policy {
                    slot, root_schema, ..
                } => {
                    let policy = storage.policy(*slot);
                    (
                        schema_rank(storage, root_schema.as_str()),
                        policy.created_at,
                        0,
                    )
                }
                SchemaObject::InboundFk { table, fk_index } => {
                    let (schema, created_at) = {
                        let def = storage.table_def(*table, txn.txid);
                        (
                            def.fkeys[*fk_index].parent_schema,
                            def.identity().created_at,
                        )
                    };
                    (schema_rank(storage, schema.as_str()), created_at, 1)
                }
            }
        };
        {
            let slice = &mut objects[..n_objects];
            slice.sort_unstable_by_key(|o| sort_key(storage, o.as_ref().expect("filled")));
        }
        // Renders one swept object the way PostgreSQL's dependency report does:
        // qualified only when its schema is not on the current search path.
        let in_path = |storage: &Storage, schema: &str| {
            storage.path().entries().iter().any(|e| match e {
                crate::storage::PathEntry::Schema(slot) => {
                    storage
                        .schema_def_for(*slot as usize, txn.txid)
                        .name
                        .as_str()
                        == schema
                }
                crate::storage::PathEntry::Catalog => schema == "pg_catalog",
                crate::storage::PathEntry::InformationSchema => schema == "information_schema",
                crate::storage::PathEntry::Toast => schema == "pg_toast",
            })
        };
        let write_rel = |out: &mut crate::util::StackStr<192>, schema: &SqlName, name: &SqlName| {
            if in_path(storage, schema.as_str()) {
                write_identifier(out, name.as_str());
            } else {
                write_identifier(out, schema.as_str());
                let _ = out.write_char('.');
                write_identifier(out, name.as_str());
            }
        };
        let describe = |storage: &Storage,
                        o: &SchemaObject,
                        out: &mut crate::util::StackStr<192>|
         -> Result<(), SqlError> {
            match o {
                SchemaObject::Table(t) => {
                    let def = storage.table_def(*t, txn.txid);
                    let _ = write!(
                        out,
                        "{}",
                        if def.kind == crate::storage::TableKind::Foreign {
                            "foreign table "
                        } else {
                            "table "
                        }
                    );
                    write_rel(out, &def.schema, &def.name);
                }
                SchemaObject::View(v) => {
                    let view = storage.view(*v);
                    let _ = write!(out, "view ");
                    write_rel(out, &view.schema, &view.name);
                }
                SchemaObject::Routine(slot) => {
                    let routine = storage.routine_for(*slot, txn.txid);
                    // PostgreSQL's getObjectDescription names every routine a function.
                    let _ = write!(out, "function ");
                    write_rel(
                        out,
                        &routine.schema_for(txn.txid),
                        &routine.name_for(txn.txid),
                    );
                    let signature = routine_dependency_suffix(storage, txn.txid, &routine)?;
                    let _ = write!(out, "{}", signature.as_str());
                }
                SchemaObject::Collation(slot) => {
                    let definition = storage.collation(*slot).definition_for(txn.txid);
                    let _ = write!(out, "collation ");
                    write_rel(out, &definition.schema, &definition.name);
                }
                SchemaObject::Conversion(slot) => {
                    let definition = storage.conversion(*slot).definition_for(txn.txid);
                    let _ = write!(out, "conversion ");
                    write_rel(out, &definition.schema, &definition.name);
                }
                SchemaObject::TextSearch(slot) => {
                    let definition = storage.text_search_object(*slot).definition_for(txn.txid);
                    let _ = write!(out, "{} ", definition.kind().noun());
                    write_rel(out, &definition.schema(), &definition.name());
                }
                SchemaObject::Matview { table, .. } => {
                    let def = storage.table_def(*table, txn.txid);
                    let _ = write!(out, "materialized view ");
                    write_rel(out, &def.schema, &def.name);
                }
                SchemaObject::Sequence(sequence) => {
                    let sequence = storage.sequence_for(*sequence, txn.txid);
                    let _ = write!(out, "sequence ");
                    write_rel(out, &sequence.schema, &sequence.name);
                }
                SchemaObject::Domain(domain) => {
                    let domain = storage.domain_for(*domain, txn.txid);
                    let _ = write!(out, "type ");
                    write_rel(out, &domain.schema, &domain.name);
                }
                SchemaObject::Enum(enumeration) => {
                    let enumeration = storage.enum_for(*enumeration, txn.txid);
                    let _ = write!(out, "type ");
                    write_rel(out, &enumeration.schema, &enumeration.name);
                }
                SchemaObject::Composite(composite) => {
                    let definition = storage.composite_for(*composite, txn.txid);
                    let _ = write!(out, "type ");
                    write_rel(out, &definition.schema, &definition.name);
                }
                SchemaObject::Operator(operator) => {
                    let definition = storage.operator_for(*operator, txn.txid);
                    let _ = write!(out, "operator ");
                    if !in_path(storage, definition.schema.as_str()) {
                        write_identifier(out, definition.schema.as_str());
                        let _ = out.write_char('.');
                    }
                    let _ = out.write_str(definition.name.as_str());
                    let signature = dependency_signature_suffix(
                        storage,
                        txn.txid,
                        "operator",
                        [definition.signature.left, definition.signature.right],
                    )?;
                    let _ = out.write_str(signature.as_str());
                }
                SchemaObject::OperatorFamily(family) => {
                    let definition = storage.operator_family_for(*family, txn.txid);
                    let _ = write!(out, "operator family ");
                    write_rel(out, &definition.schema, &definition.name);
                    // User-defined operator classes and families are btree only.
                    let _ = write!(out, " for access method btree");
                }
                SchemaObject::OperatorClass(class) => {
                    let definition = storage.operator_class_for(*class, txn.txid);
                    let _ = write!(out, "operator class ");
                    write_rel(out, &definition.schema, &definition.name);
                    // User-defined operator classes and families are btree only.
                    let _ = write!(out, " for access method btree");
                }
                SchemaObject::Statistics(statistics) => {
                    let definition = storage
                        .extended_statistics(*statistics)
                        .definition_for(txn.txid);
                    let _ = write!(out, "statistics object ");
                    write_rel(out, &definition.schema, &definition.name);
                }
                SchemaObject::Policy { slot, .. } => {
                    let policy = storage.policy(*slot);
                    let table = storage.table_def(usize::from(policy.table), txn.txid);
                    let _ = write!(out, "policy {} on table ", policy.name.as_str());
                    write_rel(out, &table.schema, &table.name);
                }
                SchemaObject::InboundFk { table, fk_index } => {
                    let def = storage.table_def(*table, txn.txid);
                    let _ = write!(
                        out,
                        "constraint {} on table ",
                        def.fkeys[*fk_index].name.as_str()
                    );
                    write_rel(out, &def.schema, &def.name);
                }
            }
            Ok(())
        };
        let independently_reported = |object: &SchemaObject| match object {
            // PostgreSQL reports the owning table and suppresses its internal
            // statistics dependents. A statistics object on a surviving table is
            // still reported independently.
            SchemaObject::Statistics(statistics) => {
                let table = usize::from(storage.extended_statistics(*statistics).table);
                !objects[..n_objects].iter().flatten().any(|candidate| {
                    matches!(
                        candidate,
                        SchemaObject::Table(selected) if *selected == table
                    ) || matches!(
                        candidate,
                        SchemaObject::Matview { table: selected, .. } if *selected == table
                    )
                })
            }
            _ => true,
        };
        let reported_object_count = objects[..n_objects]
            .iter()
            .flatten()
            .filter(|object| independently_reported(object))
            .count();
        if reported_object_count > 0 && !cascade {
            let first = slots[0];
            let mut detail =
                crate::util::StackStr::<{ crate::sql::eval::MAX_DIAGNOSTIC_DETAIL_BYTES }>::new();
            for (i, o) in objects[..n_objects]
                .iter()
                .flatten()
                .filter(|object| independently_reported(object))
                .enumerate()
            {
                let mut line = crate::util::StackStr::<192>::new();
                if let Err(error) = describe(storage, o, &mut line) {
                    return sql_fail(error);
                }
                let schema = match o {
                    SchemaObject::Table(t) => storage.table_def(*t, txn.txid).schema,
                    SchemaObject::View(v) => storage.view(*v).schema,
                    SchemaObject::Routine(routine) => {
                        storage.routine_for(*routine, txn.txid).schema_for(txn.txid)
                    }
                    SchemaObject::Collation(slot) => {
                        storage.collation(*slot).definition_for(txn.txid).schema
                    }
                    SchemaObject::Conversion(slot) => {
                        storage.conversion(*slot).definition_for(txn.txid).schema
                    }
                    SchemaObject::TextSearch(slot) => storage
                        .text_search_object(*slot)
                        .definition_for(txn.txid)
                        .schema(),
                    SchemaObject::Matview { table, .. } => {
                        storage.table_def(*table, txn.txid).schema
                    }
                    SchemaObject::Sequence(sequence) => {
                        storage.sequence_for(*sequence, txn.txid).schema
                    }
                    SchemaObject::Domain(domain) => storage.domain_for(*domain, txn.txid).schema,
                    SchemaObject::Enum(enumeration) => {
                        storage.enum_for(*enumeration, txn.txid).schema
                    }
                    SchemaObject::Composite(composite) => {
                        storage.composite_for(*composite, txn.txid).schema
                    }
                    SchemaObject::Operator(operator) => {
                        storage.operator_for(*operator, txn.txid).schema
                    }
                    SchemaObject::OperatorFamily(family) => {
                        storage.operator_family_for(*family, txn.txid).schema
                    }
                    SchemaObject::OperatorClass(class) => {
                        storage.operator_class_for(*class, txn.txid).schema
                    }
                    SchemaObject::Statistics(statistics) => {
                        storage
                            .extended_statistics(*statistics)
                            .definition_for(txn.txid)
                            .schema
                    }
                    SchemaObject::Policy { root_schema, .. } => *root_schema,
                    SchemaObject::InboundFk { table, fk_index } => {
                        storage.table_def(*table, txn.txid).fkeys[*fk_index].parent_schema
                    }
                };
                if let SchemaObject::Policy {
                    root_class: Some(root_class),
                    root_slot,
                    ..
                } = o
                {
                    let mut dependency = crate::util::StackStr::<192>::new();
                    match root_class {
                        crate::storage::DependencyClass::Table => {
                            let definition = storage.table_def(*root_slot, txn.txid);
                            let kind = if storage
                                .matview_slot(
                                    definition.schema.as_str(),
                                    definition.name.as_str(),
                                    txn.txid,
                                )
                                .is_some()
                            {
                                "materialized view"
                            } else {
                                "table"
                            };
                            let _ = write!(dependency, "{kind} ");
                            write_rel(&mut dependency, &definition.schema, &definition.name);
                        }
                        crate::storage::DependencyClass::View => {
                            let view = storage.view(*root_slot);
                            let _ = write!(dependency, "view ");
                            write_rel(&mut dependency, &view.schema, &view.name);
                        }
                        crate::storage::DependencyClass::Sequence => {
                            let sequence = storage.sequence_for(*root_slot, txn.txid);
                            let _ = write!(dependency, "sequence ");
                            write_rel(&mut dependency, &sequence.schema, &sequence.name);
                        }
                        crate::storage::DependencyClass::Domain => {
                            let domain = storage.domain_for(*root_slot, txn.txid);
                            let _ = write!(dependency, "type ");
                            write_rel(&mut dependency, &domain.schema, &domain.name);
                        }
                        crate::storage::DependencyClass::Enum => {
                            let enumeration = storage.enum_for(*root_slot, txn.txid);
                            let _ = write!(dependency, "type ");
                            write_rel(&mut dependency, &enumeration.schema, &enumeration.name);
                        }
                        crate::storage::DependencyClass::Composite => {
                            let composite = storage.composite(*root_slot);
                            let _ = write!(dependency, "type ");
                            write_rel(&mut dependency, &composite.schema, &composite.name);
                        }
                        crate::storage::DependencyClass::Routine => {
                            let routine = storage.routine(*root_slot);
                            let _ = write!(dependency, "function ");
                            write_rel(
                                &mut dependency,
                                &routine.schema_for(txn.txid),
                                &routine.name_for(txn.txid),
                            );
                        }
                        crate::storage::DependencyClass::Operator => {
                            let operator = storage.operator_for(*root_slot, txn.txid);
                            let _ = write!(dependency, "operator ");
                            write_rel(&mut dependency, &operator.schema, &operator.name);
                        }
                        crate::storage::DependencyClass::Collation => {
                            let collation = storage.collation(*root_slot).definition_for(txn.txid);
                            let _ = write!(dependency, "collation ");
                            write_rel(&mut dependency, &collation.schema, &collation.name);
                        }
                        crate::storage::DependencyClass::TextSearchConfiguration => {
                            let configuration = storage
                                .text_search_object(*root_slot)
                                .definition_for(txn.txid);
                            let _ = write!(dependency, "text search configuration ");
                            write_rel(
                                &mut dependency,
                                &configuration.schema(),
                                &configuration.name(),
                            );
                        }
                    }
                    let _ = write!(
                        detail,
                        "{}{} depends on {}",
                        if i > 0 { "\n" } else { "" },
                        line.as_str(),
                        dependency.as_str(),
                    );
                } else {
                    let _ = write!(
                        detail,
                        "{}{} depends on schema {}",
                        if i > 0 { "\n" } else { "" },
                        line.as_str(),
                        schema.as_str(),
                    );
                }
            }
            let mut hint = crate::util::StackStr::<128>::new();
            let _ = write!(
                hint,
                "Use DROP ... CASCADE to drop the dependent objects too."
            );
            crate::sql::eval::stash_diagnostic(Some(detail), Some(hint));
            return sql_fail(sql_err!(
                crate::sql::eval::sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
                "cannot drop schema {} because other objects depend on it",
                storage.schema_def_for(first, txn.txid).name.as_str()
            ));
        }
        let view_locks = match arena.alloc_slice_with(storage.view_count(), |_| false) {
            Ok(locks) => locks,
            Err(_) => return sql_fail(arena_full()),
        };
        for object in objects[..n_objects].iter().flatten() {
            let requested = match object {
                SchemaObject::Table(table)
                | SchemaObject::Matview { table, .. }
                | SchemaObject::InboundFk { table, .. } => {
                    Some((*table, crate::sql::ast::TableLockMode::AccessExclusive))
                }
                SchemaObject::View(view) => {
                    view_locks[*view] = true;
                    None
                }
                SchemaObject::Policy { slot, .. } => {
                    let table = usize::from(storage.policy(*slot).table);
                    Some((table, crate::sql::ast::TableLockMode::ShareRowExclusive))
                }
                _ => None,
            };
            if let Some((table, mode)) = requested {
                let Some(selection) = table_locks[table].as_mut() else {
                    return sql_fail(sql_err!(
                        sqlstate::SERIALIZATION_FAILURE,
                        "schema drop selected a table without its original definition source"
                    ));
                };
                if selection.mode.is_none()
                    || mode == crate::sql::ast::TableLockMode::AccessExclusive
                {
                    selection.mode = Some(mode);
                }
            }
        }
        // Resolve all waits before cascade notices, journal writes or catalog edits.
        for (table, selection) in table_locks.iter().copied().enumerate() {
            let Some(TableDropSelection {
                source,
                mode: Some(mode),
            }) = selection
            else {
                continue;
            };
            if let Err(error) = storage
                .lock_table(txn.txid, table, mode, false)
                .and_then(|()| source.validate(storage))
            {
                return sql_fail(error);
            }
        }
        for (view, selected) in view_locks.iter().copied().enumerate() {
            if selected
                && let Err(error) = storage.lock_object(
                    txn.txid,
                    crate::storage::ObjectLockTarget::View(view),
                    crate::sql::ast::TableLockMode::AccessExclusive,
                    false,
                )
            {
                return sql_fail(error);
            }
        }
        if temporary.is_none() && reported_object_count > 0 {
            let mut detail =
                crate::util::StackStr::<{ crate::sql::eval::MAX_DIAGNOSTIC_DETAIL_BYTES }>::new();
            for (i, o) in objects[..n_objects]
                .iter()
                .flatten()
                .filter(|object| independently_reported(object))
                .enumerate()
            {
                let mut line = crate::util::StackStr::<192>::new();
                if let Err(error) = describe(storage, o, &mut line) {
                    return sql_fail(error);
                }
                let _ = write!(
                    detail,
                    "{}drop cascades to {}",
                    if i > 0 { "\n" } else { "" },
                    line.as_str()
                );
            }
            if let Err(error) = dependency_report::send_cascade_lines(
                responder,
                detail.as_str(),
                reported_object_count,
            ) {
                return sql_fail(error);
            }
        }
        let owned_sequence_undo = objects[..n_objects]
            .iter()
            .flatten()
            .filter_map(|object| match object {
                SchemaObject::Table(table) => Some((*storage.table_def(*table, txn.txid)).clone()),
                _ => None,
            })
            .map(|table| {
                (0..storage.sequence_count())
                    .filter(|sequence_slot| {
                        let sequence = storage.sequence_for(*sequence_slot, txn.txid);
                        sequence.visible_to(txn.txid)
                            && matches!(
                                sequence.owner,
                                Some(owner)
                                    if owner.table_schema == table.schema
                                        && owner.table == table.name
                            )
                    })
                    .count()
            })
            .sum::<usize>();
        let table_trigger_undo = storage
            .triggers_with_slots_visible_to(txn.txid)
            .filter(|(_, trigger)| {
                matches!(
                    trigger.target,
                    crate::storage::TriggerTarget::Table(table)
                        if objects[..n_objects].iter().flatten().any(|object| {
                            matches!(object, SchemaObject::Table(selected) if *selected == usize::from(table))
                        })
                )
            })
            .count();
        let routine_trigger_undo = storage
            .triggers_with_slots_visible_to(txn.txid)
            .filter(|(_, trigger)| {
                objects[..n_objects].iter().flatten().any(|object| {
                    matches!(
                        object,
                        SchemaObject::Routine(routine)
                            if trigger.function.routine() == Some(*routine)
                    )
                })
            })
            .count();
        let undo_needed = n_objects
            + objects[..n_objects]
                .iter()
                .flatten()
                .filter(|object| matches!(object, SchemaObject::Matview { .. }))
                .count()
            + owned_sequence_undo
            + table_trigger_undo
            + routine_trigger_undo
            + n_slots;
        if txn.ddl().len() + undo_needed > txn.ddl_capacity() {
            return sql_fail(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "DROP SCHEMA needs {} DDL undo entries but only {} remain",
                undo_needed,
                txn.ddl_capacity() - txn.ddl().len()
            ));
        }
        // Persist drops while every referenced type and routine can still be
        // resolved. The notice above retains PostgreSQL's creation order.
        let drop_rank = |object: &SchemaObject| match object {
            SchemaObject::OperatorClass(_) => 0,
            SchemaObject::OperatorFamily(_) => 1,
            SchemaObject::Operator(_) => 2,
            SchemaObject::Domain(_) | SchemaObject::Composite(_) => 4,
            SchemaObject::Enum(_) => 5,
            _ => 3,
        };
        objects[..n_objects]
            .sort_unstable_by_key(|object| drop_rank(object.as_ref().expect("filled")));
        let no_views = match dependency_flags(arena, storage.view_count()) {
            Ok(values) => values,
            Err(error) => return sql_fail(error),
        };
        let no_matviews = match dependency_flags(arena, storage.matview_count()) {
            Ok(values) => values,
            Err(error) => return sql_fail(error),
        };
        let selected_routines = match dependency_flags(arena, storage.routine_count()) {
            Ok(values) => values,
            Err(error) => return sql_fail(error),
        };
        let no_rules = match dependency_flags(arena, storage.rule_count()) {
            Ok(values) => values,
            Err(error) => return sql_fail(error),
        };
        for o in objects[..n_objects].iter().flatten() {
            match o {
                SchemaObject::InboundFk { table, fk_index } => {
                    let (edit_target, def) = storage.select_table_definition(*table, txn.txid);
                    let fk_name = def.fkeys[*fk_index].name;
                    let (schema, tname) = (def.schema, def.name);
                    let lsn = storage.bump_lsn();
                    if let Err(e) = wal.stage_reserved(
                        txn.txid,
                        lsn,
                        &WalOp::DropTableFk {
                            schema: schema.as_str(),
                            table: tname.as_str(),
                            fk_name: fk_name.as_str(),
                        },
                    ) {
                        return sql_fail(e);
                    }
                    let mut updated = TableDefBuilder::from_definition(&def);
                    if !drop_named_constraint(&mut updated, fk_name.as_str()) {
                        continue;
                    }
                    let mut identity_mapping = [None; MAX_COLUMNS];
                    for (column, target) in
                        identity_mapping.iter_mut().enumerate().take(def.n_columns)
                    {
                        *target = Some(def.columns()[column].name);
                    }
                    if let Err(error) = txn.write_table_definition(
                        storage,
                        edit_target,
                        updated,
                        &identity_mapping,
                        false,
                        crate::storage::ColumnSet::EMPTY,
                    ) {
                        return sql_fail(error);
                    }
                }
                SchemaObject::View(v) => {
                    let (schema, vname, temporary) = {
                        let view = storage.view(*v);
                        (
                            view.schema_for(txn.txid),
                            view.name_for(txn.txid),
                            view.persistence == crate::storage::RelationPersistence::Temporary,
                        )
                    };
                    if let Err(error) = drop_row_type_users(
                        storage,
                        wal,
                        txn,
                        ("view", vname),
                        crate::storage::RowTypeRelation::View(*v),
                        &[],
                        &dropped_schema,
                        true,
                        RowTypeColumnCascade {
                            scratch: &mut *scratch,
                            seq_session,
                        },
                        arena,
                        responder,
                    ) {
                        return sql_fail(error);
                    }
                    if !temporary {
                        let lsn = storage.bump_lsn();
                        if let Err(e) = wal.stage_reserved(
                            txn.txid,
                            lsn,
                            &WalOp::DropView {
                                schema: schema.as_str(),
                                name: vname.as_str(),
                            },
                        ) {
                            return sql_fail(e);
                        }
                    }
                    let dropped = match storage.drop_view(schema.as_str(), vname.as_str(), txn.txid)
                    {
                        Ok(d) => d,
                        Err(e) => return sql_fail(e),
                    };
                    if let Some(undo) = dropped
                        && let Err(error) =
                            txn.record_ddl(storage, super::txn::DdlUndo::ViewDropped(undo))
                    {
                        storage.rollback_view_drop(undo);
                        return sql_fail(error);
                    }
                }
                SchemaObject::Routine(routine) => {
                    if storage.routine_identity_for(*routine, txn.txid).is_some() {
                        let routine_oid =
                            crate::storage::routine_oid(&storage.routine_for(*routine, txn.txid));
                        if let Err(error) = cascade_routine_cast_operator_dependents(
                            storage,
                            wal,
                            txn,
                            &mut *scratch,
                            seq_session,
                            &mut *responder,
                            routine_oid,
                            arena,
                        ) {
                            return sql_fail(error);
                        }
                    }
                    selected_routines.fill(false);
                    selected_routines[*routine] = true;
                    if let Err(error) = drop_selected_stored_queries(
                        storage,
                        wal,
                        txn,
                        no_views,
                        no_matviews,
                        selected_routines,
                        no_rules,
                        ViewRowTypeColumnCascade {
                            columns: RowTypeColumnCascade {
                                scratch: &mut *scratch,
                                seq_session,
                            },
                            arena,
                            responder: &mut *responder,
                        },
                    ) {
                        return sql_fail(error);
                    }
                }
                SchemaObject::Collation(slot) => {
                    if !storage.collation(*slot).visible_to(txn.txid) {
                        continue;
                    }
                    let definition = storage.collation(*slot).definition_for(txn.txid);
                    let Some(owner) = storage.role_slot_by_oid(definition.owner, txn.txid) else {
                        return sql_fail(sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "collation owner does not exist"
                        ));
                    };
                    let owner = storage.role_name(owner, txn.txid);
                    let qualified = QualName {
                        schema: Some(definition.schema.as_str()),
                        name: definition.name.as_str(),
                    };
                    let owner = match storage.capture_role(owner.as_str(), txn.txid) {
                        Ok(role) => crate::storage::SessionIdentity::bound(role),
                        Err(error) => return sql_fail(error),
                    };
                    let outcome = run_as_role(owner, || {
                        responder.without_command_complete(|responder| {
                            drop_collation(
                                storage,
                                &mut *wal,
                                txn,
                                scratch,
                                &qualified,
                                false,
                                true,
                                arena,
                                seq_session,
                                responder,
                            )
                        })
                    });
                    match outcome {
                        Ok(Ok(())) => {}
                        Ok(Err(error)) => return sql_fail(error),
                        Err(error) => return Err(error),
                    }
                }
                SchemaObject::Conversion(slot) => {
                    if !storage.conversion(*slot).visible_to(txn.txid) {
                        continue;
                    }
                    let definition = storage.conversion(*slot).definition_for(txn.txid);
                    let Some(owner) = storage.role_slot_by_oid(definition.owner, txn.txid) else {
                        return sql_fail(sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "conversion owner does not exist"
                        ));
                    };
                    let owner = storage.role_name(owner, txn.txid);
                    let qualified = QualName {
                        schema: Some(definition.schema.as_str()),
                        name: definition.name.as_str(),
                    };
                    let owner = match storage.capture_role(owner.as_str(), txn.txid) {
                        Ok(role) => crate::storage::SessionIdentity::bound(role),
                        Err(error) => return sql_fail(error),
                    };
                    let outcome = run_as_role(owner, || {
                        responder.without_command_complete(|responder| {
                            drop_conversion(
                                storage, &mut *wal, txn, &qualified, false, true, responder,
                            )
                        })
                    });
                    match outcome {
                        Ok(Ok(())) => {}
                        Ok(Err(error)) => return sql_fail(error),
                        Err(error) => return Err(error),
                    }
                }
                SchemaObject::TextSearch(slot) => {
                    if storage.text_search_object(*slot).visible_to(txn.txid)
                        && let Err(error) = drop_text_search_slot(
                            storage,
                            wal,
                            txn,
                            &mut *scratch,
                            seq_session,
                            &mut *responder,
                            *slot,
                            true,
                            arena,
                        )
                    {
                        return sql_fail(error);
                    }
                }
                SchemaObject::Matview { table, catalog } => {
                    let def = (*storage.table_def(*table, txn.txid)).clone();
                    let lsn = storage.bump_lsn();
                    if let Err(error) = wal.stage_reserved(
                        txn.txid,
                        lsn,
                        &WalOp::DropTable {
                            identity: storage.table_position(*table),
                            schema: def.schema.as_str(),
                            name: def.name.as_str(),
                        },
                    ) {
                        return sql_fail(error);
                    }
                    if let Err(error) = drop_row_type_users(
                        storage,
                        wal,
                        txn,
                        ("materialized view", def.name),
                        crate::storage::RowTypeRelation::Table(*table),
                        &[],
                        &dropped_schema,
                        true,
                        RowTypeColumnCascade {
                            scratch: &mut *scratch,
                            seq_session,
                        },
                        arena,
                        responder,
                    ) {
                        return sql_fail(error);
                    }
                    let dropped = match storage.drop_table_in(*table, txn.txid) {
                        Ok(undo) => undo,
                        Err(error) => return sql_fail(error),
                    };
                    if let Err(error) = txn.record_table_drop(storage, dropped) {
                        return sql_fail(error);
                    }
                    storage.drop_indexes_for(*table, txn.txid);
                    let lsn = storage.bump_lsn();
                    if let Err(error) = wal.stage_reserved(
                        txn.txid,
                        lsn,
                        &WalOp::DropMatview {
                            identity: storage.matview_position(*catalog),
                            schema: def.schema.as_str(),
                            name: def.name.as_str(),
                        },
                    ) {
                        return sql_fail(error);
                    }
                    let target = match storage.prepare_matview_edit(*catalog, txn.txid) {
                        Ok(target) => target,
                        Err(error) => return sql_fail(error),
                    };
                    let change = match storage.drop_matview(target, txn.txid) {
                        Ok(change) => change,
                        Err(error) => return sql_fail(error),
                    };
                    if let Err(error) = txn.record_matview_change(storage, change) {
                        return sql_fail(error);
                    }
                }
                SchemaObject::Sequence(sequence) => {
                    let identity = storage.sequence_position(*sequence);
                    let sequence = storage.sequence_for(*sequence, txn.txid);
                    let (schema, name) = (sequence.schema, sequence.name);
                    if sequence.persistence != crate::storage::RelationPersistence::Temporary {
                        let lsn = storage.bump_lsn();
                        if let Err(error) = wal.stage_reserved(
                            txn.txid,
                            lsn,
                            &WalOp::DropSequence {
                                identity,
                                schema: schema.as_str(),
                                name: name.as_str(),
                            },
                        ) {
                            return sql_fail(error);
                        }
                    }
                    match storage.drop_sequence(schema.as_str(), name.as_str(), txn.txid) {
                        Ok(Some(slot)) => {
                            if let Err(error) = txn.record_sequence_change(storage, slot) {
                                return sql_fail(error);
                            }
                        }
                        Ok(None) => {}
                        Err(error) => return sql_fail(error),
                    }
                }
                SchemaObject::Domain(domain) => {
                    // Casts, operators and routines on the domain go with it.
                    let selected = match arena
                        .alloc_slice_with(storage.domain_count(), |slot| slot == *domain)
                    {
                        Ok(selected) => selected,
                        Err(_) => return sql_fail(arena_full()),
                    };
                    if let Err(error) = drop_type_dependent_routines(
                        storage,
                        wal,
                        txn,
                        &mut *scratch,
                        seq_session,
                        selected,
                        None,
                        None,
                        true,
                        arena,
                        responder,
                    ) {
                        return sql_fail(error);
                    }
                    let domain = storage.domain_for(*domain, txn.txid);
                    let (schema, name) = (domain.schema, domain.name);
                    let lsn = storage.bump_lsn();
                    if let Err(error) = wal.stage_reserved(
                        txn.txid,
                        lsn,
                        &WalOp::DropDomain {
                            schema: schema.as_str(),
                            name: name.as_str(),
                        },
                    ) {
                        return sql_fail(error);
                    }
                    match storage.stage_type_drop(
                        crate::storage::NamedTypeKind::Domain,
                        schema.as_str(),
                        name.as_str(),
                        txn.txid,
                    ) {
                        Ok(Some(slot)) => {
                            if let Err(error) =
                                txn.record_ddl(storage, super::txn::DdlUndo::DomainDropped(slot))
                            {
                                storage.finish_type_ddl(
                                    slot,
                                    crate::storage::TypeDdlDecision::Rollback,
                                );
                                return sql_fail(error);
                            }
                        }
                        Ok(None) => {}
                        Err(error) => return sql_fail(error),
                    }
                }
                SchemaObject::Enum(enumeration) => {
                    // Casts, operators and routines on the type go with it.
                    if let Err(error) = drop_type_dependent_routines(
                        storage,
                        wal,
                        txn,
                        &mut *scratch,
                        seq_session,
                        &[],
                        Some(*enumeration),
                        None,
                        true,
                        arena,
                        responder,
                    ) {
                        return sql_fail(error);
                    }
                    let enumeration = storage.enum_for(*enumeration, txn.txid);
                    let (schema, name) = (enumeration.schema, enumeration.name);
                    let lsn = storage.bump_lsn();
                    if let Err(error) = wal.stage_reserved(
                        txn.txid,
                        lsn,
                        &WalOp::DropEnum {
                            schema: schema.as_str(),
                            name: name.as_str(),
                        },
                    ) {
                        return sql_fail(error);
                    }
                    match storage.stage_type_drop(
                        crate::storage::NamedTypeKind::Enum,
                        schema.as_str(),
                        name.as_str(),
                        txn.txid,
                    ) {
                        Ok(Some(slot)) => {
                            if let Err(error) =
                                txn.record_ddl(storage, super::txn::DdlUndo::EnumDropped(slot))
                            {
                                storage.finish_type_ddl(
                                    slot,
                                    crate::storage::TypeDdlDecision::Rollback,
                                );
                                return sql_fail(error);
                            }
                        }
                        Ok(None) => {}
                        Err(error) => return sql_fail(error),
                    }
                }
                SchemaObject::Composite(composite) => {
                    if storage.composite(*composite).visible_to(txn.txid)
                        && let Err(error) = drop_composite_type(
                            storage,
                            wal,
                            txn,
                            scratch,
                            *composite,
                            true,
                            arena,
                            seq_session,
                            responder,
                        )
                    {
                        return sql_fail(error);
                    }
                }
                SchemaObject::Operator(operator) => {
                    if storage.operator(*operator).visible_to(txn.txid) {
                        let operator_oid = storage.operator(*operator).oid();
                        if let Err(error) = cascade_operator_dependencies(
                            storage,
                            wal,
                            txn,
                            &mut *scratch,
                            seq_session,
                            &mut *responder,
                            operator_oid,
                            arena,
                        ) {
                            return sql_fail(error);
                        }
                        if let Err(error) = stage_operator_drop(storage, wal, txn, *operator) {
                            return sql_fail(error);
                        }
                    }
                }
                SchemaObject::OperatorFamily(family) => {
                    if storage.operator_family(*family).visible_to(txn.txid) {
                        let family_oid = storage.operator_family(*family).oid();
                        loop {
                            let dependent = storage.operator_classes_visible_to(txn.txid).find_map(
                                |(slot, class)| (class.family == family_oid).then_some(slot),
                            );
                            let Some(class) = dependent else { break };
                            if let Err(error) =
                                stage_operator_class_drop(storage, wal, txn, class, true)
                            {
                                return sql_fail(error);
                            }
                        }
                        if let Err(error) = stage_operator_family_drop(storage, wal, txn, *family) {
                            return sql_fail(error);
                        }
                    }
                }
                SchemaObject::OperatorClass(class) => {
                    if storage.operator_class(*class).visible_to(txn.txid)
                        && let Err(error) =
                            stage_operator_class_drop(storage, wal, txn, *class, true)
                    {
                        return sql_fail(error);
                    }
                }
                SchemaObject::Statistics(statistics) => {
                    if !storage
                        .extended_statistics(*statistics)
                        .visible_to(txn.txid)
                    {
                        continue;
                    }
                    let definition = storage
                        .extended_statistics(*statistics)
                        .definition_for(txn.txid);
                    if let Err(error) = storage.drop_extended_statistics(*statistics, txn.txid) {
                        return sql_fail(error);
                    }
                    if storage
                        .table_def(
                            usize::from(storage.extended_statistics(*statistics).table),
                            txn.txid,
                        )
                        .persistence
                        != crate::storage::RelationPersistence::Temporary
                    {
                        let lsn = storage.bump_lsn();
                        if let Err(error) = wal.stage_reserved(
                            txn.txid,
                            lsn,
                            &WalOp::DropExtendedStatistics {
                                schema: definition.schema.as_str(),
                                name: definition.name.as_str(),
                            },
                        ) {
                            storage.rollback_extended_statistics_drop(*statistics, txn.txid);
                            return sql_fail(error);
                        }
                    }
                    if let Err(error) = txn.record_ddl(
                        storage,
                        super::txn::DdlUndo::StatisticsDropped(*statistics as u32),
                    ) {
                        storage.rollback_extended_statistics_drop(*statistics, txn.txid);
                        return sql_fail(error);
                    }
                }
                SchemaObject::Policy { slot, .. } => {
                    if let Err(error) = drop_policy_slot(storage, wal, txn, *slot) {
                        return sql_fail(error);
                    }
                }
                SchemaObject::Table(t) => {
                    if let Some(other) = storage.table(*t).ddl_locked_by_other(txn.txid) {
                        if let Err(error) = storage.wait_for_transaction(txn.txid, other) {
                            return sql_fail(error);
                        }
                        return sql_fail(sql_err!(
                            crate::sql::eval::sqlstate::INTERNAL_LOCK_WAIT,
                            "statement is waiting for concurrent DDL on \"{}\"",
                            storage.table_def(*t, txn.txid).name.as_str()
                        ));
                    }
                    let def = (*storage.table_def(*t, txn.txid)).clone();
                    for sequence_slot in 0..storage.sequence_count() {
                        let sequence = storage.sequence_for(sequence_slot, txn.txid);
                        if !sequence.visible_to(txn.txid)
                            || !matches!(
                                sequence.owner,
                                Some(owner)
                                    if owner.table_schema == def.schema
                                        && owner.table == def.name
                            )
                        {
                            continue;
                        }
                        let (schema, name) = (sequence.schema, sequence.name);
                        if sequence.persistence != crate::storage::RelationPersistence::Temporary {
                            let lsn = storage.bump_lsn();
                            if let Err(error) = wal.stage_reserved(
                                txn.txid,
                                lsn,
                                &WalOp::DropSequence {
                                    identity: storage.sequence_position(sequence_slot),
                                    schema: schema.as_str(),
                                    name: name.as_str(),
                                },
                            ) {
                                return sql_fail(error);
                            }
                        }
                        match storage.drop_sequence(schema.as_str(), name.as_str(), txn.txid) {
                            Ok(Some(slot)) => {
                                if let Err(error) = txn.record_sequence_change(storage, slot) {
                                    return sql_fail(error);
                                }
                            }
                            Ok(None) => {}
                            Err(error) => return sql_fail(error),
                        }
                    }
                    let trigger_target = crate::storage::TriggerTarget::Table(*t as u16);
                    loop {
                        let trigger = storage.triggers_with_slots_visible_to(txn.txid).find_map(
                            |(slot, trigger)| (trigger.target == trigger_target).then_some(slot),
                        );
                        let Some(slot) = trigger else { break };
                        if let Err(error) = storage.drop_trigger(slot, txn.txid) {
                            return sql_fail(error);
                        }
                        if let Err(error) = txn
                            .record_ddl(storage, super::txn::DdlUndo::TriggerDropped(slot as u32))
                        {
                            storage.rollback_trigger_drop(slot, txn.txid);
                            return sql_fail(error);
                        }
                    }
                    if def.persistence != crate::storage::RelationPersistence::Temporary {
                        let lsn = storage.bump_lsn();
                        if let Err(e) = wal.stage_reserved(
                            txn.txid,
                            lsn,
                            &WalOp::DropTable {
                                identity: storage.table_position(*t),
                                schema: def.schema.as_str(),
                                name: def.name.as_str(),
                            },
                        ) {
                            return sql_fail(e);
                        }
                    }
                    if let Err(error) = drop_row_type_users(
                        storage,
                        wal,
                        txn,
                        ("table", def.name),
                        crate::storage::RowTypeRelation::Table(*t),
                        &[],
                        &dropped_schema,
                        true,
                        RowTypeColumnCascade {
                            scratch: &mut *scratch,
                            seq_session,
                        },
                        arena,
                        responder,
                    ) {
                        return sql_fail(error);
                    }
                    let dropped = match storage.drop_table_in(*t, txn.txid) {
                        Ok(undo) => undo,
                        Err(error) => return sql_fail(error),
                    };
                    if let Err(e) = txn.record_table_drop(storage, dropped) {
                        return sql_fail(e);
                    }
                    storage.drop_indexes_for(*t, txn.txid);
                }
            }
        }
        for &slot in &slots[..n_slots] {
            let name = storage.schema_def_for(slot, txn.txid).name;
            for default_slot in 0..storage.default_acl_entry_count() {
                let entry = storage.default_acl_entry(default_slot);
                if entry.database != storage.current_database_oid()
                    || usize::from(entry.schema) != slot
                    || entry.image_to(txn.txid).is_none()
                {
                    continue;
                }
                let change = match storage.change_default_acl(
                    crate::storage::DefaultAclKey {
                        owner: entry.owner,
                        schema: entry.schema,
                        class: entry.class,
                        grantee: entry.grantee,
                    },
                    false,
                    crate::storage::PrivilegeSet::NONE,
                    crate::storage::PrivilegeSet::NONE,
                    txn.txid,
                ) {
                    Ok(change) => change,
                    Err(error) => return sql_fail(error),
                };
                if let Some((changed, prior)) = change
                    && let Err(error) = txn.record_ddl(
                        storage,
                        super::txn::DdlUndo::DefaultAclChanged {
                            slot: changed as u32,
                            prior,
                        },
                    )
                {
                    storage.restore_default_acl_pending(changed, prior);
                    return sql_fail(error);
                }
            }
            if let Err(error) = storage.drop_schema_in(slot, txn.txid) {
                return sql_fail(error);
            }
            if let Err(error) = remove_schema_from_publications(storage, wal, txn, slot as u8) {
                storage.rollback_schema_drop(slot, txn.txid);
                return sql_fail(error);
            }
            let lsn = storage.bump_lsn();
            if let Err(e) = wal.stage_reserved(
                txn.txid,
                lsn,
                &WalOp::DropSchema {
                    identity: storage
                        .schema_def(slot)
                        .identity()
                        .expect("dropped schema retains its identity"),
                    name: name.as_str(),
                },
            ) {
                storage.rollback_schema_drop(slot, txn.txid);
                return sql_fail(e);
            }
            if let Err(e) = txn.record_ddl(storage, super::txn::DdlUndo::SchemaDropped(slot as u32))
            {
                storage.rollback_schema_drop(slot, txn.txid);
                return sql_fail(e);
            }
        }
        responder.command_complete("DROP SCHEMA")?;
        sql_ok()
    })
}

fn remove_schema_from_publications(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut TxnState,
    schema_slot: u8,
) -> Result<(), SqlError> {
    while let Some((name, mut definition)) =
        storage.publication_selecting_schema(schema_slot, txn.txid)
    {
        let index = definition.schemas[..definition.schema_count]
            .iter()
            .position(|member| *member == schema_slot)
            .expect("selected schema");
        definition
            .schemas
            .copy_within(index + 1..definition.schema_count, index);
        definition.schema_count -= 1;
        definition.schemas[definition.schema_count] = u8::MAX;
        let (slot, prior) = storage.alter_publication(name.as_str(), definition, txn.txid)?;
        let lsn = storage.bump_lsn();
        if let Err(error) = wal.stage_reserved(
            txn.txid,
            lsn,
            &WalOp::AlterPublication {
                name: name.as_str(),
                all_tables: definition.all_tables,
                tables: definition.tables,
                table_column_masks: crate::wal::WalColumnSets::Captured(
                    &definition.table_column_masks[..definition.table_count],
                ),
                table_include_descendants: definition.table_include_descendants,
                table_filter_sql: definition
                    .table_filters
                    .materialize_sql(definition.table_count),
                table_count: definition.table_count,
                schemas: definition.schemas,
                schema_count: definition.schema_count,
                publish_insert: definition.publish_insert,
                publish_update: definition.publish_update,
                publish_delete: definition.publish_delete,
                publish_truncate: definition.publish_truncate,
                publish_via_partition_root: definition.publish_via_partition_root,
                publish_generated_columns: definition.publish_generated_columns,
            },
        ) {
            storage.rollback_publication_alter(slot, prior);
            return Err(error);
        }
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::PublicationAltered {
                slot: slot as u32,
                prior,
            },
        ) {
            storage.rollback_publication_alter(slot, prior);
            return Err(error);
        }
    }
    Ok(())
}

/// CREATE PUBLICATION records a transaction-owned catalog entry and its
/// complete initial selection before the commit record makes it visible.
#[allow(clippy::too_many_arguments)]
pub fn create_publication(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut super::txn::TxnState,
    name: &str,
    all_tables: bool,
    tables: &[PublicationTarget],
    schemas: &[&str],
    publish: crate::sql::ast::PublicationOperations,
    publish_via_partition_root: bool,
    publish_generated_columns: crate::sql::ast::PublishGeneratedColumns,
    responder: &mut Responder,
    arena: &Arena,
) -> Outcome {
    if all_tables && (!tables.is_empty() || !schemas.is_empty()) {
        return sql_fail(sql_err!(
            sqlstate::SYNTAX_ERROR,
            "FOR ALL TABLES cannot name tables"
        ));
    }
    let Some(role) = storage.current_role_slot(txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "current role is not present in the role catalog"
        ));
    };
    let superuser = storage.role(role).attributes_to(txn.txid).superuser;
    if !superuser && !storage.has_current_database_create_privilege(role, txn.txid) {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied for database"
        ));
    }
    if all_tables && !superuser {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be superuser to create a FOR ALL TABLES publication"
        ));
    }
    let (members, table_column_masks, table_include_descendants, table_filter_sql, table_count) =
        match publication_members(
            storage,
            txn.txid,
            tables,
            publish.update || publish.delete,
            arena,
        ) {
            Ok(members) => members,
            Err(error) => return sql_fail(error),
        };
    if let Err(error) = validate_partitioned_publication_features(
        storage,
        txn.txid,
        name,
        &members[..table_count],
        &table_column_masks[..table_count],
        &table_filter_sql[..table_count],
        publish_via_partition_root,
    ) {
        return sql_fail(error);
    }
    let schema_members = match publication_schemas(storage, txn.txid, schemas) {
        Ok(schemas) => schemas,
        Err(error) => return sql_fail(error),
    };
    if let Err(error) =
        validate_publication_target_mix(&table_column_masks[..table_count], schemas.len())
    {
        return sql_fail(error);
    }
    let name = match SqlName::parse(name) {
        Ok(name) => name,
        Err(error) => return sql_fail(error),
    };
    match storage.create_publication(
        crate::storage::PublicationSpec {
            creation: crate::storage::CatalogCreation::New,
            name,
            all_tables,
            tables: &members[..table_count],
            table_column_masks: &table_column_masks[..table_count],
            table_include_descendants: &table_include_descendants[..table_count],
            table_filter_sql: &table_filter_sql[..table_count],
            schemas: &schema_members[..schemas.len()],
            publish_insert: publish.insert,
            publish_update: publish.update,
            publish_delete: publish.delete,
            publish_truncate: publish.truncate,
            publish_via_partition_root,
            publish_generated_columns: publish_generated_columns.into(),
        },
        txn.txid,
    ) {
        Ok(slot) => {
            let owner = storage.publication_owner(slot, txn.txid);
            let lsn = storage.bump_lsn();
            if let Err(error) = wal.stage_reserved(
                txn.txid,
                lsn,
                &WalOp::CreatePublication {
                    created_at: storage.publication_at(slot).created_at,
                    name: name.as_str(),
                    owner,
                    all_tables,
                    tables: members,
                    table_column_masks: crate::wal::WalColumnSets::Captured(
                        &table_column_masks[..table_count],
                    ),
                    table_include_descendants,
                    table_filter_sql,
                    table_count,
                    schemas: schema_members,
                    schema_count: schemas.len(),
                    publish_insert: publish.insert,
                    publish_update: publish.update,
                    publish_delete: publish.delete,
                    publish_truncate: publish.truncate,
                    publish_via_partition_root,
                    publish_generated_columns: publish_generated_columns.into(),
                },
            ) {
                storage.rollback_publication_create(slot);
                return sql_fail(error);
            }
            match txn.record_ddl(
                storage,
                super::txn::DdlUndo::PublicationCreated(slot as u32),
            ) {
                Ok(()) => Ok(Ok(responder.command_complete("CREATE PUBLICATION")?)),
                Err(error) => {
                    storage.rollback_publication_create(slot);
                    sql_fail(error)
                }
            }
        }
        Err(error) => sql_fail(error),
    }
}

fn publication_schemas(
    storage: &Storage,
    txid: u32,
    schemas: &[&str],
) -> Result<[u8; crate::storage::MAX_PUBLICATION_SCHEMAS], SqlError> {
    let mut members = [u8::MAX; crate::storage::MAX_PUBLICATION_SCHEMAS];
    if schemas.is_empty() {
        return Ok(members);
    }
    let role = storage.current_role_slot(txid).ok_or_else(|| {
        sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "current role is not present in the role catalog"
        )
    })?;
    if txid != 0 && !storage.role(role).attributes_to(txid).superuser {
        return Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be superuser to publish schemas"
        ));
    }
    for (index, name) in schemas.iter().enumerate() {
        let Some(slot) = storage.find_schema_visible(name, txid) else {
            return Err(sql_err!(
                sqlstate::INVALID_SCHEMA_NAME,
                "schema \"{}\" does not exist",
                name
            ));
        };
        if members[..index].contains(&(slot as u8)) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "schema \"{}\" is listed more than once",
                name
            ));
        }
        members[index] = slot as u8;
    }
    Ok(members)
}

pub fn drop_publication(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut super::txn::TxnState,
    names: &[&str],
    if_exists: bool,
    responder: &mut Responder,
) -> Outcome {
    for name in names {
        let Some((slot, _)) = storage.publication_definition(name, txn.txid) else {
            if if_exists {
                responder.notice(
                    sqlstate::SUCCESSFUL_COMPLETION,
                    stack_format!(128, "publication \"{}\" does not exist, skipping", name)
                        .as_str(),
                )?;
                continue;
            }
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "publication \"{}\" does not exist",
                name
            ));
        };
        if let Err(error) = storage.require_publication_owner(slot, txn.txid) {
            return sql_fail(error);
        }
        match storage.drop_publication(name, txn.txid) {
            Ok(Some(slot)) => {
                let lsn = storage.bump_lsn();
                if let Err(error) =
                    wal.stage_reserved(txn.txid, lsn, &WalOp::DropPublication { name })
                {
                    storage.rollback_publication_drop(slot, txn.txid);
                    return sql_fail(error);
                }
                if let Err(error) = txn.record_ddl(
                    storage,
                    super::txn::DdlUndo::PublicationDropped(slot as u32),
                ) {
                    storage.rollback_publication_drop(slot, txn.txid);
                    return sql_fail(error);
                }
            }
            Ok(None) => {
                return sql_fail(sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "publication disappeared before DROP PUBLICATION completed"
                ));
            }
            Err(error) => return sql_fail(error),
        }
    }
    Ok(Ok(responder.command_complete("DROP PUBLICATION")?))
}

#[derive(Clone, Copy)]
pub struct CreateSubscriptionCommand<'a> {
    pub name: &'a str,
    pub connection: &'a str,
    pub publications: &'a [&'a str],
    pub options: crate::sql::ast::SubscriptionOptions<'a>,
}

pub fn create_subscription(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut super::txn::TxnState,
    command: CreateSubscriptionCommand<'_>,
    responder: &mut Responder,
) -> Outcome {
    let CreateSubscriptionCommand {
        name,
        connection,
        publications,
        options,
    } = command;
    let role = match storage.current_role_slot(txn.txid) {
        Some(role) => role,
        None => {
            return sql_fail(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            ));
        }
    };
    // PostgreSQL 18.6 CreateSubscription: pg_create_subscription, CREATE on
    // the database, and for non-superusers a password in the connection.
    if !storage.role_has_privileges_of(
        role,
        crate::storage::PredefinedRole::CreateSubscription.slot(),
        txn.txid,
    ) {
        return sql_fail(crate::sql::eval::with_detail(
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to create subscription"
            ),
            format_args!(
                "Only roles with privileges of the \"pg_create_subscription\" role may create subscriptions."
            ),
        ));
    }
    if !storage.has_current_database_create_privilege(role, txn.txid) {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied for database {}",
            storage.current_database_name(txn.txid).as_str()
        ));
    }
    let superuser = storage.role(role).attributes_to(txn.txid).superuser;
    if !options.behavior.password_required && !superuser {
        return sql_fail(crate::sql::eval::with_detail(
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "password_required=false is superuser-only"
            ),
            format_args!(
                "Subscriptions with the password_required option set to false may only be created or modified by the superuser."
            ),
        ));
    }
    if options.behavior.two_phase {
        return sql_fail(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "two_phase subscriptions require durable prepared transactions, which are not supported by the object-native transaction model"
        ));
    }
    let name = match SqlName::parse(name) {
        Ok(name) => name,
        Err(error) => return sql_fail(error),
    };
    let connection = match crate::storage::SubscriptionConnInfo::parse(connection) {
        Ok(connection) => connection,
        Err(error) => return sql_fail(error),
    };
    if options.behavior.password_required
        && !superuser
        && !crate::pg::replication_client::connection_names_password(connection.as_str())
            .unwrap_or(false)
    {
        return sql_fail(crate::sql::eval::with_detail(
            sql_err!(
                sqlstate::INVALID_AUTHORIZATION_SPECIFICATION,
                "password is required"
            ),
            format_args!("Non-superusers must provide a password in the connection string."),
        ));
    }
    let resolve_slot_name = |slot: crate::sql::ast::SubscriptionSlotName<'_>| match slot {
        crate::sql::ast::SubscriptionSlotName::Default => {
            crate::storage::ReplicationSlotName::parse(name.as_str())
        }
        crate::sql::ast::SubscriptionSlotName::Named(slot) => {
            crate::storage::ReplicationSlotName::parse(slot)
        }
    };
    let publisher_slot = match options.slot {
        crate::sql::ast::SubscriptionSlotPlan::Managed(slot) => match resolve_slot_name(slot) {
            Ok(slot) => crate::storage::SubscriptionSlot::Managed(slot),
            Err(error) => return sql_fail(error),
        },
        crate::sql::ast::SubscriptionSlotPlan::External(slot) => match resolve_slot_name(slot) {
            Ok(slot) => crate::storage::SubscriptionSlot::External(slot),
            Err(error) => return sql_fail(error),
        },
        crate::sql::ast::SubscriptionSlotPlan::Absent => crate::storage::SubscriptionSlot::Absent,
    };
    let bootstrap = match (options.connect, publisher_slot, options.copy_data) {
        (crate::sql::ast::SubscriptionConnect::Deferred, _, _) => {
            crate::storage::SubscriptionBootstrap::Deferred
        }
        (
            crate::sql::ast::SubscriptionConnect::Now,
            crate::storage::SubscriptionSlot::Managed(_),
            copy_data,
        ) => crate::storage::SubscriptionBootstrap::CreateManagedSlot { copy_data },
        (
            crate::sql::ast::SubscriptionConnect::Now,
            crate::storage::SubscriptionSlot::External(_),
            true,
        ) => crate::storage::SubscriptionBootstrap::CopyExternalSlot,
        (
            crate::sql::ast::SubscriptionConnect::Now,
            crate::storage::SubscriptionSlot::Absent,
            true,
        ) => crate::storage::SubscriptionBootstrap::CopyWithoutSlot,
        _ => crate::storage::SubscriptionBootstrap::Ready,
    };
    if options.enabled {
        match connection.require_endpoint_for(name) {
            Ok(_) => {}
            Err(error) => return sql_fail(error),
        }
    }
    let mut publication_names = [SqlName::EMPTY; crate::storage::MAX_SUBSCRIPTION_PUBLICATIONS];
    if publications.len() > publication_names.len() {
        return sql_fail(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "too many publications in subscription (limit {})",
            publication_names.len()
        ));
    }
    for (index, publication) in publications.iter().enumerate() {
        let publication = match SqlName::parse(publication) {
            Ok(publication) => publication,
            Err(error) => return sql_fail(error),
        };
        if publication_names[..index].contains(&publication) {
            return sql_fail(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "publication \"{}\" is listed more than once",
                publication.as_str()
            ));
        }
        publication_names[index] = publication;
    }
    let slot = match storage.create_subscription(
        crate::storage::SubscriptionSpec {
            name,
            connection,
            publications: &publication_names[..publications.len()],
            enabled: options.enabled,
            slot: publisher_slot,
            behavior: options.behavior.into(),
            bootstrap,
        },
        txn.txid,
    ) {
        Ok(slot) => slot,
        Err(error) => return sql_fail(error),
    };
    let definition = storage
        .subscription(name.as_str(), txn.txid)
        .expect("new subscription is visible to its creating transaction")
        .1;
    let owner = definition.ownership.owner_to(txn.txid);
    let lsn = storage.bump_lsn();
    if let Err(error) = wal.stage_reserved(
        txn.txid,
        lsn,
        &WalOp::CreateSubscription {
            created_at: definition.created_at,
            name: name.as_str(),
            owner,
            connection: connection.as_str(),
            publications: publication_names,
            publication_count: publications.len(),
            enabled: options.enabled,
            slot: publisher_slot,
            behavior: options.behavior.into(),
            bootstrap,
        },
    ) {
        storage.rollback_subscription_create(slot);
        return sql_fail(error);
    }
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::SubscriptionCreated(slot as u32),
    ) {
        storage.rollback_subscription_create(slot);
        return sql_fail(error);
    }
    Ok(Ok(responder.command_complete("CREATE SUBSCRIPTION")?))
}

pub fn alter_subscription(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut super::txn::TxnState,
    name: &str,
    action: crate::sql::ast::AlterSubscriptionAction<'_>,
    responder: &mut Responder,
) -> Outcome {
    let (slot, subscription) = match storage.subscription(name, txn.txid) {
        Some(subscription) => subscription,
        None => {
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "subscription \"{}\" does not exist",
                name
            ));
        }
    };
    if let Err(error) = storage.require_subscription_owner(slot, txn.txid) {
        return sql_fail(error);
    }
    let actor_superuser = storage
        .current_role_slot(txn.txid)
        .is_some_and(|role| storage.role(role).attributes_to(txn.txid).superuser);
    let definition = storage.subscription_definition_to(slot, txn.txid);
    if !actor_superuser && !definition.behavior.password_required {
        return sql_fail(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "only superusers may modify subscriptions with password_required = false"
        ));
    }
    match action {
        crate::sql::ast::AlterSubscriptionAction::Enable
        | crate::sql::ast::AlterSubscriptionAction::Disable => {
            let enabled = matches!(action, crate::sql::ast::AlterSubscriptionAction::Enable);
            if enabled {
                if definition.slot.name().is_none() {
                    return sql_fail(sql_err!(
                        sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                        "cannot enable a subscription without an existing publisher slot"
                    ));
                }
                if let Err(error) = validate_enabled_subscription(
                    definition.connection,
                    subscription.name_for(txn.txid),
                ) {
                    return sql_fail(error);
                }
            }
            let prior = match storage.set_subscription_enabled(slot, enabled, txn.txid) {
                Ok(crate::storage::SubscriptionEnabledChange::Changed { prior }) => prior,
                Ok(crate::storage::SubscriptionEnabledChange::Unchanged) => {
                    return Ok(Ok(responder.command_complete("ALTER SUBSCRIPTION")?));
                }
                Err(error) => return sql_fail(error),
            };
            let lsn = storage.bump_lsn();
            if let Err(error) = wal.stage_reserved(
                txn.txid,
                lsn,
                &WalOp::SetSubscriptionEnabled { name, enabled },
            ) {
                storage.restore_subscription_enabled(slot, prior);
                return sql_fail(error);
            }
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::SubscriptionEnabled {
                    slot: slot as u32,
                    prior,
                },
            ) {
                storage.restore_subscription_enabled(slot, prior);
                return sql_fail(error);
            }
        }
        crate::sql::ast::AlterSubscriptionAction::SetConnection(connection) => {
            let connection = match crate::storage::SubscriptionConnInfo::parse(connection) {
                Ok(connection) => connection,
                Err(error) => return sql_fail(error),
            };
            if subscription.enabled_to(txn.txid)
                && let Err(error) =
                    validate_enabled_subscription(connection, subscription.name_for(txn.txid))
            {
                return sql_fail(error);
            }
            let mut definition = storage.subscription_definition_to(slot, txn.txid);
            definition.connection = connection;
            if let Err(error) = alter_subscription_definition(
                storage,
                wal,
                txn,
                SubscriptionDefinitionUpdate {
                    slot,
                    name,
                    definition,
                },
            ) {
                return sql_fail(error);
            }
        }
        action @ (crate::sql::ast::AlterSubscriptionAction::SetPublications { .. }
        | crate::sql::ast::AlterSubscriptionAction::AddPublications { .. }
        | crate::sql::ast::AlterSubscriptionAction::DropPublications { .. }) => {
            let (requested, refresh, operation) = match action {
                crate::sql::ast::AlterSubscriptionAction::SetPublications {
                    publications,
                    refresh,
                } => (publications, refresh, SubscriptionPublicationChange::Set),
                crate::sql::ast::AlterSubscriptionAction::AddPublications {
                    publications,
                    refresh,
                } => (publications, refresh, SubscriptionPublicationChange::Add),
                crate::sql::ast::AlterSubscriptionAction::DropPublications {
                    publications,
                    refresh,
                } => (publications, refresh, SubscriptionPublicationChange::Drop),
                _ => unreachable!(),
            };
            let mut definition = storage.subscription_definition_to(slot, txn.txid);
            let (names, count) = match subscription_publication_change(
                definition.publications(),
                requested,
                operation,
            ) {
                Ok(value) => value,
                Err(error) => return sql_fail(error),
            };
            if let Err(error) = definition.replace_publications(&names[..count]) {
                return sql_fail(error);
            }
            if let Err(error) = alter_subscription_definition(
                storage,
                wal,
                txn,
                SubscriptionDefinitionUpdate {
                    slot,
                    name,
                    definition,
                },
            ) {
                return sql_fail(error);
            }
            if let crate::sql::ast::SubscriptionPublicationRefresh::Refresh { copy_data } = refresh
                && let Err(error) =
                    stage_subscription_refresh(storage, wal, txn, slot, name, copy_data)
            {
                return sql_fail(error);
            }
        }
        crate::sql::ast::AlterSubscriptionAction::RefreshPublications { copy_data } => {
            if let Err(error) = stage_subscription_refresh(storage, wal, txn, slot, name, copy_data)
            {
                return sql_fail(error);
            }
        }
        crate::sql::ast::AlterSubscriptionAction::SetOptions(patch) => {
            let alters_remote_slot = patch.failover.is_some() || patch.two_phase == Some(false);
            let mut definition = storage.subscription_definition_to(slot, txn.txid);
            if (patch.failover.is_some() || patch.two_phase.is_some())
                && subscription.enabled_to(txn.txid)
            {
                return sql_fail(sql_err!(
                    sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                    "cannot set failover or two_phase for an enabled subscription"
                ));
            }
            if let Some(setting) = patch.slot {
                definition.slot = match setting {
                    crate::sql::ast::SubscriptionSlotSetting::Named(value) => {
                        match crate::storage::ReplicationSlotName::parse(value) {
                            Ok(name) => crate::storage::SubscriptionSlot::External(name),
                            Err(error) => return sql_fail(error),
                        }
                    }
                    crate::sql::ast::SubscriptionSlotSetting::Absent => {
                        crate::storage::SubscriptionSlot::Absent
                    }
                };
            }
            if alters_remote_slot && definition.slot.name().is_none() {
                return sql_fail(sql_err!(
                    sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                    "cannot alter failover or two_phase without an associated replication slot"
                ));
            }
            if definition.slot.name().is_none() && subscription.enabled_to(txn.txid) {
                return sql_fail(sql_err!(
                    sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                    "cannot set slot_name = NONE for an enabled subscription"
                ));
            }
            if let Some(value) = patch.binary {
                definition.behavior.binary = value;
            }
            if let Some(value) = patch.streaming {
                definition.behavior.streaming = value.into();
            }
            if let Some(value) = patch.synchronous_commit {
                definition.behavior.synchronous_commit = value.into();
            }
            if let Some(value) = patch.two_phase {
                if value {
                    return sql_fail(sql_err!(
                        sqlstate::FEATURE_NOT_SUPPORTED,
                        "two_phase subscriptions require durable prepared transactions, which are not supported by the object-native transaction model"
                    ));
                }
                definition.behavior.two_phase = value;
            }
            if let Some(value) = patch.disable_on_error {
                definition.behavior.disable_on_error = value;
            }
            if let Some(value) = patch.password_required {
                if !value && !actor_superuser {
                    return sql_fail(sql_err!(
                        sqlstate::INSUFFICIENT_PRIVILEGE,
                        "only superusers may set password_required = false"
                    ));
                }
                definition.behavior.password_required = value;
            }
            if let Some(value) = patch.run_as_owner {
                definition.behavior.run_as_owner = value;
            }
            if let Some(value) = patch.origin {
                definition.behavior.origin = value.into();
            }
            if let Some(value) = patch.failover {
                definition.behavior.failover = value;
            }
            if let Err(error) = alter_subscription_definition(
                storage,
                wal,
                txn,
                SubscriptionDefinitionUpdate {
                    slot,
                    name,
                    definition,
                },
            ) {
                return sql_fail(error);
            }
        }
        crate::sql::ast::AlterSubscriptionAction::Skip { lsn } => {
            let mut definition = storage.subscription_definition_to(slot, txn.txid);
            definition.behavior.skip_lsn = lsn;
            if let Err(error) = alter_subscription_definition(
                storage,
                wal,
                txn,
                SubscriptionDefinitionUpdate {
                    slot,
                    name,
                    definition,
                },
            ) {
                return sql_fail(error);
            }
        }
        crate::sql::ast::AlterSubscriptionAction::SetOwner(role_name) => {
            let role_name = resolve_role_name(role_name);
            let Some(new_owner) = storage.find_role_visible(role_name.as_str(), txn.txid) else {
                return sql_fail(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "role \"{}\" does not exist",
                    role_name.as_str()
                ));
            };
            let Some(current_role) = storage.current_role_slot(txn.txid) else {
                return sql_fail(sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "current role is not present in the role catalog"
                ));
            };
            let superuser = storage.role(current_role).attributes_to(txn.txid).superuser;
            if !superuser
                && current_role != new_owner
                && !storage.role_can_set(current_role, new_owner, txn.txid)
            {
                return sql_fail(sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "must be able to SET ROLE \"{}\"",
                    role_name.as_str()
                ));
            }
            let prior = match storage.set_subscription_owner(slot, new_owner, txn.txid) {
                Ok(prior) => prior,
                Err(error) => return sql_fail(error),
            };
            let lsn = storage.bump_lsn();
            if let Err(error) = wal.stage_reserved(
                txn.txid,
                lsn,
                &WalOp::SetSubscriptionOwner {
                    name,
                    owner: new_owner as u16,
                },
            ) {
                storage.restore_subscription_owner_pending(slot, prior);
                return sql_fail(error);
            }
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::SubscriptionOwnerChanged {
                    slot: slot as u32,
                    prior,
                },
            ) {
                storage.restore_subscription_owner_pending(slot, prior);
                return sql_fail(error);
            }
        }
        crate::sql::ast::AlterSubscriptionAction::Rename(new_name) => {
            let new_name = match SqlName::parse(new_name) {
                Ok(name) => name,
                Err(error) => return sql_fail(error),
            };
            let prior = match storage.rename_subscription(slot, new_name, txn.txid) {
                Ok(prior) => prior,
                Err(error) => return sql_fail(error),
            };
            let lsn = storage.bump_lsn();
            if let Err(error) = wal.stage_reserved(
                txn.txid,
                lsn,
                &WalOp::RenameSubscription {
                    name,
                    new_name: new_name.as_str(),
                },
            ) {
                storage.rollback_subscription_rename(slot, prior);
                return sql_fail(error);
            }
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::SubscriptionRenamed {
                    slot: slot as u32,
                    prior,
                },
            ) {
                storage.rollback_subscription_rename(slot, prior);
                return sql_fail(error);
            }
        }
    }
    Ok(Ok(responder.command_complete("ALTER SUBSCRIPTION")?))
}

#[derive(Clone, Copy)]
enum SubscriptionPublicationChange {
    Set,
    Add,
    Drop,
}

fn subscription_publication_change(
    current: &[SqlName],
    requested: &[&str],
    operation: SubscriptionPublicationChange,
) -> Result<
    (
        [SqlName; crate::storage::MAX_SUBSCRIPTION_PUBLICATIONS],
        usize,
    ),
    SqlError,
> {
    if requested.is_empty() {
        return Err(sql_err!(
            sqlstate::SYNTAX_ERROR,
            "subscription publication list must not be empty"
        ));
    }
    let mut names = [SqlName::EMPTY; crate::storage::MAX_SUBSCRIPTION_PUBLICATIONS];
    let mut count = 0usize;
    if !matches!(operation, SubscriptionPublicationChange::Set) {
        names[..current.len()].copy_from_slice(current);
        count = current.len();
    }
    for (request_index, requested_name) in requested.iter().enumerate() {
        let publication = SqlName::parse(requested_name)?;
        if requested[..request_index]
            .iter()
            .any(|candidate| SqlName::parse(candidate).is_ok_and(|name| name == publication))
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "publication \"{}\" is listed more than once",
                publication.as_str()
            ));
        }
        match operation {
            SubscriptionPublicationChange::Set | SubscriptionPublicationChange::Add => {
                if names[..count].contains(&publication) {
                    return Err(sql_err!(
                        sqlstate::DUPLICATE_OBJECT,
                        "publication \"{}\" is already subscribed",
                        publication.as_str()
                    ));
                }
                if count == names.len() {
                    return Err(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many publications in subscription (limit {})",
                        names.len()
                    ));
                }
                names[count] = publication;
                count += 1;
            }
            SubscriptionPublicationChange::Drop => {
                let Some(index) = names[..count].iter().position(|name| *name == publication)
                else {
                    return Err(sql_err!(
                        sqlstate::UNDEFINED_OBJECT,
                        "publication \"{}\" is not subscribed",
                        publication.as_str()
                    ));
                };
                names.copy_within(index + 1..count, index);
                count -= 1;
                names[count] = SqlName::EMPTY;
            }
        }
    }
    if count == 0 {
        return Err(sql_err!(
            sqlstate::SYNTAX_ERROR,
            "subscription publication list must not be empty"
        ));
    }
    Ok((names, count))
}

fn stage_subscription_refresh(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut super::txn::TxnState,
    slot: usize,
    name: &str,
    copy_data: bool,
) -> Result<(), SqlError> {
    let definition = storage.subscription_definition_to(slot, txn.txid);
    if definition.slot.name().is_none() {
        return Err(sql_err!(
            sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
            "cannot refresh a subscription without a replication slot"
        ));
    }
    validate_enabled_subscription(definition.connection, SqlName::parse(name)?)?;
    let bootstrap = crate::storage::SubscriptionBootstrap::Refresh { copy_data };
    let prior = match storage.set_subscription_bootstrap(slot, bootstrap, txn.txid)? {
        crate::storage::SubscriptionBootstrapChange::Unchanged => return Ok(()),
        crate::storage::SubscriptionBootstrapChange::Changed { prior } => prior,
    };
    let lsn = storage.bump_lsn();
    if let Err(error) = wal.stage_reserved(
        txn.txid,
        lsn,
        &WalOp::SetSubscriptionBootstrap { name, bootstrap },
    ) {
        storage.restore_subscription_bootstrap(slot, prior);
        return Err(error);
    }
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::SubscriptionBootstrapChanged {
            slot: slot as u32,
            prior,
        },
    ) {
        storage.restore_subscription_bootstrap(slot, prior);
        return Err(error);
    }
    Ok(())
}

fn validate_enabled_subscription(
    connection: crate::storage::SubscriptionConnInfo,
    subscription: SqlName,
) -> Result<(), SqlError> {
    connection.require_endpoint_for(subscription).map(|_| ())
}

struct SubscriptionDefinitionUpdate<'a> {
    slot: usize,
    name: &'a str,
    definition: crate::storage::SubscriptionDefinition,
}

fn alter_subscription_definition(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut super::txn::TxnState,
    update: SubscriptionDefinitionUpdate<'_>,
) -> Result<(), SqlError> {
    let SubscriptionDefinitionUpdate {
        slot,
        name,
        definition,
    } = update;
    let change = storage.set_subscription_definition(slot, definition, txn.txid)?;
    if !change.changed {
        return Ok(());
    }
    let prior = change.prior;
    let definition = storage.subscription_definition_to(slot, txn.txid);
    let lsn = storage.bump_lsn();
    if let Err(error) = wal.stage_reserved(
        txn.txid,
        lsn,
        &WalOp::AlterSubscription {
            name,
            connection: definition.connection.as_str(),
            publications: definition.publication_array(),
            publication_count: definition.publication_count(),
            slot: definition.slot,
            behavior: definition.behavior,
        },
    ) {
        storage.restore_subscription_definition(slot, prior);
        return Err(error);
    }
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::SubscriptionDefinitionChanged {
            slot: slot as u32,
            prior,
        },
    ) {
        storage.restore_subscription_definition(slot, prior);
        return Err(error);
    }
    Ok(())
}

pub fn drop_subscription(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut super::txn::TxnState,
    names: &[&str],
    if_exists: bool,
    responder: &mut Responder,
) -> Outcome {
    for name in names {
        let Some((slot, _)) = storage.subscription(name, txn.txid) else {
            if if_exists {
                responder.notice(
                    sqlstate::SUCCESSFUL_COMPLETION,
                    stack_format!(128, "subscription \"{}\" does not exist, skipping", name)
                        .as_str(),
                )?;
                continue;
            }
            return sql_fail(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "subscription \"{}\" does not exist",
                name
            ));
        };
        if let Err(error) = storage.require_subscription_owner(slot, txn.txid) {
            return sql_fail(error);
        }
        let Some(slot) = (match storage.drop_subscription(name, txn.txid) {
            Ok(slot) => slot,
            Err(error) => return sql_fail(error),
        }) else {
            return sql_fail(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "subscription disappeared before DROP SUBSCRIPTION completed"
            ));
        };
        let lsn = storage.bump_lsn();
        if let Err(error) = wal.stage_reserved(txn.txid, lsn, &WalOp::DropSubscription { name }) {
            storage.rollback_subscription_drop(slot, txn.txid);
            return sql_fail(error);
        }
        if let Err(error) = txn.record_ddl(
            storage,
            super::txn::DdlUndo::SubscriptionDropped(slot as u32),
        ) {
            storage.rollback_subscription_drop(slot, txn.txid);
            return sql_fail(error);
        }
    }
    Ok(Ok(responder.command_complete("DROP SUBSCRIPTION")?))
}

/// Applies one fully parsed publication definition change.  The storage layer
/// stages it by transaction id; WAL carries the complete resulting definition
/// so recovery has no dependence on the prior catalog image.
pub fn alter_publication(
    storage: &mut Storage,
    wal: &mut Wal,
    txn: &mut super::txn::TxnState,
    name: &str,
    action: crate::sql::ast::AlterPublicationAction<'_>,
    responder: &mut Responder,
    arena: &Arena,
) -> Outcome {
    let Some((slot, current)) = storage.publication_definition(name, txn.txid) else {
        return sql_fail(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "publication \"{}\" does not exist",
            name
        ));
    };
    if let Err(error) = storage.require_publication_owner(slot, txn.txid) {
        return sql_fail(error);
    }
    let mut definition = current;
    let mut definition_filter_sql = definition
        .table_filters
        .materialize_sql(definition.table_count);
    match action {
        crate::sql::ast::AlterPublicationAction::Rename(new_name) => {
            let new_name = match SqlName::parse(new_name) {
                Ok(name) => name,
                Err(error) => return sql_fail(error),
            };
            let prior = match storage.rename_publication(slot, new_name, txn.txid) {
                Ok(prior) => prior,
                Err(error) => return sql_fail(error),
            };
            let lsn = storage.bump_lsn();
            if let Err(error) = wal.stage_reserved(
                txn.txid,
                lsn,
                &WalOp::RenamePublication {
                    name,
                    new_name: new_name.as_str(),
                },
            ) {
                storage.rollback_publication_rename(slot, prior);
                return sql_fail(error);
            }
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::PublicationRenamed {
                    slot: slot as u32,
                    prior,
                },
            ) {
                storage.rollback_publication_rename(slot, prior);
                return sql_fail(error);
            }
            return Ok(Ok(responder.command_complete("ALTER PUBLICATION")?));
        }
        crate::sql::ast::AlterPublicationAction::SetOwner(role_name) => {
            let role_name = resolve_role_name(role_name);
            let Some(new_owner) = storage.find_role_visible(role_name.as_str(), txn.txid) else {
                return sql_fail(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "role \"{}\" does not exist",
                    role_name.as_str()
                ));
            };
            let Some(current_role) = storage.current_role_slot(txn.txid) else {
                return sql_fail(sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "current role is not present in the role catalog"
                ));
            };
            let superuser = storage.role(current_role).attributes_to(txn.txid).superuser;
            if !superuser
                && current_role != new_owner
                && !storage.role_can_set(current_role, new_owner, txn.txid)
            {
                return sql_fail(sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "must be able to SET ROLE \"{}\"",
                    role_name.as_str()
                ));
            }
            if !superuser && !storage.has_current_database_create_privilege(new_owner, txn.txid) {
                return sql_fail(sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "permission denied for database"
                ));
            }
            if !superuser
                && (current.all_tables || current.schema_count != 0)
                && !storage.role(new_owner).attributes_to(txn.txid).superuser
            {
                return sql_fail(sql_err!(
                    sqlstate::INSUFFICIENT_PRIVILEGE,
                    "new owner of a schema or all-tables publication must be superuser"
                ));
            }
            let prior = match storage.set_publication_owner(slot, new_owner, txn.txid) {
                Ok(prior) => prior,
                Err(error) => return sql_fail(error),
            };
            let lsn = storage.bump_lsn();
            if let Err(error) = wal.stage_reserved(
                txn.txid,
                lsn,
                &WalOp::SetPublicationOwner {
                    name,
                    owner: new_owner as u16,
                },
            ) {
                storage.restore_publication_owner_pending(slot, prior);
                return sql_fail(error);
            }
            if let Err(error) = txn.record_ddl(
                storage,
                super::txn::DdlUndo::PublicationOwnerChanged {
                    slot: slot as u32,
                    prior,
                },
            ) {
                storage.restore_publication_owner_pending(slot, prior);
                return sql_fail(error);
            }
            return Ok(Ok(responder.command_complete("ALTER PUBLICATION")?));
        }
        crate::sql::ast::AlterPublicationAction::SetOptions {
            publish,
            publish_via_partition_root,
            publish_generated_columns,
        } => {
            if let Some(operations) = publish {
                definition.publish_insert = operations.insert;
                definition.publish_update = operations.update;
                definition.publish_delete = operations.delete;
                definition.publish_truncate = operations.truncate;
            }
            if let Some(via_root) = publish_via_partition_root {
                definition.publish_via_partition_root = via_root;
            }
            if let Some(generated) = publish_generated_columns {
                definition.publish_generated_columns = generated.into();
            }
        }
        crate::sql::ast::AlterPublicationAction::SetTargets { tables, schemas } => {
            if current.all_tables {
                return sql_fail(sql_err!(
                    sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                    "publication \"{}\" is defined as FOR ALL TABLES",
                    name
                ));
            }
            let (members, masks, descendants, filters, count) = match publication_members(
                storage,
                txn.txid,
                tables,
                definition.publish_update || definition.publish_delete,
                arena,
            ) {
                Ok(members) => members,
                Err(error) => return sql_fail(error),
            };
            definition.tables = members;
            definition.table_column_masks = masks;
            definition.table_include_descendants = descendants;
            definition_filter_sql = filters;
            definition.table_count = count;
            let schema_members = match publication_schemas(storage, txn.txid, schemas) {
                Ok(schemas) => schemas,
                Err(error) => return sql_fail(error),
            };
            if let Err(error) = validate_publication_target_mix(&masks[..count], schemas.len()) {
                return sql_fail(error);
            }
            definition.schemas = schema_members;
            definition.schema_count = schemas.len();
        }
        crate::sql::ast::AlterPublicationAction::AddTargets { tables, schemas } => {
            if current.all_tables {
                return sql_fail(sql_err!(
                    sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                    "publication \"{}\" is defined as FOR ALL TABLES",
                    name
                ));
            }
            let (members, masks, descendants, filters, count) = match publication_members(
                storage,
                txn.txid,
                tables,
                definition.publish_update || definition.publish_delete,
                arena,
            ) {
                Ok(members) => members,
                Err(error) => return sql_fail(error),
            };
            if definition.table_count + count > crate::storage::MAX_PUBLICATION_TABLES {
                return sql_fail(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "too many tables in publication (limit {})",
                    crate::storage::MAX_PUBLICATION_TABLES
                ));
            }
            if let Err(error) = validate_publication_target_mix(
                &masks[..count],
                definition.schema_count + schemas.len(),
            ) {
                return sql_fail(error);
            }
            if let Err(error) = validate_publication_target_mix(
                &definition.table_column_masks[..definition.table_count],
                schemas.len(),
            ) {
                return sql_fail(error);
            }
            for (index, table) in members[..count].iter().enumerate() {
                if definition.tables[..definition.table_count].contains(table) {
                    return sql_fail(sql_err!(
                        sqlstate::DUPLICATE_OBJECT,
                        "relation is already in publication \"{}\"",
                        name
                    ));
                }
                definition.tables[definition.table_count] = *table;
                definition.table_column_masks[definition.table_count] = masks[index];
                definition.table_include_descendants[definition.table_count] = descendants[index];
                definition_filter_sql[definition.table_count] = filters[index];
                definition.table_count += 1;
            }
            let schema_members = match publication_schemas(storage, txn.txid, schemas) {
                Ok(schemas) => schemas,
                Err(error) => return sql_fail(error),
            };
            if definition.schema_count + schemas.len() > crate::storage::MAX_PUBLICATION_SCHEMAS {
                return sql_fail(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "too many schemas in publication"
                ));
            }
            for schema in &schema_members[..schemas.len()] {
                if definition.schemas[..definition.schema_count].contains(schema) {
                    return sql_fail(sql_err!(
                        sqlstate::DUPLICATE_OBJECT,
                        "schema is already in publication \"{}\"",
                        name
                    ));
                }
                definition.schemas[definition.schema_count] = *schema;
                definition.schema_count += 1;
            }
        }
        crate::sql::ast::AlterPublicationAction::DropTargets { tables, schemas } => {
            if tables.iter().any(|table| !table.columns.is_empty()) {
                return sql_fail(sql_err!(
                    sqlstate::SYNTAX_ERROR,
                    "ALTER PUBLICATION DROP TABLE does not accept a column list"
                ));
            }
            if current.all_tables {
                return sql_fail(sql_err!(
                    sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                    "publication \"{}\" is defined as FOR ALL TABLES",
                    name
                ));
            }
            let (members, _, _, _, count) =
                match publication_members(storage, txn.txid, tables, false, arena) {
                    Ok(members) => members,
                    Err(error) => return sql_fail(error),
                };
            for table in &members[..count] {
                let Some(index) = definition.tables[..definition.table_count]
                    .iter()
                    .position(|member| member == table)
                else {
                    return sql_fail(sql_err!(
                        sqlstate::UNDEFINED_OBJECT,
                        "relation is not part of publication \"{}\"",
                        name
                    ));
                };
                definition
                    .tables
                    .copy_within(index + 1..definition.table_count, index);
                definition
                    .table_column_masks
                    .copy_within(index + 1..definition.table_count, index);
                definition
                    .table_include_descendants
                    .copy_within(index + 1..definition.table_count, index);
                definition.table_count -= 1;
                definition.tables[definition.table_count] = u16::MAX;
                definition.table_column_masks[definition.table_count] = ColumnSet::EMPTY;
                definition.table_include_descendants[definition.table_count] = false;
                definition_filter_sql[definition.table_count] = StackStr::new();
            }
            let schema_members = match publication_schemas(storage, txn.txid, schemas) {
                Ok(schemas) => schemas,
                Err(error) => return sql_fail(error),
            };
            for schema in &schema_members[..schemas.len()] {
                let Some(index) = definition.schemas[..definition.schema_count]
                    .iter()
                    .position(|member| member == schema)
                else {
                    return sql_fail(sql_err!(
                        sqlstate::UNDEFINED_OBJECT,
                        "schema is not part of publication \"{}\"",
                        name
                    ));
                };
                definition
                    .schemas
                    .copy_within(index + 1..definition.schema_count, index);
                definition.schema_count -= 1;
                definition.schemas[definition.schema_count] = u8::MAX;
            }
        }
    }
    definition.table_filters = match crate::storage::PublicationFilters::from_sql(
        &definition_filter_sql[..definition.table_count],
    ) {
        Ok(filters) => filters,
        Err(error) => return sql_fail(error),
    };
    if let Err(error) = validate_partitioned_publication_features(
        storage,
        txn.txid,
        name,
        &definition.tables[..definition.table_count],
        &definition.table_column_masks[..definition.table_count],
        &definition_filter_sql[..definition.table_count],
        definition.publish_via_partition_root,
    ) {
        return sql_fail(error);
    }
    if let Err(error) = validate_publication_replica_identity(storage, &definition, txn.txid) {
        return sql_fail(error);
    }
    let (slot, prior) = match storage.alter_publication(name, definition, txn.txid) {
        Ok(result) => result,
        Err(error) => return sql_fail(error),
    };
    let lsn = storage.bump_lsn();
    if let Err(error) = wal.stage_reserved(
        txn.txid,
        lsn,
        &WalOp::AlterPublication {
            name,
            all_tables: definition.all_tables,
            tables: definition.tables,
            table_column_masks: crate::wal::WalColumnSets::Captured(
                &definition.table_column_masks[..definition.table_count],
            ),
            table_include_descendants: definition.table_include_descendants,
            table_filter_sql: definition_filter_sql,
            table_count: definition.table_count,
            schemas: definition.schemas,
            schema_count: definition.schema_count,
            publish_insert: definition.publish_insert,
            publish_update: definition.publish_update,
            publish_delete: definition.publish_delete,
            publish_truncate: definition.publish_truncate,
            publish_via_partition_root: definition.publish_via_partition_root,
            publish_generated_columns: definition.publish_generated_columns,
        },
    ) {
        storage.rollback_publication_alter(slot, prior);
        return sql_fail(error);
    }
    if let Err(error) = txn.record_ddl(
        storage,
        super::txn::DdlUndo::PublicationAltered {
            slot: slot as u32,
            prior,
        },
    ) {
        storage.rollback_publication_alter(slot, prior);
        return sql_fail(error);
    }
    Ok(Ok(responder.command_complete("ALTER PUBLICATION")?))
}

type PublicationMembers = (
    [u16; crate::storage::MAX_PUBLICATION_TABLES],
    [ColumnSet; crate::storage::MAX_PUBLICATION_TABLES],
    [bool; crate::storage::MAX_PUBLICATION_TABLES],
    [StackStr<{ crate::storage::PUBLICATION_FILTER_SQL_MAX }>;
        crate::storage::MAX_PUBLICATION_TABLES],
    usize,
);

fn validate_publication_target_mix(
    column_masks: &[ColumnSet],
    schema_count: usize,
) -> Result<(), SqlError> {
    if schema_count != 0 && column_masks.iter().any(|mask| !mask.is_empty()) {
        return Err(sql_err!(
            sqlstate::FEATURE_NOT_SUPPORTED,
            "cannot specify a column list when publishing tables in a schema"
        ));
    }
    Ok(())
}

fn validate_partitioned_publication_features<const N: usize>(
    storage: &Storage,
    txid: u32,
    publication: &str,
    tables: &[u16],
    column_masks: &[ColumnSet],
    filters: &[StackStr<N>],
    publish_via_partition_root: bool,
) -> Result<(), SqlError> {
    if publish_via_partition_root {
        return Ok(());
    }
    for ((table, column_mask), filter) in tables.iter().zip(column_masks).zip(filters) {
        let definition = storage.table_def(usize::from(*table), txid);
        if !definition.partition.is_partitioned() {
            continue;
        }
        if !filter.is_empty() {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "cannot use publication WHERE clause for relation \"{}\" when publish_via_partition_root is false",
                definition.name.as_str()
            ));
        }
        if !column_mask.is_empty() {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "cannot use column list for relation \"{}.{}\" in publication \"{}\" when publish_via_partition_root is false",
                definition.schema.as_str(),
                definition.name.as_str(),
                publication
            ));
        }
    }
    Ok(())
}

fn publication_members(
    storage: &Storage,
    txid: u32,
    tables: &[PublicationTarget],
    require_replica_identity: bool,
    arena: &Arena,
) -> Result<PublicationMembers, SqlError> {
    let mut members = [u16::MAX; crate::storage::MAX_PUBLICATION_TABLES];
    let mut masks = [ColumnSet::EMPTY; crate::storage::MAX_PUBLICATION_TABLES];
    let mut descendants = [false; crate::storage::MAX_PUBLICATION_TABLES];
    let mut filters = [StackStr::new(); crate::storage::MAX_PUBLICATION_TABLES];
    for (index, table) in tables.iter().enumerate() {
        let Some(crate::storage::ResolvedRelation::Table(slot)) =
            storage.resolve_relation(table.relation.schema, table.relation.name, txid)
        else {
            return Err(sql_err!(
                sqlstate::UNDEFINED_TABLE,
                "relation \"{}\" does not exist",
                table.relation.name
            ));
        };
        storage.require_owner(storage.table_access_object(slot, txid), txid, "table")?;
        if members[..index].contains(&(slot as u16)) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "relation \"{}\" is listed more than once",
                table.relation.name
            ));
        }
        let definition = storage.table_def(slot, txid);
        if definition.persistence != crate::storage::RelationPersistence::Permanent {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "cannot add relation \"{}\" to publication",
                table.relation.name
            ));
        }
        let mut mask = ColumnSet::EMPTY;
        for (column_index, column_name) in table.columns.iter().enumerate() {
            let Some(column) = definition.column_index(column_name) else {
                return Err(crate::sql::error_position::at_reference(
                    sql_err!(
                        sqlstate::UNDEFINED_COLUMN,
                        "column \"{}\" of relation \"{}\" does not exist",
                        column_name,
                        table.relation.name
                    ),
                    column_name,
                ));
            };
            if mask.contains(column) {
                return Err(sql_err!(
                    sqlstate::DUPLICATE_COLUMN,
                    "column \"{}\" is listed more than once",
                    column_name
                ));
            }
            mask.insert(column);
            debug_assert!(column_index < crate::storage::MAX_COLUMNS);
        }
        if require_replica_identity {
            validate_publication_column_mask(storage, slot, mask, txid)?;
        }
        if let Some(filter) = table.filter {
            if filter
                .contains_nonimmutable_function_with(&|name| {
                    storage.builtin_routine_name_is_nonimmutable(name, txid)
                })
                .is_some()
            {
                crate::sql::eval::stash_diagnostic(
                    Some(StackStr::from_str(
                        "User-defined or built-in mutable functions are not allowed.",
                    )),
                    None,
                );
                return Err(sql_err!(
                    sqlstate::FEATURE_NOT_SUPPORTED,
                    "invalid publication WHERE expression"
                ));
            }
            let referenced = crate::sql::exec::ddl::check_referenced_columns(filter, &definition)?;
            let (type_oid, _) =
                describe::infer_type_catalog(filter, Some(&definition), storage, txid, arena)?;
            if type_oid != ColType::Bool.oid() {
                return Err(sql_err!(
                    sqlstate::DATATYPE_MISMATCH,
                    "argument of WHERE must be type boolean, not {}",
                    ColType::from_oid(type_oid).map_or("unknown", |ty| ty.name())
                ));
            }
            if require_replica_identity
                && replica_identity_columns(storage, slot, txid)?
                    .is_none_or(|identity| !referenced.difference(identity).is_empty())
            {
                return Err(sql_err!(
                    sqlstate::INVALID_PARAMETER_VALUE,
                    "publication row filter must use only replica identity columns"
                ));
            }
            let Some(filter_text) = table.filter_text else {
                return Err(sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "publication filter lost its source"
                ));
            };
            use core::fmt::Write as _;
            write!(filters[index], "{filter_text}").map_err(|_| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "publication row filter exceeds {} bytes",
                    crate::storage::PUBLICATION_FILTER_SQL_MAX
                )
            })?;
            if filters[index].is_truncated() {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "publication row filter exceeds {} bytes",
                    crate::storage::PUBLICATION_FILTER_SQL_MAX
                ));
            }
        }
        members[index] = slot as u16;
        masks[index] = mask;
        descendants[index] = matches!(
            table.descendants,
            crate::sql::ast::PublicationDescendants::Include
        );
    }
    Ok((members, masks, descendants, filters, tables.len()))
}

fn validate_publication_replica_identity(
    storage: &Storage,
    definition: &crate::storage::PublicationDefinition,
    txid: u32,
) -> Result<(), SqlError> {
    if !definition.publish_update && !definition.publish_delete {
        return Ok(());
    }
    for (table, mask) in definition.tables[..definition.table_count]
        .iter()
        .zip(&definition.table_column_masks[..definition.table_count])
    {
        validate_publication_column_mask(storage, *table as usize, *mask, txid)?;
    }
    Ok(())
}

fn validate_publication_column_mask(
    storage: &Storage,
    table_slot: usize,
    mask: ColumnSet,
    txid: u32,
) -> Result<(), SqlError> {
    if mask.is_empty() {
        return Ok(());
    }
    let identity = replica_identity_columns(storage, table_slot, txid)?;
    if let Some(identity) = identity
        && identity.difference(mask).is_empty()
    {
        return Ok(());
    }
    Err(sql_err!(
        sqlstate::INVALID_PARAMETER_VALUE,
        "publication column list must include the replica identity"
    ))
}

fn replica_identity_columns(
    storage: &Storage,
    table_slot: usize,
    txid: u32,
) -> Result<Option<ColumnSet>, SqlError> {
    let definition = storage.table_def(table_slot, txid);
    let all_columns = ColumnSet::all(definition.n_columns);
    match definition.replica_identity {
        crate::storage::ReplicaIdentityMode::Nothing => Ok(None),
        crate::storage::ReplicaIdentityMode::Full => Ok(Some(all_columns)),
        crate::storage::ReplicaIdentityMode::Default => {
            let mut identity = ColumnSet::EMPTY;
            for (index, column) in definition.columns().iter().enumerate() {
                if column.primary {
                    identity.insert(index);
                }
            }
            Ok((!identity.is_empty()).then_some(identity))
        }
        crate::storage::ReplicaIdentityMode::Index => {
            let mut identity = None;
            for index_slot in 0..storage.index_count() {
                let Some(index) = storage.index_visible_to(index_slot, txid) else {
                    continue;
                };
                if storage.index_table_slot_to(index_slot, txid) != Some(table_slot)
                    || !index.mutable_for(txid).replica_identity
                {
                    continue;
                }
                let mut columns = ColumnSet::EMPTY;
                for column in index.columns[..index.n_cols].iter().copied() {
                    columns.insert(usize::from(column));
                }
                if identity.replace(columns).is_some() {
                    return Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "relation has more than one replica identity index"
                    ));
                }
            }
            Ok(identity)
        }
    }
}

/// The user-supplied portion of CREATE VIEW, grouped to keep execution's
/// transaction and response dependencies distinct from statement input.
pub struct CreateViewCommand<'a> {
    pub name: &'a QualName<'a>,
    pub persistence: super::ast::RelationPersistence,
    pub columns: &'a [&'a str],
    pub or_replace: bool,
    pub security: super::ast::ViewSecurity,
    pub security_barrier: super::ast::ViewSecurityBarrier,
    pub check_option: Option<super::ast::ViewCheckOption>,
    pub sql: &'a str,
    pub raw_path: &'a str,
}

pub struct AlterViewCommand<'a> {
    pub name: QualName<'a>,
    pub if_exists: bool,
    pub action: crate::sql::ast::AlterViewAction<'a>,
}

#[derive(Clone, Copy)]
enum TriggerReturn<'a> {
    New,
    Old,
    Null,
    Void,
    Value(&'a Expr<'a>),
}

#[derive(Clone, Copy)]
enum TriggerReturnValue<'a> {
    New,
    Old,
    Null,
    Void,
    Value(Datum<'a>),
}

/// The PL/pgSQL execution boundary determines which runtime-only names and
/// return forms can enter the parsed program.
#[derive(Clone, Copy, PartialEq, Eq)]
enum PlpgsqlProgramKind {
    Trigger,
    EventTrigger,
    Function,
    VoidFunction,
    OutputFunction,
    SetFunction,
    Procedure,
    Anonymous,
}

fn plpgsql_function_program_kind(routine: &crate::storage::RoutineDef) -> PlpgsqlProgramKind {
    match routine.kind {
        crate::storage::RoutineKind::Function { result } if result.ctype == ColType::Void => {
            PlpgsqlProgramKind::VoidFunction
        }
        crate::storage::RoutineKind::Function { .. }
            if routine
                .parameters()
                .iter()
                .any(|parameter| parameter.mode.is_output()) =>
        {
            PlpgsqlProgramKind::OutputFunction
        }
        crate::storage::RoutineKind::Function { .. } => PlpgsqlProgramKind::Function,
        crate::storage::RoutineKind::RecordFunction {
            set_returning: false,
        } => PlpgsqlProgramKind::OutputFunction,
        crate::storage::RoutineKind::SetFunction { .. }
        | crate::storage::RoutineKind::RecordFunction {
            set_returning: true,
        }
        | crate::storage::RoutineKind::TableFunction => PlpgsqlProgramKind::SetFunction,
        _ => unreachable!("PL/pgSQL execution requires a function"),
    }
}

/// A variable as a statement names it: `x`, or `label.x` for the `x` that
/// the block, loop or routine labelled `label` declares.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PlpgsqlVariableName {
    label: Option<SqlName>,
    name: SqlName,
}

impl PlpgsqlVariableName {
    const fn plain(name: SqlName) -> Self {
        Self { label: None, name }
    }

    fn names(self, local: &TriggerLocalDecl) -> bool {
        local.name == self.name && self.label.is_none_or(|label| local.label == Some(label))
    }
}

#[derive(Clone, Copy)]
struct TriggerLocalAssignment<'a> {
    name: PlpgsqlVariableName,
    expression: &'a Expr<'a>,
    // Dependencies include the original target's subscripts after lowering.
    exception_variables: bool,
}

#[derive(Clone, Copy)]
struct ParsedTriggerLocalDecl<'a> {
    /// The declaration's text, a slice of the program text.
    source: &'a str,
    name: SqlName,
    ty: ParsedPlpgsqlLocalType<'a>,
    initial: Option<&'a Expr<'a>>,
    constant: bool,
    not_null: bool,
    /// `name [NO] [SCROLL] CURSOR [(arguments)] FOR query`: a `refcursor`
    /// local whose `OPEN` runs this query.
    bound: Option<BoundPlpgsqlCursor<'a>>,
}

/// A bound cursor's declared query, as PostgreSQL's `cursor_explicit_expr`.
#[derive(Clone, Copy)]
struct BoundPlpgsqlCursor<'a> {
    scroll: super::cursor::CursorScroll,
    parameters: &'a [BoundCursorParameter<'a>],
    query: &'a str,
}

#[derive(Clone, Copy)]
struct BoundCursorParameter<'a> {
    name: SqlName,
    type_name: &'a str,
}

/// One argument of `OPEN c(...)`, already in declaration order and converted
/// to its parameter's type; the query sees it under the parameter's name.
#[derive(Clone, Copy)]
struct BoundCursorArgument<'a> {
    name: SqlName,
    type_name: &'a str,
    value: &'a Expr<'a>,
}

thread_local! {
    /// The bound cursors of the program being parsed, for its `OPEN`s.
    static BOUND_CURSORS: core::cell::Cell<(*const (), usize)> =
        const { core::cell::Cell::new((core::ptr::null(), 0)) };
}

/// Runs `parse` with `locals` visible to [`bound_plpgsql_cursor`].
fn with_bound_plpgsql_cursors<'a, T>(
    locals: &'a [ParsedTriggerLocalDecl<'a>],
    parse: impl FnOnce() -> T,
) -> T {
    struct Restore((*const (), usize));
    impl Drop for Restore {
        fn drop(&mut self) {
            BOUND_CURSORS.with(|slot| slot.set(self.0));
        }
    }
    let previous = BOUND_CURSORS.with(|slot| slot.replace((locals.as_ptr().cast(), locals.len())));
    let _restore = Restore(previous);
    parse()
}

/// The bound cursor declared as `name` in the program being parsed.
fn bound_plpgsql_cursor<'a>(name: SqlName, _arena: &'a Arena) -> Option<BoundPlpgsqlCursor<'a>> {
    plpgsql_cursor_variable(name).flatten()
}

/// The `refcursor` local declared as `name` in the program being parsed:
/// `Some(Some(_))` when it is bound to a query, `Some(None)` when unbound.
fn plpgsql_cursor_variable<'a>(name: SqlName) -> Option<Option<BoundPlpgsqlCursor<'a>>> {
    let (pointer, len) = BOUND_CURSORS.with(core::cell::Cell::get);
    if pointer.is_null() {
        return None;
    }
    // SAFETY: `with_bound_plpgsql_cursors` publishes these declarations only
    // while the program that owns them is parsed from the same arena, and
    // restores the previous value before that borrow ends. Statements parsed
    // in that window borrow the arena for the declarations' lifetime.
    let locals =
        unsafe { core::slice::from_raw_parts(pointer.cast::<ParsedTriggerLocalDecl<'a>>(), len) };
    let local = locals.iter().find(|local| local.name == name)?;
    match (local.bound, local.ty) {
        (Some(bound), _) => Some(Some(bound)),
        (None, ParsedPlpgsqlLocalType::Named { name, .. })
            if name.eq_ignore_ascii_case("refcursor") =>
        {
            Some(None)
        }
        _ => None,
    }
}

/// A local declaration has either a complete type spelling or a catalog
/// reference that is resolved before the interpreter receives the program.
/// In particular, `%TYPE` and `%ROWTYPE` cannot reach execution as strings.
#[derive(Clone, Copy)]
enum ParsedPlpgsqlLocalType<'a> {
    Named { name: &'a str, type_mod: i32 },
    Column { relation: &'a str, column: &'a str },
    Row { relation: &'a str },
    Record,
}

#[derive(Clone, Copy)]
enum PlpgsqlRecordShape {
    Dynamic,
    /// A table's row type: the table's slot, and the row type whose fields
    /// a NULL row's field references are typed by.
    Table {
        slot: u16,
        row_type: crate::storage::TypeCreation,
    },
}

/// Ordering follows lexical nesting, independently of handler-buffer slots.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum PlpgsqlScope {
    Invocation,
    Frame(core::num::NonZeroUsize),
}

impl PlpgsqlScope {
    fn frame(depth: usize) -> Self {
        Self::Frame(core::num::NonZeroUsize::new(depth).expect("active procedural frame"))
    }
}

#[derive(Clone, Copy)]
struct TriggerLocalDecl {
    scope: PlpgsqlScope,
    /// The label of the block, loop or routine that declares the variable,
    /// which qualifies it as `label.name`. A routine labels its parameters
    /// with its own name.
    label: Option<SqlName>,
    name: SqlName,
    ctype: ColType,
    user_type: Option<crate::storage::UserTypeName>,
    type_mod: i32,
    record_shape: Option<PlpgsqlRecordShape>,
    constant: bool,
    not_null: bool,
}

impl TriggerLocalDecl {
    /// The type the variable is declared with: a table's row variable has
    /// the table's row type.
    fn declared_type(&self) -> ColType {
        match self.record_shape {
            Some(PlpgsqlRecordShape::Table { row_type, .. }) => ColType::Composite(Some(row_type)),
            _ => self.ctype,
        }
    }
}

/// Per-firing context stays distinct from lexical local bindings, including
/// in detached scopes used by nested trigger writes.
#[derive(Clone, Copy)]
struct TriggerInvocation<'a> {
    program_kind: PlpgsqlProgramKind,
    name: &'a str,
    routine_schema: &'a str,
    routine_name: &'a str,
    table_schema: &'a str,
    table_name: &'a str,
    relid: i32,
    routine_oid: i32,
    input_origin: super::plpgsql_inputs::Origin,
    input_owner: super::type_input_plans::Owner,
    input_collation: crate::sql::ast::Collation,
    input_sites: &'a [super::plpgsql_inputs::Site<'a>],
    /// How the body's statements resolve a name that is both a variable and
    /// a column: its `#variable_conflict` option, else the setting it was
    /// compiled under.
    variable_conflict: super::guc::VariableConflict,
    /// `STRICT` failures list the statement's variables (`#print_strict_params`
    /// or `plpgsql.print_strict_params`).
    print_strict_params: bool,
    /// PostgreSQL runs each query of a volatile function, a procedure, a
    /// trigger or a DO block under a new snapshot that sees the transaction's
    /// earlier commands; a stable or immutable function reads its caller's.
    fresh_snapshots: bool,
    materialized_relations: Option<&'a [(&'a str, &'a crate::sql::ast::MaterializedCte<'a>)]>,
    nargs: i32,
    when: &'static str,
    level: &'static str,
    operation: &'static str,
    argv: Datum<'a>,
    event: &'a str,
    tag: &'a str,
    exception: Option<TriggerExceptionBinding<'a>>,
}

#[derive(Clone, Copy)]
struct TriggerRelationIdentity {
    target: crate::storage::TriggerTarget,
    schema: SqlName,
    name: SqlName,
}

#[derive(Clone, Copy)]
enum TriggerContextField {
    Name,
    When,
    Level,
    Operation,
    Relid,
    Relname,
    TableName,
    TableSchema,
    Nargs,
    Argv,
    Event,
    Tag,
}

impl TriggerContextField {
    fn parse(name: &str) -> Option<Self> {
        if name == "tg_name" {
            Some(Self::Name)
        } else if name == "tg_when" {
            Some(Self::When)
        } else if name == "tg_level" {
            Some(Self::Level)
        } else if name == "tg_op" {
            Some(Self::Operation)
        } else if name == "tg_relid" {
            Some(Self::Relid)
        } else if name == "tg_relname" {
            Some(Self::Relname)
        } else if name == "tg_table_name" {
            Some(Self::TableName)
        } else if name == "tg_table_schema" {
            Some(Self::TableSchema)
        } else if name == "tg_nargs" {
            Some(Self::Nargs)
        } else if name == "tg_argv" {
            Some(Self::Argv)
        } else if name == "tg_event" {
            Some(Self::Event)
        } else if name == "tg_tag" {
            Some(Self::Tag)
        } else {
            None
        }
    }

    const fn ctype(self) -> ColType {
        match self {
            Self::Relid => ColType::Oid,
            Self::Nargs => ColType::Int4,
            Self::Name | Self::Relname | Self::TableName | Self::TableSchema => ColType::Name,
            Self::Argv => ColType::Array(ArrElem::Text),
            Self::When | Self::Level | Self::Operation | Self::Event | Self::Tag => ColType::Text,
        }
    }
}

fn plpgsql_context_field(kind: PlpgsqlProgramKind, name: &str) -> Option<TriggerContextField> {
    let field = TriggerContextField::parse(name)?;
    match (kind, field) {
        (
            PlpgsqlProgramKind::EventTrigger,
            TriggerContextField::Event | TriggerContextField::Tag,
        ) => Some(field),
        (PlpgsqlProgramKind::Trigger, TriggerContextField::Event | TriggerContextField::Tag) => {
            None
        }
        (PlpgsqlProgramKind::Trigger, field) => Some(field),
        _ => None,
    }
}

impl<'a> TriggerInvocation<'a> {
    fn new(
        storage: &Storage,
        trigger: &crate::storage::TriggerDef,
        relation: TriggerRelationIdentity,
        event: u8,
        routine: &crate::storage::RoutineDef,
        settings: super::guc::PlpgsqlSettings,
        arena: &'a Arena,
    ) -> Result<Self, SqlError> {
        let mut arguments = [Datum::Null; crate::storage::MAX_TRIGGER_ARGUMENTS];
        for (index, argument) in trigger.arguments.values().iter().enumerate() {
            arguments[index] = Datum::Text(
                arena
                    .alloc_str(argument.as_str())
                    .map_err(|_| super::query::arena_full_pub())?,
            );
        }
        let count = trigger.arguments.values().len();
        let argv = if count == 0 {
            Datum::Null
        } else {
            // PostgreSQL trigger arguments are zero-based, unlike ordinary arrays.
            Datum::Array {
                element: ArrElem::Text,
                raw: crate::sql::array::build_shaped(
                    &arguments[..count],
                    crate::sql::array::Shape::new(&[count], &[0])?,
                    arena,
                )?,
            }
        };
        let operation = match event {
            TriggerEvents::INSERT => "INSERT",
            TriggerEvents::UPDATE => "UPDATE",
            TriggerEvents::DELETE => "DELETE",
            TriggerEvents::TRUNCATE => "TRUNCATE",
            _ => unreachable!("trigger event was validated at the parser boundary"),
        };
        Ok(Self {
            program_kind: PlpgsqlProgramKind::Trigger,
            name: arena
                .alloc_str(trigger.name.as_str())
                .map_err(|_| super::query::arena_full_pub())?,
            routine_schema: arena
                .alloc_str(routine.schema.as_str())
                .map_err(|_| super::query::arena_full_pub())?,
            routine_name: arena
                .alloc_str(routine.name.as_str())
                .map_err(|_| super::query::arena_full_pub())?,
            table_schema: arena
                .alloc_str(relation.schema.as_str())
                .map_err(|_| super::query::arena_full_pub())?,
            table_name: arena
                .alloc_str(relation.name.as_str())
                .map_err(|_| super::query::arena_full_pub())?,
            relid: match relation.target {
                crate::storage::TriggerTarget::Table(slot) => {
                    crate::sql::catalog::user_table_oid(storage, usize::from(slot))
                }
                crate::storage::TriggerTarget::View(slot) => {
                    crate::sql::catalog::view_oid(storage, usize::from(slot))
                }
            },
            routine_oid: crate::storage::routine_oid(routine),
            input_origin: super::plpgsql_inputs::Origin::Routine {
                oid: crate::storage::routine_oid(routine),
                version: routine.version,
            },
            input_owner: super::type_input_plans::Owner::Backend,
            input_collation: crate::sql::ast::Collation::None,
            input_sites: &[],
            variable_conflict: settings.variable_conflict,
            print_strict_params: settings.print_strict_params,
            fresh_snapshots: true,
            materialized_relations: None,
            nargs: i32::try_from(trigger.arguments.values().len())
                .expect("trigger argument capacity fits int4"),
            when: match trigger.timing {
                TriggerTiming::Before => "BEFORE",
                TriggerTiming::After => "AFTER",
                TriggerTiming::InsteadOf => "INSTEAD OF",
            },
            level: match trigger.level {
                TriggerLevel::Row => "ROW",
                TriggerLevel::Statement => "STATEMENT",
            },
            operation,
            argv,
            event: "",
            tag: "",
            exception: None,
        })
    }

    fn anonymous(settings: super::guc::PlpgsqlSettings) -> Result<Self, SqlError> {
        Ok(Self {
            program_kind: PlpgsqlProgramKind::Anonymous,
            name: "",
            routine_schema: "",
            routine_name: "inline_code_block",
            table_schema: "",
            table_name: "",
            relid: 0,
            routine_oid: 0,
            input_origin: super::plpgsql_inputs::Origin::Anonymous,
            input_owner: super::type_input_plans::owner()?,
            input_collation: crate::sql::ast::Collation::None,
            input_sites: &[],
            variable_conflict: settings.variable_conflict,
            print_strict_params: settings.print_strict_params,
            fresh_snapshots: true,
            materialized_relations: None,
            nargs: 0,
            when: "",
            level: "",
            operation: "",
            argv: Datum::Null,
            event: "",
            tag: "",
            exception: None,
        })
    }

    fn procedure(
        routine: &crate::storage::RoutineDef,
        input_collation: crate::sql::ast::Collation,
        settings: super::guc::PlpgsqlSettings,
        arena: &'a Arena,
    ) -> Result<Self, SqlError> {
        Ok(Self {
            program_kind: PlpgsqlProgramKind::Procedure,
            name: "",
            routine_schema: arena
                .alloc_str(routine.schema.as_str())
                .map_err(|_| super::query::arena_full_pub())?,
            routine_name: arena
                .alloc_str(routine.name.as_str())
                .map_err(|_| super::query::arena_full_pub())?,
            table_schema: "",
            table_name: "",
            relid: 0,
            routine_oid: crate::storage::routine_oid(routine),
            input_origin: super::plpgsql_inputs::Origin::Routine {
                oid: crate::storage::routine_oid(routine),
                version: routine.version,
            },
            input_owner: super::type_input_plans::owner()?,
            input_collation,
            input_sites: &[],
            variable_conflict: settings.variable_conflict,
            print_strict_params: settings.print_strict_params,
            fresh_snapshots: true,
            materialized_relations: None,
            nargs: 0,
            when: "",
            level: "",
            operation: "",
            argv: Datum::Null,
            event: "",
            tag: "",
            exception: None,
        })
    }

    fn function(
        routine: &crate::storage::RoutineDef,
        program_kind: PlpgsqlProgramKind,
        input_collation: crate::sql::ast::Collation,
        settings: super::guc::PlpgsqlSettings,
        arena: &'a Arena,
    ) -> Result<Self, SqlError> {
        Ok(Self {
            program_kind,
            name: "",
            routine_schema: arena
                .alloc_str(routine.schema.as_str())
                .map_err(|_| super::query::arena_full_pub())?,
            routine_name: arena
                .alloc_str(routine.name.as_str())
                .map_err(|_| super::query::arena_full_pub())?,
            table_schema: "",
            table_name: "",
            relid: 0,
            routine_oid: crate::storage::routine_oid(routine),
            input_origin: super::plpgsql_inputs::Origin::Routine {
                oid: crate::storage::routine_oid(routine),
                version: routine.version,
            },
            input_owner: super::type_input_plans::owner()?,
            input_collation,
            input_sites: &[],
            variable_conflict: settings.variable_conflict,
            print_strict_params: settings.print_strict_params,
            fresh_snapshots: routine.attributes.volatility
                == crate::storage::RoutineVolatility::Volatile,
            materialized_relations: None,
            nargs: i32::try_from(routine.arguments().len())
                .expect("routine argument capacity fits int4"),
            when: "",
            level: "",
            operation: "",
            argv: Datum::Null,
            event: "",
            tag: "",
            exception: None,
        })
    }

    fn event_trigger(
        routine: &crate::storage::RoutineDef,
        event: &'a str,
        tag: &'a str,
        settings: super::guc::PlpgsqlSettings,
        arena: &'a Arena,
    ) -> Result<Self, SqlError> {
        Ok(Self {
            program_kind: PlpgsqlProgramKind::EventTrigger,
            name: "",
            routine_schema: arena
                .alloc_str(routine.schema.as_str())
                .map_err(|_| super::query::arena_full_pub())?,
            routine_name: arena
                .alloc_str(routine.name.as_str())
                .map_err(|_| super::query::arena_full_pub())?,
            table_schema: "",
            table_name: "",
            relid: 0,
            routine_oid: crate::storage::routine_oid(routine),
            input_origin: super::plpgsql_inputs::Origin::Routine {
                oid: crate::storage::routine_oid(routine),
                version: routine.version,
            },
            input_owner: super::type_input_plans::Owner::Backend,
            input_collation: crate::sql::ast::Collation::None,
            input_sites: &[],
            variable_conflict: settings.variable_conflict,
            print_strict_params: settings.print_strict_params,
            fresh_snapshots: true,
            materialized_relations: None,
            nargs: 0,
            when: "",
            level: "",
            operation: "",
            argv: Datum::Null,
            event,
            tag,
            exception: None,
        })
    }

    fn with_input_sites(mut self, sites: &'a [super::plpgsql_inputs::Site<'a>]) -> Self {
        self.input_sites = sites;
        self
    }

    fn input_plan_key(
        self,
        site: super::plpgsql_inputs::Site<'_>,
    ) -> Result<super::type_input_plans::Key, SqlError> {
        let (owner, source) = match self.input_origin {
            super::plpgsql_inputs::Origin::Routine { oid, version } => (
                self.input_owner,
                super::type_inputs::Source::PlpgsqlBodyExpression {
                    routine_oid: oid,
                    definition_version: version,
                    expression: site.position,
                },
            ),
            super::plpgsql_inputs::Origin::Anonymous => (
                self.input_owner,
                super::type_inputs::Source::PlpgsqlAnonymousExpression {
                    expression: site.position,
                },
            ),
        };
        Ok(super::type_input_plans::Key { owner, source })
    }

    fn with_exception(
        mut self,
        values: TriggerExceptionVariables<'a>,
        scope: PlpgsqlScope,
    ) -> Self {
        self.exception = Some(TriggerExceptionBinding { values, scope });
        self
    }

    fn value(self, field: TriggerContextField) -> Datum<'a> {
        match field {
            TriggerContextField::Name => Datum::Text(self.name),
            TriggerContextField::When => Datum::Text(self.when),
            TriggerContextField::Level => Datum::Text(self.level),
            TriggerContextField::Operation => Datum::Text(self.operation),
            TriggerContextField::Relid => Datum::Oid(self.relid as u32),
            TriggerContextField::Relname => Datum::Text(self.table_name),
            TriggerContextField::TableName => Datum::Text(self.table_name),
            TriggerContextField::TableSchema => Datum::Text(self.table_schema),
            TriggerContextField::Nargs => Datum::Int4(self.nargs),
            TriggerContextField::Argv => self.argv,
            TriggerContextField::Event => Datum::Text(self.event),
            TriggerContextField::Tag => Datum::Text(self.tag),
        }
    }
}

#[derive(Clone, Copy)]
struct TriggerSelectInto<'a> {
    query: &'a Select<'a>,
    targets: &'a [PlpgsqlVariableName],
    strict: bool,
}

/// A dynamic PL/pgSQL query has a closed clause shape at creation time.  Its
/// command text crosses one typed parse boundary only after `USING` values
/// have been evaluated for the current invocation.
#[derive(Clone, Copy)]
struct PlpgsqlDynamicQuery<'a> {
    command: &'a Expr<'a>,
    arguments: &'a [&'a Expr<'a>],
}

#[derive(Clone, Copy)]
struct PlpgsqlDynamicSelectInto<'a> {
    query: PlpgsqlDynamicQuery<'a>,
    targets: &'a [PlpgsqlVariableName],
    strict: bool,
}

#[derive(Clone, Copy)]
enum PlpgsqlCursorQuery<'a> {
    Static(&'a str),
    Dynamic(PlpgsqlDynamicQuery<'a>),
}

#[derive(Clone, Copy)]
struct PlpgsqlCursorOpen<'a> {
    variable: PlpgsqlVariableName,
    /// The variable as written, for its compile-time check.
    written: &'a str,
    scroll: super::cursor::CursorScroll,
    query: PlpgsqlCursorQuery<'a>,
    /// A bound cursor's arguments, visible to its query by parameter name.
    arguments: &'a [BoundCursorArgument<'a>],
}

#[derive(Clone, Copy)]
struct PlpgsqlCursorClose<'a> {
    variable: PlpgsqlVariableName,
    written: &'a str,
}

#[derive(Clone, Copy)]
struct PlpgsqlCursorMotion<'a> {
    variable: PlpgsqlVariableName,
    /// The variable as written, for its compile-time check.
    written: &'a str,
    /// How the direction's first word reads, which depends on whether it
    /// names a variable as PostgreSQL's grammar decides.
    leading: Option<MotionLeading<'a>>,
    /// The direction, or the default replaced by an evaluated `count`.
    motion: super::cursor::FetchMotion,
    count: Option<PlpgsqlMotionCount<'a>>,
    move_only: bool,
    targets: &'a [PlpgsqlVariableName],
}

/// A FETCH or MOVE whose direction starts with a bare name. PostgreSQL reads
/// a declared variable there as the cursor variable, and anything else as a
/// count expression.
#[derive(Clone, Copy)]
struct MotionLeading<'a> {
    name: PlpgsqlVariableName,
    written: &'a str,
    /// The token after the name when it was read as a count expression; a
    /// lone name was read as the cursor variable.
    next: Option<&'a str>,
    /// The end of the statement, where an unfinished expression is reported.
    end: &'a str,
}

/// A FETCH or MOVE count or position written as an expression, evaluated
/// as an integer each time the statement runs.
#[derive(Clone, Copy)]
struct PlpgsqlMotionCount<'a> {
    kind: PlpgsqlMotionCountKind,
    expression: &'a Expr<'a>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum PlpgsqlMotionCountKind {
    Forward,
    Backward,
    Absolute,
    Relative,
}

impl PlpgsqlMotionCount<'_> {
    fn motion(self, count: Datum) -> Result<super::cursor::FetchMotion, SqlError> {
        use super::cursor::FetchMotion;
        let count = match count {
            Datum::Null => {
                return Err(sql_err!(
                    sqlstate::NULL_VALUE_NOT_ALLOWED,
                    "relative or absolute cursor position is null"
                ));
            }
            Datum::Int4(count) => count,
            _ => {
                return Err(sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "cursor count was not converted to integer"
                ));
            }
        };
        Ok(match self.kind {
            PlpgsqlMotionCountKind::Forward => FetchMotion::Count(count),
            PlpgsqlMotionCountKind::Backward if count == 0 => FetchMotion::BackwardZero,
            PlpgsqlMotionCountKind::Backward => {
                FetchMotion::Count(count.checked_neg().ok_or_else(|| {
                    sql_err!(sqlstate::NUMERIC_OUT_OF_RANGE, "integer out of range")
                })?)
            }
            PlpgsqlMotionCountKind::Absolute => FetchMotion::Absolute(count),
            PlpgsqlMotionCountKind::Relative => FetchMotion::Relative(count),
        })
    }
}

