#[derive(Clone, Copy)]
enum TriggerDml<'a> {
    Insert(Insert<'a>),
    Update(Update<'a>),
    Delete(Delete<'a>),
    Merge(&'a crate::sql::ast::Merge<'a>),
    With(TriggerDmlWith<'a>),
}

impl<'a> TriggerDml<'a> {
    /// The statement a PL/pgSQL body writes, as parsed.
    fn from_statement(statement: &'a Stmt<'a>) -> Option<Self> {
        Some(match statement {
            Stmt::Insert(statement) => Self::Insert(*statement),
            Stmt::Update(statement) => Self::Update(*statement),
            Stmt::Delete(statement) => Self::Delete(*statement),
            Stmt::Merge(statement) => Self::Merge(statement),
            Stmt::With { ctes, statement } => Self::With(TriggerDmlWith::new(ctes, statement)?),
            _ => return None,
        })
    }

    fn statement(self) -> Stmt<'a> {
        match self {
            Self::Insert(statement) => Stmt::Insert(statement),
            Self::Update(statement) => Stmt::Update(statement),
            Self::Delete(statement) => Stmt::Delete(statement),
            Self::Merge(statement) => Stmt::Merge(*statement),
            Self::With(with) => Stmt::With {
                ctes: with.ctes,
                statement: with.statement,
            },
        }
    }

    fn returns(self) -> bool {
        match self {
            Self::Insert(statement) => !statement.returning.is_empty(),
            Self::Update(statement) => !statement.returning.is_empty(),
            Self::Delete(statement) => !statement.returning.is_empty(),
            Self::Merge(statement) => !statement.returning.is_empty(),
            Self::With(with) => match with.statement {
                Stmt::Insert(statement) => !statement.returning.is_empty(),
                Stmt::Update(statement) => !statement.returning.is_empty(),
                Stmt::Delete(statement) => !statement.returning.is_empty(),
                _ => unreachable!("checked when the WITH statement was built"),
            },
        }
    }
}

/// `WITH ... INSERT/UPDATE/DELETE` in a PL/pgSQL body. The statement after
/// the `WITH` queries is one of the three writes, never another `WITH`.
#[derive(Clone, Copy)]
struct TriggerDmlWith<'a> {
    ctes: &'a [crate::sql::ast::Cte<'a>],
    statement: &'a Stmt<'a>,
}

impl<'a> TriggerDmlWith<'a> {
    fn new(ctes: &'a [crate::sql::ast::Cte<'a>], statement: &'a Stmt<'a>) -> Option<Self> {
        matches!(
            statement,
            Stmt::Insert(_) | Stmt::Update(_) | Stmt::Delete(_)
        )
        .then_some(Self { ctes, statement })
    }

    fn writes(self) -> bool {
        self.ctes.iter().any(|cte| cte.dml.is_some())
    }
}

static NO_TRIGGER_DML_COLUMNS: NoColumns = NoColumns;

/// The INSERT source is either evaluated by the ordinary executor or already
/// converted and encoded by a trigger's short-lived read phase. The latter
/// has no storage borrow; its write phase must not repeat assignment casts.
#[derive(Clone, Copy)]
pub(crate) enum InsertSource<'a> {
    Statement,
    MaterializedSelect {
        rows: &'a [&'a [u8]],
        assignments: AssignmentCasts<'a>,
        /// Rows staged unconverted, with their deferred calls still to run.
        deferred: Option<deferred_source::DeferredSource<'a>>,
    },
}

#[derive(Clone, Copy)]
enum TriggerStatement<'a> {
    Null,
    TransactionControl(PlpgsqlTransactionCommand),
    LocalAssign(TriggerLocalAssignment<'a>),
    SelectInto(TriggerSelectInto<'a>),
    DynamicQuery(PlpgsqlDynamicQuery<'a>),
    DynamicSelectInto(PlpgsqlDynamicSelectInto<'a>),
    Utility {
        source: &'a str,
        statement: &'a Stmt<'a>,
    },
    /// `CALL`: output parameters are assigned to the argument variables.
    Call {
        source: &'a str,
        statement: &'a Stmt<'a>,
    },
    CursorOpen(PlpgsqlCursorOpen<'a>),
    CursorMotion(PlpgsqlCursorMotion<'a>),
    CursorClose(PlpgsqlCursorClose<'a>),
    Perform(&'a Select<'a>),
    Assert(TriggerAssert<'a>),
    Raise(TriggerRaise<'a>),
    GetDiagnostics(TriggerGetDiagnostics<'a>),
    GetStackedDiagnostics(TriggerGetStackedDiagnostics<'a>),
    Exception(TriggerException<'a>),
    Dml {
        source: &'a str,
        statement: TriggerDml<'a>,
        into: Option<PlpgsqlInto<'a>>,
    },
    /// A nested `BEGIN ... END` block without exception handlers, or a
    /// labelled block with or without them.
    Block(TriggerNestedBlock<'a>),
    If(TriggerIf<'a>),
    Case(TriggerCase<'a>),
    For(TriggerFor<'a>),
    While(TriggerWhile<'a>),
    Loop(TriggerBlock<'a>),
    LoopControl(TriggerLoopControl<'a>),
    ReturnNext(Option<&'a Expr<'a>>),
    ReturnQuery(&'a Select<'a>),
    ReturnDynamicQuery(PlpgsqlDynamicQuery<'a>),
    Return(TriggerReturn<'a>),
}

